INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('192c1e43-db29-5e1f-a55d-346cda99b5c3', '936de3bf-6257-57fd-a317-f333a7dce57e', '6fe09823-ddcf-5bd4-a7db-584db5d76492', 2, 12, 'የእስራኤልም ልጆች ከሲና ምድረ በዳ በየጉዞአቸው ተጓዙ፤ ደመናውም በፋራን ምድረ በዳ ቆመ።'),
  ('1e6985dc-3cf6-55e8-ad36-caa0a93e9b32', '936de3bf-6257-57fd-a317-f333a7dce57e', '6fe09823-ddcf-5bd4-a7db-584db5d76492', 3, 13, 'በመጀመሪያም እግዚአብሔር በሙሴ ቃል እንዳዘዘ ተጓዙ።'),
  ('88b5adf6-334d-5d4f-a55a-b289a34de10a', '936de3bf-6257-57fd-a317-f333a7dce57e', '6fe09823-ddcf-5bd4-a7db-584db5d76492', 4, 14, 'በመጀመሪያም የይሁዳ ልጆች ሰፈር በሥርዐታቸው ከየሠራዊቶቻቸው ጋር ተጓዘ፤ በሠራዊቱም ላይ የአሚናዳብ ልጅ ነአሶን አለቃ ነበረ።'),
  ('ff421c2a-0567-5733-ac5f-715eff318e1c', '936de3bf-6257-57fd-a317-f333a7dce57e', '6fe09823-ddcf-5bd4-a7db-584db5d76492', 5, 15, 'በይሳኮርም ልጆች ነገድ ሠራዊት ላይ የሰገር ልጅ ናትናኤል አለቃ ነበረ።'),
  ('0826898f-dd24-5cd1-a3ba-ba4c9544ff5c', '936de3bf-6257-57fd-a317-f333a7dce57e', '6fe09823-ddcf-5bd4-a7db-584db5d76492', 6, 16, 'በዛብሎንም ልጆች ነገድ ሠራዊት ላይ የኬሎን ልጅ ኤልያብ አለቃ ነበረ።'),
  ('5cf643e1-8b2d-5427-ad69-d0341c717e06', '936de3bf-6257-57fd-a317-f333a7dce57e', '6fe09823-ddcf-5bd4-a7db-584db5d76492', 7, 17, 'ድንኳኑም ተነቀለ፤ ድንኳኑንም የተሸከሙ የጌድሶን ልጆችና የሜራሪ ልጆች ተጓዙ።'),
  ('6a0b6f14-6dda-55fe-a84a-1f38fb9276fe', '936de3bf-6257-57fd-a317-f333a7dce57e', '6fe09823-ddcf-5bd4-a7db-584db5d76492', 8, 18, 'የሮቤልም ሰፈር በሥርዐታቸው ከየሠራዊቶቻቸው ጋር ተጓዘ፤ በሠራዊቱም ላይ የሰዲዮር ልጅ ኤሊሱር አለቃ ነበረ።'),
  ('c8c6fe3c-1f46-53cd-a2b3-62a8f69d5cdf', '936de3bf-6257-57fd-a317-f333a7dce57e', '6fe09823-ddcf-5bd4-a7db-584db5d76492', 9, 19, 'በስምዖንም ልጆች ነገድ ሠራዊት ላይ የሲሩሳዴ ልጅ ሰላምያል አለቃ ነበረ።'),
  ('4986cfd7-02ee-5ede-a2bb-e9d0014c16a2', '936de3bf-6257-57fd-a317-f333a7dce57e', '6fe09823-ddcf-5bd4-a7db-584db5d76492', 10, 20, 'በጋድም ልጆች ነገድ ሠራዊት ላይ የራጉኤል ልጅ ኤሊሳፍ አለቃ ነበረ።'),
  ('db403261-549c-5eb0-a95d-2ad09844e765', '936de3bf-6257-57fd-a317-f333a7dce57e', '6fe09823-ddcf-5bd4-a7db-584db5d76492', 11, 21, 'የቀዓትም ልጆች ንዋየ ቅድሳቱን ተሸክመው ተጓዙ፤ እነዚህም እስኪመጡ ድረስ እነዚያ ድንኳኑን ተከሉ።'),
  ('861b9168-fe29-5c28-ac6d-f479163c5d32', '936de3bf-6257-57fd-a317-f333a7dce57e', '6fe09823-ddcf-5bd4-a7db-584db5d76492', 12, 22, 'የኤፍሬምም ልጆች ሰፈር በሥርዐታቸው ከየሠራዊቶቻቸው ጋር ተጓዘ፤ በሠራዊቱም ላይ የኣሚሁድ ልጅ ኤሊሳማ አለቃ ነበረ።'),
  ('460e9bd4-f61a-57cb-a01a-e7446435c878', '936de3bf-6257-57fd-a317-f333a7dce57e', '6fe09823-ddcf-5bd4-a7db-584db5d76492', 13, 23, 'በምናሴም ልጆች ነገድ ሠራዊት ላይ የፈዳሱር ልጅ ገማልያል አለቃ ነበረ።'),
  ('1ef94b2f-2b48-546b-a827-605d9621b845', '936de3bf-6257-57fd-a317-f333a7dce57e', '6fe09823-ddcf-5bd4-a7db-584db5d76492', 14, 24, 'በብንያምም ልጆች ነገድ ሠራዊት ላይ የጋዲዮን ልጅ አቢዳን አለቃ ነበረ።'),
  ('de91f202-4910-5769-a6ce-2a3736d3ee1f', '936de3bf-6257-57fd-a317-f333a7dce57e', '6fe09823-ddcf-5bd4-a7db-584db5d76492', 15, 25, 'ከሠራዊቱ ሁሉ በኋላ የዳን ልጆች ሰፈር በሥርዐታቸው ከየሠራዊታቸው ጋር ተጓዘ፤ በሠራዊቱም ላይ የአሚሳዲ ልጅ አኪያዜር አለቃ ነበረ።'),
  ('4212bb7f-1647-5e4d-ae90-1080e5707bc2', '936de3bf-6257-57fd-a317-f333a7dce57e', '6fe09823-ddcf-5bd4-a7db-584db5d76492', 16, 26, 'በአሴርም ልጆች ነገድ ሠራዊት ላይ የኤክራን ልጅ ፋግኤል አለቃ ነበረ።'),
  ('b72c033d-52fb-54c2-a073-91bc69855617', '936de3bf-6257-57fd-a317-f333a7dce57e', '6fe09823-ddcf-5bd4-a7db-584db5d76492', 17, 27, 'በንፍታሌምም ልጆች ነገድ ሠራዊት ላይ የዔናን ልጅ አኪሬ አለቃ ነበረ።'),
  ('a7574e42-5157-59db-a06d-a114e3af02bb', '936de3bf-6257-57fd-a317-f333a7dce57e', '6fe09823-ddcf-5bd4-a7db-584db5d76492', 18, 28, 'የእስራኤል ልጆች ጉዞ እንደዚህ ነበር፤ ከሠራዊታቸው ጋር ተጓዙ።'),
  ('30706279-807a-56f9-af03-bd51ca4579e1', '936de3bf-6257-57fd-a317-f333a7dce57e', '6fe09823-ddcf-5bd4-a7db-584db5d76492', 19, 29, 'ሙሴም የሚስቱን አባት የምድያማዊውን የራጉኤልን ልጅ ኦባብን፥ “እግዚአብሔር፦ ለእናንተ እሰጠዋለሁ ወዳለው ስፍራ እንሄዳለን፤ እግዚአብሔር ስለ እስራኤል መልካምን ነገር ተናግሮአልና አንተ ከእኛ ጋር ና፥ መልካምን እናደርግልሃለን” አለው።'),
  ('418840a6-0337-5e00-aeee-f37ba1590218', '936de3bf-6257-57fd-a317-f333a7dce57e', '6fe09823-ddcf-5bd4-a7db-584db5d76492', 20, 30, 'እርሱም፥ “አልሄድም፥ ነገር ግን ወደ ሀገሬና ወደ ዘመዶች እመለሳለሁ” አለው።'),
  ('6533428d-0f5e-5df2-a04a-da67c97ad496', '936de3bf-6257-57fd-a317-f333a7dce57e', '6fe09823-ddcf-5bd4-a7db-584db5d76492', 21, 31, 'እርሱም፥ “እባክህ፥ በምድረ በዳ ከእኛ ጋር ኑረሃልና በእኛም ዘንድ አርጅተሃልና አትተወን፤'),
  ('1dbd62e8-82a4-5f73-a295-5340200a5dab', '936de3bf-6257-57fd-a317-f333a7dce57e', '6fe09823-ddcf-5bd4-a7db-584db5d76492', 22, 32, 'ከእኛም ጋር ብትሄድ እግዚአብሔር ከሚያደርግልን መልካም ነገር ሁሉ እኛ ለአንተ እናደርጋለን” አለው።'),
  ('290c2871-6d22-550d-aa9e-ab697d82e1ce', '936de3bf-6257-57fd-a317-f333a7dce57e', 'f1f80614-e079-5a2b-af8f-429a9002dd8f', 1, 33, 'ከእግዚአብሔርም ተራራ የሦስት ቀን መንገድ ያህል ተጓዙ፤ የእግዚአብሔርም የኪዳኑ ታቦት የሚያድሩበትን ቦታ ታገኝላቸው ዘንድ የሦስት ቀን መንገድ ትቀድማቸው ነበር።'),
  ('2e255fa1-246a-5ae5-a7b2-3b32dc423aa6', '936de3bf-6257-57fd-a317-f333a7dce57e', 'f1f80614-e079-5a2b-af8f-429a9002dd8f', 2, 34, 'ሙሴም ታቦቷ በተጓዘች ጊዜ፥ “አቤቱ፥ ተነሣ፤ ጠላቶችህ ይበተኑ፤ የሚጠሉህም ከፊትህ ይሽሹ” ይል ነበር።'),
  ('59185e80-97ae-5dac-ac82-5022f74cbf22', '936de3bf-6257-57fd-a317-f333a7dce57e', 'f1f80614-e079-5a2b-af8f-429a9002dd8f', 3, 35, 'ባረፈም ጊዜ፥ “አቤቱ፥ ወደ እስራኤል እልፍ አእላፋት ተመለስ” ይል ነበር።'),
  ('210105fe-3b38-53ff-a63e-433fdf4e4882', '936de3bf-6257-57fd-a317-f333a7dce57e', 'f1f80614-e079-5a2b-af8f-429a9002dd8f', 4, 36, 'ከሰፈራቸውም በተጓዙ ጊዜ የእግዚአብሔር ደመና ቀን ቀን በላያቸው ላይ ነበረ።'),
  ('05a2f7f6-cb94-5894-a47e-f84281fc052c', 'cd20585f-df15-5910-a99e-1fe0d75f4503', '4c3cab82-5481-538c-a970-bfb495f23602', 1, 1, 'ሕዝቡም በክፋት በእግዚአብሔር ፊት አጕረመረሙ፤ እግዚአብሔርም ሰምቶ ተቈጣ፤ እሳትም ከእግዚአብሔር ዘንድ በእነርሱ ላይ ነደደች፤ ከሰፈሩም አንዱን ወገን በላች።'),
  ('aca8b83a-2389-5f69-ae65-d249cdb9a262', 'cd20585f-df15-5910-a99e-1fe0d75f4503', '4c3cab82-5481-538c-a970-bfb495f23602', 2, 2, 'ሕዝቡም ወደ ሙሴ ጮኹ፤ ሙሴም ወደ እግዚአብሔር ጸለየ፤ እሳቲቱም ጠፋች።'),
  ('527b41ac-e46d-5ac5-a2c3-1c9c106b75db', 'cd20585f-df15-5910-a99e-1fe0d75f4503', '4c3cab82-5481-538c-a970-bfb495f23602', 3, 3, 'ከእግዚአብሔርም ዘንድ በእነርሱ ላይ እሳት ስለ ነደደች የዚያ ስፍራ ስም “መካነ ውዕየት” ተብሎ ተጠራ።'),
  ('3efc406f-a457-5b69-a515-739f92025485', 'cd20585f-df15-5910-a99e-1fe0d75f4503', 'e797c9ca-1ca4-50b7-acaf-fb04307414f2', 1, 4, 'ከእነርሱም ጋር የተቀላቀሉ ሕዝብ እጅግ ጐመጁ፤ የእስራኤልም ልጆች ተቀምጠው እንዲህ እያሉ አለቀሱ፥ “ሥጋ ማን ያበላናል?'),
  ('b361fea5-7e94-53ca-acd5-28c9903bd040', 'cd20585f-df15-5910-a99e-1fe0d75f4503', 'e797c9ca-1ca4-50b7-acaf-fb04307414f2', 2, 5, 'በግብፅ ያለ ዋጋ እንበላው የነበረውን ዓሣ፥ ዳቦውንም፥ በጢኹንም፥ ኩራቱንም፥ ቀዩንም ሽንኩርት፥ ነጩንም ሽንኩርት ቍንዶ በርበሬውንም እናስባለን።'),
  ('314f8b82-11a4-51ea-aa7d-e2941643c0c0', 'cd20585f-df15-5910-a99e-1fe0d75f4503', 'e797c9ca-1ca4-50b7-acaf-fb04307414f2', 3, 6, 'አሁን ግን ሰውነታችን ደረቀች፤ ዐይናችንም ከዚህ መና በቀር ምንም አታይም” አሉ።'),
  ('a3edde73-e5c2-5e15-ac9f-0d052c0d07ce', 'cd20585f-df15-5910-a99e-1fe0d75f4503', 'e797c9ca-1ca4-50b7-acaf-fb04307414f2', 4, 7, 'መናውም እንደ ድንብላል ዘር ነበረ፤ መልኩም እንደ በረድ ነጭ ነበር።'),
  ('14698e95-cfa9-5498-a5f6-e7c003705188', 'cd20585f-df15-5910-a99e-1fe0d75f4503', 'e797c9ca-1ca4-50b7-acaf-fb04307414f2', 5, 8, 'ሕዝቡም እየዞሩ ይለቅሙ ነበር፤ በወፍጮም ይፈጩት፥ ወይም በሙቀጫ ይወቅጡት፥ በምንቸትም ይቀቅሉት ነበር፤ እንጎቻም ያደርጉት ነበር፤ ጣዕሙም በዘይት እንደ ተለወሰ እንጎቻ ነበረ።'),
  ('37ee7037-1693-5541-a2e7-f78816c57b7d', 'cd20585f-df15-5910-a99e-1fe0d75f4503', 'e797c9ca-1ca4-50b7-acaf-fb04307414f2', 6, 9, 'ሌሊትም ጠል በሰፈሩ ላይ በወረደ ጊዜ መናው በላዩ ይወርድ ነበር።'),
  ('6c042e5d-35eb-5334-acff-acd0687295a7', 'cd20585f-df15-5910-a99e-1fe0d75f4503', 'e797c9ca-1ca4-50b7-acaf-fb04307414f2', 7, 10, 'ሙሴም እያንዳንዳቸው በየወገናቸው በድንኳኑ ደጃፍ፥ ሲያለቅሱ ሰማ፤ እግዚአብሔርም እጅግ ተቈጣ፤ ነገሩም በሙሴ ፊት ክፉ ሆነ።'),
  ('d903578d-ab52-5c2a-aedd-3f0ffa0b3c1d', 'cd20585f-df15-5910-a99e-1fe0d75f4503', 'e797c9ca-1ca4-50b7-acaf-fb04307414f2', 8, 11, 'ሙሴም እግዚአብሔርን አለው፥ “ለምን በአገልጋይህ ላይ ክፉ አደረግህ? ለምንስ በፊትህ ሞገስን አላገኘሁም? ለምንስ የዚህን ሁሉ ሕዝብ ሸክም በእኔ ላይ አደረግህ?'),
  ('aad3cd21-dfd5-5760-a0f9-58585a327835', 'cd20585f-df15-5910-a99e-1fe0d75f4503', 'e797c9ca-1ca4-50b7-acaf-fb04307414f2', 9, 12, 'አንተ ለአባቶቻቸው ወደ ማልህላቸው ምድር አደርሳቸው ዘንድ፦ ሞግዚት የሚጠባውን ልጅ እንድታቅፍ በብትህ እቀፋቸው የምትለኝ፥ በውኑ ይህን ሕዝብ ሁሉ እኔ ፀነስሁትን? ወይስ ወለድሁትን?'),
  ('9e1d703b-04ab-5bb6-abd4-5ffcbbe3a698', 'cd20585f-df15-5910-a99e-1fe0d75f4503', 'e797c9ca-1ca4-50b7-acaf-fb04307414f2', 10, 13, 'በፊቴ ያለቅሳሉና፦ የምንበላውን ሥጋ ስጠን ይላሉና ለዚህ ሕዝብ ሁሉ የምሰጠው ሥጋ ከየት አለኝ?'),
  ('91d5c9df-a39d-529f-aea2-56a7a2fba330', 'cd20585f-df15-5910-a99e-1fe0d75f4503', 'e797c9ca-1ca4-50b7-acaf-fb04307414f2', 11, 14, 'እጅግ ከብዶኛልና ይህን ሁሉ ሕዝብ ብቻዬን ልሸከም አልችልም።'),
  ('ba2b3182-6afb-559f-ad5b-18cbc648a30b', 'cd20585f-df15-5910-a99e-1fe0d75f4503', 'e797c9ca-1ca4-50b7-acaf-fb04307414f2', 12, 15, 'እንዲህስ ከምታደርግብኝ፥ በፊትህ ይቅርታን አግኝቼ እንደ ሆነ፥ በእኔ ላይ የሚሆነውን መከራ እንዳላይ፥ እባክህ፥ ፈጽሞ ግደለኝ።”'),
  ('1bd6399b-27ed-5671-a0fc-0de075c06ae2', 'cd20585f-df15-5910-a99e-1fe0d75f4503', '0a514183-9009-5a00-a58d-77356ee74727', 1, 16, 'እግዚአብሔርም ሙሴን አለው፥ “ከእስራኤል ሽማግሌዎች፥ ለሕዝቡ ሽማግሌዎችና ጸሐፍት ይሆኑ ዘንድ የምታውቃቸውን፥ ሰባ ሰዎች ሰብስብልኝ፤ ወደ ምስክሩም ድንኳን አምጣቸው፤ በዚያም ከአንተ ጋር አቁማቸው።'),
  ('6d3ea785-24ce-520b-a870-c6aad8236075', 'cd20585f-df15-5910-a99e-1fe0d75f4503', '0a514183-9009-5a00-a58d-77356ee74727', 2, 17, 'እኔም እወርዳለሁ፤ በዚያም አነጋግርሃለሁ፤ በአንተ ካለውም መንፈስ ወስጄ በእነርሱ ላይ አደርገዋለሁ፤ አንተም ብቻ እንዳትሸከም የሕዝቡን ሸክም ከአንተ ጋር ይሸከማሉ።'),
  ('dc7045e1-2859-59c3-ab95-256967ce7bf5', 'cd20585f-df15-5910-a99e-1fe0d75f4503', '0a514183-9009-5a00-a58d-77356ee74727', 3, 18, 'ሕዝቡንም በላቸው፦ ሥጋ ማን ያበላናል? በግብፅ ደኅና ነበረልን እያላችሁ በእግዚአብሔር ፊት አልቅሳችኋልና ለነገ ተቀደሱ፤ ሥጋንም ትበላላችሁ፤ እግዚአብሔርም ሥጋን ይሰጣችኋል፤ ትበሉማላችሁ።'),
  ('8d91efd6-9232-5db2-a7a4-fd3279e776cb', 'cd20585f-df15-5910-a99e-1fe0d75f4503', '0a514183-9009-5a00-a58d-77356ee74727', 4, 19, 'አንድ ቀን፥ ወይም ሁለት ቀን፥ ወይም አምስት ቀን፥ ወይም ዐሥር ቀን ወይም ሃያ ቀን አትበሉም፤'),
  ('72e15e04-ae7a-537f-a69a-f5356beb450d', 'cd20585f-df15-5910-a99e-1fe0d75f4503', '0a514183-9009-5a00-a58d-77356ee74727', 5, 20, 'ነገር ግን በመካከላችሁ ያለውን እግዚአብሔርን ንቃችኋልና፥ በፊቱም፦ ለምን ከግብፅ አወጣኸን? ብላችሁ አልቅሳችኋልና በአፍንጫችሁ እስኪወጣ መርዝም እስኪሆንባችሁ ድረስ ወር ሙሉ ትበሉታላችሁ።”'),
  ('f3b4aec7-00c3-5e39-a731-69d8e611df03', 'cd20585f-df15-5910-a99e-1fe0d75f4503', '0a514183-9009-5a00-a58d-77356ee74727', 6, 21, 'ሙሴም፥ “እኔ በመካከላቸው ያለሁ ሕዝብ ስድስት መቶ ሺህ እግረኛ ናቸው፤ አንተም፦ ሥጋን እሰጣቸዋለሁ፥ ወር ሙሉም ይበሉታል አልህ።'),
  ('c582b636-0790-55e5-a971-60b2e47793c3', 'cd20585f-df15-5910-a99e-1fe0d75f4503', '0a514183-9009-5a00-a58d-77356ee74727', 7, 22, 'የበሬና የበግ መንጋ ቢታረድ፥ የባሕር ዓሣ ሁሉ ቢሰበሰብ ይበቃቸዋልን?” አለ።'),
  ('e42b5648-d26e-5adf-a8e7-0ac131813cbf', 'cd20585f-df15-5910-a99e-1fe0d75f4503', '0a514183-9009-5a00-a58d-77356ee74727', 8, 23, 'እግዚአሔርም ሙሴን፥ “በውኑ የእግዚአብሔር እጅ አትችልምን? አሁን ቃሌ ይፈጸም ወይም አይፈጸም እንደ ሆነ እነሆ፥ አንተ ታያለህ” አለው።'),
  ('4870550e-02c5-5c60-a430-18a4edc85962', 'cd20585f-df15-5910-a99e-1fe0d75f4503', '0a514183-9009-5a00-a58d-77356ee74727', 9, 24, 'ሙሴም ወጣ፤ የእግዚአብሔርንም ቃሎች ለሕዝቡ ነገረ፤ ከሕዝቡ ሽማግሌዎችም ሰባውን ሰዎች ሰብስቦ በድንኳኑ ዙሪያ አቆማቸው።'),
  ('5a0a8cc4-e38f-58a6-a0ac-bbb6dc20ac98', 'cd20585f-df15-5910-a99e-1fe0d75f4503', '0a514183-9009-5a00-a58d-77356ee74727', 10, 25, 'እግዚአብሔርም በደመናው ወረደ፤ ተናገረውም፤ በእርሱም ላይ ከነበረው መንፈስ ወስዶ በሰባው ሽማግሌዎች ላይ አደረገ፤ መንፈሱም በላያቸው ባደረ ጊዜ ትንቢት ተናገሩ፤ ከዚያ በኋላ ግን አልተጨመረላቸውም።'),
  ('46091673-e846-5c1e-a8c6-c94687c04025', 'cd20585f-df15-5910-a99e-1fe0d75f4503', '0a514183-9009-5a00-a58d-77356ee74727', 11, 26, 'ከእነርሱም ሁለት ሰዎች በሰፈር ቀርተው ነበር፤ የአንዱም ስም ኤልዳድ የሁለተኛውም ሞዳድ ነበረ፤ መንፈስም ዐረፈባቸው፤ እነርሱም ከተጻፉት ጋር ነበሩ፤ ወደ ድንኳኑ ግን አልወጡም ነበር፤ በሰፈሩም ውስጥ ትንቢት ተናገሩ።'),
  ('74478b1a-fbbb-58ed-a62f-b6c7668cce1a', 'cd20585f-df15-5910-a99e-1fe0d75f4503', '0a514183-9009-5a00-a58d-77356ee74727', 12, 27, 'አንድ ጐልማሳ ሰው እየሮጠ መጥቶ፥ “ኤልዳድና ሞዳድ በሰፈር ትንቢት ይናገራሉ” ብሎ ለሙሴ ነገረው።'),
  ('840c7915-91b9-5e0d-ad76-71e6790d50ff', 'cd20585f-df15-5910-a99e-1fe0d75f4503', '0a514183-9009-5a00-a58d-77356ee74727', 13, 28, 'የሙሴ ምርጥ ባለሟል የነበረው የነዌ ልጅ ኢያሱ፥ “ጌታዬ ሙሴ ሆይ ፥ ከልክላቸው” አለው።'),
  ('ddc707a3-52bb-5699-a7d6-1c769022ae78', 'cd20585f-df15-5910-a99e-1fe0d75f4503', '0a514183-9009-5a00-a58d-77356ee74727', 14, 29, 'ሙሴም “የእግዚአብሔር ሕዝብ ሁሉ ነቢያት ቢሆኑ፥ እግዚአብሔርም በእነርሱ ላይ መንፈሱን ቢያሳድር አንተ ስለ እኔ ትቀናለህን?” አለው።'),
  ('c37b846e-6534-5509-afe0-a49072e58992', 'cd20585f-df15-5910-a99e-1fe0d75f4503', '0a514183-9009-5a00-a58d-77356ee74727', 15, 30, 'ሙሴም ከእስራኤል ሽማግሌዎች ጋር ወደ ሰፈር ተመለሰ።'),
  ('84435d8d-675a-5050-ae5f-a445039b60a2', 'cd20585f-df15-5910-a99e-1fe0d75f4503', 'eefec652-d432-58d2-a758-361c17eadca1', 1, 31, 'ነፋስም ከእግዚአብሔር ዘንድ ወጣ፤ ከባሕርም ድርጭቶችን አወጣ፤ የአንድ ቀንም መንገድ ያህል በዚህ፥ የአንድ ቀንም መንገድ ያህል በዚያ በሰፈሩ ላይ በተናቸው፤ በዚያም በሰፈሩ ዙሪያ ከፍታው ከምድር ወደ ላይ ሁለት ክንድ ነበረ።'),
  ('56481fa1-d01f-5780-a791-333631c53002', 'cd20585f-df15-5910-a99e-1fe0d75f4503', 'eefec652-d432-58d2-a758-361c17eadca1', 2, 32, 'በዚያም ቀን ሁሉ፥ በሌሊትም ሁሉ፥ በነጋውም ሁሉ ሕዝቡ ተነሥተው ድርጭትን ሰበሰቡ፤ ከሁሉ ጥቂት የሰበሰበ ዐሥር የቆሮስ መስፈሪያ ያህል ሰበሰበ፤ በሰፈሩም ዙሪያ ሁሉ አስጥተው አደረቁት።'),
  ('b66d0b19-2ab7-5693-ac59-666ef927096b', 'cd20585f-df15-5910-a99e-1fe0d75f4503', 'eefec652-d432-58d2-a758-361c17eadca1', 3, 33, 'ሥጋውም ገና በጥርሳቸው መካከል ሳለ ሳያኝኩትም፥ እግዚአብሔር ሕዝቡን እጅግ ታላቅ በሆነ መቅሠፍት አጠፋቸው።'),
  ('611a4f7e-fd27-5e11-aa8b-bb93fbf3daf4', 'cd20585f-df15-5910-a99e-1fe0d75f4503', 'eefec652-d432-58d2-a758-361c17eadca1', 4, 34, 'የጐመጁ ሕዝብ በዚያ ተቀብረዋልና የዚያ ስፍራ ስም “መቃብረ ፍትወት” ተብሎ ተጠራ።'),
  ('08ef7e4c-2e91-5cfa-a2e9-e7c2b15531c0', 'cd20585f-df15-5910-a99e-1fe0d75f4503', 'eefec652-d432-58d2-a758-361c17eadca1', 5, 35, 'ሕዝቡም ከመቃብረ ፍትወት ወደ አሴሮት ተጓዙ፤ በአሴሮትም ተቀመጡ።'),
  ('c48fbecb-0301-5af2-abe8-bb0b26f059b6', 'b2b21340-9d97-5b69-aa32-6efcb0818065', '62f0a4c0-1dc6-5ecf-ae53-60d64aec6235', 1, 1, 'ሙሴም ኢትዮጵያዊቱን ሴት አግብቶአልና ባገባት በኢትዮጵያዊቱ ሴት ምክንያት ማርያምና አሮን አሙት።'),
  ('2e89a286-fbd9-5eb7-a97b-3ffa17388309', 'b2b21340-9d97-5b69-aa32-6efcb0818065', '62f0a4c0-1dc6-5ecf-ae53-60d64aec6235', 2, 2, 'እነርሱም፥ “በውኑ እግዚአብሔር በሙሴ ብቻ ተናግሮአልን? በእኛስ ደግሞ የተናገረ አይደለምን?” አሉ፤ እግዚአብሔርም ሰማ።'),
  ('b420401a-fb46-5dae-a400-a72500f73ead', 'b2b21340-9d97-5b69-aa32-6efcb0818065', '62f0a4c0-1dc6-5ecf-ae53-60d64aec6235', 3, 3, 'ሙሴም በምድር ላይ ካሉት ሰዎች ሁሉ ይልቅ እጅግ የዋህ ሰው ነበረ።'),
  ('1aacbfa5-8918-5830-aa73-5075e6078759', 'b2b21340-9d97-5b69-aa32-6efcb0818065', '62f0a4c0-1dc6-5ecf-ae53-60d64aec6235', 4, 4, 'እግዚአብሔርም ወዲያው ሙሴንና አሮንን ማርያምንም፥ “ሦስታችሁ ወደ ምስክሩ ድንኳን ኑ ብሎ ተናገረ፤ ሦስቱም ወደ ምስክሩ ድንኳን ወጡ።'),
  ('5cb631bf-b753-57cc-ae9a-c7a2ecce96c5', 'b2b21340-9d97-5b69-aa32-6efcb0818065', '62f0a4c0-1dc6-5ecf-ae53-60d64aec6235', 5, 5, 'እግዚአብሔርም በደመና ዐምድ ወረደ፤ በምስክሩም ድንኳን ደጃፍ ቆመ፤ አሮንንና ማርያምንም ጠራቸው፤ ሁለቱም ወጡ።'),
  ('b4f27655-70a1-54d5-af4f-18b042c2fc12', 'b2b21340-9d97-5b69-aa32-6efcb0818065', '62f0a4c0-1dc6-5ecf-ae53-60d64aec6235', 6, 6, 'እርሱም፥ “ቃሌን ስሙ፤ በመካከላችሁ ለእግዚአብሔር ነቢይ የሆነ ቢኖር በራእይ እገለጥለታለሁ፤ ወይም በሕልም እናገረዋለሁ።'),
  ('abe79367-95b3-543f-a357-4d5d26cd8afc', 'b2b21340-9d97-5b69-aa32-6efcb0818065', '62f0a4c0-1dc6-5ecf-ae53-60d64aec6235', 7, 7, 'አገልጋዬ ሙሴ ግን እንዲህ አይደለም፤ እርሱ በቤቴ ሁሉ የታመነ ነው።'),
  ('9f6d5732-e479-5b2c-ad9a-c1964201146e', 'b2b21340-9d97-5b69-aa32-6efcb0818065', '62f0a4c0-1dc6-5ecf-ae53-60d64aec6235', 8, 8, 'እኔ አፍ ለአፍ በግልጥ እናገረዋለሁ፤ በስውርም አይደለም፤ የእግዚአብሔርንም ክብር ያያል፤ አገልጋዬ ሙሴን ማማትን ስለ ምን አልፈራችሁም?” አለ።'),
  ('4bd782bb-e098-546f-a22d-550988b5c3f8', 'b2b21340-9d97-5b69-aa32-6efcb0818065', '62f0a4c0-1dc6-5ecf-ae53-60d64aec6235', 9, 9, 'የእግዚአብሔርም ቍጣ በእነርሱ ላይ ወረደ፤ እርሱም ሄደ።'),
  ('c26be4b6-539c-514b-a81e-d75fd45b5e57', 'b2b21340-9d97-5b69-aa32-6efcb0818065', '62f0a4c0-1dc6-5ecf-ae53-60d64aec6235', 10, 10, 'ደመናውም ከድንኳኑ ተነሣ፤ እነሆም፥ ማርያም ለምጻም ሆነች፤ እንደ በረዶም ነጭ ሆነች፤ አሮንም ማርያምን ተመለከተ፤ እነሆም፥ ለምጻም ሆና ነበር።'),
  ('dd0ff3c3-629f-5f17-a4e4-930e7fa66aa2', 'b2b21340-9d97-5b69-aa32-6efcb0818065', '62f0a4c0-1dc6-5ecf-ae53-60d64aec6235', 11, 11, 'አሮንም ሙሴን፥ “ጌታዬ ሆይ፥ ስንፍና አድርገናልና፥ በድለንማልና እባክህ፥ ኀጢአት አታድርግብን።'),
  ('bd40b766-59a7-510f-a1d7-b60d8bce607d', 'b2b21340-9d97-5b69-aa32-6efcb0818065', '62f0a4c0-1dc6-5ecf-ae53-60d64aec6235', 12, 12, 'ከእናቱ ማኅፀን ሞቶ እንደ ተወለደ፥ ከተበላ ግማሽ ሥጋዋ ጋር ለሞት አትተዋት።”'),
  ('a6ee5418-2baa-53a9-aefc-059bacdc0473', 'b2b21340-9d97-5b69-aa32-6efcb0818065', '62f0a4c0-1dc6-5ecf-ae53-60d64aec6235', 13, 13, 'ሙሴም ወደ እግዚአብሔር እየጮኸ፥ “አቤቱ፥ እባክህ፥ አድናት” አለው።'),
  ('7f0ce7eb-1c31-5db9-ad71-8ca0cc675caa', 'b2b21340-9d97-5b69-aa32-6efcb0818065', '62f0a4c0-1dc6-5ecf-ae53-60d64aec6235', 14, 14, 'እግዚአብሔርም ሙሴን፥ “አባቷ ምራቁን በፊቷ ቢተፋባት ስንኳ ሰባት ቀን ታፍር ዘንድ ይገባት ነበር፤ ሰባት ቀን ከሰፈር ውጭ ተዘግታ ትቀመጥ፤ ከዚያም በኋላ ወደ ሰፈር ትመለስ” አለው።'),
  ('bc17117d-6e11-5984-afc8-f425b25a8931', 'b2b21340-9d97-5b69-aa32-6efcb0818065', '62f0a4c0-1dc6-5ecf-ae53-60d64aec6235', 15, 15, 'ማርያምም ከሰፈር ውጭ ሰባት ቀን ተለይታ ተቀመጠች፤ ማርያምም እስክትነጻ ድረስ ሕዝቡ አልተጓዙም።'),
  ('08d8bbab-690c-5030-a107-8fb0bcd03bd4', 'b2b21340-9d97-5b69-aa32-6efcb0818065', '62f0a4c0-1dc6-5ecf-ae53-60d64aec6235', 16, 16, 'ከዚያም በኋላ ሕዝቡ ከአሴሮት ተጓዙ፤ በፋራንም ምድረ በዳ ሰፈሩ።'),
  ('7f32f045-53ae-5949-afbe-e8a11418829f', 'd7a33630-d73d-501c-ad75-6de874579369', '3a9f3963-d8b2-58d1-af9a-4072fd6727d7', 1, 1, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('79ce042b-b5fd-5d5d-ad6a-7573c9faefb7', 'd7a33630-d73d-501c-ad75-6de874579369', '3a9f3963-d8b2-58d1-af9a-4072fd6727d7', 2, 2, '“ይገዙአት ዘንድ እኔ ለእስራኤል ልጆች የምሰጣትን የከነዓንን ምድር የሚሰልሉ ሰዎችን ላክ፤ ከአባቶች ቤት ከእያንዳንዱ ነገድ ሁሉ በመካከላቸው አለቃ የሆነ አንድ አንድ ሰው ትልካላችሁ።”'),
  ('60760eb6-68be-530f-a9d1-9ca305e026bb', 'd7a33630-d73d-501c-ad75-6de874579369', '3a9f3963-d8b2-58d1-af9a-4072fd6727d7', 3, 3, 'ሙሴም እንደ እግዚአብሔር ትእዛዝ ከፋራን ምድረ በዳ ላካቸው፤ እነርሱም ሁሉ የእስራኤል ልጆች አለቆች ነበሩ።'),
  ('942231b5-c3b2-5fc9-ae5b-1026e1b75a6c', 'd7a33630-d73d-501c-ad75-6de874579369', '3a9f3963-d8b2-58d1-af9a-4072fd6727d7', 4, 4, 'ስማቸውም ይህ ነበረ፤ ከሮቤል ነገድ የዝኩር ልጅ ሰሙኤል፤'),
  ('8ec99d54-ad4f-5f42-a173-a58e5335b5d8', 'd7a33630-d73d-501c-ad75-6de874579369', '3a9f3963-d8b2-58d1-af9a-4072fd6727d7', 5, 5, 'ከስምዖን ነገድ የሱሬ ልጅ ሰፈጥ ፤'),
  ('a0387b40-1b74-5e3e-afcd-bc0bdcc6ea38', 'd7a33630-d73d-501c-ad75-6de874579369', '3a9f3963-d8b2-58d1-af9a-4072fd6727d7', 6, 6, 'ከይሁዳ ነገድ የዮፎኒ ልጅ ካሌብ፤'),
  ('1214c5c6-fa48-5b8f-a5d6-f90aaffbac90', 'd7a33630-d73d-501c-ad75-6de874579369', '3a9f3963-d8b2-58d1-af9a-4072fd6727d7', 7, 7, 'ከይሳኮር ነገድ የዮሴፍ ልጅ ኢጋል፤'),
  ('cb1dbf36-6929-5471-afa8-5570df8f0503', 'd7a33630-d73d-501c-ad75-6de874579369', '3a9f3963-d8b2-58d1-af9a-4072fd6727d7', 8, 8, 'ከኤፍሬም ነገድ የነዌ ልጅ አውሴ፤'),
  ('ea7d87fa-856c-5a56-a2ff-f96c4b6a13cf', 'd7a33630-d73d-501c-ad75-6de874579369', '3a9f3963-d8b2-58d1-af9a-4072fd6727d7', 9, 9, 'ከብንያም ነገድ የራፋ ልጅ ፈልጢ፤'),
  ('39eaf3a8-6a8d-561a-a929-b8c9c30f5e75', 'd7a33630-d73d-501c-ad75-6de874579369', '3a9f3963-d8b2-58d1-af9a-4072fd6727d7', 10, 10, 'ከዛብሎን ነገድ የሶዲ ልጅ ጉዲኤል፤'),
  ('a4f364b2-806f-5609-a3a7-e32d1bdde6ad', 'd7a33630-d73d-501c-ad75-6de874579369', '3a9f3963-d8b2-58d1-af9a-4072fd6727d7', 11, 11, 'ከዮሴፍ ነገድ ከምናሴ ልጆች የሱሲ ልጅ ጋዲ፤'),
  ('74d9d985-966a-5a1d-a594-9825645273ff', 'd7a33630-d73d-501c-ad75-6de874579369', '3a9f3963-d8b2-58d1-af9a-4072fd6727d7', 12, 12, 'ከዳን ነገድ የገማሊ ልጅ ዓሚሄል፤'),
  ('9f710cb3-4467-51a6-afa5-555041b491ac', 'd7a33630-d73d-501c-ad75-6de874579369', '3a9f3963-d8b2-58d1-af9a-4072fd6727d7', 13, 13, 'ከአሴር ነገድ የሚካኤል ልጅ ሳቱር፤'),
  ('f7082161-b322-5645-ac49-ee47a0646d8f', 'd7a33630-d73d-501c-ad75-6de874579369', '3a9f3963-d8b2-58d1-af9a-4072fd6727d7', 14, 14, 'ከንፍታሌም ነገድ የያቢ ልጅ ናቢ፤'),
  ('2266a57a-0e13-5ddd-a459-20e4a4ea1bd3', 'd7a33630-d73d-501c-ad75-6de874579369', '3a9f3963-d8b2-58d1-af9a-4072fd6727d7', 15, 15, 'ከጋድ ነገድ የማኪ ልጅ ጉዲኤል።'),
  ('40409787-36ab-5f72-a690-b6dfeefd37ea', 'd7a33630-d73d-501c-ad75-6de874579369', '3a9f3963-d8b2-58d1-af9a-4072fd6727d7', 16, 16, 'ምድሪቱን ይሰልሉ ዘንድ ሙሴ የላካቸው ሰዎች ስሞች እነዚህ ናቸው። ሙሴም የነዌን ልጅ አውሴን ኢያሱ ብሎ ጠራው።'),
  ('b3ad683b-3dcb-5f8f-a056-f7deb51a3b3a', 'd7a33630-d73d-501c-ad75-6de874579369', '3a9f3963-d8b2-58d1-af9a-4072fd6727d7', 17, 17, 'ሙሴም የከነዓንን ምድር ይሰልሉ ዘንድ ላካቸው፤ አላቸውም፥ “ከዚህ ወደ ምድረ በዳ ሂዱ፥ ወደ ተራሮችም ውጡ።'),
  ('72872d2f-1cac-5113-aafa-c8965c6412ac', 'd7a33630-d73d-501c-ad75-6de874579369', '3a9f3963-d8b2-58d1-af9a-4072fd6727d7', 18, 18, 'ምድሪቱንም እንዴት እንደ ሆነች፥ በእርስዋም የሚኖሩ ሰዎች ብርቱዎች ወይም ደካሞች፥ ጥቂቶች ወይም ብዙዎች እንደ ሆኑ፥'),
  ('1b1e86d9-7168-5aa4-a61f-6346ee3c1dd1', 'd7a33630-d73d-501c-ad75-6de874579369', '3a9f3963-d8b2-58d1-af9a-4072fd6727d7', 19, 19, 'የሚኖሩባትም ምድር መልካም ወይም ክፉ፥ የሚኖሩባቸውም ከተሞች ቅጥር ያላቸው ወይም የሌላቸው እንደ ሆኑ፥'),
  ('43c346ef-b849-5997-a8dd-700c7d1db9e8', 'd7a33630-d73d-501c-ad75-6de874579369', '3a9f3963-d8b2-58d1-af9a-4072fd6727d7', 20, 20, 'ምድሪቱም ለም ወይም ጠፍ፥ ዛፍ ያለባት ወይም የሌለባት እንደ ሆነች አይታችሁ፥ ከምድሪቱ ፍሬ አምጡ፤” ወራቱም ወይኑ አስቀድሞ ፍሬ የሚያፈራበት ነበረ።'),
  ('75167b81-eb9e-53e9-a6c8-aa1c8121ecfd', 'd7a33630-d73d-501c-ad75-6de874579369', '3a9f3963-d8b2-58d1-af9a-4072fd6727d7', 21, 21, 'ወጡም፤ ምድሪቱንም ከጺን ምድረ በዳ በኤማት ዳር እስካለችው እስከ ረአብ ድረስ ሰለሉ።'),
  ('7105dcd5-50d8-5938-a361-7ddcfbc110ca', 'd7a33630-d73d-501c-ad75-6de874579369', '3a9f3963-d8b2-58d1-af9a-4072fd6727d7', 22, 22, 'ወደ ምድረ በዳም ወጡ፤ ወደ ኬብሮንም ደረሱ፤ በዚያም የዔናቅ ዘሮች አኪማን፥ ሴሲ፥ ተላሚ ነበሩ። ኬብሮንም በግብፅ ካለችው ከጣኔዎስ ከተማ በፊት ሰባት ዓመታት ተሠርታ ነበር።'),
  ('c0ed137e-7bd8-52e2-a9b5-5fe5b0057dad', 'd7a33630-d73d-501c-ad75-6de874579369', '3a9f3963-d8b2-58d1-af9a-4072fd6727d7', 23, 23, 'ወደ ወይን ዘለላ ሸለቆም መጡ፤ አዩኣትም፤ ከዚያም ከወይኑ አንድ ዘለላ የነበረበትን አረግ ቈረጡ፤ በመሎጊያም ተሸከሙት፤ ደግሞም ከሮማኑ ከበለሱም አመጡ።'),
  ('be4ef5ff-02bb-5f5d-afc1-2e30cc6aee36', 'd7a33630-d73d-501c-ad75-6de874579369', '3a9f3963-d8b2-58d1-af9a-4072fd6727d7', 24, 24, 'የእስራኤል ልጆች ከዚያ ስለ ቈረጡት ዘለላ የዚያን ስፍራ ስም የወይን ዘለላ ሸለቆ ብለው ጠሩት።'),
  ('3e91cb20-1ec1-5ad6-af4f-6c722e951170', 'd7a33630-d73d-501c-ad75-6de874579369', '1ffb1898-4ba5-5389-a494-a24b34ea6767', 1, 25, 'ምድሪቱንም ሰልለው ከአርባ ቀን በኋላ ከዚያ ተመለሱ።'),
  ('b379be8e-62dc-56ca-acb8-5b7c52edc7d4', 'd7a33630-d73d-501c-ad75-6de874579369', '1ffb1898-4ba5-5389-a494-a24b34ea6767', 2, 26, 'ገሥግሠውም በቃዴስ ፋራን ምድረ በዳ ወዳሉት ወደ ሙሴና ወደ አሮን፥ ወደ እስራኤልም ልጆች ማኅበር ሁሉ ደረሱ፤ ወሬውንም ለእነርሱና ለማኅበሩ ሁሉ ነገሩአቸው፤ የምድሪቱንም ፍሬ አሳዩአቸው።'),
  ('ecae6e9d-dda4-5b60-a6cc-7ca25563cfe9', 'd7a33630-d73d-501c-ad75-6de874579369', '1ffb1898-4ba5-5389-a494-a24b34ea6767', 3, 27, 'እንዲህም ብለው ነገሩት፥ “ወደ ላክኸን ምድር ደረስን፤ እርስዋም ወተትና ማር ታፈስሳለች፤ ፍሬዋም ይህ ነው።'),
  ('e2e836c6-f99b-55a6-a1de-82b33e86caf5', 'd7a33630-d73d-501c-ad75-6de874579369', '1ffb1898-4ba5-5389-a494-a24b34ea6767', 4, 28, 'ነገር ግን በምድሪቱ የሚኖሩ ሰዎች ኀያላን ናቸው፤ ከተሞቻቸውም የተመሸጉ፥ እጅግም የጸኑ ታላላቅ ናቸው።'),
  ('994b0f70-322e-5040-a3e2-cfa477e54eef', 'd7a33630-d73d-501c-ad75-6de874579369', '1ffb1898-4ba5-5389-a494-a24b34ea6767', 5, 29, 'ደግሞም በዚያ የዔናቅን ዘሮች አየን፤ በአዜብ በኩል ዐማሌቅ ተቀምጦአል፤ በተራሮችዋም ኬጤዎናዊውና ኤዌዎናዊውም፥ ኢያቡሴዎናዊው፥ አሞሬዎናዊውም ተቀምጠዋል፤ ከነዓናዊውም በባሕር ዳርና በዮርዳኖስ ወንዝ አጠገብ ተቀምጦአል።”'),
  ('37777561-a77e-5a1b-a41d-3d48eea66ac3', 'd7a33630-d73d-501c-ad75-6de874579369', '1ffb1898-4ba5-5389-a494-a24b34ea6767', 6, 30, 'ካሌብም ሕዝቡን በሙሴ ፊት ዝም አሰኘና፥ “አይደለም! ማሸነፍን እንችላለንና እንውጣ፤ እንውረሳት” አለ።'),
  ('ba274ac0-787a-5c64-a493-494e29926a1b', 'd7a33630-d73d-501c-ad75-6de874579369', '1ffb1898-4ba5-5389-a494-a24b34ea6767', 7, 31, 'ከእርሱ ጋር የወጡ ሰዎች ግን ፥ “በኀይል ከእኛ ይበረታሉና በዚህ ሕዝብ ላይ መውጣት አንችልም” አሉ።'),
  ('3c48f7fd-c35f-5624-a8dc-13b99e3a5e3e', 'd7a33630-d73d-501c-ad75-6de874579369', '1ffb1898-4ba5-5389-a494-a24b34ea6767', 8, 32, 'ስለ ሰለሉአትም ምድር ለእስራኤል ልጆች እያወሩ፥ “እኛ ዞረን የሰለልናት ምድር የሚኖሩባትን ሰዎች የምትበላ ምድር ናት፤ በእርስዋም ዘንድ ያየናቸው ሰዎች ሁሉ ረጃጅም ሰዎች ናቸው፤'),
  ('9043fdcd-45a5-5f3f-aa0c-f88b18001007', 'd7a33630-d73d-501c-ad75-6de874579369', '1ffb1898-4ba5-5389-a494-a24b34ea6767', 9, 33, 'በዚያም ግዙፋን የሆኑትን አየን፤ እኛም በእነርሱ ፊት እንደ አንበጣዎች ሆን፤ እንዲሁም በፊታቸው ነበርን፤” እያሉ የሰለሉአትን ምድር ለእስራኤል ልጆች አስፈሪ አደረጓት።'),
  ('04ed61bd-43f0-58ce-a431-3e257b006e51', '6c732036-acd1-50a1-a414-5888b2d783ba', 'cf5638ae-2a59-55a3-a089-e97176b9811a', 1, 1, 'ማኅበሩም ሁሉ ድምፃቸውን አንስተው ጮኹ፤ ሕዝቡም ሌሊቱን ሁሉ አለቀሱ።'),
  ('9b5013bf-d8ff-5c3f-a376-e93fd373eb9b', '6c732036-acd1-50a1-a414-5888b2d783ba', 'cf5638ae-2a59-55a3-a089-e97176b9811a', 2, 2, 'የእስራኤልም ልጆች ሁሉ በሙሴና በአሮን ላይ አጕረመረሙ፤ ማኅበሩም ሁሉ፥ “በዚህ ምድረ በዳ ከምንሞት በግብፅ ምድር ሳለን ብንሞት በተሻለን ነበር።'),
  ('4963d0ee-c0a9-5fb7-aa66-a799775283ff', '6c732036-acd1-50a1-a414-5888b2d783ba', 'cf5638ae-2a59-55a3-a089-e97176b9811a', 3, 3, 'እግዚአብሔርም በጦርነት እንሞት ዘንድ ወደዚች ምድር ለምን ያገባናል? ሴቶቻችንና ልጆቻችን ለንጥቂያ ይሆናሉ፤ አሁንም ወደ ግብፅ መመለስ አይሻለንምን?” አሉአቸው።'),
  ('822ee1d9-52df-58bc-a9c9-667f78d06f59', '6c732036-acd1-50a1-a414-5888b2d783ba', 'cf5638ae-2a59-55a3-a089-e97176b9811a', 4, 4, 'እርስ በርሳቸውም፥ “ኑ፥ አለቃ ሾመን ወደ ግብፅ እንመለስ” ተባባሉ።'),
  ('8fcc08c4-576d-51c7-ac80-856ae7996474', '6c732036-acd1-50a1-a414-5888b2d783ba', 'cf5638ae-2a59-55a3-a089-e97176b9811a', 5, 5, 'ሙሴና አሮንም በእስራኤል ልጆች ጉባኤ ፊት በግንባራቸው ወደቁ።'),
  ('8d916805-42e2-5116-aff3-5830cc5bc75a', '6c732036-acd1-50a1-a414-5888b2d783ba', 'cf5638ae-2a59-55a3-a089-e97176b9811a', 6, 6, 'ምድሪቱን ከሰለሉት ጋር የነበሩት የነዌ ልጅ ኢያሱና የዮፎኒ ልጅ ካሌብ ልብሳቸውን ቀደዱ፤'),
  ('01a737ce-8515-58e2-ae02-16a46c4a63bb', '6c732036-acd1-50a1-a414-5888b2d783ba', 'cf5638ae-2a59-55a3-a089-e97176b9811a', 7, 7, 'ለእስራኤልም ልጆች ማኅበር ሁሉ “የሰለልናት ምድር እጅግ በጣም መልካም ናት።'),
  ('4d688a52-6ada-52a9-a3bc-6ed268dc189a', '6c732036-acd1-50a1-a414-5888b2d783ba', 'cf5638ae-2a59-55a3-a089-e97176b9811a', 8, 8, 'እግዚአብሔርስ ከመረጠን ወተትና ማር ወደምታፈስሰው ወደዚች ምድር ያገባናል፤ እርስዋንም ይሰጠናል።'),
  ('4244dc65-fa90-58b4-abd1-51ffacc71ffd', '6c732036-acd1-50a1-a414-5888b2d783ba', 'cf5638ae-2a59-55a3-a089-e97176b9811a', 9, 9, 'ነገር ግን እናንተ በእግዚአብሔር ላይ አታምፁ፤ እኛ እናጠፋቸዋለንና የምድሪቱን ሰዎች አትፍሩ፤ ጊዜአቸው አልፎባቸዋል፤ እግዚአብሔርም ከእኛ ጋር ነው፤ አትፍሩአቸው” ብለው ተናገሩአቸው።'),
  ('6b1a8a80-f903-5e50-a8c5-70f2495dfd6c', '6c732036-acd1-50a1-a414-5888b2d783ba', 'cf5638ae-2a59-55a3-a089-e97176b9811a', 10, 10, 'ማኅበሩ ሁሉ ግን “በድንጋይ እንውገራቸው” አሉ። የእግዚአብሔርም ክብር ለእስራኤል ልጆች ሁሉ በምስክሩ ድንኳን ተገለጠ።'),
  ('8e5a4240-3529-5cd0-a2d2-b4485966ca3f', '6c732036-acd1-50a1-a414-5888b2d783ba', '61825db4-9753-5bae-a046-620163c243f5', 1, 11, 'እግዚአብሔርም ሙሴን፥ “እኒህ ሕዝብ እስከ መቼ ያስቈጡኛል? በፊታቸውስ ባደረግሁት ተአምራት ሁሉ እስከ መቼ አያምኑብኝም?'),
  ('2d3432fe-bad1-5aef-ac72-28c36a0ec496', '6c732036-acd1-50a1-a414-5888b2d783ba', '61825db4-9753-5bae-a046-620163c243f5', 2, 12, 'በሞት እቀጣቸዋለሁ፤ አጠፋቸዋለሁም፤ አንተንና የአባትህን ቤት ግን ለታላቅና ከዚህ ለሚበዛ ሕዝብ አደርግሃለሁ” አለው።'),
  ('8143299a-e7c8-5456-ab11-23b99d6f93cc', '6c732036-acd1-50a1-a414-5888b2d783ba', '61825db4-9753-5bae-a046-620163c243f5', 3, 13, 'ሙሴም እግዚአብሔርን አለው፥ “ግብፃውያን ይሰማሉ፤ እኒህን ሕዝብ ከእነርሱ በኀይልህ አውጥተኻቸዋልና፤'),
  ('64b94765-3ee4-5425-af2b-f4038b20ea59', '6c732036-acd1-50a1-a414-5888b2d783ba', '61825db4-9753-5bae-a046-620163c243f5', 4, 14, 'የዚያች ምድር ሰዎች፥ አንተ እግዚአብሔር በዚህ ሕዝብህ መካከል እንደ ሆንህ ሰምተዋል፤ አንተም፥ አቤቱ፥ ዐይን በዐይን እንደሚተያይ ተገልጠህላቸዋል። ደመናህም በላያቸው ቆመች። በቀንም በደመና ዐምድ ፥ በሌሊትም በእሳት ዐምድ በፊታቸው ትሄዳለህ።'),
  ('07d899c2-34fe-5b8d-a0ac-ed70f298271a', '6c732036-acd1-50a1-a414-5888b2d783ba', '61825db4-9753-5bae-a046-620163c243f5', 5, 15, 'እኒህን ሕዝብ እንደ አንድ ሰው ብትገድል ስምህን የሰሙ አሕዛብ፦'),
  ('b5e17a6e-b6b4-5497-a8f2-2a2afe6032b7', '6c732036-acd1-50a1-a414-5888b2d783ba', '61825db4-9753-5bae-a046-620163c243f5', 6, 16, 'እግዚአብሔር ‘እነዚህን ሕዝብ ወደ ማለላቸው ምድር ያገባቸው ዘንድ አልቻለምና በምድረ በዳ ገደላቸው’ ብለው ይናገራሉ።'),
  ('b749dded-c1bd-5a57-adca-e7f4d76977e7', '6c732036-acd1-50a1-a414-5888b2d783ba', '61825db4-9753-5bae-a046-620163c243f5', 7, 17, 'አሁንም አቤቱ፥ ኀይልህ ይገለጥ፤ እንዲህ ብለህ እንደ ተናገርህ፦'),
  ('043c2e61-fe19-55fd-abe1-1ab1aec7b2ea', '6c732036-acd1-50a1-a414-5888b2d783ba', '61825db4-9753-5bae-a046-620163c243f5', 8, 18, 'እግዚአብሔር መዓቱ የራቀ ምሕረቱ የበዛ ጻድቅ፥ አበሳን፥ መተላለፍንና ኀጢአትን ይቅር የሚል፥ ኀጢአተኞችንም ከቶ የማያነጻ፥ የአባቶችን ኀጢአት እስከ ሦስትና አራት ትውልድ ድረስ በልጆች ላይ የሚያመጣ ነው።'),
  ('a12e2aa9-af8e-517d-a0a0-62e34591db21', '6c732036-acd1-50a1-a414-5888b2d783ba', '61825db4-9753-5bae-a046-620163c243f5', 9, 19, 'እነዚህን ሕዝብ ከግብፅ ምድር ካወጣህ ጀምሮ እስከ ዛሬ ድረስ ይቅር እንዳልሃቸው፥ እንደ ምሕረትህ ብዛት የእነዚህን ሕዝብ ኀጢአት ይቅር በል።”'),
  ('4cb8ca36-8cb5-5746-aa59-72ca7b52f641', '6c732036-acd1-50a1-a414-5888b2d783ba', '61825db4-9753-5bae-a046-620163c243f5', 10, 20, 'እግዚአብሔርም ሙሴን አለው፥ “እንደ ቃልህ ይቅር አልሁ፤'),
  ('30008953-cd2a-5983-a4b9-4e7818cbec16', '6c732036-acd1-50a1-a414-5888b2d783ba', '61825db4-9753-5bae-a046-620163c243f5', 11, 21, 'ነገር ግን እኔ ሕያው ነኝ፤ ስሜም ሕያው ነው፤ በእውነት የእግዚአብሔር ክብር ምድርን ሁሉ ይሞላል።'),
  ('23aafc50-13c7-52b6-a3f5-b36910dd6d17', '6c732036-acd1-50a1-a414-5888b2d783ba', '61825db4-9753-5bae-a046-620163c243f5', 12, 22, 'በግብፅ ምድርና በምድረ በዳ ያደረግሁትን ተአምራቴንና ክብሬን ያዩ እነዚህ ሰዎች ሁሉ ዐሥር ጊዜ ስለ ተፈታተኑኝ፥ ቃሌንም ስላልሰሙ፥'),
  ('d68596c0-eee6-5626-a4b3-ed7cb6bf5e6c', '6c732036-acd1-50a1-a414-5888b2d783ba', '61825db4-9753-5bae-a046-620163c243f5', 13, 23, 'በእውነት ለአባቶቻቸው የማልሁላቸውን ምድር አያዩም፤ ከእኔ ጋር በዚህ ላሉ መልካምንና ክፉን ለይተው ለማያውቁ ልጆቻቸው፥ የሚያውቀው ለሌለ ለታናሹ ሁሉ ያችን ሀገር እሰጣታለሁ፤ ለጥፋት ያነሳሱኝ ሁሉ አያዩአትም።'),
  ('938fa080-1ef6-5823-a240-208900432d3a', '6c732036-acd1-50a1-a414-5888b2d783ba', '61825db4-9753-5bae-a046-620163c243f5', 14, 24, 'ወዳጄ ካሌብ ግን ሌላ መንፈስ በእርሱ ላይ ስለ ሆነና ስለ ተከተለኝ እርሱ ወደ ገባባት ምድር አገባዋለሁ፤ ዘሩም ይወርሳታል።'),
  ('739aa4cc-a5a7-5138-a857-4276d496f5c6', '6c732036-acd1-50a1-a414-5888b2d783ba', '61825db4-9753-5bae-a046-620163c243f5', 15, 25, 'ዐማሌቅና ከነዓናዊውም በሸለቆ ውስጥ ተቀምጠዋል፤ እናንተ ግን ነገ ተመልሳችሁ በኤርትራ ባሕር መንገድ ወደ ምድረ በዳ ሂዱ።”'),
  ('e5025565-3489-5d45-a960-8261a6fe1c53', '6c732036-acd1-50a1-a414-5888b2d783ba', '2d80aa50-9868-539e-af1a-804336bef2fa', 1, 26, 'እግዚአብሔርም ሙሴንና አሮንን እንዲህ ብሎ ተናገራቸው፦'),
  ('438ef9a9-a9c8-5142-a154-635c2ec16d4f', '6c732036-acd1-50a1-a414-5888b2d783ba', '2d80aa50-9868-539e-af1a-804336bef2fa', 2, 27, '“የሚያጕረመርሙብኝን እኒህን ክፉ ማኅበር እስከ መቼ እታገሣቸዋለሁ? ስለ እናንተ በእኔ ላይ የሚያጕረመርሙትን የእስራኤል ልጆች ማጕረምረምን ሰማሁ።'),
  ('bf451ee8-1de2-5583-aea9-93988a27dffe', '6c732036-acd1-50a1-a414-5888b2d783ba', '2d80aa50-9868-539e-af1a-804336bef2fa', 3, 28, 'እንዲህ በላቸው፦ እኔ ሕያው ነኝና በጆሮዬ እንደ ተናገራችሁት እንዲሁ በእውነት አደርግባችኋለሁ፥ ይላል እግዚአብሔር።'),
  ('33b59841-c3a2-5fe8-ab4f-4d5b77e6f719', '6c732036-acd1-50a1-a414-5888b2d783ba', '2d80aa50-9868-539e-af1a-804336bef2fa', 4, 29, 'በድኖቻችሁ በዚህ ምድረ በዳ ይወድቃሉ፤ የተቈጠራችሁ ሁሉ፥ እንደ ቍጥራችሁ ከሃያ ዓመት ጀምሮ ከዚያም በላይ የሆነ ሁሉ፥ እናንተ ያጕረመረማችሁብኝ፥'),
  ('83c6d2e8-e697-5620-a339-82229f177f79', '6c732036-acd1-50a1-a414-5888b2d783ba', '2d80aa50-9868-539e-af1a-804336bef2fa', 5, 30, 'ከዮፎኒ ልጅ ከካሌብና ከነዌ ልጅ ከኢያሱ በቀር በእርስዋ አስቀምጣችሁ ዘንድ እጄን ዘርግቼ ወደ ማልሁላችሁ ምድር በእውነት እናንተ አትገቡም።'),
  ('923c65a8-6f07-5ea4-ae99-07dbeeb70caa', '6c732036-acd1-50a1-a414-5888b2d783ba', '2d80aa50-9868-539e-af1a-804336bef2fa', 6, 31, 'ንጥቂያ ይሆናሉ ያላችኋቸውን ልጆቻችሁን እነርሱን አገባቸዋለሁ፤ እናንተም የናቃችኋትን ምድር ይወርሷታል።'),
  ('8d148f1e-e9ff-5a22-a020-6a30aa5fbe47', '6c732036-acd1-50a1-a414-5888b2d783ba', '2d80aa50-9868-539e-af1a-804336bef2fa', 7, 32, 'የእናንተ ግን በድኖቻችሁ በዚህ ምድረ በዳ ይወድቃሉ።'),
  ('09f947a5-2cf3-537e-a8bf-b1bf7a68810f', '6c732036-acd1-50a1-a414-5888b2d783ba', '2d80aa50-9868-539e-af1a-804336bef2fa', 8, 33, 'ልጆቻችሁም በምድረ በዳ አርባ ዓመት ይቅበዘበዛሉ፤ በድኖቻችሁም በምድረ በዳ እስኪጠፉ ድረስ ግልሙትናችሁን ይሸከማሉ።'),
  ('ccd6303f-8c1e-5c2f-af04-5b78ccbac960', '6c732036-acd1-50a1-a414-5888b2d783ba', '2d80aa50-9868-539e-af1a-804336bef2fa', 9, 34, 'ምድሪቱን እንደ ሰለሉባቸው እንደ እነዚያ አርባ ቀኖች ቍጥር ስለ ኀጢአታችሁ ሁሉ አርባው ቀን አርባ ዓመት፥ አንዱ ቀንም አንድ ዓመት ይሁንባችሁ፤ እንግዲህ የቍጣዬን መቅሠፍት ታውቃላችሁ።'),
  ('c8311df2-b40f-50ad-a082-e6d7f0c25ef1', '6c732036-acd1-50a1-a414-5888b2d783ba', '2d80aa50-9868-539e-af1a-804336bef2fa', 10, 35, 'እኔ እግዚአብሔር፦ በእኔ ላይ በተሰበሰበ በዚህ ክፉ ማኅበር ሁሉ ላይ እንዲህ አደርጋለሁ ብዬ ተናገርሁ፤ በዚህ ምድረ በዳ ያልቃሉ፤ በዚያም ይሞታሉ።”'),
  ('2a8bed1c-63f4-5d64-aa26-82f1ce5a1c30', '6c732036-acd1-50a1-a414-5888b2d783ba', '2d80aa50-9868-539e-af1a-804336bef2fa', 11, 36, 'ምድሪቱንም ሊሰልሉ ሙሴ ልኮአቸው የተመለሱት ሰዎች ስለ እርስዋ በማኅበሩ ሁሉ ፊት አጕረመረሙ።'),
  ('ad6f92bb-86f8-535f-a4fd-249b70a81503', '6c732036-acd1-50a1-a414-5888b2d783ba', '2d80aa50-9868-539e-af1a-804336bef2fa', 12, 37, 'ስለዚያችም ምድር ክፉን ነገር ተናገሩ፤ ስለዚያችም ምድር ክፉ የተናገሩ እነዚያ ሰዎች በእግዚአብሔር ፊት በመቅሠፍት ሞቱ፤ ምድሪቱ ግን መልካም ነበረች።'),
  ('22ba3af6-0e37-59e4-a27b-9743beb75b42', '6c732036-acd1-50a1-a414-5888b2d783ba', '2d80aa50-9868-539e-af1a-804336bef2fa', 13, 38, 'ነገር ግን ምድሪቱን ሊሰልሉ ከሄዱ ሰዎች የነዌ ልጅ ኢያሱና የዮፎኒ ልጅ ካሌብ በሕይወት ኖሩ።'),
  ('4c14e800-8ddb-56e9-a68d-5fe5cf154800', '6c732036-acd1-50a1-a414-5888b2d783ba', 'eb84f0e0-043c-534f-aab2-36558db45001', 1, 39, 'ሙሴም ይህን ነገር ለእስራኤል ልጆች ሁሉ ነገረ። ሕዝቡም እጅግ አዘኑ፤'),
  ('6588d7e8-e53b-5516-af13-afec738adbf5', '6c732036-acd1-50a1-a414-5888b2d783ba', 'eb84f0e0-043c-534f-aab2-36558db45001', 2, 40, 'በነጋውም ማልደው ተነሡ፤ ወደ ተራራውም ራስ ወጥተው፥ “እነሆ፥ እኛ ከዚህ አለን፤ በድለናልና እግዚአብሔር ወዳለው ስፍራ እንወጣለን” አሉ።'),
  ('21d8750a-6c0c-50ab-ad6d-68732e730aae', '6c732036-acd1-50a1-a414-5888b2d783ba', 'eb84f0e0-043c-534f-aab2-36558db45001', 3, 41, 'ሙሴም አለ፥ “የእግዚአብሔርን ትእዛዝ ለምን ትተላለፋላችሁ? ይህ ለእናንተ መልካም አይደለም።'),
  ('25886dbc-6476-5e48-a8ce-d046b48c7924', '6c732036-acd1-50a1-a414-5888b2d783ba', 'eb84f0e0-043c-534f-aab2-36558db45001', 4, 42, 'እግዚአብሔር ከእናንተ ጋር አይደለምና በጠላቶቻችሁ ፊት እንዳትወድቁ አትውጡ።'),
  ('8b22b0ab-6fb7-51e1-ade3-1da9587e1d8a', '6c732036-acd1-50a1-a414-5888b2d783ba', 'eb84f0e0-043c-534f-aab2-36558db45001', 5, 43, 'ዐማሌቃዊና ከነዓናዊ በፊታችሁ ናቸውና በሰይፍ ትወድቃላችሁ፤ እግዚአብሔርን ከመከተል ተመልሳችኋልና እግዚአብሔር ከእናንተ ጋር አይሆንም።”'),
  ('c955cf0a-eebd-5c1a-a56a-daddf9d72c96', '6c732036-acd1-50a1-a414-5888b2d783ba', 'eb84f0e0-043c-534f-aab2-36558db45001', 6, 44, 'እነርሱ ግን ተደፋፍረው ወደ ተራራው ራስ ወጡ፤ ነገር ግን የእግዚአብሔር ቃል ኪዳን ታቦትና ሙሴ ከሰፈሩ አልተንቀሳቀሱም።'),
  ('ee47cded-96d2-55a1-a8a7-cd2709a03f7b', '6c732036-acd1-50a1-a414-5888b2d783ba', 'eb84f0e0-043c-534f-aab2-36558db45001', 7, 45, 'በዚያም ተራራ ላይ የተቀመጡ ዐማሌቃዊና ከነዓናዊ ወረዱ፤ መትተዋቸውም እስከ ኤርማ ድረስ አሳደዱአቸው። ወደ ከተማም ተመለሱ።'),
  ('5093c023-24e4-5e5c-afe8-c4108968bc38', '85715fba-ee7d-51cb-a1a6-aece0f0b9815', 'aef6359a-9f48-5fa0-ae08-e9f97baa3f17', 1, 1, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('397deeac-ec19-542e-aea0-e2d4a4a1a892', '85715fba-ee7d-51cb-a1a6-aece0f0b9815', 'aef6359a-9f48-5fa0-ae08-e9f97baa3f17', 2, 2, '“ለእስራኤል ልጆች እንዲህ ብለህ ንገራቸው፦ ወደምሰጣችሁ ወደ መኖሪያችሁ ምድር በገባችሁ ጊዜ፥'),
  ('4f98fbc5-bdbb-5e59-a875-61a7e20ac9d4', '85715fba-ee7d-51cb-a1a6-aece0f0b9815', 'aef6359a-9f48-5fa0-ae08-e9f97baa3f17', 3, 3, 'በፈቃዳችሁም ቢሆን በበዓላችሁም ቢሆን ለእግዚአብሔር በጎ መዓዛ ይሆን ዘንድ ስእለቱን አብዝታችሁ በአመጣችሁ ጊዜ ከላም ወይም ከበግ የሚቃጠል መሥዋዕት ወይም መሥዋዕት የሚሆን የእሳት ቍርባን ለእግዚአብሔር አቅርቡ።'),
  ('5a2915ec-c91d-539c-ac50-74ffce5f6c0a', '85715fba-ee7d-51cb-a1a6-aece0f0b9815', 'aef6359a-9f48-5fa0-ae08-e9f97baa3f17', 4, 4, 'ቍርባኑን ለእግዚአብሔር የሚያቀርብ የኢፍ መስፈሪያ አራተኛ እጅ በሆነ ዘይት የተለወሰ የኢፍ መስፈሪያ ዐሥረኛ እጅ የሆነ የመልካም ዱቄት መሥዋዕት ያመጣል።'),
  ('c78a64f8-383c-55ec-ae0d-b2b31076376c', '85715fba-ee7d-51cb-a1a6-aece0f0b9815', 'aef6359a-9f48-5fa0-ae08-e9f97baa3f17', 5, 5, 'ለመጠጥ ቍርባንም የኢን መስፈሪያ የሆነ መልካም ዱቄት አራተኛ እጅ በሚቃጠለው መሥዋዕት ወይም በእህሉ ቍርባን ላይ ያደርጋል፤ ለእያንዳንዱ ጠቦት ለእግዚአብሔር በጎ መዓዛ ያለው መሥዋዕት ይሆን ዘንድ ይህን ያህል ያድርግ።'),
  ('0348b791-6dc1-567f-a0d2-87c477c4d174', '85715fba-ee7d-51cb-a1a6-aece0f0b9815', 'aef6359a-9f48-5fa0-ae08-e9f97baa3f17', 6, 6, 'ለአንዱም አውራ በግ የሚቃጠል ቍርባን ወይም መሥዋዕት ባደረጋችሁ ጊዜ የኢን መስፈሪያ ሢሶ በሆነ ዘይት የተለወሰ ከመስፈሪያው ከዐሥር እጅ ሁለት እጅ መልካም ዱቄት ለእህል ቍርባን ታዘጋጃላችሁ።'),
  ('bd96bcaa-19d3-5dfd-a4af-f6590e4db19f', '85715fba-ee7d-51cb-a1a6-aece0f0b9815', 'aef6359a-9f48-5fa0-ae08-e9f97baa3f17', 7, 7, 'ለመጠጥ ቍርባንም ለእግዚአብሔር በጎ መዓዛ እንዲሆን የኢን መስፈሪያ ሦስተኛ እጅ ወይን ታቀርባለህ።'),
  ('dd50e142-5b91-546c-a979-dc7f0e135c4b', '85715fba-ee7d-51cb-a1a6-aece0f0b9815', 'aef6359a-9f48-5fa0-ae08-e9f97baa3f17', 8, 8, 'ለሚቃጠልም መሥዋዕት፥ ወይም ለሌላ መሥዋዕት፥ ወይም ስእለትን ለመፈጸም፥ ወይም ለደኅንነት መሥዋዕት ከላም ወገን ለእግዚአብሔር ብታዘጋጅ፥'),
  ('e2c8faef-2501-57f2-a713-deda546977ba', '85715fba-ee7d-51cb-a1a6-aece0f0b9815', 'aef6359a-9f48-5fa0-ae08-e9f97baa3f17', 9, 9, 'በላሙ ላይ የኢን መስፈሪያ ግማሽ በሆነ ዘይት የተለወሰ ከመስፈሪያው ከዐሥር እጅ ሦስት እጅ መልካም ዱቄት ለእህል ቍርባን ታቀርባለህ።'),
  ('152d4931-71fd-55fd-a40f-0c8d66815615', '85715fba-ee7d-51cb-a1a6-aece0f0b9815', 'aef6359a-9f48-5fa0-ae08-e9f97baa3f17', 10, 10, 'ለእግዚአብሔር በጎ መዓዛ እንዲሆን በእሳት ለተደረገ ቍርባን፥ የኢን መስፈሪያ ግማሽ ወይን ለመጠጥ ቍርባን ታቀርባለህ።'),
  ('d40881b7-a73f-59c0-add5-f50e97c43c02', '85715fba-ee7d-51cb-a1a6-aece0f0b9815', 'aef6359a-9f48-5fa0-ae08-e9f97baa3f17', 11, 11, '“እንዲሁ ለእያንዳንዱ ወይፈን፥ ወይም ለእያንዳንዱ አውራ በግ፥ ወይም ለእያንዳንዱ ተባት የበግ ወይም የፍየል ጠቦት ይደረጋል።'),
  ('3780106b-5482-591b-a0dc-f11ea8e84b46', '85715fba-ee7d-51cb-a1a6-aece0f0b9815', 'aef6359a-9f48-5fa0-ae08-e9f97baa3f17', 12, 12, 'እንዳዘጋጃችሁት ቍጥር፥ እንዲሁ እንደ ቍጥራቸው ለእያንዳንዱ ታደርጋላችሁ።'),
  ('bec79f91-a10b-5c02-a448-2fed14524d75', '85715fba-ee7d-51cb-a1a6-aece0f0b9815', 'aef6359a-9f48-5fa0-ae08-e9f97baa3f17', 13, 13, 'የሀገር ልጅ ሁሉ ለእግዚአብሔር በጎ መዓዛ እንዲሆን ቍርባን ባቀረበ ጊዜ እንዲሁ ያደርጋል።'),
  ('920ed89b-b3a4-5a82-a5df-73ce0b3e8f49', '85715fba-ee7d-51cb-a1a6-aece0f0b9815', 'aef6359a-9f48-5fa0-ae08-e9f97baa3f17', 14, 14, 'መጻተኛም ከእናንተ ጋር ቢቀመጥ፥ ወይም በትውልዳችሁ መካከል ማንም ሰው ቢኖር፥ ለእግዚአብሔር በጎ መዓዛ እንዲሆን ቍርባን በእሳት ቢያቀርብ እናንተ የምታደርጉትን እርሱ እንዲሁ ያደርጋል።'),
  ('3b1b4755-b64e-58d3-a2e6-a05beed9e84f', '85715fba-ee7d-51cb-a1a6-aece0f0b9815', 'aef6359a-9f48-5fa0-ae08-e9f97baa3f17', 15, 15, 'ለእናንተ፥ በእናንተም መካከል ለሚኖሩ መጻተኞች አንድ ሥርዐት ይሆናል፤ ለልጅ ልጃችሁም የዘለዓለም ሥርዐት ይሆናል፤ እናንተ እንደ ሆናችሁ እንዲሁ በእግዚአብሔር ፊት መጻተኛ ይሆናል።'),
  ('0bf1b29a-cc1b-54a2-a2ab-a620ab4cbe83', '85715fba-ee7d-51cb-a1a6-aece0f0b9815', 'aef6359a-9f48-5fa0-ae08-e9f97baa3f17', 16, 16, 'ለእናንተና ከእናንተ ጋር ለሚኖር መጻተኛ አንድ ሕግና አንድ ፍርድ ይሆናል።”'),
  ('1f137b34-3af3-5237-a418-0c635b7fee8d', '85715fba-ee7d-51cb-a1a6-aece0f0b9815', 'aef6359a-9f48-5fa0-ae08-e9f97baa3f17', 17, 17, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ፤ ተናገረው፦'),
  ('5415ca4e-aa13-56dd-a017-c9b086fc3f1b', '85715fba-ee7d-51cb-a1a6-aece0f0b9815', 'aef6359a-9f48-5fa0-ae08-e9f97baa3f17', 18, 18, '“ለእስራኤል ልጆች እንዲህ ብለህ ንገራቸው፤'),
  ('119bb083-1369-5050-a9c8-48ed233293eb', '85715fba-ee7d-51cb-a1a6-aece0f0b9815', 'aef6359a-9f48-5fa0-ae08-e9f97baa3f17', 19, 19, 'ወደማመጣችሁ ምድር በገባችሁ ጊዜ፥ እናንተ የምድሪቱን እንጀራ በበላችሁ ጊዜ ለእግዚአብሔር የተለየ ቍርባን ታደርጋላችሁ።'),
  ('0daf63f9-e3d6-5655-a61c-d2af3b4304a6', '85715fba-ee7d-51cb-a1a6-aece0f0b9815', 'aef6359a-9f48-5fa0-ae08-e9f97baa3f17', 20, 20, 'መጀመሪያ ከምታደርጉት ሊጥ አንድ እንጎቻ ለይታችሁ ቍርባን ታቀርባላችሁ፤ ከአውድማውም እንደምትለዩት ቍርባን እንዲሁ ትለያላችሁ።'),
  ('76abd831-1009-5dfc-aa29-7be551836186', '85715fba-ee7d-51cb-a1a6-aece0f0b9815', 'aef6359a-9f48-5fa0-ae08-e9f97baa3f17', 21, 21, 'መጀመሪያም ከምታደርጉት ሊጥ የተለየ ቍርባን እስከ ልጅ ልጃችሁ ለእግዚአብሔር ትሰጣላችሁ።'),
  ('271822ed-bffb-5b95-aba0-793698bcc2a6', '85715fba-ee7d-51cb-a1a6-aece0f0b9815', '76c0be3b-07ee-5975-a561-696723bb79d1', 1, 22, '“ብትበድሉም፥ እግዚአብሔር ለሙሴ ያዘዛቸውን እነዚህን ትእዛዛት ሁሉ ባታደርጉ፥'),
  ('f3cca455-d51e-5e9a-a069-c6628f878f0e', '85715fba-ee7d-51cb-a1a6-aece0f0b9815', '76c0be3b-07ee-5975-a561-696723bb79d1', 2, 23, 'እግዚአብሔር ካዘዘበት ከፊተኛው ቀን ጀምሮ ወደ ፊትም እስከ ልጅ ልጃችሁ እግዚአብሔር በሙሴ እጅ እንደ አዘዛችሁ ባታደርጉ፥'),
  ('f03b5fac-d5eb-556c-a92b-834b2cacee59', '85715fba-ee7d-51cb-a1a6-aece0f0b9815', '76c0be3b-07ee-5975-a561-696723bb79d1', 3, 24, 'በማኅበሩም ፊት ያልታወቀ ኀጢአት ቢኖር፥ ማኅበሩ ሁሉ ለሚቃጠል መሥዋዕትና ለእግዚአብሔር በጎ መዓዛ እንዲሆን ከመንጋዎች አንድ ንጹሕ ወይፈን ያቀርባሉ። የእህሉ ቍርባንና የመጠጡ ቍርባንም እንደ ሕጉ ነው፤ ለኀጢአትም መሥዋዕት አንድ አውራ ፍየል ያቀርባሉ።'),
  ('cdb5571e-c6e5-56d4-af6f-20bb73e58b11', '85715fba-ee7d-51cb-a1a6-aece0f0b9815', '76c0be3b-07ee-5975-a561-696723bb79d1', 4, 25, 'ካህኑም ለእስራኤል ልጆች ማኅበር ሁሉ ያስተሰርይላቸዋል፤ ባለማወቅ ነበርና ይሰረይላቸዋል፤ እነርሱም ስለ ኀጢአታቸውና ስላለማወቃቸው ቍርባናቸውንና መሥዋዕታቸውን ለእግዚአብሔር ያቀርባሉ።'),
  ('dcf93386-93d5-50fb-aca6-e2dd4ff0174d', '85715fba-ee7d-51cb-a1a6-aece0f0b9815', '76c0be3b-07ee-5975-a561-696723bb79d1', 5, 26, 'በሕዝቡም ሁሉ ዘንድ ያለ ዕውቀት ተደርጎአልና ለእስራኤል ልጆች ማኅበር ሁሉ ወደ እናንተም ለሚመጣ መጻተኛ ስርየት ይደረግላቸዋል።'),
  ('003cd38f-8a85-5481-aebc-60285e7bf008', '85715fba-ee7d-51cb-a1a6-aece0f0b9815', '76c0be3b-07ee-5975-a561-696723bb79d1', 6, 27, '“አንድ ሰው ሳያውቅ ኀጢአት ቢሠራ፥ ስለ ኀጢአት አንዲት የአንድ ዓመት እንስት ፍየል ያቀርባል።'),
  ('0d84c58f-4abd-5cdd-a6f0-5a0fc4198c09', '85715fba-ee7d-51cb-a1a6-aece0f0b9815', '76c0be3b-07ee-5975-a561-696723bb79d1', 7, 28, 'ካህኑም ባለማወቅ ስለ በደለው ያስተሰርያል፤ ባለማወቅም በእግዚአብሔር ፊት ኀጢአት ስለ ሠራው ሰው ያስተሰርይለታል።'),
  ('8836a4fa-a765-59dd-a4d9-ec0be5bd385a', '85715fba-ee7d-51cb-a1a6-aece0f0b9815', '76c0be3b-07ee-5975-a561-696723bb79d1', 8, 29, 'ትውልዱ በእስራኤል ልጆች መካከል ቢሆን፥ ወይም በመካከላቸው የሚኖር መጻተኛ ቢሆን፥ ሳያውቅ ኀጢአትን ለሚሠራ ሁሉ ሕጉ አንድ ይሆንለታል።'),
  ('52e0e0f6-e443-5807-a75b-89d94620fa2c', '85715fba-ee7d-51cb-a1a6-aece0f0b9815', '76c0be3b-07ee-5975-a561-696723bb79d1', 9, 30, 'የሀገር ልጅ ቢሆንም ወይም መጻተኛ ቢሆን፥ በእጁ ትዕቢትን የሚያደርግ ሰው እግዚአብሔርን ሰድቦአል፤ ያም ሰው ከሕዝቡ መካከል ተለይቶ ይጠፋል።'),
  ('d819fec6-9dc6-5974-a569-e64915577d44', '85715fba-ee7d-51cb-a1a6-aece0f0b9815', '76c0be3b-07ee-5975-a561-696723bb79d1', 10, 31, 'የእግዚአብሔርን ቃል ስለናቀ፥ ትእዛዙንም ስለ ሰበረ፥ ያ ሰው ፈጽሞ ይጥፋ፤ ኀጢአቱ በራሱ ላይ ነው።”'),
  ('34d94212-780d-5c29-a708-8340719b2c8f', '85715fba-ee7d-51cb-a1a6-aece0f0b9815', '583e7a52-c871-5d40-a4c8-4728242952d5', 1, 32, 'የእስራኤልም ልጆች በምድረ በዳ ነበሩ፤ አንድ ሰውም በሰንበት ቀን ዕንጨት ሲለቅም አገኙ።'),
  ('8da21399-55fe-5cf9-a0d5-9e4614feda53', '85715fba-ee7d-51cb-a1a6-aece0f0b9815', '583e7a52-c871-5d40-a4c8-4728242952d5', 2, 33, 'በሰንበት ቀን ዕንጨት ሲለቅም ያገኙትም ሰዎች ወደ ሙሴና ወደ አሮን፥ ወደ እስራኤልም ልጆች ማኅበር ሁሉ አመጡት።'),
  ('91b85e54-d429-59db-a5c0-7ddcf1647b60', '85715fba-ee7d-51cb-a1a6-aece0f0b9815', '583e7a52-c871-5d40-a4c8-4728242952d5', 3, 34, 'እንዴት እንደሚያደርጉት አልፈረዱምና በግዞት ቤት አዋሉት።'),
  ('8fe336a2-301c-5660-ac11-41ce1e952d1a', '85715fba-ee7d-51cb-a1a6-aece0f0b9815', '583e7a52-c871-5d40-a4c8-4728242952d5', 4, 35, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ነገረው፥ “ሰውዬው ይገደል፤ ማኅበሩም ሁሉ በድንጋይ ይውገሩት” አለው።'),
  ('a1c45bde-6524-5df7-abec-8b876480793c', '85715fba-ee7d-51cb-a1a6-aece0f0b9815', '583e7a52-c871-5d40-a4c8-4728242952d5', 5, 36, 'ማኅበሩም ሁሉ ከሰፈሩ ወደ ውጭ አወጡት፤ እግዚአብሔርም ሙሴን እንዳዘዘው በድንጋይ ወገሩት።'),
  ('b0d67fd6-e0fd-52fb-a176-f1a87718c20b', '85715fba-ee7d-51cb-a1a6-aece0f0b9815', '9e66eeba-0105-5de2-aa36-33804e5f0576', 1, 37, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('4dc66d5a-d020-5f0f-a6be-b81133c30e55', '85715fba-ee7d-51cb-a1a6-aece0f0b9815', '9e66eeba-0105-5de2-aa36-33804e5f0576', 2, 38, '“ለእስራኤል ልጆች እንዲህ በላቸው፦ እነርሱም በትውልዳቸው ሁሉ በልብሳቸው ጫፍ ዘርፍ ያደርጉ ዘንድ፥ በዘርፉም ሁሉ ላይ ሰማያዊ ፈትል ያደርጉ ዘንድ እዘዛቸው።'),
  ('0a27b3c0-b887-5572-af3e-8712b54d7bfa', '85715fba-ee7d-51cb-a1a6-aece0f0b9815', '9e66eeba-0105-5de2-aa36-33804e5f0576', 3, 39, 'እርሱም በዘርፉ ይሁንላችሁ፤ ትመለከቱታላችሁም፤ የእግዚአብሔርንም ትእዛዛት ታስባላችሁ፤ ታደርጉአቸውማላችሁ፤ እነርሱን በመከተል ያመነዘራችሁባትን የሕሊናችሁንና የዐይኖቻችሁን ፈቃድ አትከተሉ።'),
  ('ad19183d-3e62-5261-a4fd-c0f9d9e875a8', '85715fba-ee7d-51cb-a1a6-aece0f0b9815', '9e66eeba-0105-5de2-aa36-33804e5f0576', 4, 40, 'ትእዛዙን ታስቡና ታደርጉ ዘንድ፥ ለአምላካችሁም ቅዱሳን ትሆኑ ዘንድ፤'),
  ('ffd55b8b-1c9d-583e-acd6-42f4b04619ef', '85715fba-ee7d-51cb-a1a6-aece0f0b9815', '9e66eeba-0105-5de2-aa36-33804e5f0576', 5, 41, 'እኔ እግዚአብሔር አምላካችሁ ነኝ፤ አምላክ እሆናችሁ ዘንድ ከግብፅ ምድር ያወጣኋችሁ እኔ እግዚአብሔር አምላካችሁ ነኝ።”'),
  ('78dda4ce-edb3-5480-ae6c-b651604c61e4', '5c5422ac-2a87-5c61-a196-824f933f73a4', '4ec2ebd9-1893-5fbe-a8a2-85d15f0be9ca', 1, 1, 'የሌዊም ልጅ የቀዓት ልጅ የይስዓር ልጅ ቆሬ ከኤልያብ ልጆች ከዳታንና ከአቤሮን፥ ከሮቤልም ልጅ ከፋሌት ልጅ ከአውናን ጋር ተናገረ።'),
  ('194a52d5-53d1-5d4c-a543-90f9d97ac07f', '5c5422ac-2a87-5c61-a196-824f933f73a4', '4ec2ebd9-1893-5fbe-a8a2-85d15f0be9ca', 2, 2, 'በሙሴም ላይ ተነሡ፤ ከእስራኤልም ልጆች በምክር የተመረጡ፥ ዝናቸውም የተሰማ ሁለት መቶ አምሳ የማኅበሩ አለቆች ከእነርሱ ጋር ነበሩ።'),
  ('8b27989c-7e28-5c25-a49e-c2129fdf334e', '5c5422ac-2a87-5c61-a196-824f933f73a4', '4ec2ebd9-1893-5fbe-a8a2-85d15f0be9ca', 3, 3, 'በሙሴና በአሮን ላይ ተነሡ፤ “ለእናንተ ይበቃችኋል፤ ማኅበሩ ሁሉ እያንዳንዳቸው ቅዱሳን ናቸውና፥ እግዚአብሔርም በመካከላቸው ነውና፤ በእግዚአብሔርስ ጉባኤ ላይ ለምን ትታበያላችሁ?” አሉአቸው።'),
  ('44bcbf9b-c6d8-5f03-aa15-c051555a8f19', '5c5422ac-2a87-5c61-a196-824f933f73a4', '4ec2ebd9-1893-5fbe-a8a2-85d15f0be9ca', 4, 4, 'ሙሴም በሰማ ጊዜ በግንባሩ ወደቀ።'),
  ('21e746fe-8f70-555a-afbd-1a4e8526a346', '5c5422ac-2a87-5c61-a196-824f933f73a4', '4ec2ebd9-1893-5fbe-a8a2-85d15f0be9ca', 5, 5, 'ለቆሬም ለማኅበሩም ሁሉ እንዲህ አላቸው፥ “ነገ እግዚአብሔር የእርሱ የሚሆኑትን፥ ቅዱሳንም የሆኑትን ያያል፥ ያውቃልም፤ የመረጣቸውንም ሰዎች ወደ እርሱ ያቀርባቸዋል።'),
  ('0f3f7b9c-e959-5970-a71c-ab618fe6d2c1', '5c5422ac-2a87-5c61-a196-824f933f73a4', '4ec2ebd9-1893-5fbe-a8a2-85d15f0be9ca', 6, 6, 'እንዲሁ አድርጉ፤ ቆሬና ማኅበሩ ሁሉ፥ ጥናዎቹን ውሰዱ፤'),
  ('c2b00f15-bfd3-5f69-aec0-a5eef0cc8f49', '5c5422ac-2a87-5c61-a196-824f933f73a4', '4ec2ebd9-1893-5fbe-a8a2-85d15f0be9ca', 7, 7, 'ነገም በእግዚአብሔር ፊት እሳት አድርጉባቸው፤ ዕጣንም ጨምሩባቸው፤ እግዚአብሔርም የሚመርጠው ይህ ሰው ለሌዊ ልጆች ቅዱስ ይሁንላቸው።”'),
  ('8e4a8d67-b1b8-5a1b-a4ab-c14d7b385db0', '5c5422ac-2a87-5c61-a196-824f933f73a4', '4ec2ebd9-1893-5fbe-a8a2-85d15f0be9ca', 8, 8, 'ሙሴም ቆሬን አለው፥ “እናንተ የሌዊ ልጆች፥ ስሙኝ፤'),
  ('3a482ed2-d4e2-56f0-a571-04e4054f190c', '5c5422ac-2a87-5c61-a196-824f933f73a4', '4ec2ebd9-1893-5fbe-a8a2-85d15f0be9ca', 9, 9, 'የእስራኤል አምላክ ከእስራኤል ማኅበር ለይቶ የመረጣችሁን፥ የእግዚአብሔርን ድንኳን አገልግሎት ትሠሩ ዘንድ፥ እንድታገለግሉአቸውም በማኅበሩ ፊት ትቆሙ ዘንድ ወደ እርሱ ያቀረባችሁን ታሳንሱታላችሁን?'),
  ('8558ba49-a5fc-59f0-a379-9803655b788a', '5c5422ac-2a87-5c61-a196-824f933f73a4', '4ec2ebd9-1893-5fbe-a8a2-85d15f0be9ca', 10, 10, 'አንተን ከአንተም ጋር የሌዊን ልጆች ወንድሞችህን ሁሉ ወደ እርሱ አቅርቦአል፤ ካህናትም ትሆኑ ዘንድ ትፈልጋላችሁን?'),
  ('a1257b6d-ab09-5f5f-a0ac-fd86ef32749a', '5c5422ac-2a87-5c61-a196-824f933f73a4', '4ec2ebd9-1893-5fbe-a8a2-85d15f0be9ca', 11, 11, 'ስለዚህም አንተና ማኅበርህ ሁሉ በእግዚአብሔር ላይ ተሰብስባችኋል፤ በእርሱም ላይ ታጕረመርሙ ዘንድ አሮን ማንነው?”'),
  ('37f40447-c3e6-5535-ab32-4af8b2f2c84e', '5c5422ac-2a87-5c61-a196-824f933f73a4', '4ec2ebd9-1893-5fbe-a8a2-85d15f0be9ca', 12, 12, 'ሙሴም የኤልያብን ልጆች ዳታንንና አቤሮንን እንዲጠሩአቸው ላከ፤ እነርሱም፥ “አንመጣም፤'),
  ('54a62c78-21cf-57e3-aa2b-6cc51e7b3fa9', '5c5422ac-2a87-5c61-a196-824f933f73a4', '4ec2ebd9-1893-5fbe-a8a2-85d15f0be9ca', 13, 13, 'በምድረ በዳ ትገድለን ዘንድ፥ በእኛም ላይ አለቃችን ትሆን ዘንድ ወተትና ማር ከምታፈስሰው ምድር ያወጣኸን አነሰህን?'),
  ('4cae8738-b7db-5143-a6f5-775df660effa', '5c5422ac-2a87-5c61-a196-824f933f73a4', '4ec2ebd9-1893-5fbe-a8a2-85d15f0be9ca', 14, 14, 'አንተ አለቃ ነህን? ደግሞስ ወተትና ማር ወደምታፈስስ ምድር አገባኸንን? እርሻንና የወይን ቦታንስ አወረስኸንን? የእነዚህንስ ሰዎች ዐይኖቻቸውን ታወጣለህን? አንመጣም” አሉ።'),
  ('fead0dce-ee68-5d32-aebd-c6ec711cdd0f', '5c5422ac-2a87-5c61-a196-824f933f73a4', '4ec2ebd9-1893-5fbe-a8a2-85d15f0be9ca', 15, 15, 'ሙሴም እጅግ አዘነ፤ እግዚአብሔርንም አለው፥ “ወደ መሥዋዕታቸው አትመልከት፤ እኔ ከእነርሱ አንዳችም ተመኝቼ አልወሰድሁም፤ ከእነርሱም አንድ ሰው አልበደልሁም።”'),
  ('490b8840-3a4f-53ac-a87d-19d5c6f1f76a', '5c5422ac-2a87-5c61-a196-824f933f73a4', '4ec2ebd9-1893-5fbe-a8a2-85d15f0be9ca', 16, 16, 'ሙሴም ቆሬን አለው፥ “ማኅበርህን ለይ፤ ነገ አንተ፥ ማኅበርህም ሁሉ፥ አሮንም በእግዚአብሔር ፊት ዝግጁዎች ሁኑ።'),
  ('ce8bdd0c-b0d8-52e2-ac3c-66a4ef6af3e7', '5c5422ac-2a87-5c61-a196-824f933f73a4', '4ec2ebd9-1893-5fbe-a8a2-85d15f0be9ca', 17, 17, 'ሁላችሁም ጥናዎቻችሁን ውሰዱ፤ ዕጣንም አድርጉባቸው፤ እያንዳንዳችሁም ሁለት መቶ አምሳ ጥናዎቻችሁን ወደ እግዚአብሔር ፊት አምጡ፤ አንተ ደግሞ አሮንም ጥናዎቻችሁን አምጡ” አለው።'),
  ('326f6a74-c6d9-5bb9-a2ff-b7bcf746a94f', '5c5422ac-2a87-5c61-a196-824f933f73a4', '4ec2ebd9-1893-5fbe-a8a2-85d15f0be9ca', 18, 18, 'እያንዳንዱም ጥናውን ወሰደ፤ እሳትም አደረገበት፤ ዕጣንም ጨመረበት፤ ሙሴና አሮንም በምስክሩ ድንኳን ደጃፍ ቆሙ።'),
  ('ea3b77ae-1275-5dc4-a500-29a67e35763c', '5c5422ac-2a87-5c61-a196-824f933f73a4', '4ec2ebd9-1893-5fbe-a8a2-85d15f0be9ca', 19, 19, 'ቆሬም ማኅበሩን ሁሉ ወደ ምስክሩ ደጃፍ በእነርሱ ላይ ሰበሰበ፤ የእግዚአብሔርም ክብር ለማኅበሩ ሁሉ ተገለጠ።'),
  ('f70cf7bb-f781-5ace-a2a3-c7328807595f', '5c5422ac-2a87-5c61-a196-824f933f73a4', '4ec2ebd9-1893-5fbe-a8a2-85d15f0be9ca', 20, 20, 'እግዚአብሔርም ሙሴንና አሮንን እንዲህ ብሎ ተናገራቸው፦'),
  ('82d8b6c6-6f85-54b4-ac9a-aa186c46e1df', '5c5422ac-2a87-5c61-a196-824f933f73a4', '4ec2ebd9-1893-5fbe-a8a2-85d15f0be9ca', 21, 21, '“ሁሉን በቅጽበት አጠፋቸው ዘንድ ከዚህ ማኅበር መካከል ፈቀቅ በሉ።”'),
  ('5ecc4a20-22fa-5261-a6dd-fa5d58007714', '5c5422ac-2a87-5c61-a196-824f933f73a4', '4ec2ebd9-1893-5fbe-a8a2-85d15f0be9ca', 22, 22, 'እነርሱም በግንባራቸው ወድቀው፥ “የነፍስና የሥጋ ሁሉ አምላክ እግዚአብሔር ሆይ፥ አንድ ሰው ኀጢአት ቢሠራ የእግዚአብሔር ቍጣ በማኅበሩ ላይ ይሆናልን?” አሉ።'),
  ('b09f4a4b-b229-5675-a831-4209b04a9627', '5c5422ac-2a87-5c61-a196-824f933f73a4', '4ec2ebd9-1893-5fbe-a8a2-85d15f0be9ca', 23, 23, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('8c5c0cd4-eff2-5af4-a78c-7a01189637d4', '5c5422ac-2a87-5c61-a196-824f933f73a4', '4ec2ebd9-1893-5fbe-a8a2-85d15f0be9ca', 24, 24, '“ለማኅበሩ፦ ከቆሬ ማኅበር ዙሪያ ፈቀቅ በሉ ብለህ ንገራቸው።”'),
  ('1df5618f-4b5c-5550-a530-437d0d0d15a3', '5c5422ac-2a87-5c61-a196-824f933f73a4', '4ec2ebd9-1893-5fbe-a8a2-85d15f0be9ca', 25, 25, 'ሙሴም ተነሥቶ ወደ ዳታንና ወደ አቤሮን ሄደ፤ የእስራኤልም ሽማግሌዎች ሁሉ ከእርሱ ጋር ሄዱ።'),
  ('35b7a832-e2c9-53b7-a444-97bf1a7aa9a0', '5c5422ac-2a87-5c61-a196-824f933f73a4', '4ec2ebd9-1893-5fbe-a8a2-85d15f0be9ca', 26, 26, 'ማኅበሩንም፥ “ከእነዚህ ክፉዎች ሰዎች ድንኳን ፈቀቅ በሉ፤ በኀጢአታቸውም ሁሉ እንዳትጠፉ ለእነርሱ የሆነውን ሁሉ አትንኩ” ብሎ ተናገራቸው።'),
  ('0fa2edf0-4de9-599d-ae30-f8145adc3d3f', '5c5422ac-2a87-5c61-a196-824f933f73a4', '4ec2ebd9-1893-5fbe-a8a2-85d15f0be9ca', 27, 27, 'ከቆሬ ድንኳን ዙሪያም ሁሉ ፈቀቅ አሉ፤ ዳታንና አቤሮንም ከሴቶቻቸው፥ ከልጆቻቸውና ከጓዛቸው ጋር ወጥተው በድንኳኖቻቸው ደጃፍ ቆሙ።'),
  ('b6cff51e-876d-5679-a68a-b20dd60920bf', '5c5422ac-2a87-5c61-a196-824f933f73a4', '4ec2ebd9-1893-5fbe-a8a2-85d15f0be9ca', 28, 28, 'ሙሴም አለ፥ “ይህን ሥራ ሁሉ አደርግ ዘንድ እግዚአብሔር እንደ ላከኝ እንጂ ከልቤ እንዳይደለ በዚህ ታውቃላቸሁ።'),
  ('a528e710-d6dd-51a5-ab06-0ca4ebb4e818', '5c5422ac-2a87-5c61-a196-824f933f73a4', '4ec2ebd9-1893-5fbe-a8a2-85d15f0be9ca', 29, 29, 'እነዚህ ሰዎች ሰው እንደሚሞት ቢሞቱ፥ ወይም መቅሠፍታቸው እንደ ሰው ሁሉ መቅሠፍት ቢሆን እግዚአብሔር አልላከኝም።'),
  ('a3ce8a85-d708-52d2-af49-43686277729b', '5c5422ac-2a87-5c61-a196-824f933f73a4', '4ec2ebd9-1893-5fbe-a8a2-85d15f0be9ca', 30, 30, 'እግዚአብሔር ግን አዲስ ነገር ቢፈጥር፥ ምድርም አፍዋን ከፍታ እነርሱን፥ ቤታቸውን፥ ድንኳናቸውን፥ ለእነርሱም ያለውን ሁሉ ብትውጣቸው፥ በሕይወታቸውም ወደ ሲኦል ቢወርዱ፥ ያንጊዜ እነዚህ ሰዎች እግዚአብሔርን እንደ አስቈጡ ታውቃላቸሁ።”'),
  ('f8842e97-06d6-542d-a867-f8f62ee6086a', '5c5422ac-2a87-5c61-a196-824f933f73a4', '4ec2ebd9-1893-5fbe-a8a2-85d15f0be9ca', 31, 31, 'እንዲህም ሆነ፤ ይህን ቃል ሁሉ መናገር በፈጸመ ጊዜ ከበታቻቸው ያለችው መሬት ተሰነጠቀች፤'),
  ('49954a69-2f1d-5b39-a7b5-09726cf77943', '5c5422ac-2a87-5c61-a196-824f933f73a4', '4ec2ebd9-1893-5fbe-a8a2-85d15f0be9ca', 32, 32, 'ምድሪቱም አፍዋን ከፍታ እነርሱን፥ ቤተ ሰቦቻቸውንም፥ ለቆሬም የነበሩትን ሰዎች ሁሉ፥ ከብቶቻቸውንም ሁሉ ዋጠቻቸው።'),
  ('6d5854eb-ea1d-5310-a590-fe17f60f7b83', '5c5422ac-2a87-5c61-a196-824f933f73a4', '4ec2ebd9-1893-5fbe-a8a2-85d15f0be9ca', 33, 33, 'እነርሱም፥ ለእነርሱም የነበሩ ሁሉ በሕይወታቸው ወደ ሲኦል ወረዱ፤ ምድሪቱም ተዘጋችባቸው፤ ከማኅበሩም መካከል ጠፉ።'),
  ('021d092d-74b4-5e25-a8bf-2380192de4a9', '5c5422ac-2a87-5c61-a196-824f933f73a4', '4ec2ebd9-1893-5fbe-a8a2-85d15f0be9ca', 34, 34, 'በዙሪያቸው የነበሩ የእስራኤል ማኅበር ሁሉ ከጩኸታቸው የተነሣ፥ “ምድሪቱ እንዳትውጠን” ብለው ሸሹ።'),
  ('91090374-096e-505f-a072-4a0bb83c9365', '5c5422ac-2a87-5c61-a196-824f933f73a4', '4ec2ebd9-1893-5fbe-a8a2-85d15f0be9ca', 35, 35, 'እሳትም ከእግዚአብሔር ዘንድ ወጥታ ያጥኑ የነበሩትን ሁለት መቶ አምሳ ሰዎች በላች።'),
  ('b0e4d0e5-11b1-5d50-a029-30ed25639b7d', '5c5422ac-2a87-5c61-a196-824f933f73a4', '4ec2ebd9-1893-5fbe-a8a2-85d15f0be9ca', 36, 36, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው።'),
  ('0ce6c0f8-9838-5a5a-ab30-acc6db7f5499', '5c5422ac-2a87-5c61-a196-824f933f73a4', '4ec2ebd9-1893-5fbe-a8a2-85d15f0be9ca', 37, 37, 'ለካህኑ ለአሮን ልጅ ለአልዓዛር እንዲህ ብለህ ንገረው፥ “ከተቃጠሉት ሰዎች መካከል የናስ የሚሆኑ ጥናዎችን አውጣ፤ ከሌላ ያመጡትን ያንም እሳት ወዲያ ጣል፤'),
  ('83dc22b6-bf12-5214-aa8f-758f2bc8ba37', '5c5422ac-2a87-5c61-a196-824f933f73a4', '4ec2ebd9-1893-5fbe-a8a2-85d15f0be9ca', 38, 38, 'የእነዚህ ኃጥኣን ጥናዎቻቸው በሰውነታቸው ጥፋት ተቀድሰዋልና፤ የተጠፈጠፈ ሰሌዳ አድርጋቸው፤ ለመሠዊያ መለበጫም ይሁኑ፤ በእግዚአብሔር ፊት አቅርበዋቸዋልና የተቀደሱ ናቸው፤ ለእስራኤልም ልጆች ምልክት ይሆናሉ።”'),
  ('1e49d18b-e717-5375-a64e-172cfeedaf83', '5c5422ac-2a87-5c61-a196-824f933f73a4', '4ec2ebd9-1893-5fbe-a8a2-85d15f0be9ca', 39, 39, 'የካህኑም የአሮን ልጅ አልዓዛር የተቃጠሉት ሰዎች ያቀረቡአቸውን የናስ ጥናዎች ወስዶ ጠፍጥፎም ለመሠዊያ መለበጫ አደረጋቸው።'),
  ('4a08a4b2-ee3d-5240-adc0-f3a1eb74edf1', '5c5422ac-2a87-5c61-a196-824f933f73a4', '4ec2ebd9-1893-5fbe-a8a2-85d15f0be9ca', 40, 40, 'እንደ ቆሬና ከእርሱም ጋር እንደ ተቃወሙት ሰዎች እንዳይሆን፥ ከአሮን ልጆች ያልሆነ ሌላ ሰው በእግዚአብሔር ፊት ዕጣን ያጥን ዘንድ እንዳይቀርብ፥ እግዚአብሔር በሙሴ ቃል እንደ ተናገረው፥ ለእስራኤል ልጆች መታሰቢያ አደረጋቸው።'),
  ('bd59bc42-76d3-56c0-a859-3d6618698f3c', '5c5422ac-2a87-5c61-a196-824f933f73a4', '86fc2b3b-a1df-5960-a7e5-0196a35b9bcd', 1, 41, 'በነጋውም የእስራኤል ልጆች ሁሉ፥ “እናንተ የእግዚአብሔርን ሕዝብ ገድላችኋል” ብለው በሙሴና በአሮን ላይ አጕረመረሙ።'),
  ('d005e1da-51e5-541a-a33c-49b32c3a01e4', '5c5422ac-2a87-5c61-a196-824f933f73a4', '86fc2b3b-a1df-5960-a7e5-0196a35b9bcd', 2, 42, 'እንዲህም ሆነ፤ ማኅበሩ በሙሴና በአሮን ላይ በተሰበሰቡ ጊዜ በምስክሩ ድንኳን ከበቡአቸው፤ እነሆም፥ ደመናው ሸፈናት፤ የእግዚአብሔርም ክብር ተገለጠ።'),
  ('8b0b2739-ad77-5daf-ad66-4144aebdeaf4', '5c5422ac-2a87-5c61-a196-824f933f73a4', '86fc2b3b-a1df-5960-a7e5-0196a35b9bcd', 3, 43, 'ሙሴና አሮንም ወደ ምስክሩ ድንኳን ፊት ገቡ።'),
  ('d4db3419-a448-55d1-a8fd-ef07d2f5a79a', '5c5422ac-2a87-5c61-a196-824f933f73a4', '86fc2b3b-a1df-5960-a7e5-0196a35b9bcd', 4, 44, 'እግዚአብሔርም ሙሴንና አሮንን እንዲህ ብሎ ተናገራቸው፦'),
  ('e4279fee-666f-5040-a69e-1ccd06fcc6fc', '5c5422ac-2a87-5c61-a196-824f933f73a4', '86fc2b3b-a1df-5960-a7e5-0196a35b9bcd', 5, 45, '“ከዚህ ማኅበር መካከል ፈቀቅ በሉ፥ እኔም በቅጽበት አጠፋቸዋለሁ።” በግንባራቸውም ወደቁ።'),
  ('4d21e52d-2d8a-5897-acdb-bc624e4290a3', '5c5422ac-2a87-5c61-a196-824f933f73a4', '86fc2b3b-a1df-5960-a7e5-0196a35b9bcd', 6, 46, 'ሙሴም አሮንን፥ “ጥናህን ውሰድ፤ ከመሠዊያውም ላይ እሳት አድርግበት፤ ዕጣንም ጨምርበት፤ ወደ ማኅበሩም ፈጥነህ ውሰደው፤ አስተስርይላቸውም፤ ከእግዚአብሔር ፊት ቍጣ ወጥቶአልና፥ ሕዝቡንም ያጠፋቸው ዘንድ ጀምሮአል” አለው።'),
  ('6578ecc7-b10b-5d78-afd5-13e3ca8b18b0', '5c5422ac-2a87-5c61-a196-824f933f73a4', '86fc2b3b-a1df-5960-a7e5-0196a35b9bcd', 7, 47, 'አሮንም ሙሴ እንደ ተናገረው ጥናውን ወስዶ ወደ ማኅበሩ መካከል ፈጥኖ ሮጠ፤ እነሆም፥ መቅሠፍቱ በሕዝቡ መካከል ጀምሮ ነበር፤ ዕጣንም ጨመረ፤ ለሕዝቡም አስተሰረየላቸው።'),
  ('1c9a8e9d-e7f7-56e6-af22-38996160e444', '5c5422ac-2a87-5c61-a196-824f933f73a4', '86fc2b3b-a1df-5960-a7e5-0196a35b9bcd', 8, 48, 'በሙታንና በሕያዋን መካከል ቆመ፤ መቅሠፍቱም ተከለከለ።'),
  ('9300fe04-5224-553a-aa16-f5788b540e60', '5c5422ac-2a87-5c61-a196-824f933f73a4', '86fc2b3b-a1df-5960-a7e5-0196a35b9bcd', 9, 49, 'በቆሬም ምክንያት ከሞቱት ሌላ በመቅሠፍቱ የሞቱት ዐሥራ አራት ሺህ ሰባት መቶ ነበሩ።'),
  ('2d503305-262b-55fb-ae1f-b5d78fd8214e', '5c5422ac-2a87-5c61-a196-824f933f73a4', '86fc2b3b-a1df-5960-a7e5-0196a35b9bcd', 10, 50, 'አሮንም ወደ ሙሴ ወደ ምስክሩ ድንኳን ደጃፍ ተመለሰ፤ መቅሠፍቱም ፀጥ አለ።'),
  ('06079bb4-a80d-5cd7-ab00-6a5d8e13a300', '8179a0c1-828a-54de-af4f-44149e23dd43', '8ef421df-1ac0-5a90-aeff-0935c5952d32', 1, 1, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('d6c17738-c5e2-5328-ab6d-0407f9531cc8', '8179a0c1-828a-54de-af4f-44149e23dd43', '8ef421df-1ac0-5a90-aeff-0935c5952d32', 2, 2, '“ለእስራኤል ልጆች ንገራቸው፤ ከእነርሱም ከእያንዳንዱ ከየአባቶቻቸው ቤት አንድ አንድ በትር፥ ከአለቆቻቸውም ከየአባቶቻቸው ቤት ዐሥራ ሁለት በትሮች ውሰድ፤ የእያንዳንዱንም ስም በየበትሩ ላይ ጻፍ።'),
  ('d2027587-96f8-55ea-a098-c201f5b17dae', '8179a0c1-828a-54de-af4f-44149e23dd43', '8ef421df-1ac0-5a90-aeff-0935c5952d32', 3, 3, 'ለየአባቶቻቸው ቤት ወገን አንድ በትር ይሰጣሉና በሌዊ በትር ላይ የአሮንን ስም ጻፍ።'),
  ('f142ff95-5f8f-5960-a762-7540b8c799a6', '8179a0c1-828a-54de-af4f-44149e23dd43', '8ef421df-1ac0-5a90-aeff-0935c5952d32', 4, 4, 'እኔ ለእናንተ በምገለጥበት በዚያ በመገናኛው ድንኳን ውስጥ በምስክሩ ፊት አኑራቸው።'),
  ('c70d7cf0-6c28-5bf5-a10e-602ecbf9430d', '8179a0c1-828a-54de-af4f-44149e23dd43', '8ef421df-1ac0-5a90-aeff-0935c5952d32', 5, 5, 'እንዲህም ይሆናል፤ የመረጥሁት ሰው በትር ትለመልማለች፤ በእናንተም ላይ የሚያጕረመርሙባችሁ የእስራኤልን ልጆች ማጕረምረም ከእኔ ዘንድ አጠፋለሁ።”')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('29964491-f914-5827-abf2-2f68ae6e4927', '8179a0c1-828a-54de-af4f-44149e23dd43', '8ef421df-1ac0-5a90-aeff-0935c5952d32', 6, 6, 'ሙሴም ለእስራኤል ልጆች ነገራቸው፤ አለቆቻቸውም ሁሉ አንድ አንድ በትር ሰጡት፤ ለአንድ አለቃ አንድ በትር፥ በየአባቶቻቸው ቤት ዐሥራ ሁለት በትሮች፤ የአሮንም በትር በበትሮቻቸው መካከል ነበረች።'),
  ('b824bc96-8d06-5959-a8e8-e82ac42a6a3d', '8179a0c1-828a-54de-af4f-44149e23dd43', '8ef421df-1ac0-5a90-aeff-0935c5952d32', 7, 7, 'ሙሴም በትሮቹን በእግዚአብሔር ፊት በምስክሩ ድንኳን ውስጥ አኖራቸው።'),
  ('aa6bf981-c901-56a1-a2ce-f77f9d97d55c', '8179a0c1-828a-54de-af4f-44149e23dd43', '8ef421df-1ac0-5a90-aeff-0935c5952d32', 8, 8, 'እንዲህም ሆነ፤ በነጋው ሙሴና አሮን ወደ ምስክሩ ድንኳን ውስጥ ገቡ፤ እነሆም፥ ለሌዊ ቤት የሆነች የአሮን በትር አቈጠቈጠች፤ ለመለመችም፤ አበባም አወጣች፤ የበሰለ ለውዝም አፈራች።'),
  ('8b6e6527-39e2-5298-a392-05b62923439c', '8179a0c1-828a-54de-af4f-44149e23dd43', '8ef421df-1ac0-5a90-aeff-0935c5952d32', 9, 9, 'ሙሴም በትሮቹን ሁሉ ከእግዚአብሔር ፊት ወደ እስራኤል ልጆች ሁሉ አወጣቸው፤ እነርሱም አዩ፤ እያንዳንዱም በትሩን ወሰደ።'),
  ('19e07bb6-c9e3-56f1-a2a6-30cbbd6f2ed8', '8179a0c1-828a-54de-af4f-44149e23dd43', '8ef421df-1ac0-5a90-aeff-0935c5952d32', 10, 10, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ነገረው፥ “ማጕረምረማቸው ከእኔ ዘንድ እንዲጠፋ፥ እነርሱም እንዳይሞቱ ለማይሰሙ ልጆች ምልክት ሆና ትጠበቅ ዘንድ የአሮንን በትር በምስክሩ ፊት አኑር።”'),
  ('82e99816-43d3-5ad9-a072-92a5e9c80e52', '8179a0c1-828a-54de-af4f-44149e23dd43', '8ef421df-1ac0-5a90-aeff-0935c5952d32', 11, 11, 'ሙሴና አሮንም፤ እግዚአብሔር ሙሴን እንዳዘዘው አደረጉ፤ እንዲሁ አደረጉ።'),
  ('127126ee-59da-58fb-a2d0-5f0062f84ac4', '8179a0c1-828a-54de-af4f-44149e23dd43', '8ef421df-1ac0-5a90-aeff-0935c5952d32', 12, 12, 'የእስራኤልም ልጆች ሙሴን አሉት፥ “እነሆ፥ እንሞታለን፤ እንጠፋለን፤ ሁላችንም እናልቃለን።'),
  ('0a6e3ad9-2803-51ff-a24c-26a71e2e8432', '8179a0c1-828a-54de-af4f-44149e23dd43', '8ef421df-1ac0-5a90-aeff-0935c5952d32', 13, 13, 'የእግዚአብሔርን ድንኳን የሚነካ ሁሉ ይሞታል። በውኑ ሁላችን ፈጽመን እንሞታለን?”'),
  ('a55c207d-a4db-5ace-a7ab-2eae19d64a3c', '5a3ea2e4-88f2-54b1-a056-3e91a2aa3284', '8f3c78a7-e339-56a1-ac9a-25c9f9af2251', 1, 1, 'እግዚአብሔርም አሮንን እንዲህ ብሎ ነገረው፥ “አንተ ከአንተም ጋር ልጆችህና የአባቶችህ ወገኖች፥ የክህነታችሁን ኀጢአት ትሸከማላችሁ።'),
  ('a7eec704-d12b-5376-ac67-8e87b1698ea8', '5a3ea2e4-88f2-54b1-a056-3e91a2aa3284', '8f3c78a7-e339-56a1-ac9a-25c9f9af2251', 2, 2, 'ደግሞም የአባትህን የሌዊን ነገድ ወንድሞችህን ወደ አንተ ሰብስብ፤ ከአንተም ጋር በአንድነት ይሁኑ፤ ያገልግሉህም፤ አንተ ከአንተም ጋር ልጆችህ በምስክሩ ድንኳን ፊት ትሆናላችሁ።'),
  ('0c409744-b29f-577c-a93c-4bc19572bea3', '5a3ea2e4-88f2-54b1-a056-3e91a2aa3284', '8f3c78a7-e339-56a1-ac9a-25c9f9af2251', 3, 3, 'እነርሱም ትእዛዝህን የድንኳኑንም ሕግ ይጠብቁ፤ ነገር ግን እንዳይሞቱ፥ እናንተም ደግሞ ከእነርሱ ጋር እንዳትሞቱ፥ እነርሱ ወደ መቅደሱ ዕቃና ወደ መሠዊያው አይቅረቡ።'),
  ('1ac792e2-38e3-5cdc-a0a3-a5a1dc2421b6', '5a3ea2e4-88f2-54b1-a056-3e91a2aa3284', '8f3c78a7-e339-56a1-ac9a-25c9f9af2251', 4, 4, 'ነገር ግን ከእናንተ ጋር በአንድነት ይሁኑ፤ ለድንኳኑም አገልግሎት ሁሉ የምስክሩን ድንኳን ሕግ ይጠብቁ፤ ከባዕድ ወገን የሆነ ሰው ወደ አንተ አይቅረብ።'),
  ('4bcb8b03-fa99-5ad3-a69c-3acbdbd9956f', '5a3ea2e4-88f2-54b1-a056-3e91a2aa3284', '8f3c78a7-e339-56a1-ac9a-25c9f9af2251', 5, 5, 'እንደ ገና በእስራኤል ልጆች ላይ ቍጣ እንዳይሆንባቸው እናንተ የመቅደሱንና የመሠዊያውን ሕግ ጠብቁ።'),
  ('db8429df-a376-536f-a427-26ef7e76540e', '5a3ea2e4-88f2-54b1-a056-3e91a2aa3284', '8f3c78a7-e339-56a1-ac9a-25c9f9af2251', 6, 6, 'እኔም፦ እነሆ፥ ሌዋውያንን ወንድሞቻችሁን ከእስራኤል ልጆች መካከል ወስጄአለሁ፤ የምስክሩን ድንኳን አገልግሎት ያደርጉ ዘንድ ለእግዚአብሔር የተሰጡ ስጦታዎች ናቸው።'),
  ('a1859591-c698-531d-a462-978a68a821ce', '5a3ea2e4-88f2-54b1-a056-3e91a2aa3284', '8f3c78a7-e339-56a1-ac9a-25c9f9af2251', 7, 7, 'አንተም ከአንተም ጋር ልጆችህ እንደ መሠዊያውና፥ በመጋረጃውም ውስጥ እንዳለው ሥርዐት ሁሉ ክህነታችሁን ጠብቁ፤ የሀብተ ክህነት አገልግሎታችሁንም አድርጉ፤ ከሌላም ወገን የሆነ ሰው ቢቀርብ ይገደል።”'),
  ('aa897adb-1737-5c0f-aa02-85f22b39c3f5', '5a3ea2e4-88f2-54b1-a056-3e91a2aa3284', '075ad627-ea9b-59a9-a581-325620e2a6f5', 1, 8, 'እግዚአብሔርም አሮንን ተናገረው፤ እንዲህም አለው፥ “እነሆ፥ የእስራኤል ልጆች ለእኔ የለዩትን የመጀመሪያውን ቍርባኔን ሁሉ ትጠብቁ ዘንድ ለአንተ ሰጥቼሃለሁ፤ ለአንተ እስክታረጅ፥ ከአንተም በኋላ ለልጆችህ የዘለዓለም ሕግ እንዲሆን ሰጥቼሃለሁ።'),
  ('e177b77f-3d45-5023-a8b2-6c08bfe81262', '5a3ea2e4-88f2-54b1-a056-3e91a2aa3284', '075ad627-ea9b-59a9-a581-325620e2a6f5', 2, 9, 'በእሳት ከሚቀርበው ከተቀደሰው ይህ ለአንተ ይሆናል፤ ለእኔ የሚያመጡት መባቸው ሁሉ፥ ቍርባናቸውም ሁሉ፥ የኀጢአታቸውም መሥዋዕት ሁሉ፥ የበደላቸውም መሥዋዕት ሁሉ፥ ከተቀደሰውም ሁሉ ለአንተ ለልጆችህም ይሆናል።'),
  ('751352d6-6c61-5410-ae47-c5476d396e3f', '5a3ea2e4-88f2-54b1-a056-3e91a2aa3284', '075ad627-ea9b-59a9-a581-325620e2a6f5', 3, 10, 'በቅዱሰ ቅዱሳን ብሉት፤ ወንዶች ሁሉ ይብሉት፤ አንተም ልጆችህም ብሉት፤ ለአንተ የተቀደሰ ነውና።'),
  ('c56198b1-c2af-5736-aa58-de6682be3209', '5a3ea2e4-88f2-54b1-a056-3e91a2aa3284', '075ad627-ea9b-59a9-a581-325620e2a6f5', 4, 11, 'ይህም ለእናንተ ነው፤ የእስራኤል ልጆች ለስጦታ ያቀረቡትን የመጀመሪያ ቍርባን ሁሉ ለአንተ ከአንተም ጋር ለወንዶችና ለሴቶች ልጆችህ የዘለዓለም ሕግ እንዲሆን ሰጥቼሃለሁ፤ በቤትህ ውስጥ ንጹሕ የሆነ ሁሉ ይብላው።'),
  ('78cf4a9f-7b02-5260-a42e-4448eeb8a15e', '5a3ea2e4-88f2-54b1-a056-3e91a2aa3284', '075ad627-ea9b-59a9-a581-325620e2a6f5', 5, 12, 'ለእግዚአብሔር ከሚሰጡት የፍሬ መጀመሪያ ከዘይትና ከወይን ከስንዴም የተመረጠውን ሁሉ ለአንተ ሰጥቼሃለሁ፤'),
  ('b8c12cdb-e8e9-5de1-ac49-a35b0e88cad5', '5a3ea2e4-88f2-54b1-a056-3e91a2aa3284', '075ad627-ea9b-59a9-a581-325620e2a6f5', 6, 13, 'ወደ እግዚአብሔር የሚያመጡት በምድራቸው ያለው የፍሬ መጀመሪያ ሁሉ ለአንተ ይሆናል፤ በቤትህ ውስጥ ንጹሕ የሆነ ሁሉ ይብላው፤'),
  ('8178141f-788e-59aa-a746-1e17b1c4e85f', '5a3ea2e4-88f2-54b1-a056-3e91a2aa3284', '075ad627-ea9b-59a9-a581-325620e2a6f5', 7, 14, 'በእስራኤል ልጆች ዘንድ የተከለከለው ሁሉ ለአንተ ይሆናል።'),
  ('50dffd62-7265-5d5c-a042-4d42ea8b3ffc', '5a3ea2e4-88f2-54b1-a056-3e91a2aa3284', '075ad627-ea9b-59a9-a581-325620e2a6f5', 8, 15, 'ከሰው እስከ እንስሳ ቢሆን፥ ለእግዚአብሔር ከሚያቀርቡት ሥጋ ሁሉ፥ መጀመሪያ የሚወለድ ሁሉ ለአንተ ይሆናል፤ ነገር ግን የሰውን በኵራት ፈጽሞ ትቤዠዋለህ፤ ያልነጹትንም እንስሳት በኵራት ትቤዣለህ።'),
  ('4fb88820-bd80-5590-a3b3-d62a06bb0e2b', '5a3ea2e4-88f2-54b1-a056-3e91a2aa3284', '075ad627-ea9b-59a9-a581-325620e2a6f5', 9, 16, 'አንድ ወር የሆነው ልጅ ዋጋው በቤተ መቅደስ ሚዛን አምስት ሰቅል ነው። ይኸውም ሃያ አቦሊ ነው።'),
  ('e18ccfbf-5d56-5b0f-aaf0-04586f26c542', '5a3ea2e4-88f2-54b1-a056-3e91a2aa3284', '075ad627-ea9b-59a9-a581-325620e2a6f5', 10, 17, 'ነገር ግን የላሞቹን በኵራት፥ ወይም የበጎቹን በኵራት፥ የፍየሎችንም በኵራት አትቤዥም፤ ቅዱሳን ናቸውና፤ ደማቸውን በመሠዊያው ላይ ትረጨዋለህ፤ ስባቸውንም ለእግዚአብሔር በጎ መዓዛ እንዲሆን መሥዋዕት ታደርገዋለህ።'),
  ('0f424a23-3f0c-553f-aadc-554f3f4e8678', '5a3ea2e4-88f2-54b1-a056-3e91a2aa3284', '075ad627-ea9b-59a9-a581-325620e2a6f5', 11, 18, 'ሥጋውም ለአንተ ይሆናል፤ እንደሚያቀርቡት ፍርምባ እንደ ቀኙም ወርች ለአንተ ይሆናል።'),
  ('fea129ef-78c0-5d72-a16d-44f22978fadf', '5a3ea2e4-88f2-54b1-a056-3e91a2aa3284', '075ad627-ea9b-59a9-a581-325620e2a6f5', 12, 19, 'የእስራኤል ልጆች ለእግዚአብሔር የሚለዩትን የተቀደሰውን መባ ሁሉ ለአንተ ከአንተም ጋር ለወንዶችና ለሴቶች ልጆችህ ሰጥቼሃለሁ፤ ይህም ለአንተ ከአንተም በኋላ ለዘርህ በእግዚአብሔር ፊት የዘለዓለም ሕግና የሁልጊዜ ቃል ኪዳን ነው።”'),
  ('2a2a6935-9c6d-5e8a-abc3-02874067d3ea', '5a3ea2e4-88f2-54b1-a056-3e91a2aa3284', '075ad627-ea9b-59a9-a581-325620e2a6f5', 13, 20, 'እግዚአብሔርም አሮንን አለው፥ “በምድራቸው ርስት አትወርስም፤ በመካከላቸውም ድርሻ አይሆንልህም፤ በእስራኤል ልጆች መካከል ድርሻህና ርስትህ እኔ ነኝ።'),
  ('e34f756f-fbd4-5b16-a8c9-edaa381c8012', '5a3ea2e4-88f2-54b1-a056-3e91a2aa3284', '8b5187ec-0945-51cb-af84-d7a4003282e3', 1, 21, '“ለሌዊም ልጆች እነሆ፥ በምስክሩ ድንኳን አገልግሎት ስለሚያገለግሉ፥ የእስራኤልን ልጆች ዐሥራት ርስት አድርጌ ሰጥቻቸዋለሁ።'),
  ('5a22230b-d55b-5940-a5bd-9c952a6f3253', '5a3ea2e4-88f2-54b1-a056-3e91a2aa3284', '8b5187ec-0945-51cb-af84-d7a4003282e3', 2, 22, 'ከዚህም በኋላ ለሞት የሚያበቃ በደል እንዳይሆንባቸው፥ የእስራኤል ልጆች ወደ ምስክሩ ድንኳን አይግቡ።'),
  ('b5a04fa4-293d-5896-aee3-362f521f29e9', '5a3ea2e4-88f2-54b1-a056-3e91a2aa3284', '8b5187ec-0945-51cb-af84-d7a4003282e3', 3, 23, 'ሌዋውያን ግን የምስክሩን ድንኳን አገልግሎት ይሥሩ፤ እነርሱም ኀጢአታቸውን ይሸከማሉ፤ ለልጅ ልጃችሁም የዘለዓለም ሥርዐት ይሆናል፤ በእስራኤልም ልጆች መካከል ርስት አይወርሱም።'),
  ('7705ca92-212c-52e1-aecf-342abb8fa35c', '5a3ea2e4-88f2-54b1-a056-3e91a2aa3284', '8b5187ec-0945-51cb-af84-d7a4003282e3', 4, 24, 'ለእግዚአብሔር መባ አድርገው የሚለዩትን የእስራኤልን ልጆች ዐሥራት ለሌዋውያን ርስት አድርጌ ሰጥቻቸዋለሁ፤ ስለዚህ፦ በእስራኤል ልጆች መካከል ርስት አትወርሱም አልኋቸው።”'),
  ('19581228-6ecb-501f-a644-eecc73a4f659', '5a3ea2e4-88f2-54b1-a056-3e91a2aa3284', '0777b23b-f748-5020-a61c-2adac89fe902', 1, 25, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('73d8801d-d8a6-590a-aeef-ebdaff639ae2', '5a3ea2e4-88f2-54b1-a056-3e91a2aa3284', '0777b23b-f748-5020-a61c-2adac89fe902', 2, 26, '“ለሌዋውያን እንዲህ ብለህ ንገራቸው፦ ከእስራኤል ልጆች ከእናንተ ርስት አድርጌ የሰጠኋችሁን ዐሥራት በተቀበላችሁ ጊዜ፥ እናንተምከእርሱ ለእግዚአብሔር መባ አድርጋችሁ የዐሥራት ዐሥራት ታቀርባላችሁ።'),
  ('68c5d0e4-4049-5965-a6e9-e749aed78b83', '5a3ea2e4-88f2-54b1-a056-3e91a2aa3284', '0777b23b-f748-5020-a61c-2adac89fe902', 3, 27, 'መባችሁም እንደ እህል ዐውድማው ስንዴና እንደ ወይን መጭመቂያው ፍሬ ይቈጠርላችኋል።'),
  ('8796fe06-3b4a-5e47-aea5-0da938453d12', '5a3ea2e4-88f2-54b1-a056-3e91a2aa3284', '0777b23b-f748-5020-a61c-2adac89fe902', 4, 28, 'እንዲሁ እናንተ ደግሞ ከእስራኤል ልጆች ከምትቀበሉት ዐሥራት ሁሉ ለእግዚአብሔር መባ አድርጋችሁ ታቀርባላችሁ፤ የእግዚአብሔርንም መባ ለይታችሁ ለካህኑ ለአሮን ትሰጣላችሁ።'),
  ('d7ddba87-3402-5a37-a63e-a45a60b63e5f', '5a3ea2e4-88f2-54b1-a056-3e91a2aa3284', '0777b23b-f748-5020-a61c-2adac89fe902', 5, 29, 'ከምትቀበሉት ስጦታ ሁሉ፥ ከተመረጠው ከተቀደሰውም ድርሻ ሁሉ፥ የእግዚአብሔርን የመጀመሪያ መባ ሁሉ ታቀርባላችሁ።'),
  ('25926ebe-81d3-528c-aa65-65d970841ceb', '5a3ea2e4-88f2-54b1-a056-3e91a2aa3284', '0777b23b-f748-5020-a61c-2adac89fe902', 6, 30, 'ስለዚህ ትላቸዋለህ፦ ከእርሱ ከመጀመሪያው በለያችሁ ጊዜ እንደ አውድማው እህልና እንደ ወይን መጭመቂያው ፍሬ ለሌዋውያን ይቈጠርላቸዋል።'),
  ('757768bd-fde1-56ec-a49f-0e23fcfc1b66', '5a3ea2e4-88f2-54b1-a056-3e91a2aa3284', '0777b23b-f748-5020-a61c-2adac89fe902', 7, 31, 'እናንተም ቤተ ሰቦቻችሁም፥ በምስክሩ ድንኳን ውስጥ የማገልገላችሁ ዋጋ ነውና በሁሉ ስፍራ ትበሉታላችሁ።'),
  ('01683343-04d7-5bb4-aa1c-e8631f14dd05', '5a3ea2e4-88f2-54b1-a056-3e91a2aa3284', '0777b23b-f748-5020-a61c-2adac89fe902', 8, 32, 'የመጀመሪያውንም ከእርሱ ባነሣችሁ ጊዜ ስለ እርሱ ኀጢአት አይሆንባችሁም፤ እንዳትሞቱም የእስራኤል ልጆች የቀደሱትን አታርክሱ።”'),
  ('4a0fd297-72c6-5aee-ad58-b0cfd060ae86', '5ecf6858-4a78-5e17-a11a-487b96cf153c', '9386c86d-9963-5d56-a7b8-0b30328dd252', 1, 1, 'እግዚአብሔርም ሙሴንና አሮንን እንዲህ ብሎ ተናገራቸው፦'),
  ('33611a4f-1afe-531b-ad76-37710705f038', '5ecf6858-4a78-5e17-a11a-487b96cf153c', '9386c86d-9963-5d56-a7b8-0b30328dd252', 2, 2, '“እግዚአብሔር ያዘዘው የሕጉ ትእዛዝ ይህ ነው፤ መልካሚቱን፥ ነውርም የሌለባትን፥ ቀንበርም ያልተጫነባትን ቀይ ጊደር ያመጡልህ ዘንድ ለእስራኤል ልጆች ንገራቸው።'),
  ('fb7821dc-3a54-59ee-ac5b-7fae072acf9d', '5ecf6858-4a78-5e17-a11a-487b96cf153c', '9386c86d-9963-5d56-a7b8-0b30328dd252', 3, 3, 'እርስዋንም ለካህኑ ለአልዓዛር ትሰጠዋለህ፤ ከሰፈር ወደ ውጭ ወደ ንጹሕ ስፍራ ይወስዷታል፤ በፊቱም ያርዷታል።'),
  ('100773be-ed65-5940-a212-1fc3c113e7eb', '5ecf6858-4a78-5e17-a11a-487b96cf153c', '9386c86d-9963-5d56-a7b8-0b30328dd252', 4, 4, 'አልዓዛርም ከደምዋ በጣቱ ይወስዳል፤ ከደምዋም ወደ ምስክሩ ድንኳን ፊት ሰባት ጊዜ ይረጫል።'),
  ('e032a559-ef7c-55fd-a6f8-6c91e78531ca', '5ecf6858-4a78-5e17-a11a-487b96cf153c', '9386c86d-9963-5d56-a7b8-0b30328dd252', 5, 5, 'ጊደሪቱንም በፊቱ ያቃጥሏታል፤ ቍርበቷንም፥ ሥጋዋንም፥ ደምዋንም፥ ፈርስዋንም ያቃጥሉት።'),
  ('bc7efa80-d8ce-5625-acf2-77cbacf1d883', '5ecf6858-4a78-5e17-a11a-487b96cf153c', '9386c86d-9963-5d56-a7b8-0b30328dd252', 6, 6, 'ካህኑም የዝግባ ዕንጨት ሂሶጵም፥ ቀይ ግምጃም ወስዶ ጊደሪቱ በምትቃጠልበት እሳት መካከል ይጥለዋል።'),
  ('2508ddb3-e0a2-5bfa-a5d9-43ed1c16370d', '5ecf6858-4a78-5e17-a11a-487b96cf153c', '9386c86d-9963-5d56-a7b8-0b30328dd252', 7, 7, 'ካህኑም ልብሱን ያጥባል፤ ገላውንም በውሃ ይታጠባል፤ ከዚያም በኋላ ወደ ሰፈሩ ይገባል፤ ካህኑም እስከ ማታ ርኩስ ይሆናል።'),
  ('106679fd-ef0a-515b-ad93-85ebf3411524', '5ecf6858-4a78-5e17-a11a-487b96cf153c', '9386c86d-9963-5d56-a7b8-0b30328dd252', 8, 8, 'ያቃጠላትም ሰው ልብሱን በውሃ ያጥባል፤ ገላውንም በውኃ ይታጠባል፤ እስከ ማታም ድረስ ርኩስ ይሆናል።'),
  ('3fa80f23-8e8d-5038-af1d-0b86d47e1e4b', '5ecf6858-4a78-5e17-a11a-487b96cf153c', '9386c86d-9963-5d56-a7b8-0b30328dd252', 9, 9, 'ንጹሕም ሰው የጊደሪቱን አመድ ያከማቻል፤ ከሰፈሩም ውጭ በንጹሕ ስፍራ ያኖረዋል፤ ርኵሰት ለሚያነጻ ውኃ ለእስራኤል ልጆች ማኅበር ይጠበቃል፤ ይነጹበታልና።'),
  ('58610e39-a868-5d9a-aa2b-5d7dad59357c', '5ecf6858-4a78-5e17-a11a-487b96cf153c', '9386c86d-9963-5d56-a7b8-0b30328dd252', 10, 10, 'የጊደሪቱንም አመድ ያከማቸው ሰው ልብሱን ያጥባል፤ ገላውንም ይታጠባል፤ እስከ ማታም ድረስ ርኩስ ይሆናል፤ ይህም ለእስራኤል ልጆች በመካከላቸውም ለሚኖር መጻተኛ ለዘለዓለም ሥርዐት ይሆናል።'),
  ('df5c6abe-de73-5ba8-a00c-e307fa7c1b88', '5ecf6858-4a78-5e17-a11a-487b96cf153c', 'cfd88719-9d65-5c4a-a823-b3a1a9b5b6c9', 1, 11, '“የሞተውን ሰው በድን የሚነካ ሰባት ቀን ርኩስ ይሆናል።'),
  ('f6ce1df2-6477-5b1e-ab1d-51476e9e9ae3', '5ecf6858-4a78-5e17-a11a-487b96cf153c', 'cfd88719-9d65-5c4a-a823-b3a1a9b5b6c9', 2, 12, 'እንደዚሁ በሦስተኛውና በሰባተኛው ቀን ሁለመናውን ያነጻል፤ ንጹሕም ይሆናል፤ ነገር ግን በሦስተኛውና በሰባተኛው ቀን ሁለመናውን ባያነጻ ንጹሕ አይሆንም።'),
  ('4892241e-11bb-5c54-a487-5b9f3811a315', '5ecf6858-4a78-5e17-a11a-487b96cf153c', 'cfd88719-9d65-5c4a-a823-b3a1a9b5b6c9', 3, 13, 'የሞተውን ሰው በድን የነካ ሁለመናውን ባያነጻ የእግዚአብሔርን ድንኳን ያረክሳል፤ ያ ሰው ከእስራኤል ዘንድ ተለይቶ ይጠፋል፤ በእርሱም ላይ የሚያነጻ ውኃ አልተረጨምና ርኩስ ይሆናል፤ ርኵሰቱ ገና በእርሱ ላይ ነው።'),
  ('3112257b-8dab-58a7-a033-920f019453b2', '5ecf6858-4a78-5e17-a11a-487b96cf153c', 'cfd88719-9d65-5c4a-a823-b3a1a9b5b6c9', 4, 14, '“ሰው በቤት ውስጥ ቢሞት ሕጉ ይህ ነው፤ ወደ ቤት የሚገባ ሁሉ በቤቱም ውስጥ ያለው ሁሉ ሰባት ቀን ርኩስ ይሆናል።'),
  ('a9e92b91-e0dc-5186-a1b1-9a090f88f5f9', '5ecf6858-4a78-5e17-a11a-487b96cf153c', 'cfd88719-9d65-5c4a-a823-b3a1a9b5b6c9', 5, 15, 'መክደኛው ያልታሰረ የተከፈተ ዕቃ ሁሉ ርኩስ ነው።'),
  ('316a89b6-e27f-5bf7-a24e-efdcceddaf1f', '5ecf6858-4a78-5e17-a11a-487b96cf153c', 'cfd88719-9d65-5c4a-a823-b3a1a9b5b6c9', 6, 16, 'በሜዳም የተገደለውን ወይም የሞተውን በድን፥ ወይም የሰውን አጥንት፥ ወይም መቃብር የሚነካ ሰባት ቀን ርኩስ ይሆናል።'),
  ('9574b57d-4ce3-5a8b-a7f6-0cb621c758f2', '5ecf6858-4a78-5e17-a11a-487b96cf153c', 'cfd88719-9d65-5c4a-a823-b3a1a9b5b6c9', 7, 17, 'ለአንጽሖ እንድትሆን ከተቃጠለችው ጊደር አመድ ለርኩሱ ይወስዱለታል፤ በዕቃውም ውስጥ የምንጭ ውኃ ይቀላቅሉበታል።'),
  ('6cd66a59-9d0f-530c-a165-5247eb776221', '5ecf6858-4a78-5e17-a11a-487b96cf153c', 'cfd88719-9d65-5c4a-a823-b3a1a9b5b6c9', 8, 18, 'ንጹሕም ሰው ሂሶጱን ወስዶ በውኃው ውስጥ ያጠልቀዋል፤ በቤቱም፥ በዕቃውም ሁሉ፥ በዚያም ባሉ ሰዎች ላይ፥ አጥንቱንም ወይም የተገደለውን፥ ወይም የሞተውን፥ ወይም መቃብሩን በነካው ላይ ይረጨዋል።'),
  ('ae553e6d-750e-5599-a0d3-e9d8a1419e5f', '5ecf6858-4a78-5e17-a11a-487b96cf153c', 'cfd88719-9d65-5c4a-a823-b3a1a9b5b6c9', 9, 19, 'ንጹሑም በሦስተኛው ቀንና በሰባተኛው ቀን በርኩሱ ላይ ይረጨዋል፤ በሰባተኛውም ቀን ይነጻል፤ እርሱም ልብሱን ያጥባል፤ ገላውንም በውኃ ይታጠባል፥ እስከ ማታም ርኩስ ነው።'),
  ('c9f54e9f-5903-5b07-abed-2daa5dee3be5', '5ecf6858-4a78-5e17-a11a-487b96cf153c', 'cfd88719-9d65-5c4a-a823-b3a1a9b5b6c9', 10, 20, '“ሰውም ርኩስ ቢሆን ሁለመናውንም ባያነጻ፥ ያ ሰው የእግዚአብሔርን መቅደስ አርክሶአልና ከማኅበሩ መካከል ተለይቶ ይጠፋል፤ በሚያነጻ ውኃ አልተረጨምና ርኩስ ነው።'),
  ('390ff399-f851-5759-ae5f-c3fb04ef4b0b', '5ecf6858-4a78-5e17-a11a-487b96cf153c', 'cfd88719-9d65-5c4a-a823-b3a1a9b5b6c9', 11, 21, 'ይህ የዘለዓለም ሥርዐት ይሆንላችኋል፤ የሚያነጻውን ውኃ የሚረጭ ሰው ልብሱን ያጥባል፤ የሚያነጻውንም ውኃ የሚነካ እስከ ማታ ድረስ ርኩስ ይሆናል።'),
  ('80df1076-524b-5012-a5cf-7cf23cc7aa80', '5ecf6858-4a78-5e17-a11a-487b96cf153c', 'cfd88719-9d65-5c4a-a823-b3a1a9b5b6c9', 12, 22, 'ርኩሱም የሚነካው ነገር ሁሉ ርኩስ ይሆናል፤ የሚነካውም ሰው እስከ ማታ ድረስ ርኩስ ይሆናል።”'),
  ('42aaeff8-72e2-543b-afff-27b3224db409', '4d64b4d4-f3de-5d00-a389-b2924ae78ffa', '8baf0f14-301f-5048-ac93-fbe8c57e8c92', 1, 1, 'የእስራኤልም ልጆች ማኅበር ሁሉ በመጀመሪያው ወር ወደ ጺን ምድረ በዳ መጡ፤ ሕዝቡም በቃዴስ ተቀመጡ፤ ማርያምም በዚያ ሞተች፤ ተቀበረችም።'),
  ('3934a3d3-34d8-5775-a6bb-d37820e95f6f', '4d64b4d4-f3de-5d00-a389-b2924ae78ffa', '8baf0f14-301f-5048-ac93-fbe8c57e8c92', 2, 2, 'ለማኅበሩም ውኃ አልነበረም፤ ሕዝቡም በሙሴና በአሮን ላይ ተሰበሰቡ።'),
  ('a5e76b46-4eda-5baa-a44d-5c79d3cda164', '4d64b4d4-f3de-5d00-a389-b2924ae78ffa', '8baf0f14-301f-5048-ac93-fbe8c57e8c92', 3, 3, 'ሙሴንም ተጣሉት፤ እንዲህም ብለው ተናገሩት፥ “ወንድሞቻችን በእግዚአብሔር ፊት በሞቱ ጊዜ እኛም ምነው በሞትን ኖሮ፤'),
  ('2f218327-556c-5a27-afc3-90ed45f79cc2', '4d64b4d4-f3de-5d00-a389-b2924ae78ffa', '8baf0f14-301f-5048-ac93-fbe8c57e8c92', 4, 4, 'እኛ፥ ከብቶቻችንም በዚያ እንሞት ዘንድ የእግዚአብሔርን ማኅበር ወደዚህ ምድረ በዳ ለምን አወጣችሁ?'),
  ('6bbe0f24-1f57-57f1-abcf-00bd307983f5', '4d64b4d4-f3de-5d00-a389-b2924ae78ffa', '8baf0f14-301f-5048-ac93-fbe8c57e8c92', 5, 5, 'ዘር ወደማይዘራበት፥ በለስና ወይንም፥ ሮማንም፥ የሚጠጣም ውኃ ወደሌለበት ወደዚህ ክፉ ስፍራ ታመጡን ዘንድ ከግብፅ ለምን አወጣችሁን?”'),
  ('5ddde2bd-1762-5403-a118-993bac04ac47', '4d64b4d4-f3de-5d00-a389-b2924ae78ffa', '8baf0f14-301f-5048-ac93-fbe8c57e8c92', 6, 6, 'ሙሴና አሮንም ከማኅበሩ ፊት ወደ ምስክሩ ድንኳን ዳጃፍ ሄደው በግንባራቸው ወደቁ፤ የእግዚአብሔርም ክብር ተገለጠላቸው።'),
  ('3deb060e-dbe8-5d80-a598-9d7ef157313e', '4d64b4d4-f3de-5d00-a389-b2924ae78ffa', '8baf0f14-301f-5048-ac93-fbe8c57e8c92', 7, 7, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('4b738c7b-2875-5e43-af3c-85fad31a0540', '4d64b4d4-f3de-5d00-a389-b2924ae78ffa', '8baf0f14-301f-5048-ac93-fbe8c57e8c92', 8, 8, '“ይህችን በትርህን ውሰድ፤ አንተና ወንድምህ አሮንም ማኅበሩን ሰብስቡ፤ ዐለቷንም በፊታቸው እዘዟት፤ ውኃ ትሰጣለች፤ ከድንጋይዋም ውኃ ታወጡላቸዋላችሁ፤ እንዲሁም ማኅበሩን፥ ከብቶቻቸውንም ታጠጡላቸዋላችሁ።”'),
  ('5143a311-6429-5574-a445-4ef1ecf3a70a', '4d64b4d4-f3de-5d00-a389-b2924ae78ffa', '8baf0f14-301f-5048-ac93-fbe8c57e8c92', 9, 9, 'ሙሴም እግዚአብሔር እንደ አዘዘው በእግዚአብሔር ፊት የነበረችውን በትሩን ወሰደ።'),
  ('88b4ae93-3a24-5503-a9af-46b1434599d2', '4d64b4d4-f3de-5d00-a389-b2924ae78ffa', '8baf0f14-301f-5048-ac93-fbe8c57e8c92', 10, 10, 'ሙሴና አሮንም ማኅበሩን በዐለቷ ፊት ሰብስበው፥ “እናንተ ዓመፀኞች፥ እንግዲህ ስሙ፤ በውኑ ከዚህች ዐለት ውኃን እናወጣላችሁ ነበር?” አሏቸው።'),
  ('dc7ba5a1-fe8d-5db3-a745-343e64d79cc0', '4d64b4d4-f3de-5d00-a389-b2924ae78ffa', '8baf0f14-301f-5048-ac93-fbe8c57e8c92', 11, 11, 'ሙሴም እጁን ዘርግቶ ዐለቷን ሁለት ጊዜ በበትሩ መታት፤ ብዙም ውኃ ወጣ፤ ማኅበሩም፥ ከብቶቻቸውም ጠጡ።'),
  ('5035fbc4-fa52-5709-ab50-8b78bba9cfdd', '4d64b4d4-f3de-5d00-a389-b2924ae78ffa', '8baf0f14-301f-5048-ac93-fbe8c57e8c92', 12, 12, 'እግዚአብሔርም ሙሴንና አሮንን፥ “በእስራኤል ልጆች ፊት ትቀድሱኝ ዘንድ በእኔ አላመናችሁምና ስለዚህ ወደ ሰጠኋችሁ ምድር ይህን ማኅበር ይዛችሁ አትገቡም” አላቸው።'),
  ('7a5a5359-9bf0-57f1-ac46-b9b737a1dacf', '4d64b4d4-f3de-5d00-a389-b2924ae78ffa', '8baf0f14-301f-5048-ac93-fbe8c57e8c92', 13, 13, 'የእስራኤል ልጆች ተከራክረውበታልና ይህ ውኃ የክርክር ውኃ ተባለ። እርሱም ቅዱስ መሆኑ የተገለጠበት ይህ የክርክር ውኃ ነው።'),
  ('f23e0140-878c-5cf8-acbb-3e16b1a94399', '4d64b4d4-f3de-5d00-a389-b2924ae78ffa', '330bec41-1dfe-5ab3-a230-1b1ccafb2f6b', 1, 14, 'ሙሴም ከቃዴስ ወደ ኤዶምያስ ንጉሥ መልእክተኞችን እንዲህ ብሎ ላከ፥ “ወንድምህ እስራኤል እንዲህ ይላል፦ ያገኘንን መከራ ሁሉ አንተ ታውቃለህ፤'),
  ('01daa33d-4846-5b3f-a318-dde35766a5ae', '4d64b4d4-f3de-5d00-a389-b2924ae78ffa', '330bec41-1dfe-5ab3-a230-1b1ccafb2f6b', 2, 15, 'አባቶቻችን ወደ ግብፅ ወረዱ፤ በግብፅም እጅግ ዘመን ተቀመጥን፤ ግብፃውያንም እኛንና አባቶቻችንን በደሉ።'),
  ('2b6a18f6-3f65-57f2-aba1-cf1635ffb931', '4d64b4d4-f3de-5d00-a389-b2924ae78ffa', '330bec41-1dfe-5ab3-a230-1b1ccafb2f6b', 3, 16, 'ወደ እግዚአብሔርም ጮኽን፤ እግዚአብሔርም ድምፃችንን ሰማ፤ መልአክንም ልኮ ከግብፅ አወጣን፤ እነሆም፥ በምድርህ ዳርቻ ባለችው ከተማ በቃዴስ ተቀምጠናል።'),
  ('81090931-8676-5f45-a29a-79762b0f4539', '4d64b4d4-f3de-5d00-a389-b2924ae78ffa', '330bec41-1dfe-5ab3-a230-1b1ccafb2f6b', 4, 17, 'እባክህ፥ በምድርህ ላይ እንለፍ፤ ወደ እርሻም ወደ ወይንም አንገባም፤ ከጕድጓዶችም ውኃን አንጠጣም፤ በንጉሡ ጎዳና እንሄዳለን፤ ዳርቻህንም እስክናልፍ ድረስ ወደ ቀኝም ወደ ግራም አንልም።”'),
  ('d7e647f0-1666-5907-a57a-7b0a5c6e92f4', '4d64b4d4-f3de-5d00-a389-b2924ae78ffa', '330bec41-1dfe-5ab3-a230-1b1ccafb2f6b', 5, 18, 'የኤዶምያስም ንጉሥ “በእኔ በኩል አታልፍም፤ ይህ ካልሆነ ግን እንዋጋለን፤ በጦርም እቀበልህ ዘንድ እወጣለሁ” አለው።'),
  ('4dc8db85-cc74-5006-afdf-24a62a58f37b', '4d64b4d4-f3de-5d00-a389-b2924ae78ffa', '330bec41-1dfe-5ab3-a230-1b1ccafb2f6b', 6, 19, 'የእስራኤልም ልጆች፥ “በተራራው በኩል እናልፋለን፤ እኛም ከብቶቻችንም ከውኃህ ብንጠጣ ዋጋውን እንከፍላለን፤ ይህ ምንም አይደለም፤ በተራራው እንለፍ” አሉት።'),
  ('9b05b9d8-e5c2-54f3-aae0-d7df4f5c994b', '4d64b4d4-f3de-5d00-a389-b2924ae78ffa', '330bec41-1dfe-5ab3-a230-1b1ccafb2f6b', 7, 20, 'እርሱም፥ “በእኔ በኩል አታልፍም” አለ። የኤዶምያስም ንጉሥ በብዙ ሠራዊት በጽኑ እጅ ሊገጥመው ወጣ።'),
  ('48f08f0a-ec8a-50b5-a6cb-360745c7c714', '4d64b4d4-f3de-5d00-a389-b2924ae78ffa', '330bec41-1dfe-5ab3-a230-1b1ccafb2f6b', 8, 21, 'የኤዶምያስም ንጉሥ እስራኤል በዳርቻው እንዲያልፍ አልፈቀደም፤ ስለዚህ እስራኤል ከእርሱ ተመለሰ።'),
  ('87d39880-dfa6-505d-a844-a19f8bdc7719', '4d64b4d4-f3de-5d00-a389-b2924ae78ffa', 'f16d4cb7-d1ca-54ad-ab07-53fbdfa6797b', 1, 22, 'ከቃዴስም ተጓዙ፤ የእስራኤልም ልጆች ማኅበር ሁሉ በሖር ተራራ ሰፈሩ።'),
  ('1af6bca5-1b92-5b5d-af68-32f2076322a0', '4d64b4d4-f3de-5d00-a389-b2924ae78ffa', 'f16d4cb7-d1ca-54ad-ab07-53fbdfa6797b', 2, 23, 'እግዚአብሔርም ሙሴንና አሮንን በኤዶምያስ ምድር ዳርቻ ባለው በሖር ተራራ እንዲህ ብሎ ተናገራቸው፦'),
  ('7817b26b-17b4-5e1a-a908-4c973967c148', '4d64b4d4-f3de-5d00-a389-b2924ae78ffa', 'f16d4cb7-d1ca-54ad-ab07-53fbdfa6797b', 3, 24, '“አሮን ወደ ወገኑ ይጨመር፤ በክርክር ውኃ ዘንድ ስለ አሳዘናችሁኝ ለእስራኤል ልጆች ወደ ሰጠኋት ምድር አትገቡም።'),
  ('70a91d20-38dc-50ff-a2bf-932a24af43ba', '4d64b4d4-f3de-5d00-a389-b2924ae78ffa', 'f16d4cb7-d1ca-54ad-ab07-53fbdfa6797b', 4, 25, 'አሮንንና ልጁን አልዓዛርን ይዘህ በማኅበሩ ሁሉ ፊት ወደ ሖር ተራራ ላይ አምጣቸው፤'),
  ('fd97f791-7ebc-5bd5-a1c9-8515f91e1f2a', '4d64b4d4-f3de-5d00-a389-b2924ae78ffa', 'f16d4cb7-d1ca-54ad-ab07-53fbdfa6797b', 5, 26, 'ከአሮንም ልብሱን አውጣ፤ ልጁንም አልዓዛርን አልብሰው፤ አሮንም ወደ ወገኑ ይጨመር፤ በዚያም ይሙት።”'),
  ('50724259-d21c-592d-ad55-3a1f822d2a0e', '4d64b4d4-f3de-5d00-a389-b2924ae78ffa', 'f16d4cb7-d1ca-54ad-ab07-53fbdfa6797b', 6, 27, 'ሙሴም እግዚአብሔር እንዳዘዘ አደረገ፤ በማኅበሩም ሁሉ ፊት እያዩ ወደ ሖር ተራራ አወጣቸው።'),
  ('9537085e-6825-5ae7-a333-48c9def921a5', '4d64b4d4-f3de-5d00-a389-b2924ae78ffa', 'f16d4cb7-d1ca-54ad-ab07-53fbdfa6797b', 7, 28, 'ሙሴም የአሮንን ልብስ አወጣ፤ ልጁንም አልዓዛርን አለበሰው፤ አሮንም በዚያ በተራራው ራስ ላይ ሞተ፤ ሙሴና አልዓዛርም ከተራራው ራስ ላይ ወረዱ።'),
  ('c81aa7b8-732b-50fa-a754-a163e149a502', '4d64b4d4-f3de-5d00-a389-b2924ae78ffa', 'f16d4cb7-d1ca-54ad-ab07-53fbdfa6797b', 8, 29, 'ማኅበሩም ሁሉ አሮን እንደ ሞተ ባዩ ጊዜ፥ የእስራኤል ቤት ሁሉ ለአሮን ሠላሳ ቀን አለቀሱ።'),
  ('94afbae6-b99d-577e-a744-1f2d58ae7ae8', '719e3f97-3df2-565a-af4f-76d1b808c2aa', 'd7e04b2b-cafa-52c4-a5f4-e5d3471041f0', 1, 1, 'በአዜብ በኩል ተቀምጦ የነበረው ከነዓናዊው የአራድ ንጉሥ በአታሪን መንገድ እስራኤል እንደ መጡ ሰማ፤ ከእስራኤልም ጋር ሰልፍ አደረገ ከእነርሱም ምርኮ ማረከ።'),
  ('15ed2d48-1176-591e-a37d-e25ad2cbae0d', '719e3f97-3df2-565a-af4f-76d1b808c2aa', 'd7e04b2b-cafa-52c4-a5f4-e5d3471041f0', 2, 2, 'እስራኤልም ለእግዚአብሔር፥ “ይህን ሕዝብ አሳልፈህ በእጃችን ብትሰጠን እርሱንና ከተሞቹን ሕርም ብለን እናጠፋዋለን” ብለው ስእለት ተሳሉ።'),
  ('b568bfa0-0dca-5093-a4e1-ed5d0a91aef8', '719e3f97-3df2-565a-af4f-76d1b808c2aa', 'd7e04b2b-cafa-52c4-a5f4-e5d3471041f0', 3, 3, 'እግዚአብሔርም የእስራኤልን ድምፅ ሰማ፤ ከነዓናውያንንም አሳልፎ በእጃቸው ሰጣቸው፤ እነርሱንም፥ ከተሞቻቸውንም ሕርም ብለው አጠፉአቸው፤ የዚያን ስፍራ ስም “ሕርም” ብለው ጠሩት።'),
  ('c4c57c77-d7fb-533c-a1b9-d1b51c654604', '719e3f97-3df2-565a-af4f-76d1b808c2aa', 'bb659481-a457-5b3b-a8a9-90432eec01c1', 1, 4, 'ከሖርም ተራራ በኤርትራ ባሕር መንገድ ተጓዙ፤ የኤዶምንም ምድር ዞሩአት፤ ሕዝቡም በመንገድ ተበሳጩ።'),
  ('37517190-253d-5c95-a869-980c1ce0ddcd', '719e3f97-3df2-565a-af4f-76d1b808c2aa', 'bb659481-a457-5b3b-a8a9-90432eec01c1', 2, 5, 'ሕዝቡም፥ “በምድረ በዳ እንሞት ዘንድ ከግብፅ ለምን አወጣኸን?” ብለው እግዚአብሔርንና ሙሴንም አሙ። “እንጀራ የለም፤ ውኃም የለምና፥ ሰውነታችንም ይህን ጥቅም የሌለው እንጀራ ተጸየፈች” ብለው ተናገሩ።'),
  ('d8f272df-5fb1-5702-ad0f-da793b11992a', '719e3f97-3df2-565a-af4f-76d1b808c2aa', 'bb659481-a457-5b3b-a8a9-90432eec01c1', 3, 6, 'እግዚአብሔርም በሕዝቡ ላይ የሚገድሉ እባቦችን ሰደደ፤ ሕዝቡንም ነደፉ፤ ከእስራኤልም ልጆች ብዙ ሰዎች ሞቱ።'),
  ('180551be-5c68-5036-a2c8-556e592aa927', '719e3f97-3df2-565a-af4f-76d1b808c2aa', 'bb659481-a457-5b3b-a8a9-90432eec01c1', 4, 7, 'ሕዝቡም ወደ ሙሴ መጥተው፥ “በእግዚአብሔርና በአንተ ስለ ተናገርን በድለናል፤ እባቦችን ከእኛ ያርቅልን ዘንድ ወደ እግዚአብሔር ጸልይልን” አሉት። ሙሴም ስለ ሕዝቡ ወደ እግዚአብሔር ጸለየ።'),
  ('c8ad73c0-3fc7-5e90-a61b-62305d3be432', '719e3f97-3df2-565a-af4f-76d1b808c2aa', 'bb659481-a457-5b3b-a8a9-90432eec01c1', 5, 8, 'እግዚአብሔርም ሙሴን፥ “የናስ እባብን ሠርተህ በዓላማ ላይ ስቀል፤ እባቡም ሰውን ቢነድፍ የተነደፈው ሁሉ ይመልከተው፤ ይድናልም” አለው።'),
  ('66d2b39b-70fc-54dc-a357-e7bf22114188', '719e3f97-3df2-565a-af4f-76d1b808c2aa', 'bb659481-a457-5b3b-a8a9-90432eec01c1', 6, 9, 'ሙሴም የናሱን እባብ ሠርቶ በዓላማ ላይ ሰቀለ፤ እባብም የነደፈችው ሁሉ የናሱን እባብ ባየ ጊዜ ዳነ።'),
  ('f51b233c-fcd9-5ec0-a2f1-738ffaed06de', '719e3f97-3df2-565a-af4f-76d1b808c2aa', '6b97f731-087e-5d3e-a839-cc23c108c205', 1, 10, 'የእስራኤልም ልጆች ተጓዙ፤ በኦቦትም ሰፈሩ።'),
  ('20742cb8-0e86-50c1-a941-36742a836f45', '719e3f97-3df2-565a-af4f-76d1b808c2aa', '6b97f731-087e-5d3e-a839-cc23c108c205', 2, 11, 'ከኦቦትም ተጕዘው በሞዓብ ፊት ለፊት ባለችው ምድረ በዳ፥ በፀሐይ መውጫ በኩል በጌልጋይ ሰፈሩ።'),
  ('450393c2-6dbd-50f1-a228-cdab61639ec7', '719e3f97-3df2-565a-af4f-76d1b808c2aa', '6b97f731-087e-5d3e-a839-cc23c108c205', 3, 12, 'ከዚያም ተጕዘው በዘሬድ ሸለቆ ሰፈሩ።'),
  ('7fd9bede-5511-5d8f-a52a-93eb733c4e56', '719e3f97-3df2-565a-af4f-76d1b808c2aa', '6b97f731-087e-5d3e-a839-cc23c108c205', 4, 13, 'ከዚያም ተጕዘው ከአሞራውያን ዳርቻ በሚወጣው ምድረ በዳ ውስጥ በአርኖን ማዶ ሰፈሩ፤ አርኖን በሞዓብና በአሞራውያን መካከል ያለ የሞዓብ ዳርቻ ነውና።'),
  ('b861f980-ed3a-5205-a3bb-411d01efe72d', '719e3f97-3df2-565a-af4f-76d1b808c2aa', '6b97f731-087e-5d3e-a839-cc23c108c205', 5, 14, 'ስለዚህ በመጽሐፍ ተባለ የእግዚአብሔር ጦርነት ዞኦብንና የአርኖን ሸለቆዎችን አቃጠለ።'),
  ('3e0f01bb-265d-584e-abad-1f04ded0b2bb', '719e3f97-3df2-565a-af4f-76d1b808c2aa', '6b97f731-087e-5d3e-a839-cc23c108c205', 6, 15, 'ወደ ዒር ማደሪያ የሚወርድ፥ በሞዓብ ዳርቻም የሚጠጋ የሸለቆዎች ፈሳሾችንም አቆመ።'),
  ('ae8051eb-bd04-5304-a2b9-0bba2aafa6d1', '719e3f97-3df2-565a-af4f-76d1b808c2aa', '6b97f731-087e-5d3e-a839-cc23c108c205', 7, 16, 'ከዚያም እግዚአብሔር ሙሴን፥ “ሕዝቡን ሰብስብ፤ የሚጠጡት ውኃ እሰጣቸዋለሁ” ብሎ ወደ ተናገረላት ጕድጓድ ሄዱ።'),
  ('3675b800-6530-5a96-a6e4-5911e8bb073e', '719e3f97-3df2-565a-af4f-76d1b808c2aa', '6b97f731-087e-5d3e-a839-cc23c108c205', 8, 17, 'በዚያም ጊዜ እስራኤል በዚያ ጕድጓድ አጠገብ ይህን መዝሙር ስለ ጕድጓዱ መዘመር ጀመሩ፦'),
  ('65be9367-10cc-5cc1-a7cc-d7e3aaa9279d', '719e3f97-3df2-565a-af4f-76d1b808c2aa', '6b97f731-087e-5d3e-a839-cc23c108c205', 9, 18, '“አለቆች ቈፈሩአት፥'),
  ('253b96b3-7778-502e-abd2-006e82da81e0', '719e3f97-3df2-565a-af4f-76d1b808c2aa', '6b97f731-087e-5d3e-a839-cc23c108c205', 10, 19, 'ከዚያችም ምንጭ ወደ መንተናይን ተጓዙ፤ ከመንተናይንም ወደ ነሃልያል፥ ከነሃልያልም ወደ ባሞት፥'),
  ('d15f411f-92e3-5ff7-a29f-61d9983ec43d', '719e3f97-3df2-565a-af4f-76d1b808c2aa', '6b97f731-087e-5d3e-a839-cc23c108c205', 11, 20, 'ከባሞትም ምድረ በዳውን ከላይ ወደሚመለከተው ወደ ፈስጋ ተራራ ራስ በሞዓብ በረሃ ወዳለው ወደ ያኒን ሸለቆ ተጓዙ።'),
  ('a5a34dd7-3aca-5e8e-a5c6-0451db033279', '719e3f97-3df2-565a-af4f-76d1b808c2aa', 'fbfe0298-97c6-5d01-a4e4-e064cea816ca', 1, 21, 'እስራኤልም ወደ አሞሬዎናውያን ንጉሥ ወደ ሴዎን በሰላም ቃል እንዲህ ብሎ መልእክተኞችን ላከ፤'),
  ('0ce10845-c4e1-5d27-a546-c2858f238040', '719e3f97-3df2-565a-af4f-76d1b808c2aa', 'fbfe0298-97c6-5d01-a4e4-e064cea816ca', 2, 22, '“በምድርህ ላይ እንለፍ፤ በመንገዱም እንሄዳለን፤ ወደ እርሻና ወደ ወይን ቦታ አንገባም፤ ከጕድጓድህም ውኃን አንጠጣም፤ እስክንወጣ ድረስ በንጉሥ ጎዳና እንሄዳለን።”'),
  ('f399879d-ffd4-55c9-a148-f1f5120752e8', '719e3f97-3df2-565a-af4f-76d1b808c2aa', 'fbfe0298-97c6-5d01-a4e4-e064cea816ca', 3, 23, 'ሴዎንም እስራኤል በወሰኑ ላይ ያልፉ ዘንድ አልፈቀደም፤ ሴዎንም ሕዝቡን ሁሉ ሰበሰበ፤ እስራኤልንም ለመውጋት ወደ ምድረ በዳ ወጣ፤ ወደ ኢያሶንም መጣ፤ እስራኤልንም ተዋጋቸው።'),
  ('80ae494d-aa7d-5e3a-a404-77de4efaac57', '719e3f97-3df2-565a-af4f-76d1b808c2aa', 'fbfe0298-97c6-5d01-a4e4-e064cea816ca', 4, 24, 'እስራኤልም በሰይፍ መታው፤ ምድሩንም ከአርኖን ጀምሮ እስከ አሞን ልጆች እስከ ያቦቅ ድረስ ወረሰ፤ የአሞንም ልጆች ዳርቻ ኢያዜር ነበረ።'),
  ('29a9c8ed-796e-5f1e-a207-772df0120b76', '719e3f97-3df2-565a-af4f-76d1b808c2aa', 'fbfe0298-97c6-5d01-a4e4-e064cea816ca', 5, 25, 'እስራኤልም እነዚህን ከተሞች ሁሉ ወሰደ፤ እስራኤልም በአሞራውያን ከተሞች ሁሉ፥ በሐሴቦንና በመንደሮቹ ሁሉ ተቀመጠ።'),
  ('6dbd2be2-2797-56a1-a625-21945e398899', '719e3f97-3df2-565a-af4f-76d1b808c2aa', 'fbfe0298-97c6-5d01-a4e4-e064cea816ca', 6, 26, 'ሐሴቦንም የአሞራውያን ንጉሥ የሴዎን ከተማ ነበረ፤ እርሱም የፊተኛውን የሞዓብን ንጉሥ ወግቶ ከአሮኤር እስከ አርኖን ድረስ ምድሩን ሁሉ ወስዶ ነበር።'),
  ('48575e6a-22d8-5103-a770-a0ca60039c4c', '719e3f97-3df2-565a-af4f-76d1b808c2aa', 'fbfe0298-97c6-5d01-a4e4-e064cea816ca', 7, 27, 'ስለዚህ የምሳሌ ሰዎች እንዲህ ብለው ይናገራሉ፦'),
  ('c3c4ae61-b62b-5aef-a715-6d8c1cc4612b', '719e3f97-3df2-565a-af4f-76d1b808c2aa', 'fbfe0298-97c6-5d01-a4e4-e064cea816ca', 8, 28, 'እሳት ከሐሴቦን፥ ነበልባልም ከሴዎን ከተማ ወጣ፤'),
  ('97d01314-bb3f-5b58-a025-5d3b43f9b882', '719e3f97-3df2-565a-af4f-76d1b808c2aa', 'fbfe0298-97c6-5d01-a4e4-e064cea816ca', 9, 29, 'ሞዓብ ሆይ፥ ወዮልህ!'),
  ('26f51b5f-81c9-59b8-ab3c-c2de4ba552b2', '719e3f97-3df2-565a-af4f-76d1b808c2aa', 'fbfe0298-97c6-5d01-a4e4-e064cea816ca', 10, 30, 'ዘራቸውም ከሐሴቦን እስከ ዴቦን ድረስ ጠፋ፤'),
  ('20a68cc9-d7e9-558a-a3fe-e4c4a7b3cc7e', '719e3f97-3df2-565a-af4f-76d1b808c2aa', 'fbfe0298-97c6-5d01-a4e4-e064cea816ca', 11, 31, 'እስራኤልም በአሞራውያን ከተሞች ተቀመጡ።'),
  ('7607d0e2-d1f5-585b-abe3-cd1d9eaad384', '719e3f97-3df2-565a-af4f-76d1b808c2aa', 'fbfe0298-97c6-5d01-a4e4-e064cea816ca', 12, 32, 'ሙሴም ሰላዮቹን ወደ ኢያዜር ላከ፤ እርስዋንና መንደሮችዋንም ያዙ፤ በዚያም የነበሩትን አሞሬዎናውያንን አባረሩ።'),
  ('b315e166-8b3d-5203-a7be-d0c51a4f393e', '719e3f97-3df2-565a-af4f-76d1b808c2aa', 'fbfe0298-97c6-5d01-a4e4-e064cea816ca', 13, 33, 'ተመልሰውም በባሳን መንገድ ወጡ፤ የባሳንም ንጉሥ ዐግ ከሕዝቡ ሁሉ ጋር በኤድራይን ይወጋቸው ዘንድ ወጣ።'),
  ('d10352d2-5ef1-5656-a70d-8b9e6a224522', '719e3f97-3df2-565a-af4f-76d1b808c2aa', 'fbfe0298-97c6-5d01-a4e4-e064cea816ca', 14, 34, 'እግዚአብሔርም ሙሴን፥ “እርሱንና ሕዝቡን ሁሉ፥ ምድሪቱንም አሳልፌ በእጅህ ሰጥቼሃለሁና አትፍራው፤ በሐሴቦንም በተቀመጠው በአሞሬዎን ንጉሥ በሴዎን እንዳደረግህ እንዲሁ ታደርግበታለህ” አለው።'),
  ('9a154f13-047b-5aab-a83b-fbe5e9f01a41', '719e3f97-3df2-565a-af4f-76d1b808c2aa', 'fbfe0298-97c6-5d01-a4e4-e064cea816ca', 15, 35, 'እርሱንና ልጆቹን፥ ሕዝቡን ሁሉ አንድ ሰው ሳያመልጥ መቱ፤ ምድሩንም ወረሱ።'),
  ('25fad5a2-0749-51b9-a4d6-8229a81ded54', '65d35144-068b-525d-ade4-50e8f0affcc1', '49d8a2f9-92c6-50fa-aa75-d99272aa0199', 1, 1, 'የእስራኤልም ልጆች ተጓዙ፤ በኢያሪኮ በኩል በዮርዳኖስ አጠገብ በሞዓብ ምዕራብም ሰፈሩ።'),
  ('baad931d-3b32-59e1-a959-97415b2efacf', '65d35144-068b-525d-ade4-50e8f0affcc1', '49d8a2f9-92c6-50fa-aa75-d99272aa0199', 2, 2, 'የሴፎር ልጅ ባላቅ እስራኤል በአሞሬዎናውያን ላይ ያደረገውን ሁሉ አየ።'),
  ('611e8749-07ce-511c-a454-e59747436483', '65d35144-068b-525d-ade4-50e8f0affcc1', '49d8a2f9-92c6-50fa-aa75-d99272aa0199', 3, 3, 'ብዙም ነበረና ሞዓብ ከሕዝቡ እጅግ ፈራ፤ ከእስራኤልም ልጆች የተነሣ ሞዓብ ደነገጠ።'),
  ('ee38249b-8802-5f14-a966-d1aa43f4d693', '65d35144-068b-525d-ade4-50e8f0affcc1', '49d8a2f9-92c6-50fa-aa75-d99272aa0199', 4, 4, 'ሞዓብም የምድያምን ሽማግሌዎች፥ “በሬ የለመለመውን ሣር እንደሚጨርስ ይህ ሠራዊት በዙሪያችን ያለውን ሁሉ ይጨርሳል” አላቸው። በዚያን ጊዜ የሶፎር ልጅ ባላቅ የሞዓብ ንጉሥ ነበረ።'),
  ('8d40c4ac-3efa-5dd4-a8a1-ec95af541c71', '65d35144-068b-525d-ade4-50e8f0affcc1', '49d8a2f9-92c6-50fa-aa75-d99272aa0199', 5, 5, 'በወንዙም አጠገብ ባለችው በሕዝቡ ልጆች ምድር በፋቱራ ወደ ተቀመጠው ወደ ቢዖር ልጅ ወደ በለዓም፥ “እነሆ፥ ከግብፅ የወጣ ሕዝብ አለ፤'),
  ('4b8d2c30-355c-58a3-ab6a-e44285ded5c3', '65d35144-068b-525d-ade4-50e8f0affcc1', '49d8a2f9-92c6-50fa-aa75-d99272aa0199', 6, 6, 'እነሆም፥ የምድሩን ሁሉ ፊት ሸፈነ፤ በአቅራቢያችንም ተቀምጦአል፤ አሁንም ይህ ሕዝብ ከእኔ ይበልጣልና ልወጋቸውና ከምድሪቱ ላሳድዳቸው እችል እንደ ሆነ፥ ና ርገምልኝ፤ አንተ የመረቅኸው ምሩቅ፥ የረገምኸውም ርጉም እንደ ሆነ አውቃለሁና” ብሎ ይጠሩት ዘንድ መልእክተኞችን ላከ።'),
  ('ac72c519-e4e9-51bb-a4d1-ee00ce35ed84', '65d35144-068b-525d-ade4-50e8f0affcc1', '49d8a2f9-92c6-50fa-aa75-d99272aa0199', 7, 7, 'የሞዓብ ሽማግሌዎችና የምድያም ሽማግሌዎችም የምዋርቱን ዋጋ በእጃቸው ይዘው ሄዱ፤ ወደ በለዓምም መጡ፤ የባላቅንም ቃል ነገሩት።'),
  ('cf22e0b7-d9a8-5784-a650-826cf1efa09d', '65d35144-068b-525d-ade4-50e8f0affcc1', '49d8a2f9-92c6-50fa-aa75-d99272aa0199', 8, 8, 'እርሱም፥ “ዛሬ ሌሊት በዚህ እደሩ፤ እግዚእብሔርም የሚነግረኝን እነግራችኋለሁ” አላቸው፤ የሞዓብ አለቆችም በበለዓም ዘንድ አደሩ።'),
  ('0f606602-aa7f-5aea-ad97-fa457ed9e337', '65d35144-068b-525d-ade4-50e8f0affcc1', '49d8a2f9-92c6-50fa-aa75-d99272aa0199', 9, 9, 'እግዚአብሔርም ወደ በለዓም መጥቶ፥ “እነዚህ በአንተ ዘንድ ያሉ ሰዎች እነማን ናቸው?” አለው።'),
  ('427ab374-dca9-516f-ab68-23382817e38c', '65d35144-068b-525d-ade4-50e8f0affcc1', '49d8a2f9-92c6-50fa-aa75-d99272aa0199', 10, 10, 'በለዓምም እግዚአብሔርን እንዲህ አለው፥ “የሞዓብ ንጉሥ የሶፎር ልጅ ባላቅ፦ እንዲህ ሲል ወደ እኔ ልኮአቸዋል፤'),
  ('20b49071-268b-5559-ac5f-970129ca1f0f', '65d35144-068b-525d-ade4-50e8f0affcc1', '49d8a2f9-92c6-50fa-aa75-d99272aa0199', 11, 11, 'እነሆ፥ ከግብፅ የወጣ ሕዝብ የምድርን ፊት ሸፈነ፤ በአቅራቢያዬም ተቀምጦአል፤ ምናልባት እወጋው፥ አሳድደውም ዘንድ እችል እንደ ሆነ አሁንም ና እርሱን ርገምልኝ።”'),
  ('acb1b92b-795b-57cd-a9a2-7a0f25d5869b', '65d35144-068b-525d-ade4-50e8f0affcc1', '49d8a2f9-92c6-50fa-aa75-d99272aa0199', 12, 12, 'እግዚአብሔርም በለዓምን፥ “ከእነርሱ ጋር አትሂድ፤ የተባረከ ነውና ሕዝቡን አትርገም” አለው።'),
  ('f0658c6c-bc6b-59ad-a968-3cae7bedacb8', '65d35144-068b-525d-ade4-50e8f0affcc1', '49d8a2f9-92c6-50fa-aa75-d99272aa0199', 13, 13, 'በለዓምም ሲነጋ ተነሥቶ የባላቅን አለቆች፥ “ከእናንተ ጋር እሄድ ዘንድ እግዚአብሔር አልፈቀደልኝምና ወደ ጌታችሁ ሂዱ” አላቸው።'),
  ('cc711db1-8b7b-5e03-af38-648cffdf2903', '65d35144-068b-525d-ade4-50e8f0affcc1', '49d8a2f9-92c6-50fa-aa75-d99272aa0199', 14, 14, 'የሞዓብ አለቆችም ተነሡ፤ ወደ ባላቅም መጥተው፥ “በለዓም ከእኛ ጋር ይመጣ ዘንድ አልፈቀደም” አሉት።'),
  ('426ec4e9-276e-5090-a1c4-9eb7de08912e', '65d35144-068b-525d-ade4-50e8f0affcc1', '49d8a2f9-92c6-50fa-aa75-d99272aa0199', 15, 15, 'ባላቅም ደግሞ ከእነዚያ የበዙና የከበሩ ሌሎችን አለቆች ሰደደ።'),
  ('ef681bd3-7aee-5ce7-a85a-024fa25f6dee', '65d35144-068b-525d-ade4-50e8f0affcc1', '49d8a2f9-92c6-50fa-aa75-d99272aa0199', 16, 16, 'ወደ በለዓምም መጥተው፥ “የሶፎር ልጅ ባላቅ፦ እባክህ ወደ እኔ መምጣትን ቸል አትበል፤'),
  ('d567d6f5-b264-52db-a257-3fb992f0d7d7', '65d35144-068b-525d-ade4-50e8f0affcc1', '49d8a2f9-92c6-50fa-aa75-d99272aa0199', 17, 17, 'ክብርህን እጅግ ታላቅ አደርገዋለሁና፥ የተናገርኸውንም ሁሉ አደርግልሃለሁና ና፥ ይህን ሕዝብ ርገምልኝ ብሏል” አሉት።'),
  ('7fcdcfeb-cabc-5f4a-aaf3-59d06039b08b', '65d35144-068b-525d-ade4-50e8f0affcc1', '49d8a2f9-92c6-50fa-aa75-d99272aa0199', 18, 18, 'በለዓምም መልሶ የባላቅን አለቆች፥ “ባላቅ በቤቱ የሞላውን ወርቅና ብር ቢሰጠኝ፥ በትንሹ ወይም በትልቁ ቢሆን የአምላኬን የእግዚአብሔርን ቃል እተላለፍ ዘንድ አይቻለኝም፤'),
  ('47ee2f62-00bf-5b5a-a5d2-01754b09405c', '65d35144-068b-525d-ade4-50e8f0affcc1', '49d8a2f9-92c6-50fa-aa75-d99272aa0199', 19, 19, 'አሁንም እግዚአብሔር ደግሞ የሚነግረኝን አውቅ ዘንድ ዛሬ ሌሊት ደግሞ በዚህ እደሩ” አላቸው።'),
  ('fdf908e5-af1c-5f68-a89b-513a43eac4a3', '65d35144-068b-525d-ade4-50e8f0affcc1', '49d8a2f9-92c6-50fa-aa75-d99272aa0199', 20, 20, 'እግዚአብሔርም ወደ በለዓም በሌሊት መጥቶ፥ “ሰዎቹ ይጠሩህ ዘንድ መጥተው እንደ ሆነ፥ ተነሣ ከእነርሱ ጋር ሂድ፤ ነገር ግን የምነግርህን ቃል ታደርጋለህ” አለው።'),
  ('c08e9a83-2fbb-5933-afc3-81415e0fac08', '65d35144-068b-525d-ade4-50e8f0affcc1', '4dec9be5-cf1d-542a-a248-c66e9a6ad69f', 1, 21, 'በለዓምም ሲነጋ ተነሣ፤ አህያዪቱንም ጭኖ ከሞዓብ አለቆች ጋር ሄደ።'),
  ('6d7e433f-783c-5317-a32a-829f4ad2bb01', '65d35144-068b-525d-ade4-50e8f0affcc1', '4dec9be5-cf1d-542a-a248-c66e9a6ad69f', 2, 22, 'እርሱም ስለ ሄደ እግዚአብሔር ተቈጣ፤ የእግዚአብሔርም መልአክ ሊያሰናክለው ተነሣ።'),
  ('95c0003b-09c0-5b28-ab9d-677f1de7818a', '65d35144-068b-525d-ade4-50e8f0affcc1', '4dec9be5-cf1d-542a-a248-c66e9a6ad69f', 3, 23, 'እርሱም በአህያዪቱ ላይ ተቀምጦ ነበር፤ ሁለቱም ብላቴናዎቹ ከእርሱ ጋር ነበሩ። አህያዪቱም የእግዚአብሔርን መልአክ በመንገድ ላይ ቆሞ የተመዘዘም ሰይፍ በእጁ ይዞ አየች፤ ከመንገዱም ላይ ፈቀቅ ብላ ወደ ሜዳ ውስጥ ገባች፤ በለዓምም ወደ መንገድ ይመልሳት ዘንድ አህያዪቱን መታት።'),
  ('9785bb99-6a28-5a56-a580-58b582aa3d58', '65d35144-068b-525d-ade4-50e8f0affcc1', '4dec9be5-cf1d-542a-a248-c66e9a6ad69f', 4, 24, 'የእግዚአብሔርም መልአክ ከወይኑ ቦታዎች መካከል በወዲያና በወዲህ ወገን ግንብ በነበረበት ቆመ።'),
  ('7312d1c8-c4dc-5a2e-a91d-f1ba6e8e9b4d', '65d35144-068b-525d-ade4-50e8f0affcc1', '4dec9be5-cf1d-542a-a248-c66e9a6ad69f', 5, 25, 'አህያዪቱም የእግዚአብሔርን መልአክ አይታ ወደ ቅጥሩ ተጠጋች፤ የበለዓምንም እግሩን ላጠችው፤ እርሱም ደግሞ መታት።'),
  ('53ea80f8-a5aa-5dbb-ab69-0bb5ae990356', '65d35144-068b-525d-ade4-50e8f0affcc1', '4dec9be5-cf1d-542a-a248-c66e9a6ad69f', 6, 26, 'የእግዚአብሔርም መልአክ ወደ ፊት ሄደ፤ በቀኝና በግራ መተላለፊያ በሌለበት በጠባብ ስፍራ ቆመ።'),
  ('2446c68b-8e0b-5cb4-a38b-c2e88eea4008', '65d35144-068b-525d-ade4-50e8f0affcc1', '4dec9be5-cf1d-542a-a248-c66e9a6ad69f', 7, 27, 'አህያዪቱም የእግዚአብሔርን መልአክ አየች፤ ከበለዓምም በታች ተኛች፤ በለዓምም ተቈጣ፤ አህያዪቱንም በበትሩ ደበደባት።'),
  ('cc158313-5c84-5fa9-ac78-9c34db3a7ec0', '65d35144-068b-525d-ade4-50e8f0affcc1', '4dec9be5-cf1d-542a-a248-c66e9a6ad69f', 8, 28, 'እግዚአብሔርም የአህያዪቱን አፍ ከፈተ፤ በለዓምንም፥ “ሦስት ጊዜ የመታኸኝ ምን አድርጌብህ ነው?” አለችው።'),
  ('b7846584-707f-5bf5-a361-a1da082b8b12', '65d35144-068b-525d-ade4-50e8f0affcc1', '4dec9be5-cf1d-542a-a248-c66e9a6ad69f', 9, 29, 'በለዓምም አህያዪቱን፥ “ስለዘበትሽብኝ ነው፤ በእጄስ ሰይፍ ቢኖር አሁን በገደልሁሽ ነበር” አላት።'),
  ('838abdc5-9696-5eab-a074-39691a04fe95', '65d35144-068b-525d-ade4-50e8f0affcc1', '4dec9be5-cf1d-542a-a248-c66e9a6ad69f', 10, 30, 'አህያዪቱም በለዓምን፥ “ከወጣትነትህ ጀምሮ እስከ ዛሬ የምትቀመጥብኝ አህያህ አይደለሁምን? በውኑ አንተን ቸል ያልሁበት፥ በአንተም እንዲህ ያደረግሁበት ጊዜ ነበርን?” አለችው። እርሱም፥ “እንዲህ አላደረግሽብኝም” አላት።'),
  ('7f29d048-1d80-5bc9-ac0b-8d4d0de4e991', '65d35144-068b-525d-ade4-50e8f0affcc1', '4dec9be5-cf1d-542a-a248-c66e9a6ad69f', 11, 31, 'እግዚአብሔርም የበለዓምን ዐይኖች ከፈተ፤ የእግዚአብሔርንም መልአክ በመንገድ ላይ ቆሞ፥ የተመዘዘም ሰይፍ በእጁ ይዞ አየ፤ በግንባሩም ወድቆ ሰገደለት።'),
  ('45ace413-4cca-5ef1-ab7d-b9af37df67cd', '65d35144-068b-525d-ade4-50e8f0affcc1', '4dec9be5-cf1d-542a-a248-c66e9a6ad69f', 12, 32, 'የእግዚአብሔርም መልአክ፥ “አህያህን ሦስት ጊዜ ለምን መታህ? እነሆ፥ መንገድህ በፊቴ ቀና አልነበረምና ላሰናክልህ ወጥቼአለሁ፤'),
  ('8f8bb635-4534-5d77-ac3f-21c39d31dcac', '65d35144-068b-525d-ade4-50e8f0affcc1', '4dec9be5-cf1d-542a-a248-c66e9a6ad69f', 13, 33, 'አህያዪቱም አይታኝ ከፊቴ ፈቀቅ አለች፤ ይህም ሦስተኛ ጊዜ ነው፤ ከፊቴስ ፈቀቅ ባላለች በእውነት አሁን አንተን በገደልሁህ፤ እርሷንም ባዳንኋት ነበር” አለው።'),
  ('2ef6089d-8088-531f-aa9f-d3258feb3eda', '65d35144-068b-525d-ade4-50e8f0affcc1', '4dec9be5-cf1d-542a-a248-c66e9a6ad69f', 14, 34, 'በለዓምም የእግዚአብሔርን መልአክ፥ “በድያለሁ፤ አንተ በመንገድ ላይ በፊቴ እንደ ቆምህብኝ አላወቅሁም፤ እንግዲህ አሁን አትወድድ እንደሆነ እመለሳለሁ” አለው።'),
  ('82369ed7-ee2f-5863-a819-e3d88ef93e3f', '65d35144-068b-525d-ade4-50e8f0affcc1', '4dec9be5-cf1d-542a-a248-c66e9a6ad69f', 15, 35, 'የእግዚእብሔርም መልአክ በለዓምን፥ “ከሰዎቹ ጋር ሂድ፤ ነገር ግን የምናገርህን ቃል ብቻ ለመናገር ተጠንቀቅ” አለው። በለዓምም ከባላቅ አለቆች ጋር ሄደ።'),
  ('e10cc9dd-d454-5b3e-ae94-7db0a9aaac9c', '65d35144-068b-525d-ade4-50e8f0affcc1', '4dec9be5-cf1d-542a-a248-c66e9a6ad69f', 16, 36, '“ባላቅም በለዓም እንደ መጣ በሰማ ጊዜ ከዳርቻዎች በአንደኛ ክፍል በአለችው በአርኖን ዳርቻ ወደ አለችው ወደ ሞዓብ ከተማ ሊገናኘው ወጣ።'),
  ('6516210a-d486-5a52-a4b4-455c3f890da4', '65d35144-068b-525d-ade4-50e8f0affcc1', '4dec9be5-cf1d-542a-a248-c66e9a6ad69f', 17, 37, 'ባላቅም በለዓምን፥ “አንተን ለመጥራት የላክሁብህ አይደለምን? ለምንስ ወደ እኔ አልመጣህም? አንተን ለማክበር እኔ አልችልምን?” አለው።'),
  ('2f2bf5c6-8e7b-5812-ae2a-09ed29984e7b', '65d35144-068b-525d-ade4-50e8f0affcc1', '4dec9be5-cf1d-542a-a248-c66e9a6ad69f', 18, 38, 'በለዓምም ባላቅን፥ “እነሆ፥ ወደ አንተ መጥቼአለሁ፤ አሁን አንዳችን ነገር ለመናገር እችላለሁን? እግዚአብሔር በአፌ የሚያደርገውን ቃል እርሱን እናገራለሁ” አለው።'),
  ('84962f44-701a-5926-a837-31b662747f38', '65d35144-068b-525d-ade4-50e8f0affcc1', '4dec9be5-cf1d-542a-a248-c66e9a6ad69f', 19, 39, 'በለዓምም ከባላቅ ጋር ሄደ፤ ወደ ቅጽር ግቢውም ገቡ።'),
  ('b41d88fa-324c-5330-a33e-418ef0543540', '65d35144-068b-525d-ade4-50e8f0affcc1', '4dec9be5-cf1d-542a-a248-c66e9a6ad69f', 20, 40, 'ባላቅም በሬዎችንና በጎችን አርዶ ወደ በለዓም፥ ከእርሱም ጋር ወዳሉት አለቆች ላከ።'),
  ('b932a2c4-3323-5d8d-aa32-97a864b64a91', '65d35144-068b-525d-ade4-50e8f0affcc1', '4dec9be5-cf1d-542a-a248-c66e9a6ad69f', 21, 41, 'በነጋውም ባላቅ በለዓምን ይዞ ወደ በአል ኮረብታ አወጣው፤ በዚያም ሆኖ የሕዝቡን አንድ ወገን አሳየው።'),
  ('736f57c0-df25-5694-ad46-5b8fd93f6aa1', 'dd8e715a-c55e-582d-a2ae-4f89b48a800c', '3239fe6a-b873-5e87-a786-a8a2b4f35ac8', 1, 1, 'በለዓምም ባላቅን፥ “ሰባት መሠዊያ በዚህ ሥራልኝ፤ ሰባትም ወይፈን፥ ሰባትም አውራ በግ በዚህ አዘጋጅልኝ” አለው።'),
  ('dbc70aa7-9980-5d1e-aa0c-0ad48a28bf2c', 'dd8e715a-c55e-582d-a2ae-4f89b48a800c', '3239fe6a-b873-5e87-a786-a8a2b4f35ac8', 2, 2, 'ባላቅም በለዓም እንደ ተናገረ አደረገ፤ በየመሠዊያው ላይ አንድ ወይፈንና አንድ አውራ በግ አሳረገ።'),
  ('7b961aaf-7ac1-5cd8-a846-e09162a8b1e7', 'dd8e715a-c55e-582d-a2ae-4f89b48a800c', '3239fe6a-b873-5e87-a786-a8a2b4f35ac8', 3, 3, 'በለዓምም ባላቅን፥ “በመሥዋዕትህ ዘንድ ቈይ፤ እኔ እግዚአብሔር ቢገለጥልኝ፥ ቢገናኘኝም እሄዳለሁ፤ የሚገልጥልኝንም ቃል እነግርሃለሁ” አለው። ባላቅም በመሠዊያው ዘንድ ቆመ፤ በለዓም ግን እግዚአብሔርን ይጠይቅ ዘንድ አቅንቶ ሄደ።'),
  ('1eed421c-f932-56fb-a24d-0c3e51520ea0', 'dd8e715a-c55e-582d-a2ae-4f89b48a800c', '3239fe6a-b873-5e87-a786-a8a2b4f35ac8', 4, 4, 'እግዚአብሔርም ለበለዓም ታየው፤ በለዓምም ለእግዚአብሔር፥ “እነሆ፥ ሰባት መሠዊያዎች አዘጋጀሁ፤ በየመሠዊያውም ላይ አንድ ወይፈንና አንድ አውራ በግ አሳረግሁ” አለው።'),
  ('b5f77c43-9a95-56d2-ac4c-3c3b425251f7', 'dd8e715a-c55e-582d-a2ae-4f89b48a800c', '3239fe6a-b873-5e87-a786-a8a2b4f35ac8', 5, 5, 'እግዚአብሔርም በበለዓም አፍ ቃልን አኖረ፤ “ወደ ባላቅ ተመለስ፤ እንዲህም በል” አለው።'),
  ('bada428c-8b9d-5091-a458-68cb0f10007c', 'dd8e715a-c55e-582d-a2ae-4f89b48a800c', '3239fe6a-b873-5e87-a786-a8a2b4f35ac8', 6, 6, 'ወደ እርሱም ተመለሰ፤ እነሆም፥ እርሱና የሞዓብ አለቆች ሁሉ በመሥዋዕቱ ዘንድ ቆመው ነበር፤ የእግዚአብሔርም መንፈስ ወደ እርሱ መጣ፤'),
  ('930e2cb6-ae7b-533e-ad9a-4829a27ac66d', 'dd8e715a-c55e-582d-a2ae-4f89b48a800c', '3239fe6a-b873-5e87-a786-a8a2b4f35ac8', 7, 7, 'በምሳሌም ይናገር ጀመር፤ እንዲህም አለ፦'),
  ('71747b11-04e5-5db2-aa60-66c2fc714303', 'dd8e715a-c55e-582d-a2ae-4f89b48a800c', '3239fe6a-b873-5e87-a786-a8a2b4f35ac8', 8, 8, 'እግዚአብሔር ያልረገመውን እንዴት እረግማለሁ?'),
  ('5ff7c8de-6327-5735-a803-723f7d4ea391', 'dd8e715a-c55e-582d-a2ae-4f89b48a800c', '3239fe6a-b873-5e87-a786-a8a2b4f35ac8', 9, 9, 'በተራሮች ራስ ላይ ሆኜ አየዋለሁ፤'),
  ('2cb792b1-2ecc-51b7-a7a5-eed4a6d0857a', 'dd8e715a-c55e-582d-a2ae-4f89b48a800c', '3239fe6a-b873-5e87-a786-a8a2b4f35ac8', 10, 10, 'የያዕቆብን ዘር ማን ያውቀዋል?'),
  ('6ab9395d-a808-5c95-aa86-ecde1639bcd5', 'dd8e715a-c55e-582d-a2ae-4f89b48a800c', '3239fe6a-b873-5e87-a786-a8a2b4f35ac8', 11, 11, 'ባላቅም በለዓምን፥ “ያደረግኽብኝ ምንድን ነው? ጠላቶችን ትረግምልኝ ዘንድ ጠራሁህ፤ እነሆም፥ መባረክን ባረክሃቸው” አለው።'),
  ('6244aa76-6da7-5ff7-aa77-4f5eac5998d5', 'dd8e715a-c55e-582d-a2ae-4f89b48a800c', '3239fe6a-b873-5e87-a786-a8a2b4f35ac8', 12, 12, 'በለዓምም ባላቅን መልሶ፥ “በውኑ እግዚአብሔር በአፌ ያደረገውን እናገር ዘንድ የምጠነቀቅ አይደለምን?”'),
  ('94142156-f5ac-5da8-abb4-c43535140401', 'dd8e715a-c55e-582d-a2ae-4f89b48a800c', 'fae5511b-f49c-5189-a1f2-aec2d77ec649', 1, 13, 'ባላቅም፥ “በዚያ እነርሱን ወደማታይበት ወደ ሌላ ቦታ እባክህ፥ ከእኔ ጋር ና፤ ከእነርሱ አንዱን ወገን ብቻ ታያለህ፤ ሁሉን ግን አታይም፤ በዚያም እነርሱን ርገምልኝ” አለው።'),
  ('53227599-000f-5bac-a6e5-28564e1cb790', 'dd8e715a-c55e-582d-a2ae-4f89b48a800c', 'fae5511b-f49c-5189-a1f2-aec2d77ec649', 2, 14, 'በሜዳ ወደ ተገነባ ግንብ ራስ ላይም ወሰደው፤ አዞረውም፤ ሰባትም መሠዊያዎች ሠራ፤ በየመሠዊያውም ላይ አንድ ወይፈን፥ አንድም አውራ በግ አሳረገ።'),
  ('97eec87a-1b72-57aa-a1b5-b5da44d36f08', 'dd8e715a-c55e-582d-a2ae-4f89b48a800c', 'fae5511b-f49c-5189-a1f2-aec2d77ec649', 3, 15, 'በለዓምም ባላቅን አለው፥ “በዚህ በመሥዋዕትህ ዘንድ ቈይ፤ እኔም እግዚአብሔርን እጠይቅ ዘንድ እሄዳለሁ።”'),
  ('7945fb38-62a0-5fbb-a7f0-0456dd22c0ec', 'dd8e715a-c55e-582d-a2ae-4f89b48a800c', 'fae5511b-f49c-5189-a1f2-aec2d77ec649', 4, 16, 'እግዚአብሔርም በለዓምን ተገናኘው፤ ቃልንም በአፉ አኖረ፥ “ወደ ባላቅ ተመለስ፤ እንዲህም በለው።”'),
  ('e2f2bf2c-9b60-5528-af41-1f8a1f085ac7', 'dd8e715a-c55e-582d-a2ae-4f89b48a800c', 'fae5511b-f49c-5189-a1f2-aec2d77ec649', 5, 17, 'ወደ እርሱም መጣ፤ እነሆ፥ እርሱ ከእርሱም ጋር የሞዓብ አለቆች በመሥዋዕቱ ዘንድ ቆመው ነበር፤ ባላቅም በለዓምን አለው፥ “እግዚአብሔር ምን አለ?”'),
  ('9111d387-0c65-5557-a058-b6384597266f', 'dd8e715a-c55e-582d-a2ae-4f89b48a800c', 'fae5511b-f49c-5189-a1f2-aec2d77ec649', 6, 18, 'በምሳሌም ይናገር ጀመር፤ እንዲህም አለ፦'),
  ('7142e5eb-bbb6-5540-aa81-f5d5fc3fb1ed', 'dd8e715a-c55e-582d-a2ae-4f89b48a800c', 'fae5511b-f49c-5189-a1f2-aec2d77ec649', 7, 19, 'እግዚአብሔር እንደ ሰው የሚታለል አይደለም።'),
  ('75ffeb0c-deba-598a-a26c-252d769d9580', 'dd8e715a-c55e-582d-a2ae-4f89b48a800c', 'fae5511b-f49c-5189-a1f2-aec2d77ec649', 8, 20, 'እነሆ፥ መጥቻለሁ፤ እባርካለሁ፤ አልመለስምም፤'),
  ('343fd532-56f3-5ccf-a788-f1797f485923', 'dd8e715a-c55e-582d-a2ae-4f89b48a800c', 'fae5511b-f49c-5189-a1f2-aec2d77ec649', 9, 21, 'በያዕቆብ ላይ ድካም የለም፤'),
  ('ff8663f6-1408-5cfd-a8ef-5e36ef39bd2c', 'dd8e715a-c55e-582d-a2ae-4f89b48a800c', 'fae5511b-f49c-5189-a1f2-aec2d77ec649', 10, 22, 'እግዚአብሔር ከግብፅ ያወጣው እርሱ'),
  ('17411fb3-1521-560b-aebb-c979778fb80d', 'dd8e715a-c55e-582d-a2ae-4f89b48a800c', 'fae5511b-f49c-5189-a1f2-aec2d77ec649', 11, 23, 'በያዕቆብ ላይ ጥንቆላ የለም፤'),
  ('097ed1cd-b284-5455-ae98-e4aed767dd0b', 'dd8e715a-c55e-582d-a2ae-4f89b48a800c', 'fae5511b-f49c-5189-a1f2-aec2d77ec649', 12, 24, 'እነሆ፥ ሕዝቡ እንደ አንበሳ ደቦል ያገሣል፤'),
  ('b4d0658e-6347-57d2-a371-0a32350b7aca', 'dd8e715a-c55e-582d-a2ae-4f89b48a800c', 'fae5511b-f49c-5189-a1f2-aec2d77ec649', 13, 25, 'ባላቅም በለዓምን አለው፥ “ከቶ አትርገማቸው፤ ከቶም አትባርካቸው።”'),
  ('99e004cc-8337-5bdc-ae1a-db168f3dee1c', 'dd8e715a-c55e-582d-a2ae-4f89b48a800c', 'fae5511b-f49c-5189-a1f2-aec2d77ec649', 14, 26, 'በለዓምም መልሶ ባላቅን አለው፥ “እግዚአብሔር የተናገረኝን ቃል ሁሉ አደርጋለሁ ብዬ አልተናገርሁህምን?”'),
  ('7455f96b-7467-5ed6-aacf-2c5d3f37ace8', 'dd8e715a-c55e-582d-a2ae-4f89b48a800c', '1e58e877-3ccb-50fe-aa5b-b180c816f0ad', 1, 27, 'ባላቅም በለዓምን አለው፥ “ና፥ ወደ ሌላ ስፍራ እወስድሃለሁ፤ ምናልባት በዚህ ሆነህ እነርሱን ትረግምልኝ ዘንድ እግዚአብሔር ይወድድ ይሆናል።”'),
  ('71bc2be8-9c6d-5a49-a3ba-a5090d9488de', 'dd8e715a-c55e-582d-a2ae-4f89b48a800c', '1e58e877-3ccb-50fe-aa5b-b180c816f0ad', 2, 28, 'ባላቅም በለዓምን በምድረ በዳ ወደ ተከበበው ወደ ፌጎር ተራራ ወሰደው።'),
  ('d0673eda-f329-5da3-a7e3-1ff36cf358e4', 'dd8e715a-c55e-582d-a2ae-4f89b48a800c', '1e58e877-3ccb-50fe-aa5b-b180c816f0ad', 3, 29, 'በለዓምም ባላቅን፥ “በዚህ ሰባት መሠዊያዎች ሥራልኝ፤ በዚህም ሰባት ወይፈን፥ ሰባትም አውራ በግ አዘጋጅልኝ” አለው።'),
  ('43fe445a-abf1-5172-a367-d5005d95c95b', 'dd8e715a-c55e-582d-a2ae-4f89b48a800c', '1e58e877-3ccb-50fe-aa5b-b180c816f0ad', 4, 30, 'ባላቅም በለዓም እንዳለው አደረገ፤ በየመሠዊያውም ላይ አንድ ወይፈንና አንድ አውራ በግ አሳረገ።'),
  ('e6cb1b0a-b324-5893-a6b5-1cf4ecb9dd4c', '88aeedb0-a7fa-5a10-ab7e-ffef5747350b', 'c1360014-2cd8-553f-acae-cd7df2dbdcc6', 1, 1, 'በለዓምም እስራኤልን መባረክ በእግዚአብሔር ፊት መልካም እንደ ሆነ ባየ ጊዜ፥ እንደ ልማዱ ለማሟረት ወደ ፊት አልሄደም፤ ነገር ግን ወደ ምድረ በዳ ፊቱን መለሰ።'),
  ('c7031360-1b75-5048-a70c-eb415d5f2251', '88aeedb0-a7fa-5a10-ab7e-ffef5747350b', 'c1360014-2cd8-553f-acae-cd7df2dbdcc6', 2, 2, 'በለዓምም ዐይኑን አንሥቶ እስራኤል በየነገዳቸው ሲጓዙ አየ፤ የእግዚአብሔርም መንፈስ በላዩ መጣ።'),
  ('468d8c2d-0421-5be3-a966-49e9c931af73', '88aeedb0-a7fa-5a10-ab7e-ffef5747350b', 'c1360014-2cd8-553f-acae-cd7df2dbdcc6', 3, 3, 'በምሳሌም ይናገር ጀመር፤ እንዲህም አለ፥ “የቢዖር ልጅ በለዓም እንዲህ ይላል፥ በትክክል የሚያይ ሰው እንዲህ ይላል፤'),
  ('750ca917-c306-5b77-a876-ee06eea18703', '88aeedb0-a7fa-5a10-ab7e-ffef5747350b', 'c1360014-2cd8-553f-acae-cd7df2dbdcc6', 4, 4, '“የእግዚአብሔርን ቃል የሚሰማ፥'),
  ('82e8956b-f04c-521f-aaa5-4f5eca303835', '88aeedb0-a7fa-5a10-ab7e-ffef5747350b', 'c1360014-2cd8-553f-acae-cd7df2dbdcc6', 5, 5, 'ያዕቆብ ሆይ፥ ቤቶችህ፥'),
  ('dab58c1f-4509-5f70-a789-8ad2db6fff05', '88aeedb0-a7fa-5a10-ab7e-ffef5747350b', 'c1360014-2cd8-553f-acae-cd7df2dbdcc6', 6, 6, 'እንደሚጋርዱ ዛፎች፥'),
  ('df53a6ea-5789-5226-ab64-9ff86d550573', '88aeedb0-a7fa-5a10-ab7e-ffef5747350b', 'c1360014-2cd8-553f-acae-cd7df2dbdcc6', 7, 7, 'ከዘሩ ሰው ይወጣል፤'),
  ('ef85b0a6-0727-5924-aeac-986fe60141ed', '88aeedb0-a7fa-5a10-ab7e-ffef5747350b', 'c1360014-2cd8-553f-acae-cd7df2dbdcc6', 8, 8, 'እግዚአብሔር ከግብፅ መርቶ አውጥቶታል፤'),
  ('355d360c-23ef-5def-a107-99901c3c58af', '88aeedb0-a7fa-5a10-ab7e-ffef5747350b', 'c1360014-2cd8-553f-acae-cd7df2dbdcc6', 9, 9, 'አርፎአል፥'),
  ('6d334fc4-9355-52c6-a63f-ce9dad28c924', '88aeedb0-a7fa-5a10-ab7e-ffef5747350b', 'c1360014-2cd8-553f-acae-cd7df2dbdcc6', 10, 10, 'ባላቅም በበለዓም ላይ ተቈጣ፤ እጆቹንም አጨበጨበ፤ ባላቅም በለዓምን አለው፦ ጠላቶችን ትረግም ዘንድ ጠራሁህ፥'),
  ('9cf634ac-2321-5b9e-aab8-e04a594ce941', '88aeedb0-a7fa-5a10-ab7e-ffef5747350b', 'c1360014-2cd8-553f-acae-cd7df2dbdcc6', 11, 11, 'እነሆም፥ ፈጽመህ መረቅሃቸው፤ ይህ ሦስተኛህ ነው፤ አሁንም እንግዲህ ወደ ስፍራህ ሂድ፤ እኔ አከብርሃለሁ ብዬ ነበር፤ እግዚአብሔር ግን እነሆ፥ ክብርህን ከለከለ።”'),
  ('26e9ad29-00a1-5859-a295-6756c92c4cc4', '88aeedb0-a7fa-5a10-ab7e-ffef5747350b', 'c1360014-2cd8-553f-acae-cd7df2dbdcc6', 12, 12, 'በለዓምም ባላቅን አለው፦'),
  ('38dcbeac-734c-5d8b-a5b6-f3c66465cc95', '88aeedb0-a7fa-5a10-ab7e-ffef5747350b', 'c1360014-2cd8-553f-acae-cd7df2dbdcc6', 13, 13, 'ባላቅ በቤቱ የሞላውን ብርና ወርቅ ቢሰጠኝ፥ መልካሙን ወይም ክፉውን ከልቤ ለማድረግ የእግዚአብሔርን ቃል እተላለፍ ዘንድ አይቻለኝም፤ እግዚአብሔር የተናገረውን እርሱን እናገራለሁ ብዬ ወደ እኔ ለላክሃቸው መልእክተኞችህ አልተናገርኋቸውምን?'),
  ('53e40e15-070d-551e-ac97-60969c734a63', '88aeedb0-a7fa-5a10-ab7e-ffef5747350b', 'c1360014-2cd8-553f-acae-cd7df2dbdcc6', 14, 14, 'አሁንም፥ እነሆ፥ ወደ ሕዝቤ እሄዳለሁ፤ ና፥ ይህ ሕዝብ በኋለኛው ዘመን በሕዝብህ ላይ የሚያደርገውን እነግርሃለሁ።”'),
  ('f09a2686-bb18-52cf-aabc-5457ecbf61e4', '88aeedb0-a7fa-5a10-ab7e-ffef5747350b', 'd6e3e68f-c61f-5a26-af0e-09181f7d86c4', 1, 15, 'በምሳሌም ይናገር ጀመር፥ እንዲህም አለ፦'),
  ('c3898e24-4c88-581f-ab98-cd0fe7ca2dcd', '88aeedb0-a7fa-5a10-ab7e-ffef5747350b', 'd6e3e68f-c61f-5a26-af0e-09181f7d86c4', 2, 16, 'የእግዚአብሔርን ቃል የሚሰማ፥'),
  ('af8da82d-83bc-5536-ae48-164ac42dd489', '88aeedb0-a7fa-5a10-ab7e-ffef5747350b', 'd6e3e68f-c61f-5a26-af0e-09181f7d86c4', 3, 17, 'አየዋለሁ፥ አሁን ግን አይደለም፤'),
  ('b8748087-52d0-5266-afaf-2bc8173ea2e2', '88aeedb0-a7fa-5a10-ab7e-ffef5747350b', 'd6e3e68f-c61f-5a26-af0e-09181f7d86c4', 4, 18, 'ኤዶምያስም ርስቱ ይሆናል፤'),
  ('f4730c63-1cc9-5c53-ab8a-e1aadc08def1', '88aeedb0-a7fa-5a10-ab7e-ffef5747350b', 'd6e3e68f-c61f-5a26-af0e-09181f7d86c4', 5, 19, 'ከያዕቆብም ኀያል ሰው ይወጣል፤'),
  ('ffc1b91f-f2d0-5b80-a8d3-5dbf091ba307', '88aeedb0-a7fa-5a10-ab7e-ffef5747350b', 'd6e3e68f-c61f-5a26-af0e-09181f7d86c4', 6, 20, 'ዐማሌቅንም አይቶ በምሳሌ ይናገር ጀመር፤ እንዲህም አለ፦'),
  ('1dcbdde0-f88c-5a8b-a969-c97907548c6c', '88aeedb0-a7fa-5a10-ab7e-ffef5747350b', 'd6e3e68f-c61f-5a26-af0e-09181f7d86c4', 7, 21, 'ቄኔዎናውያንንም አይቶ በምሳሌ ይናገር ጀመር፤ እንዲህም አለ፦'),
  ('b4d8f97c-f298-5427-a889-891bb29857f8', '88aeedb0-a7fa-5a10-ab7e-ffef5747350b', 'd6e3e68f-c61f-5a26-af0e-09181f7d86c4', 8, 22, 'ቢዖር የጥፋት ጎጆ ቢሆንም አሦር ይማርክሃል።”'),
  ('fd264a41-d901-5fb5-a7c5-a6fad51a63e0', '88aeedb0-a7fa-5a10-ab7e-ffef5747350b', 'd6e3e68f-c61f-5a26-af0e-09181f7d86c4', 9, 23, 'አግንም ባየው ጊዜ በምሳሌ ይናገር ጀመር፤ እንዲህም አለ፦'),
  ('3aea95d3-a9c3-5dfb-a0e0-2a96254ef274', '88aeedb0-a7fa-5a10-ab7e-ffef5747350b', 'd6e3e68f-c61f-5a26-af0e-09181f7d86c4', 10, 24, 'ከቄጤዎንም እጅ የሚወጣው'),
  ('bbe69cf1-dfbf-51da-ad65-309625f7c5ef', '88aeedb0-a7fa-5a10-ab7e-ffef5747350b', 'd6e3e68f-c61f-5a26-af0e-09181f7d86c4', 11, 25, 'በለዓምም ተነሣ፤ ተመልሶም ወደ ስፍራው ሄደ፤ ባላቅም ደግሞ ወደ ቤቱ ገባ።'),
  ('df8b99e1-2055-5941-a8f9-1be076614bd0', '0e4a23b8-d724-5c1b-ae4a-59d083822151', 'a65badc1-3c9d-5145-abbf-e156a17b5be8', 1, 1, 'እስራኤልም በሰጢን አደሩ፤ ሕዝቡም ከሞዓብ ልጆች ጋር አመነዘሩ፤ ረከሱም።'),
  ('d209fa95-7238-5e49-a790-c79722b61d94', '0e4a23b8-d724-5c1b-ae4a-59d083822151', 'a65badc1-3c9d-5145-abbf-e156a17b5be8', 2, 2, 'ሕዝቡንም ወደ አምላኮቻቸው መሥዋዕት ጠሩ፤ ሕዝቡም መሥዋዕታቸውን በሉ፤ ለአምላኮቻቸውም ሰገዱ።'),
  ('6e814497-52c9-5fcd-ac17-48ab5fdded62', '0e4a23b8-d724-5c1b-ae4a-59d083822151', 'a65badc1-3c9d-5145-abbf-e156a17b5be8', 3, 3, 'እስራኤልም ለብዔል ፌጎር ራሳቸውን ለዩ፤ እግዚአብሔርም በእስራኤል ላይ ፈጽሞ ተቈጣ።'),
  ('2c6e7126-7ba2-56d7-aeae-4981e2b84145', '0e4a23b8-d724-5c1b-ae4a-59d083822151', 'a65badc1-3c9d-5145-abbf-e156a17b5be8', 4, 4, 'እግዚአብሔርም ሙሴን አለው፥ “የእግዚአብሔርን ትእዛዝ ስላፈረሱ የሕዝቡን አለቆች ሁሉ ወስደህ በፀሐይ ፊት ቅጣቸው። የእግዚአብሔርም ቍጣ ከእስራኤል ይርቃል።”'),
  ('7947ae7d-1a3f-5620-a289-5620954cd86a', '0e4a23b8-d724-5c1b-ae4a-59d083822151', 'a65badc1-3c9d-5145-abbf-e156a17b5be8', 5, 5, 'ሙሴም የእስራኤልን ሕዝቦች፥ “እናንተ እያንዳንዳችሁ ብዔል ፌጎርን የተከተሉትን ሰዎቻችሁን ግደሉ” አላቸው።'),
  ('ffec3988-2b9f-5b45-a508-576444a3c284', '0e4a23b8-d724-5c1b-ae4a-59d083822151', 'a65badc1-3c9d-5145-abbf-e156a17b5be8', 6, 6, 'እነሆም፥ ከእስራኤል ልጆች አንዱ መጥቶ በሙሴና በእስራኤል ልጆች ማኅበር ሁሉ ፊት ወንድሙን ወደ ምድያማዊት ሴት ወሰደው፤ እነርሱም በምስክሩ ድንኳን ዳጃፍ ያለቅሱ ነበር።'),
  ('de38be08-dd7b-5988-ad2d-d7b6c4a2ec61', '0e4a23b8-d724-5c1b-ae4a-59d083822151', 'a65badc1-3c9d-5145-abbf-e156a17b5be8', 7, 7, 'የካህኑም የአሮን ልጅ የአልዓዛር ልጅ ፊንሐስ ባየው ጊዜ ከማኅበሩ መካከል ተነሥቶ በእጁ ጦር አነሣ።'),
  ('06d07df2-3d82-520d-a3de-ec369dc4dca6', '0e4a23b8-d724-5c1b-ae4a-59d083822151', 'a65badc1-3c9d-5145-abbf-e156a17b5be8', 8, 8, 'ያንም የእስራኤልን ሰው ተከትሎ ወደ ድንኳኑ ገባ። ሁለቱንም እስራኤላዊውን ሰውና ምድያማዊቱን ሴት ሆዳቸውን ወጋቸው፤ ከእስራኤልም ልጆች መቅሠፍቱ ተወገደ።'),
  ('86337063-bc4e-583c-a898-3643ea55a98c', '0e4a23b8-d724-5c1b-ae4a-59d083822151', 'a65badc1-3c9d-5145-abbf-e156a17b5be8', 9, 9, 'በመቅሠፍቱም የሞቱት ሃያ አራት ሺህ ነበሩ።'),
  ('b1157e96-50e2-59f2-af69-ff7ad3ebb1fa', '0e4a23b8-d724-5c1b-ae4a-59d083822151', 'a65badc1-3c9d-5145-abbf-e156a17b5be8', 10, 10, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('c7c20352-0977-5b77-a301-10aff6854991', '0e4a23b8-d724-5c1b-ae4a-59d083822151', 'a65badc1-3c9d-5145-abbf-e156a17b5be8', 11, 11, '“የካህኑ የአሮን ልጅ የአልዓዛር ልጅ ፊንሐስ በቅንዓቴ በመካከላቸው ቀንቶአልና ቍጣዬን ከእስራኤል ልጆች መለሰ፤ እኔም የእስራኤልን ልጆች በቅንዓቴ አላጠፋሁም።'),
  ('b0bad0b6-4d62-5a2d-a318-d33be7b8f3d9', '0e4a23b8-d724-5c1b-ae4a-59d083822151', 'a65badc1-3c9d-5145-abbf-e156a17b5be8', 12, 12, 'ስለዚህ አልሁ፦ እነሆ፥ የሰላሜን ቃል ኪዳን እሰጠዋለሁ።'),
  ('bc278d1a-1b8f-5fb1-ab11-671727ff692f', '0e4a23b8-d724-5c1b-ae4a-59d083822151', 'a65badc1-3c9d-5145-abbf-e156a17b5be8', 13, 13, 'ለአምላኩ ቀንቶአልና፥ ለእስራኤልም ልጆች አስተስርዮአልና፥ ለእርሱ ከእርሱም በኋላ ለዘሩ ለዘለዓለም የክህነት ቃል ኪዳን ይሆንለታል።”'),
  ('853dc61d-0911-56d0-ab13-65f0ce09fb40', '0e4a23b8-d724-5c1b-ae4a-59d083822151', 'a65badc1-3c9d-5145-abbf-e156a17b5be8', 14, 14, 'ከምድያማዊቱም ጋር የተገደለው የእስራኤላዊው ሰው ስም ዘንበሪ ነበረ፤ የአባቱ ቤት አለቃ የስምዖናውያን የሆነ የሰሉ ልጅ ነበረ።'),
  ('847b9575-7a45-5548-a718-d53545c24ce3', '0e4a23b8-d724-5c1b-ae4a-59d083822151', 'a65badc1-3c9d-5145-abbf-e156a17b5be8', 15, 15, 'የተገደለችውም ምድያማዊት ስምዋ ከስቢ ነበረ፤ እርስዋም የሱር ልጅ ነበረች፤ እርሱም የምድያም አባቶች ወገን የሚሆን የሳሞት ወገን አለቃ ነበረ።'),
  ('65afacd2-3d86-5567-a842-fbf1d3e0120a', '0e4a23b8-d724-5c1b-ae4a-59d083822151', 'a65badc1-3c9d-5145-abbf-e156a17b5be8', 16, 16, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፥ “ለእስራኤል ልጆች እንዲህ ብለህ ንገራቸው፦'),
  ('1631243b-97a6-54c6-acec-6a8d4a95c996', '0e4a23b8-d724-5c1b-ae4a-59d083822151', 'a65badc1-3c9d-5145-abbf-e156a17b5be8', 17, 17, 'ምድያማውያንን አስጨንቋቸው፤ ግደሉአቸውም።'),
  ('73c15b0e-3573-5e99-af60-f34fe1756a96', '0e4a23b8-d724-5c1b-ae4a-59d083822151', 'a65badc1-3c9d-5145-abbf-e156a17b5be8', 18, 18, 'ስለ ምድያም አለቃ ልጅ ስለ እኅታቸው ስለ ከስቢ በፌጎር ምክንያት በሸነገሉአችሁ ሽንገላ አስጨንቀዋችኋልና።”'),
  ('40b2d2b8-d572-5cfc-ae33-010e4d46bb54', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 1, 1, 'እንዲህም ሆነ፦ መቅሠፍቱ ከሆነ በኋላ እግዚአብሔር ሙሴንና ካህኑን አልዓዛርን እንዲህ ብሎ ተናገራቸው፦'),
  ('3154199c-2e5d-566b-a927-d1151eb3478c', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 2, 2, '“ከሃያ ዓመት ጀምሮ ከዚያም በላይ ያለውን፥ ከእስራኤል ወደ ሰልፍ የሚወጣውን ሁሉ፥ የእስራኤልን ልጆች ማኅበር ሁሉ በየአባቶቻቸው ቤት ቍጠሩ።”'),
  ('a921bb6e-3c1a-54bc-aa54-d9667f973083', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 3, 3, 'ሙሴና ካህኑ አልዓዛርም በዮርዳኖስ አጠገብ በኢያሪኮ ፊት ለፊት በሞዓብ ሜዳ ላይ እንዲህ ብለው ነገሩአቸው፦'),
  ('f10bf336-90c5-595d-a106-c4a9f7bee2f3', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 4, 4, '“እግዚአብሔር ሙሴን እንዳዘዘው ከሃያ ዓመት ጀምሮ፥ ከዚያም በላይ ያለውን ሕዝብ ቍጠሩ።” ከግብፅ ምድር የወጡ የእስራኤልም ልጆች እነዚህ ናቸው።'),
  ('30586ffe-a6b4-58b8-af59-d23e3a99f7c1', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 5, 5, 'የእስራኤል በኵር ሮቤል፤ የሮቤል ልጆች፤ ከሄኖኅ የሄኖኃውያን ወገን፤ ከፈሉስ የፈሉሳውያን ወገን።'),
  ('03ffd17f-a5b7-5749-a7c1-e786f141795a', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 6, 6, 'ከአስሮን የአስሮናውያን ወገን፤ ከከርሚ የከርማውያን ወገን።'),
  ('a5487cbd-456b-5062-a8c9-905211876f6d', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 7, 7, 'እነዚህ የሮቤላውያን ወገኖች ናቸው፤ ከእነርሱም የተቈጠሩት አርባ ሦስት ሺህ ሰባት መቶ ሠላሳ ነበሩ።'),
  ('2b15b1aa-adb6-59dc-a25f-d2ef3e8c50d1', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 8, 8, 'የፈሉስም ልጆች፤ ኤልያብ።'),
  ('77b8e08f-e655-5eb9-ac05-4b65d358df27', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 9, 9, 'የኤልያብም ልጆች፥ ናሙኤል፥ ዳታን፥ አቤሮን፤ እነዚህም ከማኅበሩ የተመረጡ ነበሩ፤ ከቆሬ ወገን ጋር በእግዚአብሔር ላይ ባመፁ ጊዜ ሙሴንና አሮንን ተጣሉ፤'),
  ('0bf3f746-6782-5f3a-a84c-b7d0e0e53632', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 10, 10, 'ማኅበሩም በሞቱ ጊዜ ምድሪቱ አፍዋን ከፍታ ከቆሬ ጋር ዋጠቻቸው፤ በዚያም ጊዜ እሳቲቱ ሁለት መቶ አምሳውን ሰዎች አቃጠለቻቸው፤ እነርሱም ለምልክት ሆኑ።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('64e8f7f8-2544-58df-abd2-2e0bd38a2197', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 11, 11, 'የቆሬ ልጆች ግን አልሞቱም።'),
  ('a34e53f4-326e-5c4c-a157-628ea64214a3', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 12, 12, 'የስምዖንም ልጆች በየወገናቸው፤ ከናሙሄል የናሙሄላውያን ወገን፥ ከኢያሚን የኢያሚናውያን ልጆች ወገን፥ ከያክን የያክናውያን ልጆች ወገን፥'),
  ('6e269f70-6a6f-5980-a8ae-919ebf392bc1', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 13, 13, 'ከዛራ የዛራውያን ልጆች ወገን፥ ከሳውኡል የሳውኡላውያን ወገን።'),
  ('e8dd006a-af86-51dd-ae5f-3d7dfa601259', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 14, 14, 'እነዚህ የስምዖናውያን ወገኖች ናቸው፤ ቍጥራቸውም ሃያ ሁለት ሺህ ሁለት መቶ ነበሩ።'),
  ('f23b52e9-2280-5f49-a539-ca6c5c085102', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 15, 15, 'የይሁዳ ልጆች ኤርና አውናን፥ ሴሎምና ፋሬስ ዛራም፤ ዔርና አውናንም በከነዓን ምድር ሞቱ።'),
  ('510ab32a-4bc9-5bf6-a3a2-08dd1961953d', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 16, 16, 'የይሁዳም ልጆች በየወገናቸው፤ ከሴሎም የሴሎማውያን ወገን፥ ከፋሬስ የፋሬሳውያን ወገን፥ ከዛራ የዛራውያን ወገን።'),
  ('8c8549e6-6220-54a4-ad2b-38a744fbc6cf', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 17, 17, 'የፋሬስም ልጆች፤ ከኤስሮም የኤስሮማውያን ወገን፥ ከያሙሔል የያሙሔላውያን ወገን።'),
  ('cde5c8c5-7ef9-5a01-a296-248571c25d21', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 18, 18, 'እነዚህ የይሁዳ ወገኖች ናቸው፤ ከእነርሱም የተቈጠሩት ሰባ ስድስት ሺህ አምስት መቶ ነበሩ።'),
  ('fe9befd3-cd45-5a39-ad4f-3a133ec12a71', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 19, 19, 'የይሳኮር ልጆች በየወገናቸው፤ ከቶላ የቶላውያን ወገን፥ ከፉሓ የፉሓውያን ወገን፤'),
  ('cf872fd9-62c9-5436-a629-bdbd477aeeec', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 20, 20, 'ከያሱብ የያሱባውያን ወገን፥ ከሥምራ የሥምራውያን ወገን።'),
  ('64cec25d-7290-5582-ae59-b998b4728cae', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 21, 21, 'እነዚህ የይሳኮር ወገኖች ናቸው፤ ከእነርሱም የተቈጠሩት ስድሳ አራት ሺህ አራት መቶ ነበሩ።'),
  ('f40fc462-ffbd-52e3-aded-d40f7a740e48', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 22, 22, 'የዛብሎን ወገኖች በየወገናቸው፥ ከሳሬድ የሳሬዳውያን ወገን፥ ከኤሎኒ የኤሎኒያውያን ወገን፥ ከያሕልኤል የያሕልኤላውያን ወገን።'),
  ('1014f454-c49e-574a-a08b-d04192c79126', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 23, 23, 'እነዚህ የዛብሎን ወገኖች ናቸው፤ ከእነርሱም የተቈጠሩት ስድሳ ሺህ አምስት መቶ ነበሩ።'),
  ('930d453e-c7ef-5113-a16c-ecb10a8fdfeb', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 24, 24, 'የጋድ ልጆች በየወገናቸው፤ ከሳፎን የሳፎናውያን ወገን፥ ከሐጊ የሐጋውያን ወገን፥ ከሱኒ የሱኒያውያን ወገን፤'),
  ('e81ff9a4-d1b5-5bb5-a1c9-aa72f797ab94', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 25, 25, 'ከኤዜን የኤዜናውያን ወገን፥ ከሳድፍ የሳዳፋውያን ወገን፤'),
  ('480afa50-419e-5aad-a15c-27da66d8ce0a', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 26, 26, 'ከአሮሐድ የአሮሐዳውያን ወገን፥ ከአሩሔል የአሩሔላውያን ወገን።'),
  ('d05a3ffb-1f75-5e42-a372-ad17967923be', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 27, 27, 'እነዚህ የጋድ ልጆች ወገኖች ናቸው፤ ከእነርሱም የተቈጠሩት አርባ አራት ሺህ አምስት መቶ ነበሩ።'),
  ('ddcf1d6f-57a4-5136-ada6-885e013c499e', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 28, 28, 'የአሴር ልጆች በየወገናቸው፤ ከኢያምን የኢያምናውያን ወገን፥ ከኢያሱ የኢያሱያውያን ወገን፥ ከበርያ የበርያውያን ወገን።'),
  ('5922cd5a-2df7-5d0a-aefe-ce4f39d19b72', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 29, 29, 'ከኮቤር ልጆች፤ ከከቤር የከቤራውያን ወገን፥ ከሜልክያል የሜልክያላውያን ወገን።'),
  ('0dae2e66-707a-5803-a2ff-3f1065bba7b6', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 30, 30, 'የአሴርም የሴት ልጁ ስም ሳራ ነበረ።'),
  ('d9ec18d5-5339-5a59-a542-9f79ef95758d', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 31, 31, 'እነዚህ የአሴር ልጆች ወገኖች ናቸው፤ ከእነርሱም የተቈጠሩት አርባ ሦስት ሺህ አራት መቶ ነበሩ።'),
  ('26b97a00-f2b5-5a06-aeff-02be2bffbad9', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 32, 32, 'የዮሴፍ ልጆች በየወገናቸው፤ ምናሴና ኤፍሬም።'),
  ('c189b23b-6066-5a13-a442-80050692a1b0', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 33, 33, 'የምናሴ ልጆች፤ ከማኪር የማኪራውያን ወገን፤ ማኪርም ገለዓድን ወለደ፤ ከገለዓድ የገለዓዳውያን ወገን።'),
  ('bef04e39-3619-517e-a476-a0a95b621b09', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 34, 34, 'የገለዓድ ልጆች እነዚህ ናቸው፤ ከአክያዝር የአክያዝራውያን ወገን፥ ከኬሌግ የኬሌጋውያን ወገን፥'),
  ('69dbc665-b8b5-579b-a81c-0fb8a542ecfc', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 35, 35, 'ከኢሳርያል የኢሳርያላውያን ወገን፥ ከሴኬም የሴኬማውያን ወገን፥'),
  ('b2772d3b-6178-5a1c-a167-2b96b18e181c', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 36, 36, 'ከሲማኤር የሲማኤራውያን ወገን፥ ከኦፌር የኦፌራውያን ወገን።'),
  ('2d611d98-db63-5191-a2bc-4248e90a0bd7', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 37, 37, 'የኦፌርም ልጅ ሰለጰዓድ ሴቶች ልጆች እንጂ ወንዶች ልጆች አልነበሩትም፤ የሰለጰዓድም የሴቶች ልጆቹ ስም መሐላ፥ ኑኃ፥ ሄግላ፥ ሚልካ፥ ቴርሳ ነበረ።'),
  ('f70c91e5-44c0-579a-a324-f0ec7ce70ce9', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 38, 38, 'እነዚህም የምናሴ ወገኖች ናቸው፤ ከእነርሱም የተቈጠሩት አምሳ ሁለት ሺህ ሰባት መቶ ነበሩ።'),
  ('e18bc083-e5f8-5522-a0b5-11a1b4bcd114', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 39, 39, 'በየወገናቸው የኤፍሬም ልጆች እነዚህ ናቸው፤ ከሱቱላ የሱቱላውያን ወገን ከጣናህ የጣናሃውያን ወገን።'),
  ('d12a31a2-ffce-5558-a237-2fa5ec8a595a', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 40, 40, 'እነዚህ የሱቱላ ልጆች ናቸው፤ ከዔዴን የዔዴናውያን ወገን።'),
  ('c901e311-059d-58e0-a920-53041ad48418', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 41, 41, 'እነዚህ የኤፍሬም ልጆች ወገኖች ናቸው፤ ከእነርሱም የተቈጠሩት ሠላሳ ሁለት ሺህ አምስት መቶ ነበሩ። በየወገናቸው የዮሴፍ ልጆች እነዚህ ናቸው።'),
  ('26089f82-0cbc-57a8-ac8c-f84c367b1f90', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 42, 42, 'የብንያም ልጆች በየወገናቸው፤ ከበዓሌ የበዓላውያን ወገን፥ ከአሲቤር የአሲቤራውያን ወገን፥ ከአኪራን የአኪራናውያን ወገን፥'),
  ('e9e847f8-b9dd-5404-a7f5-c5f0fadebecc', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 43, 43, 'ከሶፋን የሶፋናውያን ወገን፥'),
  ('96583d17-5918-589a-ac12-d1d3c957cc23', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 44, 44, 'የበዓሌም ልጆች አዴርና ኖሐማን፤ ከአዴር የአዴራውያን ወገን፥ ከኖሐማን የኖሐማናውያን ወገን።'),
  ('b9236ed6-1c4a-5a60-af84-830282c3bf86', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 45, 45, 'በየወገናቸው የብንያም ልጆች እነዚህ ናቸው። ከእነርሱም የተቈጠሩት አርባ አምስት ሺህ ስድስት መቶ ነበሩ።'),
  ('850ffb72-7dbb-5edf-af65-d5859564e25d', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 46, 46, 'በየወገናቸው የዳን ልጆች እነዚህ ናቸው፤ ከሰምዒ፥ የሰምዒያውያን ወገን፤ በየወገናቸው የዳን ወገኖች እነዚህ ናቸው።'),
  ('881faba6-3af6-50df-ab95-03d9bc00d481', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 47, 47, 'የሰምዒያውያን ወገኖች ሁሉ ቍጥራቸው ስድሳ አራት ሺህ አራት መቶ ነበሩ።'),
  ('0614da87-997c-5bef-ae9c-d5a0f5ff4f34', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 48, 48, 'የንፍታሌም ልጆች በየወገናቸው፤ ከአሴሔል የአሴሔላውያን ወገን፥ ከጎሄኒ የጎሄናውያን ወገን፥'),
  ('cefa3504-f494-5e45-af17-be3230f13224', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 49, 49, 'ከየሴር የየሴራውያን ወገን፥ ከሴሌም የሴሌማውያን ወገን።'),
  ('d46328c3-8134-5e6a-a2f0-3858af14442f', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 50, 50, 'በየወገናቸው የንፍታሌም ወገኖች እነዚህ ናቸው፤ ከእነርሱም የተቈጠሩት አርባ አምስት ሺህ አራት መቶ ነበሩ።'),
  ('915486d1-ddc0-5c4e-ae9d-f8b7035d74b8', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 51, 51, 'ከእስራኤል ልጆች የተቈጠሩት እነዚህ ናቸው፤ ስድስት መቶ አንድ ሺህ ሰባት መቶ ሠላሳ ነበሩ።'),
  ('59d6e377-2aef-5034-a0bd-830276b40959', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 52, 52, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('af1b19a9-acc3-5343-a8d4-f71d8ead3aed', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 53, 53, '“ለእነዚህ በየስማቸው ቍጥር ምድሪቱ ርስት ሆና ትከፈላለች።'),
  ('1407ac59-7ea6-5175-ab0e-cd9c403bc812', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 54, 54, 'ለብዙዎቹ ብዙ ርስትን ትሰጣቸዋለህ፤ ለጥቂቶችም ጥቂት ርስትን ትሰጣቸዋለህ። ለእያንዳንዳቸው እንደ ቍጥራቸው መጠን ርስታቸውን ትሰጣቸዋለህ።'),
  ('c127bc38-c221-5eb7-ac08-9d5d6da6f6c9', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 55, 55, 'ነገር ግን ምድሪቱ በየስማቸው በዕጣ ትከፋፈላለች፤ እንደ አባቶቻቸው ነገድ ይወርሳሉ።'),
  ('29d915a3-69e0-51b9-aaae-66d2caf579d7', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 56, 56, 'በብዙዎችና በጥቂቶች መካከል ርስታቸውን በዕጣ ትከፍላለህ።'),
  ('598cbe41-d308-5ca2-ab4a-d4626ee5b983', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 57, 57, 'የሌዊ ልጆች በየወገናቸው የተቈጠሩት እነዚህ ናቸው፤ ከጌድሶን የጌድሶናውያን ወገን፥ ከቀዓት የቀዓታውያን ወገን፥ ከሜራሪ የሜራራውያን ወገን።'),
  ('a5c8bdab-f87f-53b8-a253-ec01fafd0d5d', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 58, 58, 'እነዚህ የሌዊ ልጆች ወገኖች ናቸው፤ የሎቢኒ ወገን፥ የኬብሮን ወገን፥ የሞሓሊ ወገን፥ የሐሙሲ ወገን፥'),
  ('09daf1e3-4566-5051-a66e-042d79945d7f', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 59, 59, 'የቆሬ ወገን፥ የቀዓት ወገን። ቀዓትም እንበረምን ወለደ። በግብፅ ሀገር እነዚህን ሌዋውያንን የወለደቻቸው የሌዊ ልጅ የእንበረም ሚስት ስም ዮካብድ ነበረ። ለእንበረምም አሮንንና ሙሴን እኅታቸውንም ማርያምን ወለደችለት።'),
  ('acb5b5b7-664b-5dde-a432-24ab25430f06', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 60, 60, 'ለአሮንም ናዳብ፥ አብዩድ፥ አልዓዛርና ኢታምር ተወለዱለት።'),
  ('2201883e-f32c-5435-a1d0-4f445076e3af', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 61, 61, 'በሲና በረሃ በእግዚአብሔር ፊት ከሌላ እሳት ባቀረቡ ጊዜ ናዳብና አብዩድ ሞቱ።'),
  ('49c391bd-4577-5e7b-aeb4-803dfaa9ba8c', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 62, 62, 'ከአንድ ወርም ጀምሮ ከዚያም በላይ ያሉ ወንዶች ሁሉ ከእነርሱ የተቈጠሩ ሃያ ሦስት ሺህ ነበሩ። ከእስራኤልም ልጆች መካከል ርስት አልተሰጣቸውምና ከእስራኤል ልጆች ጋር አልተቈጠሩም።'),
  ('c4d6a9d1-2fc4-56e3-ab01-d7ef098926e2', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 63, 63, 'በሞዓብ ሜዳ ላይ በዮርዳኖስ አጠገብ በኢያሪኮ ፊት ለፊት ሲቈጥሩ፥ ሙሴና ካህኑ አልዓዛር የቈጠሩአቸው የእስራኤል ልጆች እነዚህ ናቸው።'),
  ('adc4d756-4270-57f7-ab36-de652ac1baeb', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 64, 64, 'ነገር ግን ሙሴና ካህኑ አሮን በሲና ምድረ በዳ የእስራኤልን ልጆች በቈጠሩአቸው ጊዜ ከነበሩት ከእነዚያ መካከል አንድም ሰው አልነበረም።'),
  ('fa0e5e33-982c-5312-a50b-506802325b80', 'c6a6164b-77a2-5c76-aca5-a6ba59cda3b6', 'bdf1e698-e2d4-53b6-a483-03c84498e99d', 65, 65, 'እግዚአብሔር ስለ እነርሱ፥ “በእውነት በምድረ በዳ ይሞታሉ” ብሎ ተናግሮአልና። ከዮፎኒ ልጅ ከካሌብ፥ ከነዌም ልጅ ከኢያሱ በቀር ከእነርሱ አንድ ሰው ስንኳ አልቀረም።'),
  ('c9b330b3-5fe9-5912-aa75-fa8c1bbe1cca', 'cfef9028-e9f6-5337-a1f8-6483b0b68a17', '49368481-47a1-5f74-a13f-d950f126bf05', 1, 1, 'ከዮሴፍ ልጅ ከምናሴ ወገን ፥ የምናሴ ልጅ፥ የማኪር ልጅ፥ የገለአድ ልጅ፥ የኦፌር ልጅ፥ የሰለጰዓድ ሴቶች ልጆች መጡ፤ የእነዚህም ሴቶች ልጆች ስሞች መሐላ፥ ኑኃ፥ ሄግላ፥ ሚልካ፥ ቴርሳ ነበሩ።'),
  ('8c9ea009-c233-50cb-af4b-b93dfc5415e1', 'cfef9028-e9f6-5337-a1f8-6483b0b68a17', '49368481-47a1-5f74-a13f-d950f126bf05', 2, 2, 'በምስክሩም ድንኳን ደጃፍ አጠገብ በሙሴና በካህኑ በአልዓዛር፥ በአለቆቹም፥ በማኅበሩም ሁሉ ፊት ቆመው እንዲህ አሉ፦'),
  ('7d56ef71-90ae-59b2-ae07-91bc314c9df4', 'cfef9028-e9f6-5337-a1f8-6483b0b68a17', '49368481-47a1-5f74-a13f-d950f126bf05', 3, 3, '“አባታችን በምድረ በዳ ሞተ፤ በራሱ ኀጢአት ሞተ እንጂ ከቆሬ ጋር በእግዚአብሔር ላይ በተሰበሰቡ ወገን መካከል አልነበረም፤ ወንዶችም ልጆች አልነበሩትም።'),
  ('7cfc3e3c-b674-5c50-a1ee-2530cfe4a8f0', 'cfef9028-e9f6-5337-a1f8-6483b0b68a17', '49368481-47a1-5f74-a13f-d950f126bf05', 4, 4, 'ወንድ ልጅስ ባይኖረው የአባታችን ስም ከወገኑ መካከል ለምን ይጠፋል?'),
  ('cc71041d-4dd6-57eb-a5cf-1b0ded938d24', 'cfef9028-e9f6-5337-a1f8-6483b0b68a17', '49368481-47a1-5f74-a13f-d950f126bf05', 5, 5, 'በአባታችን ወንድሞች መካከል ርስትን ስጠን።” ሙሴም ነገራቸውን በእግዚአብሔር ፊት አቀረበ።'),
  ('416e7794-3489-586d-ac85-3780df4a3d1f', 'cfef9028-e9f6-5337-a1f8-6483b0b68a17', '49368481-47a1-5f74-a13f-d950f126bf05', 6, 6, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('aca52629-6649-5496-a151-270d422ce9c7', 'cfef9028-e9f6-5337-a1f8-6483b0b68a17', '49368481-47a1-5f74-a13f-d950f126bf05', 7, 7, '“የሰለጰዓድ ልጆች እውነት ተናግረዋል፤ በአባታቸው ወንድሞች መካከል የርስት ድርሻ ስጣቸው፤ የአባታቸውን ርስት ለእነርሱ ስጥ።'),
  ('fa2b7ed3-ceff-5e06-ae1e-85b25dd09551', 'cfef9028-e9f6-5337-a1f8-6483b0b68a17', '49368481-47a1-5f74-a13f-d950f126bf05', 8, 8, 'ለእስራኤልም ልጆች እንዲህ ብለህ ንገራቸው፦ ሰው ቢሞት፥ ወንድ ልጅም ባይኖረው፥ ርስቱን ለሴቶች ልጆቹ ትሰጣላችሁ፤'),
  ('14f82e4d-0a4c-5518-a7f3-7d8420a1f53b', 'cfef9028-e9f6-5337-a1f8-6483b0b68a17', '49368481-47a1-5f74-a13f-d950f126bf05', 9, 9, 'ሴት ልጅም ባትኖረው፥ ርስቱን ለወንድሞቹ ትሰጣላችሁ፤'),
  ('4481045c-e4a7-5b1f-a111-72a0287b8154', 'cfef9028-e9f6-5337-a1f8-6483b0b68a17', '49368481-47a1-5f74-a13f-d950f126bf05', 10, 10, 'ወንድሞችም ባይኖሩት፥ ርስቱን ለአባቱ ወንድሞች ትሰጣላችሁ፤'),
  ('c8ca5bfa-9a4d-52fb-a9f1-2d870cc05d2f', 'cfef9028-e9f6-5337-a1f8-6483b0b68a17', '49368481-47a1-5f74-a13f-d950f126bf05', 11, 11, 'የአባቱም ወንድሞች ባይኖሩት ከወገኑ ለቀረበ ዘመድ ርስቱን ትሰጣላችሁ፤ እርሱም ይውረሰው፤ እግዚአብሔርም ሙሴን እንዳዘዘ ለእስራኤል ልጆች ሥርዐትና ፍርድ ይሁን።”'),
  ('803d4ba8-d658-5d73-acd6-271d8305a0bd', 'cfef9028-e9f6-5337-a1f8-6483b0b68a17', '1f0fdcf6-a948-563b-a292-b27bf90c10a8', 1, 12, 'እግዚአብሔርም ሙሴን አለው፥ “ወደዚህ በናባው አሻገር ወዳለው ተራራ ውጣ፤ ለእስራኤልም ልጆች ይገዙአት ዘንድ እኔ የምሰጣቸውን የከነዓንን ምድር እያት፤'),
  ('927eab69-4f9a-5800-a91e-7f53a0c97d85', 'cfef9028-e9f6-5337-a1f8-6483b0b68a17', '1f0fdcf6-a948-563b-a292-b27bf90c10a8', 2, 13, 'ባየሃትም ጊዜ ወንድምህ አሮን በሖር ተራራ እንደ ተጨመረ አንተ ደግሞ ወደ ወገንህ ትጨመራለህ።'),
  ('9db073ad-9702-58ff-a8cc-6c3dc3bc22ab', 'cfef9028-e9f6-5337-a1f8-6483b0b68a17', '1f0fdcf6-a948-563b-a292-b27bf90c10a8', 3, 14, 'እናንተ በጺን ምድረ በዳ በማኅበሩ ጠብ በቃሌ ላይ ዐምፃችኋልና፥ በእነርሱም ፊት በውኃው ዘንድ አላከበራችሁኝምና። ይህም በጺን ምድረ በዳ በቃዴስ ያለው የክርክር ውኃ ነው።”'),
  ('f5c5a471-1385-5228-ac12-11f0d32eaf7a', 'cfef9028-e9f6-5337-a1f8-6483b0b68a17', '1f0fdcf6-a948-563b-a292-b27bf90c10a8', 4, 15, 'ሙሴም እግዚአብሔርን እንዲህ ብሎ ተናገረው፦'),
  ('76a0d7cd-e4e9-54e5-ab57-c6fd0a140765', 'cfef9028-e9f6-5337-a1f8-6483b0b68a17', '1f0fdcf6-a948-563b-a292-b27bf90c10a8', 5, 16, '“የሥጋና የነፍስ ሁሉ አምላክ እግዚአብሔር በዚህ ሕዝብ ላይ የሚሆነውን ሰው ይሹም፤'),
  ('4f2de982-c250-5e68-aaae-cc4a8a769870', 'cfef9028-e9f6-5337-a1f8-6483b0b68a17', '1f0fdcf6-a948-563b-a292-b27bf90c10a8', 6, 17, 'በፊታቸው የሚወጣውንና የሚገባውን፥ የሚያስወጣቸውንና፥ የሚያስገባቸውንም፥ የእግዚአብሔር ማኅበር እረኛ እንደሌለው መንጋ እንዳይሆን።”'),
  ('6477bfae-7cff-50bb-a28c-50e378bd8f15', 'cfef9028-e9f6-5337-a1f8-6483b0b68a17', '1f0fdcf6-a948-563b-a292-b27bf90c10a8', 7, 18, 'እግዚአብሔርም ሙሴን አለው፥ “መንፈስ ቅዱስ ያለበትን ሰው የነዌን ልጅ ኢያሱን ወስደህ እጅህን በላዩ ጫንበት፤'),
  ('035651de-624d-5a96-aa84-96103c1a5a88', 'cfef9028-e9f6-5337-a1f8-6483b0b68a17', '1f0fdcf6-a948-563b-a292-b27bf90c10a8', 8, 19, 'በካህኑም በአልዓዛር ፊት አቁመው፤ በማኅበሩም ፊት እዘዘው፤ ስለ እርሱም በፊታቸው እዘዝ።'),
  ('d52c7bf9-edb1-5fe0-ab07-f71be0e26521', 'cfef9028-e9f6-5337-a1f8-6483b0b68a17', '1f0fdcf6-a948-563b-a292-b27bf90c10a8', 9, 20, 'የእስራኤልም ልጆች ሁሉ እንዲታዘዙት ከክብርህ ስጠው።'),
  ('309ea426-f729-571f-afa7-251be5c934e0', 'cfef9028-e9f6-5337-a1f8-6483b0b68a17', '1f0fdcf6-a948-563b-a292-b27bf90c10a8', 10, 21, 'በካህኑም በአልዓዛር ፊት ይቁም፤ እርሱም በእግዚአብሔር ፊት ፍርድ ይጠይቅለት፤ እርሱ ከእርሱም ጋር የእስራኤል ልጆች ማኅበር ሁሉ በቃሉ ይውጡ፤ በቃሉም ይግቡ።”'),
  ('316f907f-0b18-5ce4-a2ec-dc454a480dad', 'cfef9028-e9f6-5337-a1f8-6483b0b68a17', '1f0fdcf6-a948-563b-a292-b27bf90c10a8', 11, 22, 'ሙሴም እግዚአብሔር እንዳዘዘው አደረገ፤ ኢያሱንም ወስዶ በካህኑ በአልዓዛርና በማኅበሩ ሁሉ ፊት አቆመው፤'),
  ('7d031850-72a8-5b63-adc6-e9260f21dcad', 'cfef9028-e9f6-5337-a1f8-6483b0b68a17', '1f0fdcf6-a948-563b-a292-b27bf90c10a8', 12, 23, 'እግዚአብሔርም ሙሴን እንደ አዘዘው፥ እጁን በላዩ ጫነበትና፥ ሾመው፤ አዘዘውም።'),
  ('b239544b-62ee-54dc-acae-62ebaeecb957', 'c08ccb16-a19d-5e15-acbb-2e8fd1d9bda1', 'ddd35f1b-4263-5be8-a779-4f2d794b051f', 1, 1, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('e69f5308-5d20-5a62-a98b-dbed2388b241', 'c08ccb16-a19d-5e15-acbb-2e8fd1d9bda1', 'ddd35f1b-4263-5be8-a779-4f2d794b051f', 2, 2, '“የእስራኤልን ልጆች እንዲህ ብለህ እዘዛቸው፦ ቍርባኔን፥ መባዬንና የበጎ መዓዛ መሥዋዕቴን በበዓላት ቀኖች ታቀርቡልኝ ዘንድ ጠብቁ።'),
  ('3170cf57-87ec-52fe-a853-6e75a6b70f4c', 'c08ccb16-a19d-5e15-acbb-2e8fd1d9bda1', 'ddd35f1b-4263-5be8-a779-4f2d794b051f', 3, 3, 'እንዲህም በላቸው፦ በእሳት ለእግዚአብሔር የምታቀርቡት ቍርባን ይህ ነው፤ ለሚቃጠል መሥዋዕት ነውር የሌለባቸውን ሁለት የአንድ ዓመት ተባት የበግ ጠቦቶች ዕለት ዕለት ታቀርባላችሁ።'),
  ('e6a93e15-3855-519b-ad11-cede112f918c', 'c08ccb16-a19d-5e15-acbb-2e8fd1d9bda1', 'ddd35f1b-4263-5be8-a779-4f2d794b051f', 4, 4, 'አንዱን ጠቦት በማለዳ፥ ሌላውንም ጠቦት በማታ አቅርቡ፤'),
  ('eaf94709-444e-5b7d-ae96-16b019b9c765', 'c08ccb16-a19d-5e15-acbb-2e8fd1d9bda1', 'ddd35f1b-4263-5be8-a779-4f2d794b051f', 5, 5, 'ለእህልም ቍርባን የኢን መስፈሪያ አራተኛ እጅ በሆነ፥ ተወቅጦ በተጠለለ ዘይት የተለወሰ የኢፍ መስፈሪያ ዐሥረኛ እጅ መልካም ዱቄት ታቀርባላችሁ።'),
  ('29b2aeef-fa9d-5816-a880-5b1a915174d3', 'c08ccb16-a19d-5e15-acbb-2e8fd1d9bda1', 'ddd35f1b-4263-5be8-a779-4f2d794b051f', 6, 6, 'በእሳት ለእግዚአብሔር በጎ መዓዛ እንዲሆን የቀረበ፥ በሲና ተራራ የተሠራ ለዘወትር የሚቃጠል መሥዋዕት ነው።'),
  ('d2308a8f-e97b-5085-a353-86e2652ae80e', 'c08ccb16-a19d-5e15-acbb-2e8fd1d9bda1', 'ddd35f1b-4263-5be8-a779-4f2d794b051f', 7, 7, 'የመጠጡም ቍርባን ለአንድ ጠቦት የኢን መስፈሪያ አራተኛው እጅ ነው፤ በመቅደሱ ውስጥ ለእግዚአብሔር ለመጠጥ ቍርባን መጠጥ ታፈስሳላችሁ።'),
  ('27d618e8-d79a-5e53-ac23-35be4129712c', 'c08ccb16-a19d-5e15-acbb-2e8fd1d9bda1', 'ddd35f1b-4263-5be8-a779-4f2d794b051f', 8, 8, 'ሌላውንም ጠቦት በማታ ጊዜ ታቀርባላችሁ፤ የእህሉን ቍርባንና የመጠጡን ቍርባን በማለዳ እንዳቀረባችሁ በእሳት ለእግዚአብሔር በጎ መዓዛ እንዲሆን ታቀርቡታላችሁ።'),
  ('928800a6-1597-507b-abe0-ab86d89ed455', 'c08ccb16-a19d-5e15-acbb-2e8fd1d9bda1', '51efd04c-9a0b-52a4-a37c-2dc9c1493ef7', 1, 9, '“በሰንበትም ቀን ነውር የሌለባቸውን ሁለት የአንድ ዓመት ተባት የበግ ጠቦቶች፥ ለእህልም ቍርባን በዘይት የተለወሰ ከመስፈሪያው ከዐሥር እጅ ሁለት እጅ መልካም ዱቄት፥ የመጠጡንም ቍርባን ታቀርባላችሁ።'),
  ('44af1652-2075-59b7-abdc-67adbef60ed3', 'c08ccb16-a19d-5e15-acbb-2e8fd1d9bda1', '51efd04c-9a0b-52a4-a37c-2dc9c1493ef7', 2, 10, 'በዘወትር ከሚቃጠለው መሥዋዕት ሌላ፥ ከመጠጡም ቍርባን ሌላ፥ በየሰንበቱ ሁሉ የምታቀርቡት የሚቃጠለው መሥዋዕት ይህ ነው።'),
  ('208b1471-35b5-5cdd-ad38-6cd11b3aa23e', 'c08ccb16-a19d-5e15-acbb-2e8fd1d9bda1', '4cc9d98c-495e-5872-a392-ba9c22ceccbd', 1, 11, '“በወሩም መባቻ ለእግዚአሔር የሚቃጠል መሥዋዕት ታቀርባላችሁ፤ ከላሞች ሁለት፥ አንድ አውራ በግ፥ ነውርም የሌለባቸውን ሰባት የአንድ ዓመት ተባት የበግ ጠቦቶች፥'),
  ('7f0e1f2f-fd02-5f8c-ac7c-4631dd3ae8bc', 'c08ccb16-a19d-5e15-acbb-2e8fd1d9bda1', '4cc9d98c-495e-5872-a392-ba9c22ceccbd', 2, 12, 'ለእያንዳንዱም ወይፈን ለእህል ቍርባን በዘይት የተለወሰ ከመስፈሪያው ከዐሥር እጅ ሦስት እጅ መልካም ዱቄት፥ ለአውራው በግ ለእህል ቍርባን በዘይት የተለወሰ፥ ከመስፈሪያው ከዐሥር እጅ ሁለት እጅ መልካም ዱቄት፥'),
  ('f91f6715-8c0a-510e-a5c8-8e2bf0fb598e', 'c08ccb16-a19d-5e15-acbb-2e8fd1d9bda1', '4cc9d98c-495e-5872-a392-ba9c22ceccbd', 3, 13, 'ለእያንዳንዱም ጠቦት ለእህል ቍርባን በዘይት የተለወሰ፥ ከመስፈሪያው ዐሥረኛ እጅ ሁለት እጅ መልካም ዱቄት፥ ለሚቃጠል መሥዋዕት ለእግዚአብሔር በጎ መዓዛ እንዲሆን በእሳት ታቀርባላችሁ።'),
  ('edbe571c-3b00-5f82-ac0a-5ce97c8e8b84', 'c08ccb16-a19d-5e15-acbb-2e8fd1d9bda1', '4cc9d98c-495e-5872-a392-ba9c22ceccbd', 4, 14, 'የመጠጥ ቍርባናቸውም ለአንድ ወይፈን የኢን ግማሽ፥ ለአውራው በግም የኢን ሲሦ፥ ለአንዱም ጠቦት የኢን አራተኛ እጅ የወይን ጠጅ ይሆናል፤ ይህ ለዓመቱ የወር መባቻ ሁሉ የሚቃጠል መሥዋዕት ነው።'),
  ('1025d6e8-8122-5f9a-a03b-24cafcdeebd4', 'c08ccb16-a19d-5e15-acbb-2e8fd1d9bda1', '4cc9d98c-495e-5872-a392-ba9c22ceccbd', 5, 15, 'ለእግዚአብሔርም ስለኀጢአት መሥዋዕት አንድ አውራ ፍየል ታቀርባላችሁ፤ በዘወትር ከሚቃጠለው መሥዋዕትና ከመጠጡ ቍርባን ሌላ ይቀርባል።'),
  ('c392e58f-66bc-519f-a4bc-0f310ee4b09f', 'c08ccb16-a19d-5e15-acbb-2e8fd1d9bda1', 'e739be14-4bd4-59ff-abf2-d01d916fd93f', 1, 16, '“በመጀመሪያው ወር ከወሩም በዐሥራ አራተኛው ቀን የእግዚአብሔር ፋሲካ ነው።'),
  ('961c3467-54d1-5b16-a20c-e15c45a13785', 'c08ccb16-a19d-5e15-acbb-2e8fd1d9bda1', 'e739be14-4bd4-59ff-abf2-d01d916fd93f', 2, 17, 'በዚህም ወር በዐሥራ አምስተኛው ቀን በዓል ይሆናል፤ ሰባት ቀን ቂጣ እንጀራ ትበላላችሁ።'),
  ('c79ee187-0eab-5ee0-a420-cb186f87aa31', 'c08ccb16-a19d-5e15-acbb-2e8fd1d9bda1', 'e739be14-4bd4-59ff-abf2-d01d916fd93f', 3, 18, 'የመጀመሪያው ቀን የተቀደሰ ይሁንላችሁ፤ በእርሱም የተግባርን ሥራ ሁሉ አትሥሩበት።'),
  ('25f2a931-093a-52fc-aa82-539503ff0c5c', 'c08ccb16-a19d-5e15-acbb-2e8fd1d9bda1', 'e739be14-4bd4-59ff-abf2-d01d916fd93f', 4, 19, 'በእሳትም የተደረገውን ለእግዚአብሔር የሚቃጠለውን መሥዋዕት ታቀርባላችሁ፤ ከላሞች ሁለት በሬዎች፥ አንድ አውራ በግ፥ ሰባት የአንድ ዓመት ተባት የበግ ጠቦቶች ነውር የሌለባቸው ይሁኑላችሁ።'),
  ('a47b048a-3b02-5164-aced-3de6235964ec', 'c08ccb16-a19d-5e15-acbb-2e8fd1d9bda1', 'e739be14-4bd4-59ff-abf2-d01d916fd93f', 5, 20, 'የእህል ቍርባናቸውንም በዘይት የተለወሰ መልካም ዱቄት፥ ለአንድ ወይፈን ከመስፈሪያው ከዐሥር እጅ ሦስት እጅ፥ ለአውራውም በግ ከመስፈሪያው ከዐሥር እጅ ሁለት እጅ፥'),
  ('f9e96505-5cf4-5dcb-aa60-878fa5ea5ac9', 'c08ccb16-a19d-5e15-acbb-2e8fd1d9bda1', 'e739be14-4bd4-59ff-abf2-d01d916fd93f', 6, 21, 'ለሰባቱም ጠቦቶች ለእያንዳንዱ ጠቦት ከመስፈሪያው ዐሥረኛ እጅ ታቀርባላችሁ።'),
  ('1ddec57f-72d1-5bff-abb0-91a4d6c36acd', 'c08ccb16-a19d-5e15-acbb-2e8fd1d9bda1', 'e739be14-4bd4-59ff-abf2-d01d916fd93f', 7, 22, 'ማስተስረያ የሚሆንላችሁን ከፍየሎች አንድ አውራ ፍየል ለኀጢአት መሥዋዕት ታቀርባላችሁ።'),
  ('c9d0284d-6cd4-5c6e-a153-604991987414', 'c08ccb16-a19d-5e15-acbb-2e8fd1d9bda1', 'e739be14-4bd4-59ff-abf2-d01d916fd93f', 8, 23, 'ማልዶ ከሚቀርበው በዘወትር ከሚቃጠል መሥዋዕት ሌላ እነዚህን ታቀርባላችሁ።'),
  ('bd606181-a89f-5aab-ae3c-f33e8a5858fe', 'c08ccb16-a19d-5e15-acbb-2e8fd1d9bda1', 'e739be14-4bd4-59ff-abf2-d01d916fd93f', 9, 24, 'ለእግዚአብሔር በጎ መዓዛ እንዲሆን በእሳት የሚደረገውን ቍርባንና መሥዋዕት ሰባት ቀን በየዕለቱ እንዲሁ ታቀርባላችሁ፤ በዘወትር ከሚቃጠለው መሥዋዕትና ከመጠጡ ቍርባን ሌላ ይቀርባል።'),
  ('7716f53e-4a28-593b-a7cf-a0795f3421c0', 'c08ccb16-a19d-5e15-acbb-2e8fd1d9bda1', 'e739be14-4bd4-59ff-abf2-d01d916fd93f', 10, 25, 'ሰባተኛውም ቀን የተቀደሰ ይሁንላችሁ፤ የተግባርን ሥራ ሁሉ አትሥሩበት።'),
  ('35915b17-25ca-5699-a7e1-1d1aa9eae017', 'c08ccb16-a19d-5e15-acbb-2e8fd1d9bda1', '7254e528-2bf1-52e4-ac3d-fe02d52ac233', 1, 26, '“በበዓለ ሠዊት ቀን በሰንበታት በዓላችሁ አዲሱን የእህል ቍርባን ለእግዚአብሔር ባቀረባችሁ ጊዜ፥ የተቀደሰ ቀን ይሆንላችኋል፤ የተግባርን ሥራ ሁሉ አትሥሩበት።'),
  ('362889da-fa87-57af-ad48-046434ae8ef0', 'c08ccb16-a19d-5e15-acbb-2e8fd1d9bda1', '7254e528-2bf1-52e4-ac3d-fe02d52ac233', 2, 27, 'ለእግዚአብሔርም በጎ መዓዛ እንዲሆን የሚቃጠለውን መሥዋዕት ታቀርባላችሁ፤ ከላሞች ሁለት በሬዎች፥ አንድ አውራ በግ፥ ሰባት የአንድ ዓመት ተባት የበግ ጠቦቶች፥'),
  ('0d0ffd7b-596f-53cc-ac70-e2a8071d32e6', 'c08ccb16-a19d-5e15-acbb-2e8fd1d9bda1', '7254e528-2bf1-52e4-ac3d-fe02d52ac233', 3, 28, 'ለእህል ቍርባናቸው በዘይት የተለወሰ መልካም ዱቄት፥ ለእያንዳንዱ ወይፈን ከመስፈሪያው ከዐሥር እጅ ሦስት እጅ፥ ለአንዱም አውራ በግ ከመስፈሪያው ከዐሥር እጅ ሁለት እጅ፥'),
  ('77dbf8b3-a282-581c-a119-a3f6cc30e6d2', 'c08ccb16-a19d-5e15-acbb-2e8fd1d9bda1', '7254e528-2bf1-52e4-ac3d-fe02d52ac233', 4, 29, 'ለሰባቱም ጠቦቶች ለእያንዳንዱ ጠቦት ከመስፈሪያው ዐሥረኛ እጅ ታቀርባላችሁ።'),
  ('293a2381-cf27-5382-a0e4-65a4935e17d1', 'c08ccb16-a19d-5e15-acbb-2e8fd1d9bda1', '7254e528-2bf1-52e4-ac3d-fe02d52ac233', 5, 30, 'ማስተስረያ የሚሆንላችሁን ከፍየሎች አንድ አውራ ፍየል ለኀጢአት መሥዋዕት ታቀርባላችሁ።'),
  ('f1ba6033-7d08-539a-a176-4ed02c437f07', 'c08ccb16-a19d-5e15-acbb-2e8fd1d9bda1', '7254e528-2bf1-52e4-ac3d-fe02d52ac233', 6, 31, 'በዘወትር ከሚቃጠለው መሥዋዕትና ከእህሉ ቍርባን ሌላ እነርሱንና የመጠጥ ቍርባናቸውን ታቀርባላችሁ፤ ነውርም የሌለባቸው ይሁኑ።'),
  ('1ac635f6-e973-5051-a095-56f599afad55', '36219c81-e33c-51e1-a07a-7124bfa8df12', 'a33a99f6-a156-5f79-a243-3cbcdd80b70f', 1, 1, '“በሰባተኛውም ወር ከወሩ የመጀመሪያዋ ቀን ለእናንተ ይህች ዕለት የተቀደሰች ናት፤ የተግባርን ሥራ ሁሉ አትሥሩባት፤ ምልክት ያለባት ቀን ትሁንላችሁ።'),
  ('d5ce7358-a3ed-56dc-a49e-979ccee27fc6', '36219c81-e33c-51e1-a07a-7124bfa8df12', 'a33a99f6-a156-5f79-a243-3cbcdd80b70f', 2, 2, 'ለእግዚአብሔር በጎ መዓዛ እንዲሆን የሚቃጠለውን መሥዋዕት፥ ከላሞች አንድ በሬ፥ አንድ አውራ በግ፥ ነውር የሌለባቸውን ሰባት የአንድ ዓመት ተባት፥ የበግ ጠቦቶች፥'),
  ('a2589dca-4b18-5a63-a8a1-78818ed391c9', '36219c81-e33c-51e1-a07a-7124bfa8df12', 'a33a99f6-a156-5f79-a243-3cbcdd80b70f', 3, 3, 'ለእህል ቍርባናቸው በዘይት የተለወሰ መልካም ዱቄት፥ ለበሬው ከመስፈሪያው ከዐሥር እጅ ሦስት እጅ፥ ለአውራው በግ ከመስፈሪያው ከዐሥር እጅ ሁለት እጅ፥'),
  ('2fe09c16-5209-5e62-a242-279c5e2a201e', '36219c81-e33c-51e1-a07a-7124bfa8df12', 'a33a99f6-a156-5f79-a243-3cbcdd80b70f', 4, 4, 'ለሰባቱ ጠቦቶች ለእያንዳንዱ ከመስፈሪያው ዐሥረኛ እጅ ታቀርባላችሁ።'),
