  ('1fa81009-7908-5948-a6c2-92754f5beaa9', '36219c81-e33c-51e1-a07a-7124bfa8df12', 'a33a99f6-a156-5f79-a243-3cbcdd80b70f', 6, 6, 'በወሩ መባቻ ከሚቃጠለው መሥዋዕት ሌላ ከእህሉ ቍርባን፥ ከመጠጡም ቍርባን እንደ ሕጋቸው ለእግዚአብሔር በጎ መዓዛ እንዲሆን በእሳት የሚቀርቡ ናቸው።'),
