  ('6fd6e0c3-31d5-5fc9-acb9-41c7828baac3', '36219c81-e33c-51e1-a07a-7124bfa8df12', '70b8fea9-3994-54c9-a36b-99b826fb735e', 2, 8, 'ለእግዚአብሔርም በጎ መዓዛ እንዲሆን የሚቃጠለውን መሥዋዕት ፥ ከላሞች አንድ በሬ፥ አንድ አውራ በግ፥ ሰባት የአንድ ዓመት ተባት የበግ ጠቦቶች ታቀርባላችሁ፤ ነውር የሌለባቸውም ይሁኑላችሁ።'),
  ('4c23d0d4-e458-587a-aa65-3d70a86a1887', '36219c81-e33c-51e1-a07a-7124bfa8df12', '70b8fea9-3994-54c9-a36b-99b826fb735e', 3, 9, 'ለእህል ቍርባናቸውም በዘይት የተለወሰ መልካም ዱቄት፥ ለበሬው ከመስፈሪያው ከዐሥር እጅ ሦስት እጅ፥ ለአውራው በግ ከመስፈሪያው ከዐሥር እጅ ሁለት እጅ፥'),
