  ('beba161b-3330-54c5-af58-093b584a65e2', '36219c81-e33c-51e1-a07a-7124bfa8df12', '941d3a9c-bc56-56fe-a2cd-416f7a4cc4ba', 22, 33, 'ለበሬዎቹ፥ ለአውራ በጎቹ፥ ለጠቦቶቹም የእህል ቍርባናቸውንና የመጠጥ ቍርባናቸውን እንደ ቍጥራቸው መጠን እንደ ሕጋቸው፥'),
  ('0e479d33-8f0a-5a62-a290-a0ceddc1fb92', '36219c81-e33c-51e1-a07a-7124bfa8df12', '941d3a9c-bc56-56fe-a2cd-416f7a4cc4ba', 23, 34, 'ለኀጢአትም መሥዋዕት ከፍየሎች አንድ አውራ ፍየል፥ በዘወትር ከሚቃጠለው መሥዋዕትና ከእህሉ ቍርባን ከመጠጡም ቍርባን ሌላ ታቀርባላችሁ።'),
  ('790cfc60-a6d5-523d-a48d-82cc3b7f2176', '36219c81-e33c-51e1-a07a-7124bfa8df12', '941d3a9c-bc56-56fe-a2cd-416f7a4cc4ba', 24, 35, '“ስምንተኛውም ቀን የተቀደሰ በዓል ይሁንላችሁ፤ የተግባርን ሥራ ሁሉ አትሥሩበት።'),
  ('f163cc46-e7c5-5bc4-a50c-73dd2bf09957', '36219c81-e33c-51e1-a07a-7124bfa8df12', '941d3a9c-bc56-56fe-a2cd-416f7a4cc4ba', 25, 36, 'ለእግዚአብሔር በጎ መዓዛ እንዲሆን በእሳት የሚቃጠለውን መሥዋዕት፥ አንድ በሬ፥ አንድ አውራ በግ፥ ነውር የሌለባቸውን ሰባት የአንድ ዓመት ተባት የበግ ጠቦቶች ታቀርባላችሁ።'),
  ('82966842-9bf9-5045-ad92-ef7168c0c34c', '36219c81-e33c-51e1-a07a-7124bfa8df12', '941d3a9c-bc56-56fe-a2cd-416f7a4cc4ba', 26, 37, 'የእህል ቍርባናቸውና የመጠጥ ቍርባናቸው ለበሬው፥ ለአውራውም በግ፥ ለጠቦቶቹም እንደ ቍጥራቸው መጠን እንደ ሕጋቸው ይሆናሉ።'),
  ('f57ad170-8032-5937-a5a8-19429ad395d3', '36219c81-e33c-51e1-a07a-7124bfa8df12', '941d3a9c-bc56-56fe-a2cd-416f7a4cc4ba', 27, 38, 'ለኀጢአትም መሥዋዕት ከፍየሎች አንድ አውራ ፍየል ታቀርባላችሁ፤ በዘወትር ከሚቃጠለው መሥዋዕትና ከእህሉ ቍርባን ከመጠጡም ቍርባን ሌላ የሚቀርቡ ናቸው።'),
  ('c71d1914-434e-5e4f-aa42-c878a56ac1bd', '36219c81-e33c-51e1-a07a-7124bfa8df12', '941d3a9c-bc56-56fe-a2cd-416f7a4cc4ba', 28, 39, '“እነዚህንም፥ ከስእለታችሁና በፈቃዳችሁ ከምታመጡት ሌላ፥ ለሚቃጠል መሥዋዕት፥ ለእህልም፥ ለመጠጥም ቍርባን፥ ለደኅንነትም መሥዋዕታችሁ በበዓላችሁ ጊዜ ለእግዚአብሔር አቅርቡ።”'),
  ('51f32a4b-4df0-54c6-af87-259453af2805', '36219c81-e33c-51e1-a07a-7124bfa8df12', '941d3a9c-bc56-56fe-a2cd-416f7a4cc4ba', 29, 40, 'ሙሴም ለእስራኤል ልጆች እግዚአብሔር ለሙሴ ያዘዘውን ሁሉ ነገራቸው።'),
  ('fd857e92-e315-50d6-a8e0-52f096ab8941', '64f4c1dc-d9bc-5add-a1fc-78caa57c54ee', '3748fbff-0713-5400-a535-b15f7d139d7b', 1, 1, 'ሙሴም ለእስራኤል ልጆች ነገዶች አለቆች እንዲህ ብሎ ነገራቸው፥ “እግዚአብሔር ያዘዘው ነገር ይህ ነው።'),
  ('d13b79b0-d957-5532-a591-6fda309d8c6f', '64f4c1dc-d9bc-5add-a1fc-78caa57c54ee', '3748fbff-0713-5400-a535-b15f7d139d7b', 2, 2, 'ሰው ሁሉ ለእግዚአብሔር ስእለት ቢሳል፥ ወይም መሐላን ቢምል፤ ራሱንም ቢለይ፥ ቃሉን አያርክስ፤ ከአፉ እንደ ወጣው ሁሉ ያድርግ።'),
  ('08e80bb5-2d83-574b-a3a9-2418495a14c0', '64f4c1dc-d9bc-5add-a1fc-78caa57c54ee', '3748fbff-0713-5400-a535-b15f7d139d7b', 3, 3, 'ሴትም ደግሞ ለእግዚአብሔር ስእለት ብትሳል፥ እርስዋም በአባቷ ቤት ሳለች በብላቴንነቷ ጊዜ ራስዋን ብትለይ፥'),
  ('ff429784-d052-5153-a7af-4ba0a6a236ab', '64f4c1dc-d9bc-5add-a1fc-78caa57c54ee', '3748fbff-0713-5400-a535-b15f7d139d7b', 4, 4, 'አባቷም ስእለቷንና ራስዋን የለየችበትን ቢሰማ፥ አባቷም ዝም ቢላት፥ ስእለቷ ሁሉ ይጸናል፤ ራስዋንም ያሰረችበት መሐላ ሁሉ ይጸናል።'),
  ('1d17faed-238b-53ab-aace-a60f9bef9540', '64f4c1dc-d9bc-5add-a1fc-78caa57c54ee', '3748fbff-0713-5400-a535-b15f7d139d7b', 5, 5, 'አባቷ ግን በሰማበት ቀን ቢከለክላት፥ ስእለቷ፥ ራስዋንም ያሰረችበት መሐላዋ አይጸኑም፤ አባቷ ከልክሎአታልና እግዚአብሔር ይቅር ይላታል።'),
  ('41e1e464-312b-5a85-acfc-17a88a6f2d7c', '64f4c1dc-d9bc-5add-a1fc-78caa57c54ee', '3748fbff-0713-5400-a535-b15f7d139d7b', 6, 6, '“ባል ያገባች ብትሆን፥ በአንደበቷም እንደ ተናገረች ስለ ራስዋ የተሳለችው ስእለት በራስዋ ላይ ቢሆን፥'),
  ('6dca6794-346e-513e-a62a-30625f86eb8b', '64f4c1dc-d9bc-5add-a1fc-78caa57c54ee', '3748fbff-0713-5400-a535-b15f7d139d7b', 7, 7, 'ባልዋም ቢሰማ፥ በሰማበትም ቀን ዝም ቢላት፥ ስእለቷ፥ ራስዋንም ያሰረችበት መሐላ ይጸናሉ።'),
  ('d00a0c22-3339-5034-a4c3-2e3693830a5b', '64f4c1dc-d9bc-5add-a1fc-78caa57c54ee', '3748fbff-0713-5400-a535-b15f7d139d7b', 8, 8, 'ባልዋ ግን በሰማበት ቀን ቢከለክላት፥ ስእለቷና ራስዋን ያሰረችበት መሐላ አይጸኑም፤ ባልዋ ከልክሎአታልና፤ እግዚአብሔርም ይቅር ይላታል።'),
  ('eb39adec-9f39-5b78-ad38-6d22f16aab2b', '64f4c1dc-d9bc-5add-a1fc-78caa57c54ee', '3748fbff-0713-5400-a535-b15f7d139d7b', 9, 9, '“ባልዋ የሞተባት ወይም የተፋታች ግን ስእለቷና ራስዋን ያሰረችበት መሐላ ይጸኑባታል።'),
  ('446f6885-baa3-5a96-a9d1-7843589c49cc', '64f4c1dc-d9bc-5add-a1fc-78caa57c54ee', '3748fbff-0713-5400-a535-b15f7d139d7b', 10, 10, 'ሴትም በባልዋ ቤት ሳለች ብትሳል፥ ወይም ራስዋን በመሐላ ብታስር፥'),
  ('4cb8d1d9-ddaf-5814-a13a-696e572c9ef0', '64f4c1dc-d9bc-5add-a1fc-78caa57c54ee', '3748fbff-0713-5400-a535-b15f7d139d7b', 11, 11, 'ባልዋም ሰምቶ ዝም ቢላት፥ ባይከለክላትም፥ ስእለቷ ሁሉ ራስዋንም ያሰረችበት መሐላ ሁሉ ይጸናል።'),
  ('cc5aef02-0ff4-58a1-a10e-e6324e5f9581', '64f4c1dc-d9bc-5add-a1fc-78caa57c54ee', '3748fbff-0713-5400-a535-b15f7d139d7b', 12, 12, 'ባልዋ ግን በሰማበት ቀን ስእለቷን ቢከለክላት፥ ስለ ስእለቷ ወይም ራስዋን ስላሰረችበት መሐላ ከአፍዋ የወጣው ነገር አይጸናም፤ ባልዋ ከልክሏታል፤ እግዚአብሔርም ያነጻታል።'),
  ('9c01a183-9f9a-5baa-af3e-59637037313d', '64f4c1dc-d9bc-5add-a1fc-78caa57c54ee', '3748fbff-0713-5400-a535-b15f7d139d7b', 13, 13, '“ስእለቷን ሁሉ፥ ነፍስዋንም የሚያዋርደውን የመሐላ ማሰሪያ ሁሉ ባልዋ ያጸናዋል፤ ወይም ባልዋ ይከለክለዋል።'),
  ('e5bf1656-7c97-59f8-a722-dcfc17a69746', '64f4c1dc-d9bc-5add-a1fc-78caa57c54ee', '3748fbff-0713-5400-a535-b15f7d139d7b', 14, 14, 'ነገር ግን በየዕለቱ ዝም ቢላት፥ ስእለቷን ሁሉ፥ በእርስዋም ላይ ያለውን መሐላ ሁሉ ያጸናዋል፤ በሰማበት ቀን ዝም ብሎአታልና አጽንቶታል።'),
  ('eb83f5fb-1a67-5664-a7df-2e4c66e59383', '64f4c1dc-d9bc-5add-a1fc-78caa57c54ee', '3748fbff-0713-5400-a535-b15f7d139d7b', 15, 15, 'ከሰማው በኋላ ግን ቢከለክላት ኀጢአቱን ይሸከማል።”'),
  ('97a83c48-a6cd-54a0-ac1a-97005d73df05', '64f4c1dc-d9bc-5add-a1fc-78caa57c54ee', '3748fbff-0713-5400-a535-b15f7d139d7b', 16, 16, 'እርስዋ በብላቴንነቷ ጊዜ በአባቷ ቤት ሳለች በአባትና በልጂቱ መካከል፥ ወይም በባልና በሚስት መካከል ይሆን ዘንድ እግዚአብሔር ሙሴን ያዘዘው ሥርዐት ይህ ነው።'),
  ('bbe92bb3-2190-5b98-a40f-8152689cb929', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', 'fea1dee3-0dae-5877-a91b-97dc319f0e06', 1, 1, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('dfc3f5e1-7d6d-5b58-a69c-3bc818a93a4e', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', 'fea1dee3-0dae-5877-a91b-97dc319f0e06', 2, 2, '“የእስራኤልን ልጆች በቀል ምድያማውያንን ተበቀል፤ ከዚያም በኋላ ወደ ወገኖችህ ትጨመራለህ።”'),
  ('17968217-27b9-5b7e-a3e4-f0a688046607', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', 'fea1dee3-0dae-5877-a91b-97dc319f0e06', 3, 3, 'ሙሴም ለሕዝቡ እንዲህ ብሎ ነገራቸው፥ “ከእናንተ መካከል ሰዎችን አስታጥቁ፤ ከእግዚአብሔር ዘንድ ምድያምን ይበቀሉ ዘንድ በእግዚአብሔር ፊት ከምድያም ጋር ይሰለፉ።'),
  ('eca76c34-61de-58cc-a5d4-b41fb89fa841', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', 'fea1dee3-0dae-5877-a91b-97dc319f0e06', 4, 4, 'ከእስራኤል ነገዶች ሁሉ ከየነገዱ አንድ አንድ ሺህ ሰው ወደ ጦርነት ስደዱ፤”'),
  ('9102ac8c-8948-5780-adca-ec27fb56b3f6', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', 'fea1dee3-0dae-5877-a91b-97dc319f0e06', 5, 5, 'ከእስራኤልም አእላፋት፥ ከየነገዱ አንድ አንድ ሺህ ቈጠሩ፤ ለጦርነት የተሰለፉትም ዐሥራ ሁለት ሺህ ሆኑ።'),
  ('88553bea-f85c-5435-a204-831195f69c3b', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', 'fea1dee3-0dae-5877-a91b-97dc319f0e06', 6, 6, 'ሙሴም ከየነገዱ አንድ ሺህ ከሠራዊታቸውና ከካህኑ ከአሮን ልጅ ከአልዓዛር ልጅ ከፊንሐስ ጋር ሰደደ፤ ንዋያተ ቅድሳቱና ምልክት መስጫ መለከቶችም በእጆቻቸው ነበሩ።'),
  ('b3f15f42-ab92-5254-a1b3-d0a53c9a77a6', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', 'fea1dee3-0dae-5877-a91b-97dc319f0e06', 7, 7, 'እግዚአብሔርም ሙሴን እንዳዘዘ ከምድያም ጋር ተዋጉ፤ ወንዶችንም ሁሉ ገደሉ።'),
  ('ffffdb3b-efb8-50a3-a9a0-fe0239e6cfc0', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', 'fea1dee3-0dae-5877-a91b-97dc319f0e06', 8, 8, 'የምድያምንም ነገሥታት በዚያው ጦርነት በአንድነት ገደሉአቸው፤ አምስቱም የምድያም ነገሥታት ኤዊ፥ ሮቆም፥ ሱር፥ ሑር፥ ሮባቅ ነበሩ፤ የቢዖርንም ልጅ በለዓምን ደግሞ በዚያው ጦርነት በሰይፍ ገደሉት።'),
  ('5a712e15-2d37-5b97-ab2e-45084bb5b057', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', 'fea1dee3-0dae-5877-a91b-97dc319f0e06', 9, 9, 'የምድያምንም ሴቶችና ልጆቻቸውን ማረኩ፤ እንስሶቻቸውንና ዕቃቸውን፥ ንብረታቸውንና ኀይላቸውን በዘበዙ።'),
  ('63ad39de-d50b-588a-ae4e-27fe91fb34f9', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', 'fea1dee3-0dae-5877-a91b-97dc319f0e06', 10, 10, 'የተቀመጡባቸውን ከተሞቻቸውን ሁሉ፥ ሰፈሮቻቸውንም ሁሉ በእሳት አቃጠሉ።'),
  ('0d5cf439-24f0-5fa6-ae7f-25c9bfc1125d', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', 'fea1dee3-0dae-5877-a91b-97dc319f0e06', 11, 11, 'ከሰው እስከ እንስሳ ምርኮአቸውንና ብዝበዛቸውን ሁሉ ወሰዱ።'),
  ('38d50238-a166-505d-a3f1-76ad3cb1fb0f', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', 'fea1dee3-0dae-5877-a91b-97dc319f0e06', 12, 12, 'የማረኩትን ምርኮውንና የዘረፉትን ወደ ሙሴና ወደ ካህኑ ወደ አልዓዛር፥ ወደ እስራኤልም ልጆች፥ በዮርዳኖስም አጠገብ በኢያሪኮ ፊት ለፊት በሞዓብ ሜዳ ወዳለው ሰፈር አመጡ።'),
  ('5f3eefc9-fbe1-529c-a448-1294df64999b', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', '7693e682-e3ef-590a-a8ae-80bab0bd3328', 1, 13, 'ሙሴና ካህኑ አልዓዛርም፥ የማኅበሩም አለቆች ሁሉ ከሰፈሩ ወደ ውጭ ሊገናኙአቸው ወጡ።'),
  ('67e4e181-604f-5432-ab75-93b03986912e', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', '7693e682-e3ef-590a-a8ae-80bab0bd3328', 2, 14, 'ሙሴም ከዘመቻ በተመለሱት በጭፍራ አለቆች፥ በሻለቆችና በመቶ አለቆች ላይ ተቈጣ።'),
  ('5d56ad67-d8e3-5d1d-a177-3fa87e03aa67', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', '7693e682-e3ef-590a-a8ae-80bab0bd3328', 3, 15, 'ሙሴም አላቸው፥ “ሴቶችን ሁሉ ለምን አዳናችኋቸው?'),
  ('6f4f9652-3494-52d3-ac23-a8b53433ea31', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', '7693e682-e3ef-590a-a8ae-80bab0bd3328', 4, 16, 'እነርሱ በበለዓም ምክር በፌጎር ምክንያት የእስራኤልን ልጆች የሚያስቱ፥ የእግዚአብሔርንም ቃል እንዲስቱ የሚያደርጉ ዕንቅፋቶች ናቸውና፤ ስለዚህም በእግዚአብሔር ማኅበር ላይ መቅሠፍት ሆኖአል፤'),
  ('1118219b-e8b1-5428-a01d-c06835a2d684', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', '7693e682-e3ef-590a-a8ae-80bab0bd3328', 5, 17, 'አሁንም እንግዲህ ወንዱን ሁሉ በአለበት ግደሉ፥ ወንድንም የምታውቀውን ሴት ሁሉ ግደሉ።'),
  ('663c472c-2dac-582a-a282-398157e2cdc8', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', '7693e682-e3ef-590a-a8ae-80bab0bd3328', 6, 18, 'ወንድን የማያውቁትን ሴቶች ልጆችን ሁሉ ግን አድኑአቸው።'),
  ('5ff58c88-c856-5136-aee3-1cd4d5ba8e9e', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', '7693e682-e3ef-590a-a8ae-80bab0bd3328', 7, 19, 'እናንተም ከሰፈሩ ውጭ ሰባት ቀን ስፈሩ፤ ሰውን የገደለ ሁሉ፥ የተገደለውንም የዳሰሰ ሁሉ፥ እናንተና የማረካችኋቸውም በሦስተኛውና በሰባተኛው ቀን ሰውነታችሁን ንጹሕ አድርጉ።'),
  ('92bce38e-2a5c-517e-a2d7-5cfdffc214a0', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', '7693e682-e3ef-590a-a8ae-80bab0bd3328', 8, 20, 'ልብስንም፥ ከቁርበትም የተዘጋጀውን ሁሉ፥ ከፍየልም ጠጕር፥ ከዕንጨትም የተሠራውን ሁሉ ንጹሕ አድርጉ።”'),
  ('54bb7988-f598-5ece-a811-39d649cec81e', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', '7693e682-e3ef-590a-a8ae-80bab0bd3328', 9, 21, 'ካህኑም አልዓዛር ከሰልፍ የመጡትን ሰዎች አላቸው፥ “እግዚአብሔር ሙሴን ያዘዘው የሕጉ ሥርዐት ይህ ነው፤'),
  ('2ff6036f-8e6b-5882-affe-ac9b14fb6c6c', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', '7693e682-e3ef-590a-a8ae-80bab0bd3328', 10, 22, 'ወርቁና ብሩ፥ ናሱም፥ ብረቱም፥ ቆርቆሮውም፥ እርሳሱም፥'),
  ('f03f3d8a-5d12-5029-a6d4-c304761f8e36', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', '7693e682-e3ef-590a-a8ae-80bab0bd3328', 11, 23, 'በእሳት ለማለፍ የሚችለው ነገር ሁሉ፥ ንጹሕ ይሆናል፤ ነገር ግን በማንጻት ውኃ ደግሞ ይጠራል። በእሳትም ለማለፍ የማይችለውን በውኃ ታሳልፉታላችሁ።'),
  ('36f65bcc-3aac-50e3-a6d2-3005c77ada40', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', '7693e682-e3ef-590a-a8ae-80bab0bd3328', 12, 24, 'በሰባተኛውም ቀን ልብሳችሁን እጠቡ፤ ንጹሓንም ትሆናላችሁ፤ ከዚያም በኋላ ወደ ሰፈሩ ትቀርባላችሁ።”'),
  ('f42f7e7e-e518-5aea-aaf8-464ac653eb89', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', '3a678636-06ee-55e9-a2e7-d6415f3faaaa', 1, 25, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('07b43834-ac4e-5b17-adae-446c2867717d', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', '3a678636-06ee-55e9-a2e7-d6415f3faaaa', 2, 26, '“አንተና ካህኑ አልዓዛር፥ የማኅበሩም አባቶች አለቆች የተማረኩትን ሰውና እንስሳ ቍጠሩ።'),
  ('21687efd-30fe-51d8-abe7-75180eba3799', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', '3a678636-06ee-55e9-a2e7-d6415f3faaaa', 3, 27, 'ምርኮውንም በተዋጉትና ወደ ሰልፍ በወጡት፥ በማኅበሩም ሁሉ መካከል ትከፍላላችሁ።'),
  ('f0a9e719-2418-500b-ad6c-09805809ba46', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', '3a678636-06ee-55e9-a2e7-d6415f3faaaa', 4, 28, 'ከእነዚያም ከተዋጉት፥ ወደ ሰልፍም ከወጡት ሰልፈኞች ዘንድ ከሰዎችም፥ ከበሬዎችም፥ ከበጎችም፥ ከአህዮችም፥ ከአምስት መቶ አንድ ለእግዚአብሔር ግብር ታወጣላችሁ።'),
  ('6f0f58e9-5511-521b-a3c8-0bb7d8c1d739', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', '3a678636-06ee-55e9-a2e7-d6415f3faaaa', 5, 29, 'ከድርሻቸው እኩሌታ ወስደህ የእግዚአብሔርን ቀዳምያት ለካህኑ ለአልዓዛር ትሰጠዋለህ።'),
  ('c73231a7-9b5e-54d9-a034-66685233f7b8', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', '3a678636-06ee-55e9-a2e7-d6415f3faaaa', 6, 30, 'ከእስራኤልም ልጆች ድርሻ እኩሌታ፥ ከሰዎችም፥ ከበሬዎችም፥ ከበጎችም፥ ከአህዮችም፥ ከእንስሶችም ሁሉ ከአምሳ አንድ ትወስዳለህ፤ የእግዚአብሔርንም ድንኳን ሥርዐት ለሚጠብቁ ለሌዋውያን ትሰጣለህ።”'),
  ('87570b33-ec06-5b91-acbd-e5e07391b672', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', '3a678636-06ee-55e9-a2e7-d6415f3faaaa', 7, 31, 'ሙሴና ካህኑ አልዓዛርም እግዚአብሔር ሙሴን እንዳዘዘው አደረጉ።'),
  ('84b02d82-baf5-50a2-ac2f-d16fba6412ed', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', '3a678636-06ee-55e9-a2e7-d6415f3faaaa', 8, 32, 'ወደ ሰልፍ የወጡ ሰዎችም ከወሰዱት ብዝበዛ የቀረው ምርኮ እንዲህ ሆነ፤ ስድስት መቶ ሰባ አምስት ሺህ በጎች፤'),
  ('2e7424f6-2a38-5f9d-a9b2-2c79ba7c94e6', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', '3a678636-06ee-55e9-a2e7-d6415f3faaaa', 9, 33, 'ሰባ ሁለት ሺህ በሬዎች፥'),
  ('703c3788-d543-5d3b-ab1f-d2644596cfa3', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', '3a678636-06ee-55e9-a2e7-d6415f3faaaa', 10, 34, 'ስድሳ አንድ ሺህ አህዮች፥'),
  ('69d348f4-470d-59b9-a2ca-b568309742ce', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', '3a678636-06ee-55e9-a2e7-d6415f3faaaa', 11, 35, 'ወንድ ከማያውቁ ሴቶችም ሠላሳ ሁለት ሺህ ነፍስ።'),
  ('cd70fa0a-3fdf-56b1-a176-53ed4816fc6b', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', '3a678636-06ee-55e9-a2e7-d6415f3faaaa', 12, 36, 'በዘመቻም ለነበሩ ሰዎች ድርሻ የሆነ እኩሌታ ከበግ ሦስት መቶ ሠላሳ ሰባት ሺህ አምስት መቶ በጎች ነበሩ፤'),
  ('4a2904b4-3bdc-5787-a6dd-2cf85be4d00b', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', '3a678636-06ee-55e9-a2e7-d6415f3faaaa', 13, 37, 'ከበጎችም የእግዚአብሔር ግብር ስድስት መቶ ሰባ አምስት ነበረ።'),
  ('848b0c14-8365-5676-a3c9-2c9a30239215', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', '3a678636-06ee-55e9-a2e7-d6415f3faaaa', 14, 38, 'በሬዎችም ሠላሳ ስድስት ሺህ ነበሩ፤ የእግዚአብሔርም ግብር ሰባ ሁለት ነበረ።'),
  ('79dc5a22-873b-5f15-a5cb-0a562a93cf50', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', '3a678636-06ee-55e9-a2e7-d6415f3faaaa', 15, 39, 'አህዮቹም ሠላሳ ሺህ አምስት መቶ ነበሩ፤ የእግዚአብሔርም ግብር ስድሳ አንድ ነበረ።'),
  ('d1f99059-4202-52b7-a856-d4cdd749995f', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', '3a678636-06ee-55e9-a2e7-d6415f3faaaa', 16, 40, 'ሰዎቹም ዐሥራ ስድስት ሺህ ነበሩ ፤ የእግዚአብሔርም ግብር ሠላሳ ሁለት ነበረ።'),
  ('1be1119a-db30-5399-a963-e75b3b067cac', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', '3a678636-06ee-55e9-a2e7-d6415f3faaaa', 17, 41, 'እግዚአብሔርም ሙሴን እንዳዘዘው ሙሴ፦ ለእግዚአብሔር የለዩትን ግብር ለካህኑ ለአልዓዛር ሰጠው።'),
  ('7382bf50-8e4d-5a23-a6b4-7bb16ec08501', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', '3a678636-06ee-55e9-a2e7-d6415f3faaaa', 18, 42, 'ከእስራኤል ልጆች እኩሌታም፥ ወደ ሰልፍ ከወጡት ወንዶች ላይ ሙሴ የለየው፥'),
  ('563c35fc-193b-513e-a033-7c72b3061c58', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', '3a678636-06ee-55e9-a2e7-d6415f3faaaa', 19, 43, 'የማኅበሩ ድርሻ ሦስት መቶ ሠላሳ ሰባት ሺህ አምስት መቶ በጎች፥'),
  ('ea2af5a5-8a01-5c8a-ae51-36e1e40c5f54', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', '3a678636-06ee-55e9-a2e7-d6415f3faaaa', 20, 44, 'ሠላሳ ስድስት ሺህ በሬዎች፤'),
  ('0d6d4e48-14bc-5106-a206-53a383457b3b', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', '3a678636-06ee-55e9-a2e7-d6415f3faaaa', 21, 45, 'ሠላሳ ሺህ አምስት መቶ አህዮች፥'),
  ('6c78e69c-b3fd-5b28-a9a2-51c245b1ddcf', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', '3a678636-06ee-55e9-a2e7-d6415f3faaaa', 22, 46, 'ዐሥራ ስድስት ሺህ ሰዎች ነበሩ።'),
  ('cbc94a3e-68ac-537a-a4f3-ce1eaf624f24', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', '3a678636-06ee-55e9-a2e7-d6415f3faaaa', 23, 47, 'ሙሴ ከእስራኤል ልጆች ድርሻ ከሰውና ከእንስሳ ከሃምሳ አንድ ወሰደ፤ እግዚአብሔርም ሙሴን እንዳዘዘው የእግዚአብሔርን ድንኳን ሥርዐት ለሚጠብቁ ሌዋውያን ሰጠ።'),
  ('e5db719c-ee34-5ec3-ae31-c1fddcde4ba5', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', '3a678636-06ee-55e9-a2e7-d6415f3faaaa', 24, 48, 'በሠራዊት አእላፋት ላይ የተሾሙት አለቆች፥ ሻለቆችና የመቶ አለቆች ወደ ሙሴ ቀረቡ፤ ሙሴንም እንዲህ አሉት፦'),
  ('b9f34db2-d664-585c-addf-7bddf49cdee6', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', '3a678636-06ee-55e9-a2e7-d6415f3faaaa', 25, 49, '“ባሪያዎችህ ወደ ሰልፍ የወጡትን ከእጃችን በታች ያሉትን ቈጠሩ፤ ከእኛም አንድ አልጐደለም።'),
  ('90795811-89eb-50d4-ad97-918023612ac8', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', '3a678636-06ee-55e9-a2e7-d6415f3faaaa', 26, 50, 'ሰውም ሁሉ ከአገኘው ከወርቅ ዕቃ፥ ከእግር አልቦም፥ ከአምባርም፥ ከቀለበትም ከጕትቻም፥ ከድሪውም ስለ እኛ በእግዚአብሔር ፊት ታስተሰርዩልን ዘንድ ለእግዚአብሔር መባ አምጥተናል” አሉት።'),
  ('623d04c2-80b6-550c-a455-1f28455d1a2f', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', '3a678636-06ee-55e9-a2e7-d6415f3faaaa', 27, 51, 'ሙሴና ካህኑ አልዓዛርም ወርቁንና በልዩ ልዩ የተሠራውን ዕቃ ሁሉ ከእጃቸው ተቀበሉ።'),
  ('9332497b-55c1-5007-a09e-ce0a857e3dd5', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', '3a678636-06ee-55e9-a2e7-d6415f3faaaa', 28, 52, 'ከሻለቆችና ከመቶ አለቆች ለእግዚአብሔር የለዩትና ያቀረቡት ወርቅ ሁሉ ዐሥራ ስድስት ሺህ ሰባት መቶ አምሳ ሰቅል ነበረ።'),
  ('83815f20-b467-56f6-a264-900542a7c0c1', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', '3a678636-06ee-55e9-a2e7-d6415f3faaaa', 29, 53, 'ወደ ሰልፍ የወጡ ሰዎች ሁሉ የማረኩትን ለየራሳቸው ወሰዱ።'),
  ('b7a73f39-2054-5a40-a60c-6295ac051805', 'ed128094-c10c-5e13-add2-7ce881fcc5e8', '3a678636-06ee-55e9-a2e7-d6415f3faaaa', 30, 54, 'ሙሴና ካህኑ አልዓዛርም ወርቁን ከሻለቆችና ከመቶ አለቆች ወሰዱ፤ በእግዚአብሔርም ፊት ለእስራኤል ልጆች መታሰቢያ ወደ ምስክሩ ድንኳን አገቡት።'),
  ('cfbc5fb5-a01a-5af5-a7c1-7a57f8cce661', '61a47e50-5e8a-51e8-a331-6767f9afcbce', '3fabfc4b-8152-5030-a606-e6d8888fd201', 1, 1, 'ለሮቤል ልጆችና ለጋድ ልጆች እጅግ ብዙ እንስሶች ነበሩአቸው፤ እነሆም፥ የኢያዜር ምድርና የገለዓድ ምድር የከብት ሀገር እንደ ነበረ አዩ።'),
  ('4a1947d6-6d43-58f1-a890-2396e1e1f2fe', '61a47e50-5e8a-51e8-a331-6767f9afcbce', '3fabfc4b-8152-5030-a606-e6d8888fd201', 2, 2, 'የሮቤል ልጆችና የጋድ ልጆችም መጥተው ሙሴንና ካህኑን አልዓዛርን፥ የማኅበሩንም አለቆች እንዲህ ብለው ተናገሩአቸው፦'),
  ('5e919b4e-ee9e-53ae-a0ca-1a8d103ed28f', '61a47e50-5e8a-51e8-a331-6767f9afcbce', '3fabfc4b-8152-5030-a606-e6d8888fd201', 3, 3, '“አጣሮት፥ ዲቦን፥ ያዜር፥ ነምራ፥ ሐሴቦን፥ ኤልያሌ፥ ሲባማ፥ ናባው፥ ቤያን፤'),
  ('7ed39ab7-466c-5340-ac39-cc0986c3621e', '61a47e50-5e8a-51e8-a331-6767f9afcbce', '3fabfc4b-8152-5030-a606-e6d8888fd201', 4, 4, 'እግዚአብሔር በእስራኤል ልጆች ፊት የሰጣት ምድር የከብት መሰማሪያ ሀገር ናት፤ ለእኛም ለአገልጋዮችህ ብዙ እንስሳት አሉን።'),
  ('313e5138-e13b-5b5a-ada6-dfec7e77761c', '61a47e50-5e8a-51e8-a331-6767f9afcbce', '3fabfc4b-8152-5030-a606-e6d8888fd201', 5, 5, 'እኛስ በአንተ ዘንድ ሞገስን አግኝተን እንደ ሆነ ይህን ምድር ለአገልጋዮችህ ርስት አድርገህ ስጠን፤ ዮርዳኖስን አታሻግረን።”'),
  ('c39dcdf4-fcd3-56ae-a68d-fced3322b840', '61a47e50-5e8a-51e8-a331-6767f9afcbce', '3fabfc4b-8152-5030-a606-e6d8888fd201', 6, 6, 'ሙሴም ለሮቤል ልጆችና ለጋድ ልጆች አላቸው፥ “ወንድሞቻችሁ ወደ ጦርነት ሲሄዱ እናንተ በዚህ ትቀመጣላችሁን?'),
  ('cb603f56-f56e-50c7-a871-477b19c7e702', '61a47e50-5e8a-51e8-a331-6767f9afcbce', '3fabfc4b-8152-5030-a606-e6d8888fd201', 7, 7, 'እግዚአብሔር ወደሚሰጣቸው ምድር እንዳይሻገሩ የእስራኤልን ልጆች ልብ ለምን ታጣምማላችሁ?'),
  ('936ced38-ce52-5bc8-a6cb-b2ce4a716082', '61a47e50-5e8a-51e8-a331-6767f9afcbce', '3fabfc4b-8152-5030-a606-e6d8888fd201', 8, 8, 'ምድሪቱን ይሰልሉ ዘንድ ከቃዴስ በርኔ በላክኋቸው ጊዜ አባቶቻችሁ እንዲህ አድርገው አልነበረምን?'),
  ('cc58799e-3286-576b-a7bf-531f02ccbebb', '61a47e50-5e8a-51e8-a331-6767f9afcbce', '3fabfc4b-8152-5030-a606-e6d8888fd201', 9, 9, 'ወደ ወይን ዘለላ ሸለቆ መጡ፤ ምድሪቱንም አዩአት፤ እግዚአብሔርም ወደ ሰጣቸው ምድር እንዳይገቡ የእስራኤልን ልጆች ልብ መለሱ።'),
  ('39aa1e7c-db83-5cbe-ae49-7f90786e21d6', '61a47e50-5e8a-51e8-a331-6767f9afcbce', '3fabfc4b-8152-5030-a606-e6d8888fd201', 10, 10, 'በዚያም ቀን እግዚአብሔር ተቈጣ፤ እንዲህም ብሎ ማለ፦'),
  ('0544b9ee-3fb5-5e22-a8f5-789a6ea95bc7', '61a47e50-5e8a-51e8-a331-6767f9afcbce', '3fabfc4b-8152-5030-a606-e6d8888fd201', 11, 11, 'ከግብፅ የወጡት ከሃያ ዓመት ጀምሮ ከዚያም በላይ ያሉት መልካምንና ክፉን የሚያውቁ ሰዎች እኔን ፈጽመው አልተከተሉምና ለአብርሃምና ለይስሐቅ ለያዕቆብም እሰጥ ዘንድ የማልሁባትን ምድር አያዩም፤'),
  ('5fef6bc6-de48-50c2-ae54-ee9cd5da8c34', '61a47e50-5e8a-51e8-a331-6767f9afcbce', '3fabfc4b-8152-5030-a606-e6d8888fd201', 12, 12, 'እግዚአብሔርን ተከትለዋልና ከእነዚህ፥ ልዩ ከሆነ ከዮፎኒ ልጅ ከካሌብና ከነዌ ልጅ ከኢያሱ በቀር፤'),
  ('0f699d40-b5ab-53f7-a9ce-5836aa4cfbc3', '61a47e50-5e8a-51e8-a331-6767f9afcbce', '3fabfc4b-8152-5030-a606-e6d8888fd201', 13, 13, 'እግዚአብሔርም በእስራኤል ላይ በጠና ተቈጣ። በእግዚአብሔርም ፊት ክፉ ያደረገ ትውልድ ሁሉ እስኪጠፋ ድረስ አርባ ዓመት በምድረ በዳ ውስጥ አንከራተታቸው።'),
  ('432918a8-2ad2-54f0-a9b5-fa690355a1ec', '61a47e50-5e8a-51e8-a331-6767f9afcbce', '3fabfc4b-8152-5030-a606-e6d8888fd201', 14, 14, 'እነሆም፥ የእግዚአብሔርን መዓት በእስራኤል ላይ አብዝታችሁ ትጨምሩ ዘንድ እናንተ በኀጢአተኞች ሰዎች በደል በአባቶቻችሁ ፋንታ ተነሥታችኋል።'),
  ('4c1ac1ec-bfd2-50df-a97f-186b4f3cbe51', '61a47e50-5e8a-51e8-a331-6767f9afcbce', '3fabfc4b-8152-5030-a606-e6d8888fd201', 15, 15, 'እርሱን ትታችሁታልና ዳግመኛም በምድረ በዳ ትታችሁታል፤ በዚችም ማኅበር ሁሉ ላይ ትበድላላችሁ።”'),
  ('314b756a-be2b-5545-ad12-837d86100600', '61a47e50-5e8a-51e8-a331-6767f9afcbce', '3fabfc4b-8152-5030-a606-e6d8888fd201', 16, 16, 'ወደ እርሱም ቀርበው አሉት፥ “በዚህ ለእንስሶቻችን በረቶችን፥ ለልጆቻችንም ከተሞችን እንሠራለን፤'),
  ('6aaec04b-548f-54f1-a4e0-23126deefe33', '61a47e50-5e8a-51e8-a331-6767f9afcbce', '3fabfc4b-8152-5030-a606-e6d8888fd201', 17, 17, 'እኛ ግን ለጦርነት ታጥቀን ወደ ስፍራቸው እስክናገባቸው ድረስ በእስራኤል ልጆች ፊት እንሄዳለን፤ በዚህም ምድር ስላሉ ሰዎች ልጆቻችን በተመሸጉ ከተሞች ይቀመጣሉ።'),
  ('0144a7ab-2453-52b5-a7b2-2659bd0d3564', '61a47e50-5e8a-51e8-a331-6767f9afcbce', '3fabfc4b-8152-5030-a606-e6d8888fd201', 18, 18, 'የእስራኤል ልጆች ሁሉ ርስታቸውን እስኪወርሱ ድረስ ወደ ቤታችን አንመለስም፤'),
  ('2a6879cc-514c-5059-afb3-c63c86a4d0d6', '61a47e50-5e8a-51e8-a331-6767f9afcbce', '3fabfc4b-8152-5030-a606-e6d8888fd201', 19, 19, 'ከዮርዳኖስ ወዲህ ወደ ምሥራቅ ርስታችን ደርሶናልና እኛ ከዮርዳኖስ ማዶ ወደዚያ ከእነርሱም ጋር ርስት አንወርስም።”'),
  ('6a99b27b-7818-5cbb-afbe-483fc58ba35e', '61a47e50-5e8a-51e8-a331-6767f9afcbce', '3fabfc4b-8152-5030-a606-e6d8888fd201', 20, 20, 'ሙሴም አላቸው፥ “ይህንስ እንዳላችሁት ብታደርጉ፥ ታጥቃችሁም በእግዚአብሔር ፊት ወደ ጦርነት ብትሄዱ፥'),
  ('45334613-92cf-52ff-a1ac-d6e6a63ac89d', '61a47e50-5e8a-51e8-a331-6767f9afcbce', '3fabfc4b-8152-5030-a606-e6d8888fd201', 21, 21, 'እርሱም ጠላቱ ከፊቱ እስኪጠፋ ድረስ ከእናንተ እያንዳንዱ ሰው የጦር መሣሪያውን ይዞ በእግዚአብሔር ፊት ዮርዳኖስን ቢሻገር፥'),
  ('26d10db4-f0c0-532c-a189-7cadd8cccc0e', '61a47e50-5e8a-51e8-a331-6767f9afcbce', '3fabfc4b-8152-5030-a606-e6d8888fd201', 22, 22, 'ምድሪቱም በእግዚአብሔር ፊት ድል እስክትሆን ድረስ ከዚያም በኋላ ትመለሳላችሁ፤ በእግዚአብሔርም ፊት በእስራኤል ዘንድ ንጹሓን ትሆናላችሁ፤ ይህች ምድርም በእግዚአብሔር ፊት ርስት ትሆናችኋለች።'),
  ('14af5623-f596-5179-aa78-2e55c3d4d319', '61a47e50-5e8a-51e8-a331-6767f9afcbce', '3fabfc4b-8152-5030-a606-e6d8888fd201', 23, 23, 'እንዲህ ባታደርጉ ግን፥ በእግዚአብሔር ፊት ትበድላላችሁ፤ ክፉ ነገር ባገኛችሁ ጊዜ በደላችሁን ታውቃላችሁ።'),
  ('f8a56c8d-1a13-539b-a485-9561df83617e', '61a47e50-5e8a-51e8-a331-6767f9afcbce', '3fabfc4b-8152-5030-a606-e6d8888fd201', 24, 24, 'ለልጆቻችሁ ከተሞችን፥ ለበጎቻችሁም በረቶችን ሥሩ፤ ከአፋችሁም የወጣውን ነገር አድርጉ።”'),
  ('8d81d453-c1a6-53bc-a37d-13f23b7c9cf9', '61a47e50-5e8a-51e8-a331-6767f9afcbce', '3fabfc4b-8152-5030-a606-e6d8888fd201', 25, 25, 'የሮቤል ልጆችና የጋድ ልጆችም ሙሴን እንዲህ ብለው ተናገሩት፥ “እኛ አገልጋዮችህ ጌታችን እንዳዘዘ እናደርጋለን።'),
  ('f2a21a41-dc06-5c6b-ab54-99368f92099c', '61a47e50-5e8a-51e8-a331-6767f9afcbce', '3fabfc4b-8152-5030-a606-e6d8888fd201', 26, 26, 'ልጆቻችን ሚስቶቻችንም፥ እንሰሶቻችንም ሁሉ በዚያ በገለዓድ ከተሞች ይሆናሉ፤'),
  ('f35f1f98-fa81-560a-a877-8f95224c8306', '61a47e50-5e8a-51e8-a331-6767f9afcbce', '3fabfc4b-8152-5030-a606-e6d8888fd201', 27, 27, 'እኛ አገልጋዮችህ ግን ሁላችን የጦር መሣሪያችንን ይዘን በእግዚአብሔር ፊት ጌታችን እንደ ተናገረ ወደ ጦርነት እንሄዳለን።”'),
  ('40d74d04-8a2b-5537-a093-9dbb57182e80', '61a47e50-5e8a-51e8-a331-6767f9afcbce', '3fabfc4b-8152-5030-a606-e6d8888fd201', 28, 28, 'ሙሴም ካህኑን አልዓዛርን፥ የነዌንም ልጅ ኢያሱን፥ የእስራኤልንም ነገድ አባቶች አለቆች አዘዛቸው።'),
  ('59a7161c-9caf-5fe1-a9c3-247a76dee8dc', '61a47e50-5e8a-51e8-a331-6767f9afcbce', '3fabfc4b-8152-5030-a606-e6d8888fd201', 29, 29, 'ሙሴም፥ “የሮቤል ልጆችና የጋድ ልጆች ሁላቸው የጦር መሣሪያቸውን ይዘው ከእናንተ ጋር በእግዚአብሔር ፊት ለጦርነት ዮርዳኖስን ቢሻገሩ፥ ምድሪቱንም ድል ብትነሡ ፥ የገለዓድን ምድር ርስት አድርጋችሁ ትሰጡአቸዋላችሁ።'),
  ('04bdfaea-2434-5174-aa0c-f365ac568181', '61a47e50-5e8a-51e8-a331-6767f9afcbce', '3fabfc4b-8152-5030-a606-e6d8888fd201', 30, 30, 'የጦር መሣሪያቸውን ይዘው ከእናንተ ጋር በእግዚአብሔር ፊት ወደ ጦርነት ባይሻገሩ ግን ልጆቻቸውን፥ ሚስቶቻቸውን፥ ከብቶቻቸውንም በፊታችሁ ወደ ከነዓን ምድር ንዱአቸው፤ በከነዓን ምድር በእናንተ መካከል ርስታቸውን ይወርሳሉ” አላቸው።'),
  ('223ccaf5-b164-5a68-abb5-0e613490f68a', '61a47e50-5e8a-51e8-a331-6767f9afcbce', '3fabfc4b-8152-5030-a606-e6d8888fd201', 31, 31, 'የሮቤል ልጆችና የጋድ ልጆችም መልሰው፥ “ጌታችን ለእኛ ለአገልጋዮችህ እንደ ተናገረ እንዲሁ እናደርጋለን።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('42a7e06b-50cc-54dd-a6aa-ba399b6bb666', '61a47e50-5e8a-51e8-a331-6767f9afcbce', '3fabfc4b-8152-5030-a606-e6d8888fd201', 32, 32, 'የጦር መሣሪያችንን ይዘን በእግዚአብሔር ፊት ወደ ከነዓን ምድር እንሻገራለን፤ ከዮርዳኖስም ማዶ የወረስነው ርስት ይሆንልናል” አሉት።'),
  ('6ff6a576-b0fe-5408-a209-f3d64b3abba3', '61a47e50-5e8a-51e8-a331-6767f9afcbce', '3fabfc4b-8152-5030-a606-e6d8888fd201', 33, 33, 'ሙሴም ለጋድ ልጆችና ለሮቤል ልጆች፥ ለዮሴፍም ልጅ ለምናሴ ነገድ እኩሌታ፥ የአሞሬዎናውያንን ንጉሥ የሴዎንን መንግሥት፥ የባሳንንም ንጉሥ የዐግን መንግሥት፥ ምድሪቱንም፥ ከተራሮችም ጋር ከተሞችን፥ በዙሪያቸውም ያሉትን የምድሪቱን ከተሞች ሰጣቸው።'),
  ('e35ef721-98e7-5c21-a599-2352dc411b0e', '61a47e50-5e8a-51e8-a331-6767f9afcbce', '3fabfc4b-8152-5030-a606-e6d8888fd201', 34, 34, 'የጋድ ልጆች ዲቦንን፥ አጣሮትን፥ አሮዔርን፤'),
  ('c4d5293a-4bfd-506b-adda-1cb28bc92cbd', '61a47e50-5e8a-51e8-a331-6767f9afcbce', '3fabfc4b-8152-5030-a606-e6d8888fd201', 35, 35, 'ሶፋንን፥ ኢያዜርን፥'),
  ('b8a5605f-8a1b-5f3a-a288-8988cef942e4', '61a47e50-5e8a-51e8-a331-6767f9afcbce', '3fabfc4b-8152-5030-a606-e6d8888fd201', 36, 36, 'ናምራን፥ ቤታራንን ሰባት የተመሸጉ ከተሞች አድርገው ሠሩ፤ አስረዘሙአቸውም፤ የበጎች በረቶችንም ሠሩ።'),
  ('d5740e97-3a7f-5dd0-ac6b-58d7bd81ccc7', '61a47e50-5e8a-51e8-a331-6767f9afcbce', '3fabfc4b-8152-5030-a606-e6d8888fd201', 37, 37, 'የሮቤልም ልጆች ሐሴቦንን፥ ኤልያሌንን፥ ቂርያታይምን፤ በቅጥር የተከበቡ በኤልሜዎንንና፥ ሴባማን ሠሩ፤'),
  ('c882535a-94e3-5b50-a754-47717c889392', '61a47e50-5e8a-51e8-a331-6767f9afcbce', '3fabfc4b-8152-5030-a606-e6d8888fd201', 38, 38, 'እነዚህንም የሠሩአቸውን ከተሞች በየስማቸው ጠሩአቸው።'),
  ('24e516c7-add6-5bcd-aded-4faa86904730', '61a47e50-5e8a-51e8-a331-6767f9afcbce', '3fabfc4b-8152-5030-a606-e6d8888fd201', 39, 39, 'የምናሴም ልጅ የማኪር ልጅ ወደ ገለዓድ ሄዶ ገለዓድን ያዘ፤ በእርስዋም የነበሩትን አሞሬዎናውያንን አጠፋ።'),
  ('9d9925ec-1ccf-5b1c-a914-c9bfbf4e596c', '61a47e50-5e8a-51e8-a331-6767f9afcbce', '3fabfc4b-8152-5030-a606-e6d8888fd201', 40, 40, 'ሙሴም ለምናሴ ልጅ ለማኪር ገለዓድን ሰጠው፤ በእርስዋም ተቀመጠ።'),
  ('706037eb-afd4-5720-a9d1-f691ebea1985', '61a47e50-5e8a-51e8-a331-6767f9afcbce', '3fabfc4b-8152-5030-a606-e6d8888fd201', 41, 41, 'የምናሴም ልጅ ኢያዕር ሄዶ መንደሮችዋን ወሰደ፤ የኢያዕርም መንደሮች ብሎ ጠራቸው።'),
  ('b9e9050f-5158-58df-ac61-105b56f2e1b2', '61a47e50-5e8a-51e8-a331-6767f9afcbce', '3fabfc4b-8152-5030-a606-e6d8888fd201', 42, 42, 'ናባውም ሄዶ ቄናትንም፥ መንደሮችዋንም ወሰደ፤ በስሙም ናቦት ብሎ ጠራቸው።'),
  ('f40779ce-7ed7-5ad6-aa01-f5183aa40af1', 'b00e81ef-9082-52f0-a614-3ec34c846efd', '013e163e-b011-5a64-a273-7ed453674c24', 1, 1, 'በሙሴና በአሮን እጅ ከሠራዊቶቻቸው ጋር ከግብፅ ከወጡ በኋላ የእስራኤል ልጆች የሰፈሩበት ይህ ነው።'),
  ('ad095e54-1608-575d-ab16-8eedaa45ffce', 'b00e81ef-9082-52f0-a614-3ec34c846efd', '013e163e-b011-5a64-a273-7ed453674c24', 2, 2, 'ሙሴም በእግዚአብሔር ትእዛዝ እንደ ተጓዙ የሰፈሩበትን ጻፈ፥ እየተጓዙ ያደሩበት ይህ ነው።'),
  ('d1228717-3476-5ff4-a8ac-0a1d67cb50aa', 'b00e81ef-9082-52f0-a614-3ec34c846efd', '013e163e-b011-5a64-a273-7ed453674c24', 3, 3, 'በመጀመሪያው ወር ከመጀመሪያውም ወር በዐሥራ አምስተኛው ቀን ከራምሴ ተጓዙ፤ ከፋሲካ በኋላ በነጋው የእስራኤል ልጆች ከግብፃውያን ሁሉ ፊት ከፍ ባለች እጅ ወጡ።'),
  ('2574797d-2c9d-5cf2-a8c7-0a0a731e2532', 'b00e81ef-9082-52f0-a614-3ec34c846efd', '013e163e-b011-5a64-a273-7ed453674c24', 4, 4, 'በዚያም ጊዜ ግብፃውያን እግዚአብሔር የገደላቸውን በኵሮቻቸውን ይቀብሩ ነበር፤ በአማልክቶቻቸውም ደግሞ እግዚአብሔር ፈረደባቸው።'),
  ('b1838dd4-61a1-5fdb-a041-16de1776e801', 'b00e81ef-9082-52f0-a614-3ec34c846efd', '013e163e-b011-5a64-a273-7ed453674c24', 5, 5, 'የእስራኤልም ልጆች ከራምሴ ተጕዘው በሱኮት ሰፈሩ።'),
  ('c10ce805-1566-5a7f-a509-c67e55ce20cd', 'b00e81ef-9082-52f0-a614-3ec34c846efd', '013e163e-b011-5a64-a273-7ed453674c24', 6, 6, 'ከሱኮትም ተጕዘው በምድረ በዳ ዳርቻ ባለች በኤታም ሰፈሩ።'),
  ('27715578-7d1f-5978-a2ba-76dac684c665', 'b00e81ef-9082-52f0-a614-3ec34c846efd', '013e163e-b011-5a64-a273-7ed453674c24', 7, 7, 'ከኤታምም ተጕዘው በኤልሴፎን ፊት ወደ ነበረች በኤሮት በር፤ በመግደሎ ፊት ለፊት ሰፈሩ።'),
  ('9ba39200-aac3-5370-a982-12cad44b4d78', 'b00e81ef-9082-52f0-a614-3ec34c846efd', '013e163e-b011-5a64-a273-7ed453674c24', 8, 8, 'ከኤሮትም ፊት ለፊት ተጕዘው በባሕሩ መካከል ወደ ምድረ በዳ ተሻገሩ፤ በኤታምም በረሃ የሦስት ቀን መንገድ ሄደው በምረት ሰፈሩ።'),
  ('465e38c7-1db8-538b-a4d6-41c0d9767917', 'b00e81ef-9082-52f0-a614-3ec34c846efd', '013e163e-b011-5a64-a273-7ed453674c24', 9, 9, 'ከምረትም ተጕዘው ወደ ኤሊም መጡ፤ በኤሊምም ዐሥራ ሁለት የውኃ ምንጮች፥ ሰባ ዘንባቦችም ነበሩ፤ በዚያም በውኃ አጠገብ ሰፈሩ።'),
  ('ae3a66c0-bc05-556a-a908-311377268adf', 'b00e81ef-9082-52f0-a614-3ec34c846efd', '013e163e-b011-5a64-a273-7ed453674c24', 10, 10, 'ከኤሊምም ተጕዘው በኤርትራ ባሕር ዳር ሰፈሩ።'),
  ('5f7fe508-1241-5d57-ac7b-fdfd99e15428', 'b00e81ef-9082-52f0-a614-3ec34c846efd', '013e163e-b011-5a64-a273-7ed453674c24', 11, 11, 'ከኤርትራም ባሕር ተጕዘው በሲና ምድረ በዳ ሰፈሩ።'),
  ('8da80ae2-1b4f-544d-a214-f97fef8598a4', 'b00e81ef-9082-52f0-a614-3ec34c846efd', '013e163e-b011-5a64-a273-7ed453674c24', 12, 12, 'ከሲና ምድረ በዳም ተጕዘው በራፋቃ ሰፈሩ።'),
  ('bdde4a45-39c3-54c5-a317-9c0ea64b11df', 'b00e81ef-9082-52f0-a614-3ec34c846efd', '013e163e-b011-5a64-a273-7ed453674c24', 13, 13, 'ከራፋቃም ተጕዘው በኤሉስ ሰፈሩ።'),
  ('7efa77bd-ef0f-59f9-af7b-11def642b523', 'b00e81ef-9082-52f0-a614-3ec34c846efd', '013e163e-b011-5a64-a273-7ed453674c24', 14, 14, 'ከኤሉስም ተጕዘው በራፊድን ሰፈሩ፤ በዚያም ሕዝቡ የሚጠጡት ውኃ አልነበረም።'),
  ('776c3dbc-660b-5400-a8bf-662b732c5dae', 'b00e81ef-9082-52f0-a614-3ec34c846efd', '013e163e-b011-5a64-a273-7ed453674c24', 15, 15, 'ከራፊድንም ተጕዘው በሲና ምድረ በዳ ሰፈሩ።'),
  ('e92c13c3-ba14-541b-ab79-074284cb2c14', 'b00e81ef-9082-52f0-a614-3ec34c846efd', '013e163e-b011-5a64-a273-7ed453674c24', 16, 16, 'ከሲና ምድረ በዳም ተጕዘው በምኞት መቃብር ሰፈሩ።'),
  ('f324dc62-1e99-5c0a-a996-0789060bdf29', 'b00e81ef-9082-52f0-a614-3ec34c846efd', '013e163e-b011-5a64-a273-7ed453674c24', 17, 17, 'ከምኞት መቃብርም ተጕዘው በአቤሮት ሰፈሩ።'),
  ('4f8f0c4d-d981-579d-a586-1075caac583f', 'b00e81ef-9082-52f0-a614-3ec34c846efd', '013e163e-b011-5a64-a273-7ed453674c24', 18, 18, 'ከአቤሮትም ተጕዘው በራታማ ሰፈሩ።'),
