  ('deca4bb7-a1c9-5970-a4a0-2d9be4cf50ed', 'b00e81ef-9082-52f0-a614-3ec34c846efd', '013e163e-b011-5a64-a273-7ed453674c24', 26, 26, 'ከመቄሎትም ተጕዘው በቀጠአት ሰፈሩ።'),
