  ('42dbefea-6255-51f4-a28a-9b293afaa562', 'b00e81ef-9082-52f0-a614-3ec34c846efd', '013e163e-b011-5a64-a273-7ed453674c24', 28, 28, 'ከተሪትም ተጕዘው በሚትቃ ሰፈሩ።'),
