  ('72ae1c1b-a277-504c-a6b3-e7bb8bc13c1a', 'b00e81ef-9082-52f0-a614-3ec34c846efd', '013e163e-b011-5a64-a273-7ed453674c24', 32, 32, 'ከብንያቅንም ተጕዘው በገድገድ ተራራ ሰፈሩ።'),
  ('29aefa1d-e6b8-5ee5-a658-4749e8cff427', 'b00e81ef-9082-52f0-a614-3ec34c846efd', '013e163e-b011-5a64-a273-7ed453674c24', 33, 33, 'ከገድገድም ተጕዘው በአጤቤት ሰፈሩ።'),
  ('1e203b67-0765-5c94-a9d2-d5b3c84dc932', 'b00e81ef-9082-52f0-a614-3ec34c846efd', '013e163e-b011-5a64-a273-7ed453674c24', 34, 34, 'ከአጤቤትም ተጕዘው በኤብሮና ሰፈሩ።'),
  ('c3adaa9e-6cd0-5785-a5b2-9e711c610edd', 'b00e81ef-9082-52f0-a614-3ec34c846efd', '013e163e-b011-5a64-a273-7ed453674c24', 35, 35, 'ከኤብሮናም ተጕዘው በጋስዮንጋቤር ሰፈሩ።'),
  ('13952a19-8a63-5de1-a595-cba301d04c6d', 'b00e81ef-9082-52f0-a614-3ec34c846efd', '013e163e-b011-5a64-a273-7ed453674c24', 36, 36, 'ከጋስዮንጋቤርም ተጕዘው በጺን ምድረ በዳ ሰፈሩ። ከጺን ምድረ በዳም ተጕዘው በፋራን ምድረ በዳ ሰፈሩ። ይህችም ቃዴስ ናት።'),
  ('b5145ece-c296-5392-adf1-89ee5a3b7ec2', 'b00e81ef-9082-52f0-a614-3ec34c846efd', '013e163e-b011-5a64-a273-7ed453674c24', 37, 37, 'ከቃዴስም ተጕዘው በኤዶምያስ ምድር ዳርቻ ባለው በሖር ተራራ ሰፈሩ።'),
  ('fe2600be-c5a3-5ef5-a5d1-74719d810c32', 'b00e81ef-9082-52f0-a614-3ec34c846efd', '013e163e-b011-5a64-a273-7ed453674c24', 38, 38, 'ካህኑም አሮን በእግዚአብሔር ትእዛዝ ወደ ሖር ተራራ ላይ ወጣ፤ በዚያም የእስራኤል ልጆች ከግብፅ ምድር ከወጡ በኋላ በአርባኛው ዓመት፥ በአምስተኛው ወር፥ ከወሩም በመጀመሪያው ቀን ሞተ።'),
  ('a09aadd6-c428-5704-a867-74251123879c', 'b00e81ef-9082-52f0-a614-3ec34c846efd', '013e163e-b011-5a64-a273-7ed453674c24', 39, 39, 'አሮንም በሖር ተራራ ላይ በሞተ ጊዜ ዕድሜው መቶ ሃያ ሦስት ዓመት ነበረ።'),
  ('2c478919-0b9c-58f1-a565-efb4f8ee4608', 'b00e81ef-9082-52f0-a614-3ec34c846efd', '013e163e-b011-5a64-a273-7ed453674c24', 40, 40, 'በከነዓን ምድርም ተቀምጦ የነበረው ከነዓናዊው የዓራድ ንጉሥ የእስራኤል ልጆች እንደ መጡ ሰማ።'),
  ('4e54cc45-453a-5d09-ae4b-39bf30bd1edd', 'b00e81ef-9082-52f0-a614-3ec34c846efd', '013e163e-b011-5a64-a273-7ed453674c24', 41, 41, 'እነርሱም ከሖር ተራራ ተጕዘው በሴልሞና ሰፈሩ።'),
  ('1269ee2a-1aaa-5273-a55a-a58a38afe6b5', 'b00e81ef-9082-52f0-a614-3ec34c846efd', '013e163e-b011-5a64-a273-7ed453674c24', 42, 42, 'ከሴልሞናም ተጕዘው በፌኖ ሰፈሩ።'),
  ('7f510ef4-3d39-52f1-ad6f-08d52f96f935', 'b00e81ef-9082-52f0-a614-3ec34c846efd', '013e163e-b011-5a64-a273-7ed453674c24', 43, 43, 'ከፌኖም ተጕዘው በአቦት ሰፈሩ።'),
  ('163af636-731d-5057-a862-4fc2785f20f3', 'b00e81ef-9082-52f0-a614-3ec34c846efd', '013e163e-b011-5a64-a273-7ed453674c24', 44, 44, 'ከአቦትም ተጕዘው በሞዓብ ዳርቻ ባለው በጋይ ሰፈሩ።'),
  ('29dad3bb-43df-598a-ad14-67a1fbda614a', 'b00e81ef-9082-52f0-a614-3ec34c846efd', '013e163e-b011-5a64-a273-7ed453674c24', 45, 45, 'ከጋይም ተጕዘው በዲቦንጋድ ሰፈሩ።'),
  ('a85db0a1-d40b-54ae-a7cd-a549a7b57deb', 'b00e81ef-9082-52f0-a614-3ec34c846efd', '013e163e-b011-5a64-a273-7ed453674c24', 46, 46, 'ከዲቦንጋድም ተጕዘው በጌልሞንዲብላታይም ሰፈሩ።'),
  ('5259a605-976b-56e3-a694-607ab3d7c956', 'b00e81ef-9082-52f0-a614-3ec34c846efd', '013e163e-b011-5a64-a273-7ed453674c24', 47, 47, 'ከጌልሞንዲብላታይምም ተጕዘው በናባው ፊት ባሉት በአባሪም ተራሮች ላይ ሰፈሩ።'),
  ('f3f072fa-c65d-5a8c-ae94-42468b3aa5ac', 'b00e81ef-9082-52f0-a614-3ec34c846efd', '013e163e-b011-5a64-a273-7ed453674c24', 48, 48, 'በናባው ፊት ካሉት ከአባሪም ተራሮችም ተጕዘው በዮርዳኖስ አጠገብ በኢያሪኮ በኩል ባለው በሞዓብ ምዕራብ ሰፈሩ።'),
  ('f9bda52c-0c9d-56d0-a3ea-0735cd581c54', 'b00e81ef-9082-52f0-a614-3ec34c846efd', '013e163e-b011-5a64-a273-7ed453674c24', 49, 49, 'በዮርዳኖስም አጠገብ በሞዓብ ምዕራብ ከአሲሞት መካከል እስከ አቤልሰጢም ድረስ ሰፈሩ።'),
  ('5b2cd3ef-4e21-581c-a84f-aa3d10e8b818', 'b00e81ef-9082-52f0-a614-3ec34c846efd', '5936c866-1c07-5410-a0e1-59dcf097fc2f', 1, 50, 'እግዚአብሔርም ሙሴን በዮርዳኖስ አጠገብ በኢያሪኮ በኩል በሞዓብ ምዕራብ እንዲህ ብሎ ተናገረው።'),
  ('215e3428-9258-543d-a661-a6c05789d95b', 'b00e81ef-9082-52f0-a614-3ec34c846efd', '5936c866-1c07-5410-a0e1-59dcf097fc2f', 2, 51, '“ለእስራኤል ልጆች እንዲህ ብለህ ንገራቸው፦ ወደ ከነዓን ምድር ዮርዳኖስን ትሻገራላችሁ፤'),
  ('3735aafd-58ce-5532-ab95-bb5c399e930a', 'b00e81ef-9082-52f0-a614-3ec34c846efd', '5936c866-1c07-5410-a0e1-59dcf097fc2f', 3, 52, 'በዚያችም ምድር የሚኖሩትን ሁሉ ከፊታችሁ አጥፉአቸው፤ የተቀረጹትንም ድንጋዮቻቸውን ሁሉ ታጠፋላችሁ፤ ቀልጠው የተሠሩትንም ምስሎቻቸውን ሁሉ ታጠፋላችሁ፤ በኮረብታ ላይ ያሉትን መስገጃዎቻቸውንም ታፈርሳላችሁ፤'),
  ('48fbb6f5-cdb4-50e6-ab62-655136293e49', 'b00e81ef-9082-52f0-a614-3ec34c846efd', '5936c866-1c07-5410-a0e1-59dcf097fc2f', 4, 53, 'በዚያች ምድር የሚኖሩትንም አጥፍታችሁ በውስጥዋ ኑሩ። ምድሪቱን ለእናንተ ርስት አድርጌ ሰጥቼአችኋለሁና።'),
  ('ad939d38-de0e-58e8-a087-641a2b0fee96', 'b00e81ef-9082-52f0-a614-3ec34c846efd', '5936c866-1c07-5410-a0e1-59dcf097fc2f', 5, 54, 'ምድሪቱንም ትወርሳላችሁ፤ በየወገኖቻችሁም ትከፋፈሏታላችሁ፤ ለብዙዎች ድርሻቸውን አብዙላቸው፤ ለጥቂቶችም ድርሻቸውን ጥቂት አድርጉ፤ እያንዳንዱ ሁሉ ዕጣ እንደ ወደቀለት በዚያ ርስቱ ይሆናል፤ በየአባቶቻችሁ ነገዶች ትወርሳላችሁ።'),
  ('e2595b7e-2cb4-599c-a3a6-91291ba0d6cd', 'b00e81ef-9082-52f0-a614-3ec34c846efd', '5936c866-1c07-5410-a0e1-59dcf097fc2f', 6, 55, 'የሀገሩንም ስዎች ከፊታችሁ ባታሳድዱ፥ ያስቀራችኋቸው ለዐይናችሁ እንደ እሾህ፥ ለጐናችሁም እንደ አሜከላ ይሆኑባችኋል፤ በምትቀመጡባትም ምድር ያስጨንቁአችኋል።'),
  ('20d2bec9-1524-5124-a20c-08fd940fc643', 'b00e81ef-9082-52f0-a614-3ec34c846efd', '5936c866-1c07-5410-a0e1-59dcf097fc2f', 7, 56, 'እኔም በእነርሱ አደርገው ዘንድ ያሰብሁትን በእናንተ አደርግባችኋለሁ።”'),
  ('54aa5f92-c95e-5928-a680-21a97ae89ad8', '6211a58d-0e74-5573-a89a-73ef692082a0', '18da78fa-28dd-50fb-ab13-b9aac0ddeba1', 1, 1, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('10c86eba-5211-5961-ae4c-a31205101e7f', '6211a58d-0e74-5573-a89a-73ef692082a0', '18da78fa-28dd-50fb-ab13-b9aac0ddeba1', 2, 2, '“የእስራኤልን ልጆች እንዲህ ብለህ እዘዛቸው፦ እነሆ እናንተ ወደ ከነዓን ምድር ትገባላችሁ፤ የከነዓንም ምድር ከአውራጃዎችዋ ጋር ለእናንተ ርስት ትሆናለች።'),
  ('b404a897-46a6-5e7c-a51c-c2453793628a', '6211a58d-0e74-5573-a89a-73ef692082a0', '18da78fa-28dd-50fb-ab13-b9aac0ddeba1', 3, 3, 'የአዜቡ ወገን ከጺን ምድረ በዳ በኤዶምያስ መያያዣ ይሆናል፤ የአዜብም ዳርቻ ከጨው ባሕር ዳር በምሥራቅ በኩል ይጀምራል፤'),
  ('8598e8d4-4223-566c-a7d8-8f1aadf922b4', '6211a58d-0e74-5573-a89a-73ef692082a0', '18da78fa-28dd-50fb-ab13-b9aac0ddeba1', 4, 4, 'ዳርቻችሁም በአቅራቦን ዐቀበት በአዜብ በኩል ይዞራል፤ እስከ ኤናቅም ይደርሳል፤ መውጫውም በቃዴስ በርኔ በአዜብ በኩል ይሆናል፤ ወደ አራድ ሀገሮችም ይደርሳል፤ ወደ አሴሞናም ያልፋል፤'),
  ('b01ab8ee-53b2-54bc-a139-a940159b6d45', '6211a58d-0e74-5573-a89a-73ef692082a0', '18da78fa-28dd-50fb-ab13-b9aac0ddeba1', 5, 5, 'ዳርቻውም ከአሴሞና ወደ ግብፅ ወንዝ ይዞራል፤ ወሰኑ ባሕሩ ይሆናል።'),
  ('21545283-b558-5e35-ae1a-086beea055d6', '6211a58d-0e74-5573-a89a-73ef692082a0', '18da78fa-28dd-50fb-ab13-b9aac0ddeba1', 6, 6, '“ለባሕርም ዳርቻ ታላቁ ባሕር ዳርቻችሁ ይሆናል፤ ይህ የባሕር ዳርቻችሁ ይሆናል።'),
  ('d7ed64af-5216-5283-a2b5-12f9d94a4ae2', '6211a58d-0e74-5573-a89a-73ef692082a0', '18da78fa-28dd-50fb-ab13-b9aac0ddeba1', 7, 7, '“በመስዕም በኩል ወሰናችሁ ከታላቁ ባሕር በተራራው በኩል ይሆንላችኋል።'),
  ('cbfbd9a0-08de-539a-a2a9-d7978b86c454', '6211a58d-0e74-5573-a89a-73ef692082a0', '18da78fa-28dd-50fb-ab13-b9aac0ddeba1', 8, 8, 'ከተራራው እስከ ተራራው ድረስ ይሆንላችኋል፤ እስከ ኤማትም ይደርሳል፤ የዳርቻውም መውጫ በሰረደክ ይሆናል፤'),
  ('6775f7ce-6e5b-5640-a7bd-d6b9f92e9ec6', '6211a58d-0e74-5573-a89a-73ef692082a0', '18da78fa-28dd-50fb-ab13-b9aac0ddeba1', 9, 9, 'ዳርቻውም ወደ ዲፍሮና ያልፋል፤ መውጫውም አርሴናይን ይሆናል፤ በመስዕ በኩል ያለው ወሰናችሁም በዚህ ይሁናችሁ።'),
  ('562aafa0-f067-5b98-a87c-613fdbfe2c4e', '6211a58d-0e74-5573-a89a-73ef692082a0', '18da78fa-28dd-50fb-ab13-b9aac0ddeba1', 10, 10, '“በምሥራቅ በኩል ያለው ወሰናችሁም ከሴፋማ አርሴናይን ጀምሮ ነው።'),
  ('4f1a400a-1d49-5099-a8ae-86861130b896', '6211a58d-0e74-5573-a89a-73ef692082a0', '18da78fa-28dd-50fb-ab13-b9aac0ddeba1', 11, 11, 'ዳርቻውም ከሴፋማ በዐይን ምሥራቅ ወዳለው ወደ አርቤላ ይወርዳል፤ እስከ ኬኔሬት የባሕር ወሽመጥ በምሥራቅ በኩል ይደርሳል፤'),
  ('89eafde6-1d4c-59c2-a2e5-81eedef08ae1', '6211a58d-0e74-5573-a89a-73ef692082a0', '18da78fa-28dd-50fb-ab13-b9aac0ddeba1', 12, 12, 'ዳርቻውም ወደ ዮርዳኖስ ይወርዳል፤ መውጫውም በጨው ባሕር ይሆናል። ምድራችሁ እንደ ዳርቻዋ በዙሪያዋ ይህች ናት።”'),
  ('74329774-4d04-504d-aa45-bcfaeb8da8b2', '6211a58d-0e74-5573-a89a-73ef692082a0', '18da78fa-28dd-50fb-ab13-b9aac0ddeba1', 13, 13, 'ሙሴም የእስራኤልን ልጆች እንዲህ ብሎ አዘዛቸው፥ “እግዚአብሔር ለዘጠኙ ነገድና ለምናሴ ነገድ እኩሌታ ይሰጡአቸው ዘንድ እንደ አዘዘ በዕጣ የምትወርሱአት ምድር ይህች ናት፤'),
  ('31591d29-a8e8-5f98-aa90-d17fb70c5570', '6211a58d-0e74-5573-a89a-73ef692082a0', '18da78fa-28dd-50fb-ab13-b9aac0ddeba1', 14, 14, 'የሮቤልም ልጆች ነገድ በየአባቶቻቸው ቤት፥ የጋድም ልጆች ነገድ በየአባቶቻቸው ቤት፥ የምናሴም ነገድ እኩሌታ ርስታቸውን ወርሰዋል።'),
  ('d4aeb4ae-9ed0-5f7e-a09b-801fb6faeecc', '6211a58d-0e74-5573-a89a-73ef692082a0', '18da78fa-28dd-50fb-ab13-b9aac0ddeba1', 15, 15, 'እነዚህ ሁለቱ ነገድና የአንዱ ነገድ እኩሌታ ርስታቸውን በዮርዳኖስ ማዶ በኢያሪኮ አንጻር በምሥራቅ በኩል ወረሱ።”'),
  ('d1f1e6ed-0bc1-57d2-a6aa-12276ce75916', '6211a58d-0e74-5573-a89a-73ef692082a0', 'fa206d0a-e51c-5795-ae43-75895a48cce2', 1, 16, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ፤ ተናገረው፦'),
  ('583e9600-036c-5a03-a8c0-a36693d00be7', '6211a58d-0e74-5573-a89a-73ef692082a0', 'fa206d0a-e51c-5795-ae43-75895a48cce2', 2, 17, '“ምድሪቱን ርስት አድርገው የሚከፍሉላችሁ ሰዎች ስማቸው ይህ ነው፤ ካህኑ አልዓዛርና የነዌ ልጅ ኢያሱ።'),
  ('c62c0ea6-b157-51ec-a756-628eb3b9bef8', '6211a58d-0e74-5573-a89a-73ef692082a0', 'fa206d0a-e51c-5795-ae43-75895a48cce2', 3, 18, 'ምድሪቱንም ርስት አድርገው የሚያካፍሏቸው ከየነገዱ አንድ አንድ አለቃ ይወስዳሉ።'),
  ('fefba608-98e2-5cb2-a573-2b4bbf50405b', '6211a58d-0e74-5573-a89a-73ef692082a0', 'fa206d0a-e51c-5795-ae43-75895a48cce2', 4, 19, 'የሰዎቹም ስም ይህ ነው፤ ከይሁዳ ነገድ የዮፎኒ ልጅ ካሌብ፥'),
  ('c3833bc9-584f-59ea-afd6-c9555a6bc402', '6211a58d-0e74-5573-a89a-73ef692082a0', 'fa206d0a-e51c-5795-ae43-75895a48cce2', 5, 20, 'ከስምዖን ልጆች ነገድ የዓሚሁድ ልጅ ሰላምያል፥'),
  ('e8dcce89-9f0d-52af-a01c-7900a525cb27', '6211a58d-0e74-5573-a89a-73ef692082a0', 'fa206d0a-e51c-5795-ae43-75895a48cce2', 6, 21, 'ከብንያም ነገድ የኪስሎን ልጅ ኤልዳድ፥'),
  ('ef143558-a715-502f-a94f-f74eae83dd4f', '6211a58d-0e74-5573-a89a-73ef692082a0', 'fa206d0a-e51c-5795-ae43-75895a48cce2', 7, 22, 'ከዳን ልጆች ነገድ አንድ አለቃ የዮቅሊ ልጅ ባቂ፥'),
  ('a8ac00c5-435c-5c6f-a147-d472cb6285ea', '6211a58d-0e74-5573-a89a-73ef692082a0', 'fa206d0a-e51c-5795-ae43-75895a48cce2', 8, 23, 'ከዮሴፍም ልጆች ከምናሴ ልጆች ነገድ አንድ አለቃ የሱፊድ ልጅ አንሄል፥'),
  ('6b6069b7-058c-56c1-abbc-7ce5daa37e9c', '6211a58d-0e74-5573-a89a-73ef692082a0', 'fa206d0a-e51c-5795-ae43-75895a48cce2', 9, 24, 'ከኤፍሬም ልጆች ነገድ አንድ አለቃ የሳፍጣን ልጅ ቃሙሔል፥'),
  ('484a2327-fa9c-5a39-af97-28a8949cb2e5', '6211a58d-0e74-5573-a89a-73ef692082a0', 'fa206d0a-e51c-5795-ae43-75895a48cce2', 10, 25, 'ከዛብሎን ልጆች ነገድ አንድ አለቃ የበርናክ ልጅ ኤሊሳፈን፥'),
  ('e7425cc6-024b-5606-a87e-7760a9f1a87b', '6211a58d-0e74-5573-a89a-73ef692082a0', 'fa206d0a-e51c-5795-ae43-75895a48cce2', 11, 26, 'ከይሳኮር ልጆች ነገድ አንድ አለቃ የሖዛ ልጅ ፈልጥሔል፥'),
  ('c4344606-59cc-52a9-a30d-225bf2bb6ba4', '6211a58d-0e74-5573-a89a-73ef692082a0', 'fa206d0a-e51c-5795-ae43-75895a48cce2', 12, 27, 'ከአሴር ልጆች ነገድ አንድ አለቃ የሴሌሚ ልጅ አኪሖር፥'),
  ('8bbc7f43-adf8-54b0-a7c0-4ef675b44c09', '6211a58d-0e74-5573-a89a-73ef692082a0', 'fa206d0a-e51c-5795-ae43-75895a48cce2', 13, 28, 'ከንፍታሌም ልጆች ነገድ አንድ አለቃ የአሚሁድ ልጅ ፈዳሄል።'),
  ('154368a0-01de-522a-a12a-71634218460e', '6211a58d-0e74-5573-a89a-73ef692082a0', 'fa206d0a-e51c-5795-ae43-75895a48cce2', 14, 29, 'እግዚአብሔር በከነዓን ምድር ለእስራኤል ልጆች ርስታቸውን ይከፍሉ ዘንድ ያዘዛቸው እነዚህ ናቸው።”'),
  ('c017b5ea-6db1-530e-a6e9-684206169857', '3e77c06b-ee80-5c68-aa38-4cd0bdb43350', '5761657e-7ba7-5942-a00f-c15ea6493c84', 1, 1, 'እግዚአብሔርም ሙሴን በዮርዳኖስ አጠገብ በኢያሪኮ አንጻር በሞዓብ ምዕራብ እንዲህ ብሎ ተናገረው፦'),
  ('7d849150-7a4b-52b5-a4c0-657649c3668d', '3e77c06b-ee80-5c68-aa38-4cd0bdb43350', '5761657e-7ba7-5942-a00f-c15ea6493c84', 2, 2, '“ሌዋውያን የሚቀመጡባቸውን ከተሞች ከሚካፈሉት ርስታቸው ይሰጡ ዘንድ የእስራኤልን ልጆች እዘዛቸው፤ በከተሞቹም ዙሪያ ያሉትን መሰማሪያዎች ለሌዋውያን ይስጡአቸው።'),
  ('0943075d-1730-5cbc-a8f1-7c1d23e4834d', '3e77c06b-ee80-5c68-aa38-4cd0bdb43350', '5761657e-7ba7-5942-a00f-c15ea6493c84', 3, 3, 'ከተሞቹም ለእነርሱ መኖሪያ ይሆናሉ፤ መሰማርያቸውም ለከብቶቻቸውና ለእንስሶቻቸው ይሁን።'),
  ('ffb1731b-4288-5b2c-a067-7a99bf6faa7e', '3e77c06b-ee80-5c68-aa38-4cd0bdb43350', '5761657e-7ba7-5942-a00f-c15ea6493c84', 4, 4, 'ለሌዋውያንም የምትሰጡት የከተማ መሰማርያ በከተማው ዙሪያ ከቅጥሩ ወደ ውጭ አንድ ሺህ ክንድ ይሁን።'),
  ('85499997-e1ec-568e-aa32-703a97c89bda', '3e77c06b-ee80-5c68-aa38-4cd0bdb43350', '5761657e-7ba7-5942-a00f-c15ea6493c84', 5, 5, 'ከከተማው ውጭ በምሥራቅ በኩል ሁለት ሺህ ክንድ፥ በደቡብ በኩል ሁለት ሺህ ክንድ፥ በምዕራብ በኩል ሁለት ሺህ ክንድ፥ በሰሜንም በኩል ሁለት ሺህ ክንድ ትከነዳላችሁ፤ ከተማውም በመካከል ይሆናል፤ ይህም የከተሞቹ መሰማርያ ይሆንላቸዋል።'),
  ('234a0e75-f4cb-56d4-a08a-2d96865c7cf8', '3e77c06b-ee80-5c68-aa38-4cd0bdb43350', '5761657e-7ba7-5942-a00f-c15ea6493c84', 6, 6, 'ለሌዋውያንም ከተሞችን ትሰጣላችሁ፤ ከምትሰጡአቸውም ከተሞች ስድስቱ ነፍሰ ገዳይ የሚሸሽባቸው የመማፀኛ ከተሞች ናቸው፤ ከእነዚህ ሌላ አርባ ሁለት ከተሞችን ትሰጣላችሁ።'),
  ('efef6e2a-e653-5c2a-ad03-a4af545061aa', '3e77c06b-ee80-5c68-aa38-4cd0bdb43350', '5761657e-7ba7-5942-a00f-c15ea6493c84', 7, 7, 'ለሌዋውያን የምትሰጡአቸው ከተሞች ሁሉ አርባ ስምንት ከተሞች ይሆናሉ፤ እነዚህም ከመሰማርያዎቻቸው ጋር ናቸው።'),
  ('0d3cecc0-a434-5801-a04f-f44acd966876', '3e77c06b-ee80-5c68-aa38-4cd0bdb43350', '5761657e-7ba7-5942-a00f-c15ea6493c84', 8, 8, 'ከእስራኤል ልጆች ርስት ለሌዋውያን የምትሰጡአቸውን ከተሞች እንዲህ ስጡ፤ ከብዙዎቹ ብዙ፥ ከጥቂቶቹ ጥቂት ትወስዳላችሁ፤ እያንዳንዱ እንደ ወረሱት እንደ ርስታቸው መጠን ከከተሞቻቸው ለሌዋውያን ይሰጣሉ።”'),
  ('cd2cdad7-6f71-59bf-a66d-dbbeb6dc9d44', '3e77c06b-ee80-5c68-aa38-4cd0bdb43350', '74385720-b76f-5430-af83-9ff3af534f62', 1, 9, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('55507cfe-a3a4-52a9-a9d3-ede7648a436a', '3e77c06b-ee80-5c68-aa38-4cd0bdb43350', '74385720-b76f-5430-af83-9ff3af534f62', 2, 10, '“ለእስራኤል ልጆች እንዲህ ብለህ ንገራቸው፦'),
  ('a8e30956-66a8-54f0-a718-4f6fbecfa4da', '3e77c06b-ee80-5c68-aa38-4cd0bdb43350', '74385720-b76f-5430-af83-9ff3af534f62', 3, 11, 'እነሆ፥ ወደ ከነዓን ምድር ዮርዳኖስን ትሻገራላችሁ፤ ባላማወቅ ነፍስ የገደለ ወደዚያ ይሸሽ ዘንድ የመማፀኛ ከተሞች እንዲሆኑላችሁ ከተሞችን ለእናንተ ለዩ።'),
  ('131c813e-34c4-5687-a7e5-172f49776c97', '3e77c06b-ee80-5c68-aa38-4cd0bdb43350', '74385720-b76f-5430-af83-9ff3af534f62', 4, 12, 'ነፍሰ ገዳዩ በማኅበሩ ፊት ለፍርድ እስከሚቆም ድረስ እንዳይሞት፥ ከተሞቹ ከደም ተበቃይ የመማፀኛ ከተሞች ይሁኑላችሁ።'),
  ('9ce91337-6ce4-549b-aa2e-3d2acb29fcd1', '3e77c06b-ee80-5c68-aa38-4cd0bdb43350', '74385720-b76f-5430-af83-9ff3af534f62', 5, 13, 'የምትሰጡአቸውም ስድስቱ ከተሞች የመማፀኛ ከተሞች ይሁኑላችሁ።'),
  ('6046e528-2f64-5fd0-a3fd-dc34572ffcd4', '3e77c06b-ee80-5c68-aa38-4cd0bdb43350', '74385720-b76f-5430-af83-9ff3af534f62', 6, 14, 'በዮርዳኖስ ማዶ ሦስት ከተሞችን ትለያላችሁ፤ በከነዓንም ምድር ሦስት ከተሞችን ትለያላችሁ፤ የመማፀኛ ከተሞችም ይሆናሉ።'),
  ('b2fb54a9-abd2-5d36-a39f-6c87c90caa21', '3e77c06b-ee80-5c68-aa38-4cd0bdb43350', '74385720-b76f-5430-af83-9ff3af534f62', 7, 15, 'ባለማወቅ ነፍስ የገደለ ሁሉ ይሸሽባቸው ዘንድ እነዚህ ስድስት ከተሞች ለእስራኤል ልጆች፥ በመካከላቸውም ለሚቀመጡ እንግዶችና መጻተኞች መማፀኛ ይሆናሉ።'),
  ('04c2e4c4-cd8f-59d5-a3e6-0657e3c57a1d', '3e77c06b-ee80-5c68-aa38-4cd0bdb43350', '74385720-b76f-5430-af83-9ff3af534f62', 8, 16, '“በብረት መሣሪያ ቢመታው፥ ቢሞትም ነፍሰ ገዳይ ነው፤ ነፍሰ ገዳዩም ፈጽሞ ይገደል።'),
  ('980fb474-6bdd-50a1-a1bb-efd02d3a42f5', '3e77c06b-ee80-5c68-aa38-4cd0bdb43350', '74385720-b76f-5430-af83-9ff3af534f62', 9, 17, 'ሰውም በሚሞትበት በእጁ ባለው ድንጋይ ቢመታው፥ የተመታውም ቢሞት፥ እርሱ ነፍሰ ገዳይ ነው፤ ነፍሰ ገዳዩም ፈጽሞ ይገደል።'),
  ('dbd0f8f7-69fc-55a9-a90c-59eb34709169', '3e77c06b-ee80-5c68-aa38-4cd0bdb43350', '74385720-b76f-5430-af83-9ff3af534f62', 10, 18, 'ሰውም በሚሞትበት በእጁ ባለው በእንጨት መሣሪያ ቢመታው፥ የተመታውም ቢሞት፥ እርሱ ነፍሰ ገዳይ ነው፤ ነፍሰ ገዳዩም ፈጽሞ ይገደል።'),
  ('734e6676-2417-53ff-a042-0b76ba588428', '3e77c06b-ee80-5c68-aa38-4cd0bdb43350', '74385720-b76f-5430-af83-9ff3af534f62', 11, 19, 'ደም ተበቃዩ ራሱ ነፍሰ ገዳዩን ይግደል፤ ባገኘው ጊዜ ይግደለው።'),
  ('62b4f083-2dec-5109-a014-3f972616c296', '3e77c06b-ee80-5c68-aa38-4cd0bdb43350', '74385720-b76f-5430-af83-9ff3af534f62', 12, 20, 'ጥል ቢጣላው፥ ወይም ሸምቆ አንዳች ነገር ቢጥልበት፥ ቢሞትም፥'),
  ('0a3b886b-bf6a-5212-ac7d-9ebabefc4372', '3e77c06b-ee80-5c68-aa38-4cd0bdb43350', '74385720-b76f-5430-af83-9ff3af534f62', 13, 21, 'ወይም በጥላቻ እስኪሞት ድረስ በእጁ ቢመታው፥ የመታው ፈጽሞ ይገደል፤ ነፍሰ ገዳይ ነው፤ ባለ ደሙ ወይም ተበቃዩ ባገኘው ጊዜ ነፍሰ ገዳዩን ይግደለው።'),
  ('bc32e7e5-1fb9-5a56-a709-2a1d68260d4c', '3e77c06b-ee80-5c68-aa38-4cd0bdb43350', '74385720-b76f-5430-af83-9ff3af534f62', 14, 22, '“ነገር ግን ያለ ጥላቻ ድንገት ቢደፋው፥ ሳይሸምቅም አንዳች ነገር ቢጥልበት፥'),
  ('f058c15e-f9c1-557e-a90f-fe62ce8faa31', '3e77c06b-ee80-5c68-aa38-4cd0bdb43350', '74385720-b76f-5430-af83-9ff3af534f62', 15, 23, 'ወይም ሳያየው እስኪሞት ድረስ ሰው የሚሞትበትን ድንጋይ ቢጥልበት፥'),
  ('71c8e66c-8616-5c01-a05a-3dbfd2598d8b', '3e77c06b-ee80-5c68-aa38-4cd0bdb43350', '74385720-b76f-5430-af83-9ff3af534f62', 16, 24, 'ጠላቱም ባይሆን፥ ክፉም ያደርግበት ዘንድ ባይሻ፥ ማኅበሩ በመቺውና በባለ ደሙ መካከል ፍርድን እንደዚህ ይፍረዱ፤'),
  ('eaf3a9d7-fc88-5be0-a7db-81d226d10f72', '3e77c06b-ee80-5c68-aa38-4cd0bdb43350', '74385720-b76f-5430-af83-9ff3af534f62', 17, 25, 'ማኅበሩም ነፍሰ ገዳዩን ከባለ ደሙ እጅ ያድኑታል፤ ማኅበሩም ወደ ሸሸበት ወደ መማፀኛው ከተማ ይመልሱታል፤ በቅዱስ ዘይትም የተቀባው ታላቁ ካህን እስኪሞት ድረስ በዚያ ይቀመጣል።'),
  ('f6fbed5b-7fbe-5156-a0a0-caac4603a30e', '3e77c06b-ee80-5c68-aa38-4cd0bdb43350', '74385720-b76f-5430-af83-9ff3af534f62', 18, 26, 'ነፍሰ ገዳዩ ግን ከሸሸበት ከመማፀኛው ከተማ ዳርቻ ቢወጣ፥ ባለ ደሙም ከመማፀኛው ከተማ ዳርቻ ውጭ ቢያገኘው፥'),
  ('bc3f2d97-0554-5012-ac85-cb662a3265a1', '3e77c06b-ee80-5c68-aa38-4cd0bdb43350', '74385720-b76f-5430-af83-9ff3af534f62', 19, 27, 'ባለ ደሙም ነፍሰ ገዳዩን ቢገድለው፥ በደል የለበትም፤'),
  ('8a536fcc-6c33-52f2-aff5-cc2f796e962e', '3e77c06b-ee80-5c68-aa38-4cd0bdb43350', '74385720-b76f-5430-af83-9ff3af534f62', 20, 28, 'ታላቁ ካህን እስኪሞት ድረስ በመማፀኛው ከተማ ውስጥ መቀመጥ ይገባው ነበርና። ታላቁ ካህን ከሞተ በኋላ ግን ነፍሰ ገዳዩ ወደ ርስቱ ምድር ይመለሳል።'),
  ('fcc3d03d-7d9b-5a89-ac5f-90c8cb4da3c1', '3e77c06b-ee80-5c68-aa38-4cd0bdb43350', '74385720-b76f-5430-af83-9ff3af534f62', 21, 29, '“እነዚህም ነገሮች ለልጅ ልጃችሁ በማደሪያችሁ ሁሉ ሥርዐትና ፍርድ ይሁኑላችሁ።'),
  ('48b23f6f-69ac-57fc-a717-4267c8a15a45', '3e77c06b-ee80-5c68-aa38-4cd0bdb43350', '74385720-b76f-5430-af83-9ff3af534f62', 22, 30, 'ነፍሰ ገዳይ ሁሉ በምስክሮች ቃል ይገደላል፤ በአንድ ምስክር ግን ማናቸውንም ሰው መግደል አይገባም።'),
  ('d03e4e3f-8803-504f-ae10-9732999664c5', '3e77c06b-ee80-5c68-aa38-4cd0bdb43350', '74385720-b76f-5430-af83-9ff3af534f62', 23, 31, 'ሞት የተፈረደበትን ነፍሰ ገዳዩንም ለማዳን የነፍስ ዋጋ አትቀበሉ፤ እርሱ ፈጽሞ ይገደል።'),
  ('d573121f-2ad1-5992-a75d-3f51cb7dfe09', '3e77c06b-ee80-5c68-aa38-4cd0bdb43350', '74385720-b76f-5430-af83-9ff3af534f62', 24, 32, 'ታላቁ ካህን እስኪሞት ወደ ምድሩ ትመልሱት ዘንድ ወደ መማፀኛው ከተማ ከሸሸው ዋጋ አትቀበሉ።'),
  ('24fe4596-5219-570e-a034-dc0f9bbe053d', '3e77c06b-ee80-5c68-aa38-4cd0bdb43350', '74385720-b76f-5430-af83-9ff3af534f62', 25, 33, 'ምድርን የሚያረክሳት ደም ነውና የምትኖሩባትን ምድር በነፍስ ግድያ አታርክሷት። ምድሪቱም በደም አፍሳሹ ደም ካልሆነ በቀር ከፈሰሰባት ደም አትነጻም።'),
  ('7856bfe7-c042-5260-ace0-7c2c35f50248', '3e77c06b-ee80-5c68-aa38-4cd0bdb43350', '74385720-b76f-5430-af83-9ff3af534f62', 26, 34, 'እናንተ በውስጥዋ የምትኖሩባትን፥ እኔም ከእናንተ ጋር የማድርባትን ምድር አታርክሱኣት፤ በእስራኤል ልጆች መካከል የማድር እኔ እግዚአብሔር ነኝና።”'),
  ('bde4ef18-8071-5990-a4c4-467ad09ee7d9', 'be8159c3-1b76-59f7-a536-211565a37a51', '20530af1-e515-5c04-a551-4da9e4d7ee8e', 1, 1, 'ከዮሴፍ ልጆች ወገኖች የምናሴ ልጅ የማኪር ልጅ የገለዓድ ልጆች ወገን አለቆች መጡ፤ በሙሴና በካህኑ በአልዓዛር፥ በእስራኤልም ልጆች አባቶች አለቆች ፊት ተናገሩ፤ አሉም፦'),
  ('f2dfd4d8-5875-5435-a762-81c8a02e3eda', 'be8159c3-1b76-59f7-a536-211565a37a51', '20530af1-e515-5c04-a551-4da9e4d7ee8e', 2, 2, '“ምድሪቱን ለእስራኤል ልጆች ርስት አድርጎ በዕጣ ከፍሎ ይሰጣቸው ዘንድ እግዚአብሔር ጌታችንን አዘዘው፤ እግዚአብሔርም የወንድማችንን የሰለጰዓድን ርስት ለሴቶች ልጆቹ ይሰጣቸው ዘንድ ጌታችንን አዘዘው።'),
  ('54a2c3cb-b096-5cdb-af6d-76a2f2c40973', 'be8159c3-1b76-59f7-a536-211565a37a51', '20530af1-e515-5c04-a551-4da9e4d7ee8e', 3, 3, 'ከሌላም ከእስራኤል ልጆች ነገድ ባል ቢያገቡ፥ ርስታቸው ከአባቶቻችን ርስት ይነቀላል፤ እነርሱም ለሚገቡበት ለሌላው ነገድ ርስት ይጨመራል፤ እንደዚህም የርስታችን ዕጣ ይጐድላል።'),
  ('4b2165d9-2544-5f27-a421-870e2a7f6931', 'be8159c3-1b76-59f7-a536-211565a37a51', '20530af1-e515-5c04-a551-4da9e4d7ee8e', 4, 4, 'ለእስራኤልም ልጆች ኢዮቤልዩ በሆነ ጊዜ ርስታቸው ሴቶቹ ወደ አገቡበት ወደ ሌላ ነገድ ርስት ይጨመራል፤ እነሆ፥ ርስታቸው ከአባቶቻችን ነገድ ርስት ይጐድላል።”'),
  ('f0eddc3d-64ed-58d3-a027-1b00b239d4ed', 'be8159c3-1b76-59f7-a536-211565a37a51', '20530af1-e515-5c04-a551-4da9e4d7ee8e', 5, 5, 'ሙሴም የእስራኤልን ልጆች እንደ እግዚአብሔር ቃል እንዲህ ብሎ አዘዛቸው፥ “የዮሴፍ ልጆች ነገድ በእውነት ተናገሩ።'),
  ('62399041-3a89-556b-a171-8896c2843980', 'be8159c3-1b76-59f7-a536-211565a37a51', '20530af1-e515-5c04-a551-4da9e4d7ee8e', 6, 6, 'እግዚአብሔር ስለ ሰለጰዓድ ሴቶች ልጆች ያዘዘው ነገር ይህ ነው፤ የወደዱትን ያግቡ፤ ነገር ግን ከአባታቸው ነገድ ብቻ ያግቡ።'),
  ('d3900e6f-bca8-5808-a009-e946768c9a67', 'be8159c3-1b76-59f7-a536-211565a37a51', '20530af1-e515-5c04-a551-4da9e4d7ee8e', 7, 7, 'እንደዚህም የእስራኤል ልጆች ርስት ከነገድ ወደ ነገድ ምንም አይተላለፍ፤ ከእስራኤልም ልጆች እያንዳንዱ ወደ አባቶቹ ነገድ ርስት ይጠጋ።'),
  ('76f44d92-9df5-5b24-af89-0b9e60ed17d0', 'be8159c3-1b76-59f7-a536-211565a37a51', '20530af1-e515-5c04-a551-4da9e4d7ee8e', 8, 8, 'ከእስራኤልም ልጆች እያንዳንዱ ሰው የአባቶቹን ርስት ይወርስ ዘንድ፥ ከእስራኤል ልጆች ነገድ ሁሉ፥ ርስት ያላት ሴት ልጅ ሁሉ ከአባቷ ነገድ ባል ታግባ።'),
  ('e6188de7-df6c-558d-ae9d-85816db1a38c', 'be8159c3-1b76-59f7-a536-211565a37a51', '20530af1-e515-5c04-a551-4da9e4d7ee8e', 9, 9, 'እንደዚህም ከአንድ ነገድ ወደ ሌላ ነገድ ምንም ርስት አይተላለፍ። ከእስራኤልም ልጆች ነገድ እያንዳንዱ ወደ ርስቱ ይጠጋ።”'),
  ('0c2b92e2-0cd7-5ebd-a68a-701d1a5eabca', 'be8159c3-1b76-59f7-a536-211565a37a51', '20530af1-e515-5c04-a551-4da9e4d7ee8e', 10, 10, 'እግዚአብሔርም ሙሴን እንዳዘዘው እንዲሁ የሰለጰዓድ ሴቶች ልጆች አደረጉ።'),
  ('5c2d0c7e-f771-5e8d-aaea-e523737658f4', 'be8159c3-1b76-59f7-a536-211565a37a51', '20530af1-e515-5c04-a551-4da9e4d7ee8e', 11, 11, 'የሰለጰዓድ ሴቶች ልጆች መሐላ፥ ቴርሳ፥ ሄግላ፥ ሚልካ፥ ኑኃ ከአባታቸው ወንድሞች ልጆች ጋር ተጋቡ።'),
  ('1bff3799-ef04-546c-a83c-90edcd8de0b5', 'be8159c3-1b76-59f7-a536-211565a37a51', '20530af1-e515-5c04-a551-4da9e4d7ee8e', 12, 12, 'ከዮሴፍ ልጅ ከምናሴ ልጆች ወገኖች ባሎቻቸውን አገቡ፥ ርስታቸውም በአባታቸው ነገድ ጸና።'),
  ('75f6f208-6e14-53c3-a6ba-96588a33e025', 'be8159c3-1b76-59f7-a536-211565a37a51', '20530af1-e515-5c04-a551-4da9e4d7ee8e', 13, 13, 'እግዚአብሔር በሙሴ እጅ የእስራኤልን ልጆች በዮርዳኖስ አጠገብ በኢያሪኮ አንጻር በሞዓብ ምዕራብ ያዘዛቸው ትእዛዝ፥ ሥርዐትና ፍርድ እነዚህ ናቸው።'),
  ('92c922b6-e272-514a-a03a-1b91b74fccb6', 'b6868e29-1cb7-567c-ae7b-356bb0abf429', '8d380bed-8550-546a-ae47-58b47ca42c6f', 1, 1, 'በዮርዳኖስ ማዶ በምድረ በዳ፥ በምዕራብ በኩል በኤርትራ ባሕር አጠገብ በፋራንና በጦፌል፥ በላባንና በአውሎን፥ በካታኪሪሲያም መካከል፥ ሙሴ ለእስራኤል ሁሉ፥ የነገራቸው ቃላት እኒህ ናቸው።'),
  ('50236b6e-bd81-50bb-aec1-972867e8b8fb', 'b6868e29-1cb7-567c-ae7b-356bb0abf429', '8d380bed-8550-546a-ae47-58b47ca42c6f', 2, 2, 'በሴይር ተራራ መንገድ ከኮሬብ እስከ ቃዴስ በርኔ ድረስ የዐሥራ አንድ ቀን ጕዞ ነው።'),
  ('4fa5b40f-acfb-54a0-aee9-027e409ea91a', 'b6868e29-1cb7-567c-ae7b-356bb0abf429', '8d380bed-8550-546a-ae47-58b47ca42c6f', 3, 3, 'በአርባኛው ዓመት በዐሥራ አንደኛው ወር ከወሩም በመጀመሪያው ቀን፥ ሙሴ እንዲነግራቸው እግዚአብሔር ስለ እነርሱ ያዘዘውን ሁሉ ለእስራኤል ልጆች ነገራቸው፤'),
  ('94f5d838-477f-5adb-a57e-cad515e87972', 'b6868e29-1cb7-567c-ae7b-356bb0abf429', '8d380bed-8550-546a-ae47-58b47ca42c6f', 4, 4, 'በሐሴቦን ተቀምጦ የነበረውን የአሞሬዎናውያንን ንጉሥ ሴዎንን፥ በአስጣሮትና በኤድራይን ተቀምጦ የነበረውንም የባሳንን ንጉሥ ዐግን ከገደሉት በኋላ፥'),
  ('be179b07-68ca-50e1-a1d4-1e4c533401b7', 'b6868e29-1cb7-567c-ae7b-356bb0abf429', '8d380bed-8550-546a-ae47-58b47ca42c6f', 5, 5, 'በዮርዳኖስ ማዶ በሞዓብ ምድር ሙሴ እንዲህ ብሎ ይህን ሕግ ይገልጥ ጀመር፦'),
  ('6e4a800c-d9c0-586e-aa29-b7674c33d33b', 'b6868e29-1cb7-567c-ae7b-356bb0abf429', '8d380bed-8550-546a-ae47-58b47ca42c6f', 6, 6, '“አምላካችን እግዚአብሔር በኮሬብ እንዲህ ብሎ ተናገረን፦ በዚህ ተራራ መቀመጣችሁ በቃ፤'),
  ('2bf03e0b-d5a4-5d0a-afb7-63408dca75b8', 'b6868e29-1cb7-567c-ae7b-356bb0abf429', '8d380bed-8550-546a-ae47-58b47ca42c6f', 7, 7, 'ተመልሳችሁ ተጓዙ፤ ወደ አሞራውያን ተራራ፥ ወደ አረባም ሀገሮች ሁሉ፥ በተራራውም፥ በሜዳውም፥ በሊባም፥ በባሕርም ዳር ወዳሉ ወደ ከነዓናውያን ምድር፥ ወደ ሊባኖስም ፊት ለፊት እስከ ታላቁ ወንዝ እስከ ኤፍራጥስ ድረስ ሂዱ።'),
  ('f9a2fbcd-bc39-52d4-a5f3-1fc34caae632', 'b6868e29-1cb7-567c-ae7b-356bb0abf429', '8d380bed-8550-546a-ae47-58b47ca42c6f', 8, 8, 'እነሆ፥ ምድሪቱን ሰጠኋችሁ፤ ግቡ፥ እግዚአብሔር ለእነርሱ፥ ከእነርሱም በኋላ ለዘራቸው ይሰጣት ዘንድ ለአባቶቻችሁ ለአብርሃምና ለይስሐቅ ለያዕቆብም የማለላቸውን ምድር ውረሱ።'),
  ('880cd865-1d6e-56a7-a823-e2f740d2d39d', 'b6868e29-1cb7-567c-ae7b-356bb0abf429', '8e9855fa-951f-512f-a0b8-75423fbfb8ac', 1, 9, '“በዚያም ዘመን እንዲህ ብዬ ተናገርኋችሁ፦ እኔ ብቻዬን ልሸከማችሁ አልችልም፤'),
  ('20f35941-7d35-59e1-ae1f-84df1da0996d', 'b6868e29-1cb7-567c-ae7b-356bb0abf429', '8e9855fa-951f-512f-a0b8-75423fbfb8ac', 2, 10, 'አምላካችሁ እግዚአብሔር አብዝቶአችኋልና፥ እነሆም፥ እናንተ ዛሬ እንደ ሰማይ ከዋክብት ብዙዎች ናችሁ።'),
  ('3cae96db-d067-5ff0-a355-431fa6b80d75', 'b6868e29-1cb7-567c-ae7b-356bb0abf429', '8e9855fa-951f-512f-a0b8-75423fbfb8ac', 3, 11, 'የአባቶቻችሁ አምላክ እግዚአብሔር በዚህ ቍጥር ላይ እልፍ አእላፋት ይጨምር፤ እንደ ተናገራችሁም ይባርካችሁ።'),
  ('4fca109c-4c48-5b19-a024-dec4333ffb89', 'b6868e29-1cb7-567c-ae7b-356bb0abf429', '8e9855fa-951f-512f-a0b8-75423fbfb8ac', 4, 12, 'እኔ ብቻዬን ድካማችሁን፥ ሸክማችሁንም፥ ክርክራችሁንም እሸከም ዘንድ እንዴት እችላለሁ?'),
  ('d4f0555f-745b-5f72-aafe-760afa001b2b', 'b6868e29-1cb7-567c-ae7b-356bb0abf429', '8e9855fa-951f-512f-a0b8-75423fbfb8ac', 5, 13, 'ከእናንተ ከየነገዳችሁ ጥበበኞች፥ አስተዋዮችም፥ ዐዋቂዎችም የሆኑትን ሰዎች አምጡ፤ እኔም በላያችሁ አለቆች አደርጋቸዋለሁ።'),
  ('674a21af-27f5-5a0a-a9b4-a8d1e4ec4cb2', 'b6868e29-1cb7-567c-ae7b-356bb0abf429', '8e9855fa-951f-512f-a0b8-75423fbfb8ac', 6, 14, 'እናንተም፦ ‘እናደርገው ዘንድ የተናገርኸው ይህ ነገር መልካም ነው’ ብላችሁ መልሳችሁ ነገራችሁኝ።'),
  ('a48b440a-6f2f-5cd8-accd-b3726b020fb2', 'b6868e29-1cb7-567c-ae7b-356bb0abf429', '8e9855fa-951f-512f-a0b8-75423fbfb8ac', 7, 15, 'ከእናንተም ጥበበኞችና ዐዋቂዎች፥ አስተዋዮችም የሆኑትን ሰዎች ወሰድሁ፤ በእናንተም ላይ አለቆች፥ የሻለቆችም፥ የመቶ አለቆችም፥ የአምሳ አለቆችም፥ የዐሥር አለቆችም፥ ለፈራጆቻችሁም ጻፎች አድርጌ ሰየምኋቸው።'),
  ('f5ed7be4-49a5-5226-aad3-ad8722bfa868', 'b6868e29-1cb7-567c-ae7b-356bb0abf429', '8e9855fa-951f-512f-a0b8-75423fbfb8ac', 8, 16, 'በዚያን ጊዜ ፈራጆቻችሁን አዘዝኋቸው። አልኋቸውም፦ የወንድሞቻችሁን ነገር ስሙ፤ በሰውና በወንድሙ፥ ከእርሱም ጋር ባለው መጻተኛ መካከል በጽድቅ ፍረዱ።'),
  ('edfd3b15-c360-556e-a4a0-4047277ffc25', 'b6868e29-1cb7-567c-ae7b-356bb0abf429', '8e9855fa-951f-512f-a0b8-75423fbfb8ac', 9, 17, 'በፍርድም ፊት አትዩ፤ ለትልቁም፥ ለትንሹም በእውነት ፍረዱ፤ ለሰው ፊት አታድሉ፤ ፍርድ የእግዚአብሔር ነውና። አንድ ነገር ቢከብዳችሁ እርሱን ወደ እኔ አምጡት፤ እኔም እሰማዋለሁ፤'),
  ('26502cba-9bf7-518e-aabf-7c365700e57d', 'b6868e29-1cb7-567c-ae7b-356bb0abf429', '8e9855fa-951f-512f-a0b8-75423fbfb8ac', 10, 18, 'በዚያን ጊዜም ልታደርጉት የሚገባችሁን ነገር ሁሉ አዘዝኋችሁ።'),
  ('7cf8c8d6-0dbc-53fa-af27-3396d707fec7', 'b6868e29-1cb7-567c-ae7b-356bb0abf429', '1ae18dd8-e7b6-55ba-a026-b9d39dc9be06', 1, 19, '“ከኮሬብም ተጓዝን፤ አምላካችን እግዚአብሔርም እንዳዘዘን በታላቁ፥ እጅግም በሚያስፈራ በዚያ ባያችሁት ምድረ በዳ ሁሉ በኩል በአሞሬዎን ተራራ መንገድ ሄድን፤ ወደ ቃዴስ በርኔም መጣን።'),
  ('81084d20-c20f-516f-a3da-15c61bb96c23', 'b6868e29-1cb7-567c-ae7b-356bb0abf429', '1ae18dd8-e7b6-55ba-a026-b9d39dc9be06', 2, 20, 'እኔም አልኋችሁ፦ አምላካችን እግዚአብሔር እስከ ሰጣችሁ እስከ አሞሬዎን ተራራ ኑ፤'),
  ('a36b7fd0-9152-5c67-ac80-a68b9c28b1ab', 'b6868e29-1cb7-567c-ae7b-356bb0abf429', '1ae18dd8-e7b6-55ba-a026-b9d39dc9be06', 3, 21, 'እነሆ፥ አምላካችሁ እግዚአብሔር ምድሪቱን በፊታችሁ እንደ ሰጣችሁ እዩ፤ የአባቶቻችሁ አምላክ እግዚአብሔር እንዳላችሁ ውጡ፤ ውረሷት፤ አትፍሩ፤ አትደንግጡም።'),
  ('befbd806-6376-593a-ad86-a6de7b0d3d82', 'b6868e29-1cb7-567c-ae7b-356bb0abf429', '1ae18dd8-e7b6-55ba-a026-b9d39dc9be06', 4, 22, 'እናንተም ሁላችሁ ወደ እኔ ቀርባችሁ፦ ምድሪቱን እንዲሰልሉልንና እንወጣባት ዘንድ የሚገባንን የመንገዱንና የምንገባባቸውን የእነዚያን ከተሞች ወሬ ተመልሰው እንዲነግሩን በፊታችን ሰዎች እንላክ አላችሁኝ።'),
  ('30f016f7-a011-57e4-a2cc-501bbe6e4add', 'b6868e29-1cb7-567c-ae7b-356bb0abf429', '1ae18dd8-e7b6-55ba-a026-b9d39dc9be06', 5, 23, 'ያም ነገር ደስ አሰኘኝ፤ ከእናንተም ዐሥራ ሁለት ሰው ወሰድሁ፤ ከየነገዱ ሁሉ አንድ አንድ ሰው ነበረ።'),
  ('262b15e4-06f7-5701-a62a-a49d3240d697', 'b6868e29-1cb7-567c-ae7b-356bb0abf429', '1ae18dd8-e7b6-55ba-a026-b9d39dc9be06', 6, 24, 'ሄዱም፤ ወደ ተራራውም ወጡ፤ ወደ ወይን ዘለላ ሸለቆ መጥተው ሰለሉአት።'),
  ('56b24b16-83ae-5940-ab54-eaa83c18f6c8', 'b6868e29-1cb7-567c-ae7b-356bb0abf429', '1ae18dd8-e7b6-55ba-a026-b9d39dc9be06', 7, 25, 'ከምድሪቱም ፍሬ በእጃቸው ወሰዱ፤ ወደ እኛም ይዘውት መጡ፦ ‘አምላካችን እግዚአብሔር የሚሰጠን ምድር መልካም ናት አሉን፤’'),
  ('63639439-7513-5168-adfa-7403cd58d4de', 'b6868e29-1cb7-567c-ae7b-356bb0abf429', '1ae18dd8-e7b6-55ba-a026-b9d39dc9be06', 8, 26, '“ወደ እርስዋ መውጣትንም እንቢ አላችሁ፤ በአምላካችሁ በእግዚአብሔር ትእዛዝ ላይም ዐመፃችሁ፤'),
  ('82b22d60-2bfb-521f-a572-890795146f80', 'b6868e29-1cb7-567c-ae7b-356bb0abf429', '1ae18dd8-e7b6-55ba-a026-b9d39dc9be06', 9, 27, 'በድንኳናችሁም ውስጥ እንዲህ እያላችሁ አጕረመረማችሁ፦ ‘እግዚአብሔር ስለ ጠላን እንዲያጠፋን በአሞሬዎናውያን እጅ አሳልፎ ይሰጠን ዘንድ ከግብፅ ምድር አወጣን።'),
  ('be5db4ce-b144-5d04-aa90-4364fba9c78e', 'b6868e29-1cb7-567c-ae7b-356bb0abf429', '1ae18dd8-e7b6-55ba-a026-b9d39dc9be06', 10, 28, 'ወዴት እንወጣለን? ሕዝቡ ታላቅና ብዙ ነው፤ ከእኛም ይጠነክራሉ፤ ከተሞቹም ታላላቆች፥ የተመሸጉም፥ እስከ ሰማይም የደረሱ ናቸው፤ የረዐይትንም ልጆች ደግሞ በዚያ አየናቸው ብለው ወንድሞቻችን ልባችንን አስፈሩት።’'),
  ('1f572805-628b-566f-a2f2-4fac6d85d6b6', 'b6868e29-1cb7-567c-ae7b-356bb0abf429', '1ae18dd8-e7b6-55ba-a026-b9d39dc9be06', 11, 29, 'እኔም አልኋችሁ፦ አትደንግጡ፤ ከእነርሱም አትፍሩ፤'),
  ('0a3285da-1fdb-5ded-a723-5e2b5bcd3a7c', 'b6868e29-1cb7-567c-ae7b-356bb0abf429', '1ae18dd8-e7b6-55ba-a026-b9d39dc9be06', 12, 30, 'በፊታችሁ የሚሄደው አምላካችሁ እግዚአብሔር፥ በግብፅ ምድር እንዳደረገላችሁ ሁሉ፥ ስለ እናንተ አብሮአችሁ ይዋጋል፤'),
  ('c9612440-18fc-58f5-a447-b55cdc81995e', 'b6868e29-1cb7-567c-ae7b-356bb0abf429', '1ae18dd8-e7b6-55ba-a026-b9d39dc9be06', 13, 31, 'ወደዚህም ስፍራ እስክትመጡ ድረስ በሄዳችሁበት መንገድ ሁሉ፥ ሰው ልጁን እንዲመግብ አምላካችሁ እግዚአብሔር በምድረ በዳ እንደመገባችሁ እናንተ አይታችኋል።'),
  ('ebdbf08f-cf57-52a0-a9f6-579c14ce66b5', 'b6868e29-1cb7-567c-ae7b-356bb0abf429', '1ae18dd8-e7b6-55ba-a026-b9d39dc9be06', 14, 32, 'ዳሩ ግን በዚህ ነገር አምላካችሁ እግዚአብሔርን አላመናችሁትም።'),
  ('e8720b06-e7c7-5cb5-af22-5fd7876a345b', 'b6868e29-1cb7-567c-ae7b-356bb0abf429', '1ae18dd8-e7b6-55ba-a026-b9d39dc9be06', 15, 33, 'እርሱም ስፍራን እንዲመርጥላችሁ፥ ትሄዱበትም ዘንድ የሚገባውን መንገድ እንዲያሳያችሁ ሌሊት በእሳት፥ ቀን በደመና በፊታችሁ በመንገድ ሲሄድ የነበረውን አላመናችሁትም።'),
  ('99503721-87cd-51d1-aa53-e50c0c25799c', 'b6868e29-1cb7-567c-ae7b-356bb0abf429', '6f59e790-c331-5442-a294-a50d0031e5b0', 1, 34, '“እግዚአብሔርም የቃላችሁን ድምፅ ሰምቶ ተቈጣ፤ እንዲህም ብሎ ማለ፦'),
  ('84058877-108c-549b-ae17-47434355d7ef', 'b6868e29-1cb7-567c-ae7b-356bb0abf429', '6f59e790-c331-5442-a294-a50d0031e5b0', 2, 35, 'ለአባቶቻችሁ እሰጣት ዘንድ የማልሁላቸውን መልካሚቱን ምድር ከእነዚህ ሰዎች ማንም አያይም፥'),
  ('e4410426-d950-53c2-a53a-58d2400bb2b7', 'b6868e29-1cb7-567c-ae7b-356bb0abf429', '6f59e790-c331-5442-a294-a50d0031e5b0', 3, 36, 'ከዮፎኒ ልጅ ከካሌብ በስተቀር፥ እርሱ ግን ያያታል፤ እግዚአብሔርን ፈጽሞ ተከትሎአልና የረገጣትን ምድር ለእርሱ፥ ለልጆቹም እሰጣለሁ።'),
  ('8fd1d500-056c-5072-a335-91981000b6ac', 'b6868e29-1cb7-567c-ae7b-356bb0abf429', '6f59e790-c331-5442-a294-a50d0031e5b0', 4, 37, 'እግዚአብሔርም በእናንተ ምክንያት በእኔ ተቈጣ፤ እንዲህም አለ፦ አንተ ደግሞ ወደዚያ አትገባም፤'),
  ('29ae771c-a19f-5022-a7f9-0160ca3f18d6', 'b6868e29-1cb7-567c-ae7b-356bb0abf429', '6f59e790-c331-5442-a294-a50d0031e5b0', 5, 38, 'በፊትህ የሚቆም የነዌ ልጅ ኢያሱ እርሱ ወደዚያ ይገባል፤ እርሱን አበርታው፤ ለእስራኤል ምድሪቱን ያወርሳልና።'),
  ('ce91e5af-4927-58a9-a568-9a280274a7cd', 'b6868e29-1cb7-567c-ae7b-356bb0abf429', '6f59e790-c331-5442-a294-a50d0031e5b0', 6, 39, 'ደግሞ፦ ይማረካሉ ያላችኋቸው ልጆቻችሁ፥ ዛሬም መልካሙን ከክፉ መለየት የማይችሉ ሕፃኖቻችሁ እነርሱ ወደዚያ ይገባሉ፤ ምድሪቱንም ለእነርሱ እሰጣለሁ፤ ይወርሱአታልም።'),
  ('924b2e35-150e-5445-aa26-979daff1dde9', 'b6868e29-1cb7-567c-ae7b-356bb0abf429', '6f59e790-c331-5442-a294-a50d0031e5b0', 7, 40, 'እናንተ ግን ተመልሳችሁ በኤርትራ ባሕር መንገድ ወደ ምድረ በዳ ሂዱ።'),
  ('bf60c71a-acc2-5c2d-a729-f863ce994a5a', 'b6868e29-1cb7-567c-ae7b-356bb0abf429', '6f59e790-c331-5442-a294-a50d0031e5b0', 8, 41, '“እናንተም፦ እግዚአብሔርን በድለናል፤ አምላካችን እግዚአብሔር እንዳዘዘን ሁሉ እንወጣለን፤ እንዋጋማለን ብላችሁ መለሳችሁልኝ። ከእናንተም ሰው ሁሉ የጦር መሣሪያውን ያዘ፤ ወደ ተራራም ወጣችሁ።'),
  ('7511af14-5891-5b64-a7dc-7c02da21f16c', 'b6868e29-1cb7-567c-ae7b-356bb0abf429', '6f59e790-c331-5442-a294-a50d0031e5b0', 9, 42, 'እግዚአብሔርም፦ እኔ ከእናንተ ጋር አይደለሁምና በጠላቶቻችሁ ፊት እንዳትወድቁ አትውጡ፤ አትዋጉም በላቸው አለኝ።'),
  ('7bfe4adf-b95d-59d8-a334-720ce24ae6ff', 'b6868e29-1cb7-567c-ae7b-356bb0abf429', '6f59e790-c331-5442-a294-a50d0031e5b0', 10, 43, 'እኔም ተናገርኋችሁ፤ እናንተ ግን አልሰማችሁም፤ የእግዚአብሔርንም ቃል ተላለፋችሁ፤ በኀይላችሁም ወደ ተራራማው አገር ወጣችሁ።'),
  ('8b219fe4-ee39-566e-ac7b-ac7ceaaf68e8', 'b6868e29-1cb7-567c-ae7b-356bb0abf429', '6f59e790-c331-5442-a294-a50d0031e5b0', 11, 44, 'በዚያም ተራራማ አገር ይኖሩ የነበሩ አሞሬዎናውያን ወጥተው ተጋጠሙአችሁ፤ ንብ እንደምትነድፍም ነደፉአችሁ፤ አሳደዱአችሁም፤ ከሴይር እስከ ሔርማም ድረስ መቱአችሁ።'),
  ('ce6a0f1d-9f30-5bfa-aed5-9d1361e793de', 'b6868e29-1cb7-567c-ae7b-356bb0abf429', '6f59e790-c331-5442-a294-a50d0031e5b0', 12, 45, 'ተቀምጣችሁም በአምላካችን በእግዚአብሔር ፊት አለቀሳችሁ፤ እግዚአብሔር ግን ድምፃችሁን አልሰማም፤ ወደ እናንተም አልተመለከተም።'),
  ('4ebed11e-e129-5ddd-a350-a35823266890', 'b6868e29-1cb7-567c-ae7b-356bb0abf429', '6f59e790-c331-5442-a294-a50d0031e5b0', 13, 46, 'ቀድሞ እንደ ተቀመጣችሁበትም ዘመን መጠን በቃዴስ ብዙ ቀን ተቀመጣችሁ።'),
  ('5639248e-9de6-5220-a9d7-60b109058394', '9af454f5-a36a-543e-a344-c9cac0f7e518', 'bff60ead-2a78-505b-a0e8-ab1c5ddf0390', 1, 1, '“እግዚአብሔርም እንዳለኝ ተመልሰን በኤርትራ ባሕር መንገድ ወደ ምድረ በዳ ሄድን፤ የሴይርንም ተራራ ብዙ ቀን ዞርን።'),
  ('1a844c32-aeca-5e32-ac77-2a0c91a091a1', '9af454f5-a36a-543e-a344-c9cac0f7e518', 'bff60ead-2a78-505b-a0e8-ab1c5ddf0390', 2, 2, 'እግዚአብሔርም እንዲህ ብሎ ተናገረኝ፦'),
  ('da476d97-0267-5658-a936-59b2871dfa9e', '9af454f5-a36a-543e-a344-c9cac0f7e518', 'bff60ead-2a78-505b-a0e8-ab1c5ddf0390', 3, 3, '‘ይህን ተራራ መዞር ይበቃችኋል፤ ተመልሳችሁ ወደ መስዕ ሂዱ።’'),
  ('2de80f84-d753-5cae-a872-15ff034ee159', '9af454f5-a36a-543e-a344-c9cac0f7e518', 'bff60ead-2a78-505b-a0e8-ab1c5ddf0390', 4, 4, 'ሕዝቡንም እንዲህ ብለህ እዘዛቸው፦ በሴይር ላይ በተቀመጡት በወንድሞቻችሁ በዔሳው ልጆች ሀገር ታልፋላችሁ፤ እነርሱ ይፈሩአችኋል፤ እንግዲህ እጅግ ተጠንቀቁ።'),
  ('775d727d-2d99-5119-adf5-dca7939182c6', '9af454f5-a36a-543e-a344-c9cac0f7e518', 'bff60ead-2a78-505b-a0e8-ab1c5ddf0390', 5, 5, 'የሴይርን ተራራ ለዔሳው ልጆች ርስት አድርጌ ስለ ሰጠሁ እኔ ከምድራቸው የጫማ መርገጫ ታህል እንኳን አልሰጣችሁምና አትጣሉአቸው።'),
  ('7f7935d8-b8f1-5914-ae55-81a525f5144e', '9af454f5-a36a-543e-a344-c9cac0f7e518', 'bff60ead-2a78-505b-a0e8-ab1c5ddf0390', 6, 6, 'ከእነርሱ በገንዘብ ምግብ ገዝታችሁ ትበላላችሁ፤ ውኃም ደግሞ በገንዘብ በመለኪያ ገዝታችሁ ትጠጣላችሁ።'),
  ('277fa52c-7c09-52b1-af2f-ecf926fb9402', '9af454f5-a36a-543e-a344-c9cac0f7e518', 'bff60ead-2a78-505b-a0e8-ab1c5ddf0390', 7, 7, 'አምላክህ እግዚአብሔር የእጅህን ሥራ ሁሉ ባርኮልሃልና፤ ይህን ታላቅና የሚያስፈራ ምድረ በዳ እንዴት እንደ ዞርኸው ዕወቅ፤ በዚህ አርባ ዓመት ውስጥ አምላክህ እግዚአብሔር ከአንተ ጋር ነበረ፤ ከተናገርኸው ሁሉ አንዳችም አላሳጣህም።'),
  ('08292d6a-0b30-5370-a59e-2e71deaec646', '9af454f5-a36a-543e-a344-c9cac0f7e518', 'bff60ead-2a78-505b-a0e8-ab1c5ddf0390', 8, 8, 'በሴይርም ከተቀመጡት ከወንድሞቻችን ከዔሳው ልጆች በዓረባ መንገድ ከኤሎንና ከጋስዮን-ጋብር አለፍን። ተመልሰንም በሞዓብ ምድረ በዳ መንገድ አለፍን።'),
  ('0b3786d6-3222-5595-a683-508c447e4609', '9af454f5-a36a-543e-a344-c9cac0f7e518', 'bff60ead-2a78-505b-a0e8-ab1c5ddf0390', 9, 9, '“እግዚአብሔርም አለኝ፦ እኔ አሮኤርን ለሎጥ ልጆች ርስት አድርጌ ስለ ሰጠሁ ከምድሩ ርስት አልሰጣችሁምና ሞዓባውያንን አትጣላ፤ በሰልፍም አትውጋቸው።'),
  ('0778b62a-1795-59f6-a37b-37789dfad796', '9af454f5-a36a-543e-a344-c9cac0f7e518', 'bff60ead-2a78-505b-a0e8-ab1c5ddf0390', 10, 10, 'እንደ ዔናቃውያን ታላቅና ብዙ ሕዝብ ኀያላንም የሆኑ ኦሚናውያን አስቀድሞ በዚያ ይቀመጡ ነበር።'),
  ('ac6a8bee-5e72-592d-a274-93da5a49b0de', '9af454f5-a36a-543e-a344-c9cac0f7e518', 'bff60ead-2a78-505b-a0e8-ab1c5ddf0390', 11, 11, 'እነርሱም ደግሞ እንደ ዔናቃውያን ራፋይም ተብለው ይታወቁ ነበር፤ ሞዓባውያን ግን “ኦሚን” ብለው ይጠሩአቸው ነበር።'),
  ('4d160476-4883-52eb-a136-8cdad566873e', '9af454f5-a36a-543e-a344-c9cac0f7e518', 'bff60ead-2a78-505b-a0e8-ab1c5ddf0390', 12, 12, 'ሖራውያንም ደግሞ አስቀድሞ በሴይር ላይ ተቀምጠው ነበር፤ የዔሳው ልጆች ግን መቱአቸው፤ ከፊታቸውም አጠፉአቸው፤ እግዚአብሔርም በሰጠው በርስቱ ምድር እስራኤል እንዳደረገ፥ በስፍራቸው ተቀመጡ።'),
  ('234feb51-3306-5f84-a551-3ac69fc6bc56', '9af454f5-a36a-543e-a344-c9cac0f7e518', 'bff60ead-2a78-505b-a0e8-ab1c5ddf0390', 13, 13, 'አሁንም ‘ተነሡና ተጓዙ፤ የዛሬድንም ፈፋ ተሻገሩ፤’ የዛሬድንም ፈፋ ተሻገርን።'),
  ('7fa350dd-7c14-514d-a177-21a514943c49', '9af454f5-a36a-543e-a344-c9cac0f7e518', 'bff60ead-2a78-505b-a0e8-ab1c5ddf0390', 14, 14, 'የዛሬድንም ፈፋ እስከ ተሻገርንበት ድረስ፥ እግዚአብሔር እንደ ማለባቸው ተዋጊዎች የሆኑ የዚያች ትውልድ ሰዎች ከሰፈሩ መካከል እስከ ጠፉ ድረስ፥ ከቃዴስ በርኔ የተጓዝንበት ዘመን ሠላሳ ስምንት ዓመት ሆነ።'),
  ('4cc1a0af-6a46-53df-a328-45783f2c65d1', '9af454f5-a36a-543e-a344-c9cac0f7e518', 'bff60ead-2a78-505b-a0e8-ab1c5ddf0390', 15, 15, 'ከሰፈርም መካከል ተለይተው እስኪጠፉ ድረስ የእግዚአብሔር እጅ በላያቸው ነበረ።'),
  ('4354ba6d-6794-511a-ac5e-2faf209556b0', '9af454f5-a36a-543e-a344-c9cac0f7e518', 'bff60ead-2a78-505b-a0e8-ab1c5ddf0390', 16, 16, '“እንዲህም ሆነ፤ ተዋጊዎቹ ከጠፉ፥ ከሕዝቡም መካከል ከሞቱ በኋላ፥'),
  ('17bb7f61-72b8-5bed-a9fc-f8bef7d57dfe', '9af454f5-a36a-543e-a344-c9cac0f7e518', 'bff60ead-2a78-505b-a0e8-ab1c5ddf0390', 17, 17, 'እግዚአብሔር እንዲህ ብሎ ተናገረኝ፦'),
  ('696bcdbd-e5db-530f-a740-e9034be45448', '9af454f5-a36a-543e-a344-c9cac0f7e518', 'bff60ead-2a78-505b-a0e8-ab1c5ddf0390', 18, 18, '‘አንተ ዛሬ የሞዓብን ዳርቻ አሮኤርን ታልፋለህ፤'),
  ('4d78e97f-d305-537b-acc8-7926e014fe47', '9af454f5-a36a-543e-a344-c9cac0f7e518', 'bff60ead-2a78-505b-a0e8-ab1c5ddf0390', 19, 19, 'ለሎጥም ልጆች ርስት አድርጌ ስለ ሰጠሁ ከአሞን ልጆች ምድር ርስት አልሰጥህምና በአሞን ልጆች አቅራቢያ ስትደርስ አትጣላቸው፤ አትውጋቸውም።’'),
  ('3b62e8ab-6024-50dd-afe5-bc55d2a9296d', '9af454f5-a36a-543e-a344-c9cac0f7e518', 'bff60ead-2a78-505b-a0e8-ab1c5ddf0390', 20, 20, 'ያም ደግሞ የራፋይም ምድር ተብሎ ተቈጠረ፤ ራፋይምም አስቀድሞ በዚያ ተቀምጠው ነበረ፤ አሞናውያን ግን “ዘምዞማውያን” ብለው ይጠሩአቸዋል።'),
  ('036cd9fe-c1d9-5c8e-a548-c384a45cfdc4', '9af454f5-a36a-543e-a344-c9cac0f7e518', 'bff60ead-2a78-505b-a0e8-ab1c5ddf0390', 21, 21, 'እነርሱም እንደ ዔናቃውያን ታላቅና ብዙ፥ ጽኑዓንም ሕዝብ ነበሩ፤ እግዚአብሔርም ከፊታቸው አጠፋቸው፤ እነርሱንም አሳድደው በስፍራቸው ተቀመጡ።'),
  ('0c7c5798-20fe-536d-a268-8169ddcf048b', '9af454f5-a36a-543e-a344-c9cac0f7e518', 'bff60ead-2a78-505b-a0e8-ab1c5ddf0390', 22, 22, 'ሖራውያንን ከፊታቸው አጥፍቶ በሴይር ለተቀመጡት ለዔሳው ልጆች እንዳደረገ እነርሱ ወረሱአቸው፤ በእነርሱም ፋንታ እስከ ዛሬ ድረስ ተቀመጡ።'),
  ('1f3d1f4d-c2c9-5ca8-aca6-dce2bc6eef80', '9af454f5-a36a-543e-a344-c9cac0f7e518', 'bff60ead-2a78-505b-a0e8-ab1c5ddf0390', 23, 23, 'እስከ ጋዛም ድረስ በአሴሮት ተቀምጠው የነበሩትን ኤዋውያንንና ከቀጰዶቅያ የወጡ ቀጰዶቃውያንን አጠፉአቸው፤ በእነርሱም ፋንታ ተቀመጡ።'),
  ('a819049f-d8ec-5925-ac9c-f4c90dcd5b91', '9af454f5-a36a-543e-a344-c9cac0f7e518', 'bff60ead-2a78-505b-a0e8-ab1c5ddf0390', 24, 24, 'ደግሞም አለ፦ ተነሥታችሁ ሂዱ፤ የአርኖንንም ሸለቆ ተሻገሩ፤ እነሆ፥ አሞሬዎናዊውን የሐሴቦንን ንጉሥ ሴዎንን፥ ምድሩንም በእጅህ አሳልፌ ሰጥቼሃለሁ፤ እርስዋን ግዛት፤ ውረሳት፥ ከእርሱም ጋር ተዋጋ።'),
  ('674c8f76-cb6b-5cc7-a697-7a2ec3d7098e', '9af454f5-a36a-543e-a344-c9cac0f7e518', 'bff60ead-2a78-505b-a0e8-ab1c5ddf0390', 25, 25, 'ከሰማይ በታች ባሉ አሕዛብ ሁሉ ላይ ማስደንገጥህንና ማስፈራትህን እሰድድ ዘንድ ዛሬ እጀምራለሁ፤ ስምህን በሰሙ ጊዜ በፊትህ ይንቀጠቀጣሉ፤ ድንጋጤም ይይዛቸዋል።'),
  ('c27cb6a6-026c-5213-ae13-9b031187aebe', '9af454f5-a36a-543e-a344-c9cac0f7e518', 'e52c4f5d-b7bf-5866-a85d-e86571b174da', 1, 26, '“ከቄድሞትም ምድረ በዳ የሰላምን ቃል ይነግሩት ዘንድ ወደ ሐሴቦን ንጉሥ ወደ ሴዎን እንዲህ ብዬ መልእክተኞችን ላክሁ፦'),
  ('e0f18ba7-0765-56b9-a0a3-8a2265a30974', '9af454f5-a36a-543e-a344-c9cac0f7e518', 'e52c4f5d-b7bf-5866-a85d-e86571b174da', 2, 27, '‘በሀገርህ ላይ ልለፍ፤ በአውራ ጎዳና እሄዳለሁ፤ ወደ ቀኝም ወደ ግራም አልተላለፍም።'),
  ('34280192-7180-5643-a11f-caa2a90160ed', '9af454f5-a36a-543e-a344-c9cac0f7e518', 'e52c4f5d-b7bf-5866-a85d-e86571b174da', 3, 28, 'የምበላውን ምግብ በገንዘብ ሽጥልኝ፤ የምጠጣውንም ውኃ በገንዘብ ስጠኝ፤ በእግሬ ብቻ ልለፍ፤'),
  ('3e5f79a4-a6ee-5ac5-a0b9-c355319f458c', '9af454f5-a36a-543e-a344-c9cac0f7e518', 'e52c4f5d-b7bf-5866-a85d-e86571b174da', 4, 29, 'በሴይር የተቀመጡ የዔሳው ልጆች፥ በአሮዔርም የተቀመጡ ሞዓባውያን እንዳደረጉልኝ፥ አምላካችን እግዚአብሔር ወደሚሰጠን ምድር ዮርዳኖስን እስክሻገር ድረስ በእግሬ ልለፍ።'),
  ('25ec0164-10cf-5ffa-a206-a8ed758c6739', '9af454f5-a36a-543e-a344-c9cac0f7e518', 'e52c4f5d-b7bf-5866-a85d-e86571b174da', 5, 30, 'የሐሴቦን ንጉሥ ሴዎን ግን ያሳልፈን ዘንድ አልፈቀደም፤ እንደ ዛሬው ሁሉ በእጅህ አሳልፎ ይሰጠው ዘንድ አምላክህ እግዚአብሔር መንፈሱን አደንድኖታልና፥ ልቡንም አጽንቶታልና።'),
  ('bec2c418-5731-55be-a4f0-c9a86975f4ab', '9af454f5-a36a-543e-a344-c9cac0f7e518', 'e52c4f5d-b7bf-5866-a85d-e86571b174da', 6, 31, 'እግዚአብሔርም፦ ‘የሐሴቦንን ንጉሥ አሞራዊውን ሴዎንንና ምድሩን በፊትህ በእጅህ አሳልፌ መስጠት እነሆ፥ ጀመርሁ፤ ምድሩን ትገዛ ዘንድ መውረስ ጀምር’ አለኝ።'),
  ('51f18356-ef64-5b77-ac65-0bf8209e1143', '9af454f5-a36a-543e-a344-c9cac0f7e518', 'e52c4f5d-b7bf-5866-a85d-e86571b174da', 7, 32, 'ሴዎንም ሕዝቡም ሁሉ ሊዋጉን ወደ ኢያሳ ወጡ።'),
  ('aaed9869-38eb-522e-a927-6bd48d69dd8f', '9af454f5-a36a-543e-a344-c9cac0f7e518', 'e52c4f5d-b7bf-5866-a85d-e86571b174da', 8, 33, 'አምላካችንም እግዚአብሔር እርሱን አሳልፎ በእጃችን ሰጠን፤ እርሱንም፥ ልጆቹንም፥ ሕዝቡንም ሁሉ መታን።'),
  ('b91554ae-5133-545f-a3c5-d950e23f43d2', '9af454f5-a36a-543e-a344-c9cac0f7e518', 'e52c4f5d-b7bf-5866-a85d-e86571b174da', 9, 34, 'በዚያን ጊዜም ከተሞቹን ሁሉ ወሰድን፤ ከተማውንም ሁሉ፥ ሴቶችንም፥ ሕፃኖችንም አጠፋን፤ አንዳችም የሸሸ በሕይወት አላስቀረንም፥'),
  ('2e004ea6-594f-58f3-aabd-69b0dfbcd8a9', '9af454f5-a36a-543e-a344-c9cac0f7e518', 'e52c4f5d-b7bf-5866-a85d-e86571b174da', 10, 35, 'ለእኛ ከማረክናቸው ከብቶቻቸውና ከከተሞቻቸው ከወሰድነው ምርኮ በቀር።'),
  ('6e71c3a7-afd4-5ba4-a4f5-25b18c064fe6', '9af454f5-a36a-543e-a344-c9cac0f7e518', 'e52c4f5d-b7bf-5866-a85d-e86571b174da', 11, 36, 'በአርኖን ሸለቆ አጠገብ ካለችው ከአሮዔርና በሸለቆውም ውስጥ ካለችው ከተማ ጀምረን እስከ ገለዓድ ተራራ ድረስ ማንኛዪቱም ከተማ አላመለጠችንም፤ አምላካችን እግዚአብሔር ሁሉን አሳልፎ በእጃችን ሰጠን።'),
  ('ed308eb6-bc51-51d0-a925-e42ed4cad3d8', '9af454f5-a36a-543e-a344-c9cac0f7e518', 'e52c4f5d-b7bf-5866-a85d-e86571b174da', 12, 37, 'ዳሩ ግን አምላካችን እግዚአብሔር እንዳዘዘን ወደ አሞን ልጆች ምድር፥ በያቦቅም ወንዝ አጠገብ ወደ አለው ስፍራ ሁሉ፥ በተራራማውም ሀገር ወደ አሉ ከተሞች አልደረስንም።'),
  ('a54df2b4-9af1-5155-a5e0-48772a2117f9', 'f2284491-3b35-5048-a5ff-401018315b9c', '127ee845-4e8e-51d7-a807-49167eb51c0a', 1, 1, '“ተመልሰንም በባሳን መንገድ ወጣን፤ የባሳን ንጉሥ ዐግም፥ ሕዝቡም ሁሉ በኤድራይን ሊዋጉን ወጡ።'),
  ('ab541594-cdaa-5dab-ad8f-c091125fa313', 'f2284491-3b35-5048-a5ff-401018315b9c', '127ee845-4e8e-51d7-a807-49167eb51c0a', 2, 2, 'እግዚአብሔርም፦ እርሱንና ሕዝቡን ሁሉ፥ ምድሩንም በእጅህ አሳልፌ ሰጥቼአለሁና አትፍራው፤ በሐሴቦን ይኖር በነበረው በአሞሬዎናውያን ንጉሥ በሴዎን ላይ እንዳደረግህ በእርሱም ታደርግበታለህ አለኝ።'),
  ('a5948c64-835c-545e-a2c3-59cf6da76904', 'f2284491-3b35-5048-a5ff-401018315b9c', '127ee845-4e8e-51d7-a807-49167eb51c0a', 3, 3, 'አምላካችን እግዚአብሔርም ደግሞ የባሳንን ንጉሥ ዐግን ሕዝቡንም ሁሉ በእጃችን አሳልፎ ሰጠን፤ እኛም አጠፋነው፤ አንድ ሰው እንኳን ለዘር አልቀረለትም።'),
  ('7b17ba9a-ef04-55ee-a403-508fda209ac8', 'f2284491-3b35-5048-a5ff-401018315b9c', '127ee845-4e8e-51d7-a807-49167eb51c0a', 4, 4, 'በዚያን ጊዜም ከተሞቹን ሁሉ ወሰድን፤ ከእነርሱም ያልወሰድነው ሀገር የለም፤ በባሳን ያለውን የዐግን መንግሥት፥ የአርጎብን አውራጃዎች ሁሉ፥ ስድሳ ከተሞችን ወሰድን።'),
  ('b4b5941d-5364-5166-a5e7-afc288593821', 'f2284491-3b35-5048-a5ff-401018315b9c', '127ee845-4e8e-51d7-a807-49167eb51c0a', 5, 5, 'እጅግ ብዙ ከሆኑት ከፌርዜዎን ከተሞች ሌላ፥ እነዚህ ከተሞች ሁሉ ቁመቱ ረዥም በሆነ ቅጥር በመዝጊያና በመወርወሪያም የተመሸጉ ነበሩ።'),
  ('ab23eeb2-1c8c-5cba-a1ed-fa35d129aaa6', 'f2284491-3b35-5048-a5ff-401018315b9c', '127ee845-4e8e-51d7-a807-49167eb51c0a', 6, 6, 'በሐሴቦንም ንጉሥ በሴዎን እንዳደረግን ፈጽሞ አጠፋናቸው፤ ከተሞቻቸውን ሁሉ በአንድነት፥ የሚሸሽ ሳናስቀር ሴቶችንም፥ ሕፃናቱንም ፈጽሞ አጠፋናቸው።'),
  ('a4cc6403-77b8-528b-a8c7-96d75a89f2d3', 'f2284491-3b35-5048-a5ff-401018315b9c', '127ee845-4e8e-51d7-a807-49167eb51c0a', 7, 7, 'ከብቶቹን ሁሉ የከተሞቹንም ምርኮ ለእኛ ወሰድን።'),
  ('a1907499-f38d-57cb-ae06-1015dc0fdd90', 'f2284491-3b35-5048-a5ff-401018315b9c', '127ee845-4e8e-51d7-a807-49167eb51c0a', 8, 8, '“በዚያም ዘመን ከአርኖን ሸለቆ ጀምሮ እስከ ኤርሞን ድረስ ምድሪቱን በዮርዳኖስ ማዶ ከነበሩ ከሁለቱ ከአሞሬዎን ነገሥታት እጅ ወሰድን፤'),
  ('70331a7f-fcc4-59c7-a0eb-ef1d72fb738d', 'f2284491-3b35-5048-a5ff-401018315b9c', '127ee845-4e8e-51d7-a807-49167eb51c0a', 9, 9, 'ፊኒቃውያን ኤርሞንን “ሳኒዮር” ብለው ይጠሩታል፤ አሞሬዎናውያንም ሳኔር ብለው ይጠሩታል።'),
  ('5d67404e-d06f-5133-a476-5b276e73e9be', 'f2284491-3b35-5048-a5ff-401018315b9c', '127ee845-4e8e-51d7-a807-49167eb51c0a', 10, 10, 'የሚሶርንም ከተሞች ሁሉ፥ የገለዓድንም ሁሉ፥ የባሳንንም ሁሉ እስከ ኤልከድና እስከ ኤድራይን ድረስ በባሳን የሚኖር የዐግን መንግሥት ከተሞች ሁሉ ወሰድን።'),
  ('b2f10511-4f1c-50f0-a38d-cfe518ab3e97', 'f2284491-3b35-5048-a5ff-401018315b9c', '127ee845-4e8e-51d7-a807-49167eb51c0a', 11, 11, 'ከራፋይንም ወገን የባሳን ንጉሥ ዐግ ብቻውን ቀርቶ ነበር፤ እነሆ፥ አልጋው የብረት አልጋ ነበረ፤ እርሱ በአሞን ልጆች ሀገር ዳርቻ አለ፤ ርዝመቱ ዘጠኝ ክንድ ወርዱም አራት ክንድ በሰው ክንድ ልክ ነበረ።'),
  ('8b5ac829-3999-55a1-a252-841b6a580d45', 'f2284491-3b35-5048-a5ff-401018315b9c', '1ff2227f-82c2-57a9-a7a6-93875c8f9bac', 1, 12, '“ይህችንም ምድር በዚያን ዘመን ወረስን፤ በአርኖንም ሸለቆ አጠገብ ካለችው ከአሮዔር ጀምሮ የገለዓድን ተራራማ ሀገር እኩሌታ፥ ከተሞቹንም ለሮቤልና ለጋድ ነገድ ሰጠኋቸው።'),
  ('520ae816-5637-5c41-aa76-aebd2369f1c7', 'f2284491-3b35-5048-a5ff-401018315b9c', '1ff2227f-82c2-57a9-a7a6-93875c8f9bac', 2, 13, 'ከገለዐድም የቀረውን የዐግን መንግሥት ባሳንን ሁሉ፥ የአርጎብንም ምድር ሁሉ ለምናሴ ነገድ እኩሌታ ሰጠሁ፤ ያችም ባሳን ሁሉ የራፋይም ሀገር ተብላ ተቈጠረች።'),
  ('8f6cf2fe-90f3-5c5a-abe1-68c5fc52260a', 'f2284491-3b35-5048-a5ff-401018315b9c', '1ff2227f-82c2-57a9-a7a6-93875c8f9bac', 3, 14, 'የምናሴ ልጅ ኢያዕር እስከ ጌርጋሴና እስከ መካቲ ዳርቻ ድረስ የአርጎብን አውራጃ ሁሉ ወሰደ፤ ይህችንም የባሳንን ምድር እስከዚች ቀን ድረስ በስሙ አውታይ ኢያዕር ብሎ ጠራ።'),
  ('c2eee45b-cf76-53fb-aa4c-ba67921ee7a3', 'f2284491-3b35-5048-a5ff-401018315b9c', '1ff2227f-82c2-57a9-a7a6-93875c8f9bac', 4, 15, 'ለማኪርም ገለዓድን ሰጠሁት።'),
  ('b3c29832-0193-562f-af94-3b8fb1819500', 'f2284491-3b35-5048-a5ff-401018315b9c', '1ff2227f-82c2-57a9-a7a6-93875c8f9bac', 5, 16, 'ለሮቤልና ለጋድም ከገለዓድ ምድር ጀምሮ እስከ አርኖን ሸለቆ ድረስ የሸለቆውን እኩሌታ ዳርቻውንም፥ እስከ አሞን ልጆች ዳርቻ እስከ ኢያቦቅ ወንዝ ድረስ፥'),
  ('44c3cc89-2b23-5084-af93-38ae316143df', 'f2284491-3b35-5048-a5ff-401018315b9c', '1ff2227f-82c2-57a9-a7a6-93875c8f9bac', 6, 17, 'ከመካናራ ወሰን ከፈስጋ ተራራ በታች ወደ ምሥራቅ እስከ ዓረባ ባሕር እርሱም የጨው ባሕር ድረስ ዓረባን፥ ዮርዳኖስንም ሰጠኋቸው።'),
  ('0ee9bc7e-f60c-5ab7-a06f-5c21688fb89c', 'f2284491-3b35-5048-a5ff-401018315b9c', '1ff2227f-82c2-57a9-a7a6-93875c8f9bac', 7, 18, '“በዚያም ዘመን እንዲህ ብዬ አዘዝኋችሁ፦ አምላካችሁ እግዚአብሔር ይህችን ምድር ርስት አድርጎ ሰጥቶአችኋል፤ መሣሪያችሁን ይዛችሁ እናንተ አርበኞች ሁሉ በወንድሞቻችሁ በእስራኤል ልጆች ፊት ትሻገራላችሁ።'),
  ('e227ca2a-6dee-52b9-a704-1d71dc9f1434', 'f2284491-3b35-5048-a5ff-401018315b9c', '1ff2227f-82c2-57a9-a7a6-93875c8f9bac', 8, 19, 'ነገር ግን እጅግ ከብቶች እንዳሉአችሁ አውቃለሁና ሴቶቻችሁና ልጆቻችሁ፥ ከብቶቻችሁም በሰጠኋችሁ ከተሞች ይቀመጣሉ፤'),
  ('b87c736f-8dff-51f6-a8b7-b5a9688d432b', 'f2284491-3b35-5048-a5ff-401018315b9c', '1ff2227f-82c2-57a9-a7a6-93875c8f9bac', 9, 20, 'ይኸውም እግዚአብሔር እንደ እናንተ፥ ወንድሞቻችሁን እስኪያሳርፍ ድረስ፥ እነርሱም ደግሞ በዮርዳኖስ ማዶ አምላካችሁ እግዚአብሔር የሚሰጣቸውን ምድር እስኪወርሱ ድረስ ነው። ከዚያም በኋላ ሁላችሁ ወደ ሰጠኋችሁ ርስት ትመለሳላችሁ።'),
  ('780de76a-3e5d-5aeb-a2d0-5f17eade22dc', 'f2284491-3b35-5048-a5ff-401018315b9c', '1ff2227f-82c2-57a9-a7a6-93875c8f9bac', 10, 21, 'በዚያም ጊዜ ኢያሱን እንዲህ ብዬ አዘዝሁት፦ አምላካችሁ እግዚአብሔር በእነዚህ በሁለቱ ነገሥት ያደረገውን ሁሉ ዐይኖችህ አይተዋል፤ እንዲሁ በምታልፍባቸው መንግሥታት ሁሉ ላይ እግዚአብሔር ያደርጋል።'),
  ('76172f19-7127-58ae-a11b-1b8ffb0c65b5', 'f2284491-3b35-5048-a5ff-401018315b9c', '1ff2227f-82c2-57a9-a7a6-93875c8f9bac', 11, 22, 'አምላካችሁ እግዚአብሔር እርሱ ስለ እናንተ ይዋጋልና ከእነርሱ የተነሣ አትፍሩ።'),
  ('1e3c22f2-0151-563d-a1c7-e46a74fa4e1e', 'f2284491-3b35-5048-a5ff-401018315b9c', '4e50d6f4-3758-5b4f-a9f4-73f694d70ae5', 1, 23, '“በዚያም ዘመን እኔ እግዚአብሔርን እንዲህ ብዬ ለመንሁት፦'),
  ('6e4c7e29-2442-5670-af72-1f4332f962fa', 'f2284491-3b35-5048-a5ff-401018315b9c', '4e50d6f4-3758-5b4f-a9f4-73f694d70ae5', 2, 24, 'ጌታ እግዚአብሔር ሆይ! ታላቅነትህንና ኀይልህን፥ የጸናች እጅህንና የተዘረጋች ክንድህን ለእኔ ለአገልጋይህ ማሳየት ጀምረሃል፤ በሰማይና በምድርም እንደ ሥራህ፥ እንደ ኀይልህም ይሠራ ዘንድ የሚችል አምላክ ማን ነው?')
